@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'cv': ['cv_object'], 'n_permutations': [Interval(Integral, 1, None, closed='left')], 'n_jobs': [Integral, None], 'random_state': ['random_state'], 'verbose': ['verbose'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def permutation_test_score(estimator, X, y, *, groups=None, cv=None, n_permutations=100, n_jobs=None, random_state=0, verbose=0, scoring=None, params=None):
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, y, groups = indexable(X, y, groups)
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    random_state = check_random_state(random_state)
    if _routing_enabled():
        router = MetadataRouter(owner='permutation_test_score').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('permutation_test_score.fit', 'permutation_test_score'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    score = _permutation_test_score(clone(estimator), X, y, cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score)
    permutation_scores = Parallel(n_jobs=n_jobs, verbose=verbose)((delayed(_permutation_test_score)(clone(estimator), X, _shuffle(y, groups, random_state), cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score) for _ in range(n_permutations)))
    permutation_scores = np.array(permutation_scores)
    pvalue = (np.sum(permutation_scores >= score) + 1.0) / (n_permutations + 1)
    return (score, permutation_scores, pvalue)

def _load_arff_response(url: str, data_home: Optional[str], target: str, output_type: str, openml_columns_info: dict, feature_names_to_select: List[str], target_names_to_select: List[str], shape: Optional[Tuple[int, int]], md5_checksum: str, n_retries: int=3, delay: float=1.0, read_csv_kwargs: Optional[Dict]=None):
    gzip_file = _open_openml_url(url, data_home, n_retries=n_retries, delay=delay)
    with closing(gzip_file):
        md5 = hashlib.md5()
        for chunk in iter(lambda: gzip_file.read(4096), b''):
            md5.update(chunk)
        actual_md5_checksum = md5.hexdigest()
    if actual_md5_checksum != md5_checksum:
        location = f'downloaded from {url}'
        if data_home is not None:
            local_path = _get_local_path(_openml_path_from_url(url), data_home)
            location += f' and cached at {local_path}'
        raise ValueError(f'The md5 checksum of the file {location} does not match the expected checksum from the dataset description: expected {md5_checksum} but got {actual_md5_checksum}. The downloaded file could have been modified or corrupted; clean the cache and retry.')

    def _open_url_and_load_gzip_file(url, data_home, n_retries, delay, arff_params):
        gzip_file = _open_openml_url(url, data_home, n_retries=n_retries, delay=delay)
        with closing(gzip_file):
            return load_arff_from_gzip_file(gzip_file, **arff_params)
    arff_params: Dict = dict(parser=target, output_type=output_type, openml_columns_info=openml_columns_info, feature_names_to_select=feature_names_to_select, target_names_to_select=target_names_to_select, shape=shape, read_csv_kwargs=read_csv_kwargs or {})
    try:
        X, y, frame, categories = _open_url_and_load_gzip_file(url, data_home, n_retries, delay, arff_params)
    except Exception as exc:
        if target != 'pandas':
            raise
        from pandas.errors import ParserError
        if not isinstance(exc, ParserError):
            raise
        arff_params['read_csv_kwargs'].update(quotechar="'")
        X, y, frame, categories = _open_url_and_load_gzip_file(url, data_home, n_retries, delay, arff_params)
    return (X, y, frame, categories)

