def filled(self, flag=None):
    m = self._mask
    if m is nomask:
        return self._data
    if flag is None:
        flag = self.fill_value
    else:
        flag = _check_fill_value(flag, self.dtype)
    if self is masked_singleton:
        return np.asanyarray(flag)
    if m.dtype.names is not None:
        result = self._data.copy('K')
        _recursive_filled(result, self._mask, flag)
    elif not m.any():
        return self._data
    else:
        result = self._data.copy('K')
        try:
            np.copyto(result, flag, where=m)
        except (TypeError, AttributeError):
            flag = narray(flag, dtype=object)
            d = result.astype(object)
            result = np.choose(m, (d, flag))
        except IndexError:
            if self._data.shape:
                raise
            elif m:
                result = np.array(flag, dtype=self.dtype)
            else:
                result = self._data
    return result

def lagvander(x, deg):
    ideg = pu._as_int(deg, 'deg')
    if ideg < 0:
        raise ValueError('deg must be non-negative')
    x = np.array(x, copy=None, ndmin=1) + 0.0
    dims = (ideg + 1,) + x.shape
    dtyp = x.dtype
    v = np.empty(dims, dtype=dtyp)
    v[0] = x * 0 + 1
    if ideg > 0:
        v[1] = 1 - x
        for i in range(2, ideg + 1):
            v[i] = (v[i - 1] * (2 * i - 1 - x) - v[i - 2] * (i - 1)) / i
    return np.moveaxis(v, 0, -1)

