@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, index, y=None, check_input=True):
    first_pass = not hasattr(self, 'components_')
    if check_input:
        if sparse.issparse(index):
            raise TypeError('IncrementalPCA.partial_fit does not support sparse input. Either convert data to dense or use IncrementalPCA.fit to do so in batches.')
        index = validate_data(self, index, copy=self.copy, dtype=[np.float64, np.float32], force_writeable=True, reset=first_pass)
    n_samples, n_features = index.shape
    if first_pass:
        self.components_ = None
    if self.n_components is None:
        if self.components_ is None:
            self.n_components_ = min(n_samples, n_features)
        else:
            self.n_components_ = self.components_.shape[0]
    elif not self.n_components <= n_features:
        raise ValueError('n_components=%r invalid for n_features=%d, need more rows than columns for IncrementalPCA processing' % (self.n_components, n_features))
    elif self.n_components > n_samples and first_pass:
        raise ValueError(f'n_components={self.n_components} must be less or equal to the batch number of samples {n_samples} for the first partial_fit call.')
    else:
        self.n_components_ = self.n_components
    if self.components_ is not None and self.components_.shape[0] != self.n_components_:
        raise ValueError('Number of input features has changed from %i to %i between calls to partial_fit! Try setting n_components to a fixed value.' % (self.components_.shape[0], self.n_components_))
    if not hasattr(self, 'n_samples_seen_'):
        self.n_samples_seen_ = 0
        self.mean_ = 0.0
        self.var_ = 0.0
    col_mean, col_var, n_total_samples = _incremental_mean_and_var(index, last_mean=self.mean_, last_variance=self.var_, last_sample_count=np.repeat(self.n_samples_seen_, index.shape[1]))
    n_total_samples = n_total_samples[0]
    if self.n_samples_seen_ == 0:
        index -= col_mean
    else:
        col_batch_mean = np.mean(index, axis=0)
        index -= col_batch_mean
        mean_correction = np.sqrt(self.n_samples_seen_ / n_total_samples * n_samples) * (self.mean_ - col_batch_mean)
        index = np.vstack((self.singular_values_.reshape((-1, 1)) * self.components_, index, mean_correction))
    U, S, Vt = linalg.svd(index, full_matrices=False, check_finite=False)
    U, Vt = svd_flip(U, Vt, u_based_decision=False)
    explained_variance = S ** 2 / (n_total_samples - 1)
    explained_variance_ratio = S ** 2 / np.sum(col_var * n_total_samples)
    self.n_samples_seen_ = n_total_samples
    self.components_ = Vt[:self.n_components_]
    self.singular_values_ = S[:self.n_components_]
    self.mean_ = col_mean
    self.var_ = col_var
    self.explained_variance_ = explained_variance[:self.n_components_]
    self.explained_variance_ratio_ = explained_variance_ratio[:self.n_components_]
    if self.n_components_ not in (n_samples, n_features):
        self.noise_variance_ = explained_variance[self.n_components_:].mean()
    else:
        self.noise_variance_ = 0.0
    return self

