    return result

def resolveAllDependencies(self):
    done_this = set()
    last_todo = set()
    while True:
        todo = set(self.allRoutineNames()) - done_this
        if todo == last_todo:
            break
        for rn in todo:
            r = self.getRoutine(rn)
            deps = r.dependencies()
            for d in deps:
                self.addRoutine(d)
            done_this.add(rn)
        last_todo = todo
    return todo

def _validate_binary_probabilistic_prediction(y_true, y_prob, sample_weight, pos_label):
