def slice(a, start=None, stop=np._NoValue, step=None, /):
    if stop is np._NoValue:
        stop = start
        start = None
    if step is None:
        step = 1
    step = np.asanyarray(step)
    if not np.issubdtype(step.dtype, np.integer):
        raise TypeError(f"unsupported type {step.dtype} for operand 'step'")
    if np.any(step == 0):
