def lexsort_indexer(keys: Sequence[ArrayLike | Index | Series], orders: bool | Sequence[bool] | None=None, na_position: str='last', key: Callable | None=None, codes_given: bool=False) -> npt.NDArray[np.intp]:
    from pandas.core.arrays import Categorical
    if na_position not in ['last', 'first']:
        raise ValueError(f'invalid na_position: {na_position}')
    orders_iter: Iterable[bool]
    if isinstance(orders, bool):
        orders_iter = itertools.repeat(orders, len(keys))
    elif orders is None:
        orders_iter = itertools.repeat(True, len(keys))
    else:
        orders_iter = reversed(orders)
    labels = []
    for k, order in zip(reversed(keys), orders_iter, strict=True):
        k = ensure_key_mapped(k, key)
        if codes_given:
            codes = cast('np.ndarray', k)
            n = codes.max() + 1 if len(codes) else 0
        else:
            arr = extract_array(k, extract_numpy=True)
            if isinstance(arr, np.ndarray) and arr.dtype.kind in 'fiub':
                if arr.dtype.kind == 'f':
                    mask = np.isnan(arr)
                    has_na = mask.any()
                    if not order:
                        arr = -arr
                        if na_position == 'first' and has_na:
                            arr[mask] = -np.inf
                    elif na_position == 'first' and has_na:
                        arr = arr.copy()
                        arr[mask] = -np.inf
                elif not order:
                    arr = ~arr
                labels.append(arr)
                continue
            cat = Categorical(k, ordered=True)
            codes = cat.codes
            n = len(cat.categories)
        mask = codes == -1
        if na_position == 'last' and mask.any():
            codes = np.where(mask, n, codes)
        if not order:
            codes = np.where(mask, codes, n - codes - 1)
        labels.append(codes)
    return np.lexsort(labels)

def idxmax(self, axis: Axis=0, skipna: bool=True, numeric_only: bool=False) -> Series:
    axis = self._get_axis_number(axis)
    if self.empty and len(self.axes[axis]):
        axis_dtype = self.axes[axis].dtype
        return self._constructor_sliced(dtype=axis_dtype)
    if numeric_only:
        data = self._get_numeric_data()
    else:
        data = self
    res = data._reduce(nanops.nanargmax, 'argmax', axis=axis, skipna=skipna, numeric_only=False)
    indices = res._values
    if (indices == -1).any():
        if skipna:
            msg = 'Encountered all NA values'
        else:
            msg = 'Encountered an NA values with skipna=False'
        raise ValueError(msg)
    index = data._get_axis(axis)
    result = index.take(indices, allow_fill=True)._values
    final_result = data._constructor_sliced(result, index=data._get_agg_axis(axis))
    return final_result.__finalize__(self, method='idxmax')

def eliminate_quotes(s):
    d = {}

    def repl(m):
        kind, value = m.groups()[:2]
        if kind:
            kind = kind[:-1]
        p = {"'": 'SINGLE', '"': 'DOUBLE'}[value[0]]
        k = f'{kind}@__f2py_QUOTES_{p}_{COUNTER.__next__()}@'
        d[k] = value
        return k
    new_s = re.sub('({kind}_|)({single_quoted}|{double_quoted})'.format(kind='\\w[\\w\\d_]*', single_quoted="('([^'\\\\]|(\\\\.))*')", double_quoted='("([^"\\\\]|(\\\\.))*")'), repl, s)
    assert '"' not in new_s
    assert "'" not in new_s
    return (new_s, d)

def legder(c, m=1, scl=1, axis=0):
    c = np.array(c, ndmin=1, copy=True)
    if c.dtype.char in '?bBhHiIlLqQpP':
        c = c.astype(np.double)
    cnt = pu._as_int(m, 'the order of derivation')
    iaxis = pu._as_int(axis, 'the axis')
    if cnt < 0:
        raise ValueError('The order of derivation must be non-negative')
    iaxis = np.lib.array_utils.normalize_axis_index(iaxis, c.ndim)
    if cnt == 0:
        return c
    c = np.moveaxis(c, iaxis, 0)
    n = len(c)
    if cnt >= n:
        c = c[:1] * 0
    else:
        for i in range(cnt):
            n = n - 1
            c *= scl
            der = np.empty((n,) + c.shape[1:], dtype=c.dtype)
            for j in range(n, 2, -1):
                der[j - 1] = (2 * j - 1) * c[j]
                c[j - 2] += c[j]
            if n > 1:
                der[1] = 3 * c[2]
            der[0] = c[1]
            c = der
    c = np.moveaxis(c, 0, iaxis)
    return c

def get_callable(obj_as_str: str) -> object:
    components = obj_as_str.split('.')
    attrs = []
    while components:
        try:
            obj = importlib.import_module('.'.join(components))
        except ImportError:
            attrs.insert(0, components.pop())
        else:
            break
    if not obj:
        raise ImportError(f'Could not import "{obj_as_str}"')
    for attr in attrs:
        obj = getattr(obj, attr)
    return obj

