def center(a, width, item=' '):
    width = np.asanyarray(width)
    if not np.issubdtype(width.dtype, np.integer):
        raise TypeError(f"unsupported type {width.dtype} for operand 'width'")
    a = np.asanyarray(a)
    item = np.asanyarray(item)
    if np.any(str_len(item) != 1):
        raise TypeError('The fill character must be exactly one character long')
    if np.result_type(a, item).char == 'T':
        return _center(a, width, item)
    item = item.astype(a.dtype, copy=False)
    width = np.maximum(str_len(a), width)
    out_dtype = f'{a.dtype.char}{width.max()}'
    shape = np.broadcast_shapes(a.shape, width.shape, item.shape)
    out = np.empty_like(a, shape=shape, dtype=out_dtype)
    return _center(a, width, item, out=out)

