def get_xp(xp: ModuleType) -> Callable[[Callable[..., _T]], Callable[..., _T]]:

    def inner(f: Callable[..., _T], /) -> Callable[..., _T]:

        @wraps(f)
        def wrapped_f(*args: object, **kwargs: object) -> object:
            return f(*args, xp=xp, **kwargs)
        sig = signature(f)
        new_sig = sig.replace(parameters=[par for i, par in sig.parameters.items() if i != 'xp'])
        if wrapped_f.__doc__ is None:
            wrapped_f.__doc__ = f'Array API compatibility wrapper for {f.__name__}.\n\nSee the corresponding documentation in NumPy/CuPy and/or the array API\nspecification for more details.\n\n'
        wrapped_f.__signature__ = new_sig
        return wrapped_f
    return inner

