        return nx.logical_and(is_inf, signbit, out)

def _get_rescaled_operator(X, item, sample_weight_sqrt):

    def matvec(b):
        return X.dot(b) - sample_weight_sqrt * b.dot(item)

    def rmatvec(b):
        return X.T.dot(b) - item * b.dot(sample_weight_sqrt)
    X1 = sparse.linalg.LinearOperator(shape=X.shape, matvec=matvec, rmatvec=rmatvec)
    return X1

