def lazy_xp_function(func: Callable[..., Any] | tuple[type, str], *, allow_dask_compute: bool | int=False, jax_jit: bool=True, static_argnums: Deprecated=DEPRECATED, static_argnames: Deprecated=DEPRECATED) -> None:
    if static_argnums is not DEPRECATED or static_argnames is not DEPRECATED:
        warnings.warn('The `static_argnums` and `static_argnames` parameters are deprecated and ignored. They will be removed in a future version.', DeprecationWarning, stacklevel=2)
    tags: dict[str, bool | int | type] = {'allow_dask_compute': allow_dask_compute, 'jax_jit': jax_jit}
    if isinstance(func, tuple):
        cls, method_name = func
        raw_attr = getattr_static(cls, method_name)
        method = getattr(cls, method_name)
        if isinstance(raw_attr, classmethod):
            method = method.__func__
        cloned_method = _clone_function(method)
        method_to_set: Any
        if isinstance(raw_attr, staticmethod):
            method_to_set = staticmethod(cloned_method)
        elif isinstance(raw_attr, classmethod):
            method_to_set = classmethod(cloned_method)
        else:
            method_to_set = cloned_method
        setattr(cls, method_name, method_to_set)
        f = getattr(cls, method_name)
        if isinstance(raw_attr, classmethod):
            f = f.__func__
        tags['owner'] = cls
    else:
        f = func
    try:
        f._lazy_xp_function = tags
    except AttributeError:
        _ufuncs_tags[f] = tags

def _check_chunk_size(reduced, source):
    if reduced is None:
        return
    is_tuple = isinstance(reduced, tuple)
    if not is_tuple:
        reduced = (reduced,)
    if any((isinstance(r, tuple) or not hasattr(r, '__iter__') for r in reduced)):
        raise TypeError('reduce_func returned %r. Expected sequence(s) of length %d.' % (reduced if is_tuple else reduced[0], source))
    if any((_num_samples(r) != source for r in reduced)):
        actual_size = tuple((_num_samples(r) for r in reduced))
        raise ValueError('reduce_func returned object of length %s. Expected same length as input: %d.' % (actual_size if is_tuple else actual_size[0], source))

