@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    names, all_estimators = self._validate_estimators()
    self._validate_final_estimator()
    stack_method = [self.stack_method] * len(all_estimators)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        sw = {'sample_weight': fit_params['sample_weight']} if 'sample_weight' in fit_params else {}
        routed_params = _manual_routing({name: {'fit': sw} for name in names})
    if self.cv == 'prefit':
        self.estimators_ = []
        for estimator in all_estimators:
            if estimator != 'drop':
                check_is_fitted(estimator)
                self.estimators_.append(estimator)
    else:
        self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_single_estimator)(clone(est), X, y, routed_params[name]['fit']) for name, est in zip(names, all_estimators) if est != 'drop'))
    self.named_estimators_ = Bunch()
    est_fitted_idx = 0
    for name_est, org_est in zip(names, all_estimators):
        if org_est != 'drop':
            current_estimator = self.estimators_[est_fitted_idx]
            self.named_estimators_[name_est] = current_estimator
            est_fitted_idx += 1
            if hasattr(current_estimator, 'feature_names_in_'):
                self.feature_names_in_ = current_estimator.feature_names_in_
        else:
            self.named_estimators_[name_est] = 'drop'
    self.stack_method_ = [self._method_name(name, est, meth) for name, est, meth in zip(names, all_estimators, stack_method)]
    if self.cv == 'prefit':
        predictions = [getattr(estimator, predict_method)(X) for estimator, predict_method in zip(all_estimators, self.stack_method_) if estimator != 'drop']
    else:
        cv = check_cv(self.cv, y=y, classifier=is_classifier(self))
        if hasattr(cv, 'random_state') and cv.random_state is None:
            cv.random_state = np.random.RandomState()
        predictions = Parallel(n_jobs=self.n_jobs)((delayed(cross_val_predict)(clone(est), X, y, cv=deepcopy(cv), method=meth, n_jobs=self.n_jobs, params=routed_params[name]['fit'], verbose=self.verbose) for name, est, meth in zip(names, all_estimators, self.stack_method_) if est != 'drop'))
    self.stack_method_ = [meth for meth, est in zip(self.stack_method_, all_estimators) if est != 'drop']
    X_meta = self._concatenate_predictions(X, predictions)
    _fit_single_estimator(self.final_estimator_, X_meta, y, fit_params=fit_params)
    return self

def get_namespace_and_device(*array_list, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT, xp=None):
