def read(self, nrows: int | None=None) -> pd.DataFrame:
    if nrows is None:
        nrows = self.nobs
    read_lines = min(nrows, self.nobs - self._lines_read)
    read_len = read_lines * self.record_length
    if read_len <= 0:
        self.close()
        raise StopIteration
    raw = self.filepath_or_buffer.read(read_len)
    data = np.frombuffer(raw, dtype=self._dtype, count=read_lines)
    df_data = {}
    for j, x in enumerate(self.columns):
        vec = data['s' + str(j)]
        ntype = self.fields[j]['ntype']
        if ntype == 'numeric':
            vec = _handle_truncated_float_vec(vec, self.fields[j]['field_length'])
            miss = self._missing_double(vec)
            v = _parse_float_vec(vec)
            v[miss] = np.nan
        elif self.fields[j]['ntype'] == 'char':
            v = [y.rstrip() for y in vec]
            if self._encoding is not None:
                v = [y.decode(self._encoding) for y in v]
        df_data.update({x: v})
    df = pd.DataFrame(df_data)
    if self._index is None:
        df.index = pd.Index(range(self._lines_read, self._lines_read + read_lines))
    else:
        df = df.set_index(self._index)
    self._lines_read += read_lines
    return df

def _write_estimator_html(out, estimator, estimator_label, estimator_label_details, is_fitted_css_class, is_fitted_icon='', first_call=False, param_prefix=''):
    from sklearn.compose import ColumnTransformer
    if first_call:
        est_block = _get_visual_block(estimator)
    else:
        is_fitted_icon = ''
        with config_context(print_changed_only=True):
            est_block = _get_visual_block(estimator)
    if hasattr(estimator, '_get_doc_link'):
        doc_link = estimator._get_doc_link()
    else:
        doc_link = ''
    has_feature_names_out = hasattr(estimator, 'get_feature_names_out')
    is_not_pipeline_step = not hasattr(estimator, 'steps')
    if est_block.kind in ('serial', 'parallel'):
        dashed_wrapped = first_call or est_block.dash_wrapped
        dash_cls = ' sk-dashed-wrapped' if dashed_wrapped else ''
        out.write(f'<div class="sk-item{dash_cls}">')
        if estimator_label:
            if hasattr(estimator, 'get_params') and hasattr(estimator, '_get_params_html'):
                params = estimator._get_params_html(False, doc_link)._repr_html_inner()
            else:
                params = ''
            if hasattr(estimator, '_get_fitted_attr_html') and is_fitted_css_class == 'fitted':
                fitted_attrs = estimator._get_fitted_attr_html(doc_link)
                attrs = fitted_attrs._repr_html_inner() if len(fitted_attrs) > 0 else ''
            else:
                attrs = ''
            _write_label_html(out, params, attrs, estimator_label, estimator_label_details, doc_link=doc_link, features=None, is_fitted_css_class=is_fitted_css_class, is_fitted_icon=is_fitted_icon, param_prefix=param_prefix)
        kind = est_block.kind
        out.write(f'<div class="sk-{kind}">')
        est_infos = zip(est_block.estimators, est_block.names, est_block.name_details)
        for est, name, name_details in est_infos:
            if param_prefix and hasattr(name, 'split'):
                new_prefix = f"{param_prefix}{name.split(':')[0]}__"
            elif hasattr(name, 'split'):
                new_prefix = f"{name.split(':')[0]}__" if name else ''
            else:
                new_prefix = param_prefix
            if kind == 'serial':
                _write_estimator_html(out, est, name, name_details, is_fitted_css_class=is_fitted_css_class, param_prefix=new_prefix)
            else:
                out.write('<div class="sk-parallel-item">')
                serial_block = _VisualBlock('serial', [est], dash_wrapped=False)
                _write_estimator_html(out, serial_block, name, name_details, is_fitted_css_class=is_fitted_css_class, param_prefix=new_prefix)
                out.write('</div>')
        out.write('</div>')
        is_column_transformer = isinstance(estimator, ColumnTransformer)
        has_single_estimator = len(est_block.estimators) == 1
        if is_fitted_css_class and has_feature_names_out and is_not_pipeline_step and (not (is_column_transformer and has_single_estimator)):
            try:
                output_features = estimator.get_feature_names_out()
            except Exception:
                output_features = None
            if output_features is not None:
                features_div = _features_html(output_features, is_fitted_css_class)
                total_output_features_item = f"<div class='total_features'>{features_div}</div>"
                out.write(total_output_features_item)
        out.write('</div>')
    elif est_block.kind == 'single':
        if has_feature_names_out and is_not_pipeline_step and is_fitted_css_class:
            try:
                output_features = estimator.get_feature_names_out()
            except Exception:
                output_features = None
        else:
            output_features = ''
        if est_block.names == 'NoneType(...)':
            est_block.names = 'passthrough'
        if hasattr(estimator, '_get_params_html') and (not est_block.names == 'passthrough'):
            params = estimator._get_params_html(doc_link=doc_link)._repr_html_inner()
        else:
            params = ''
        if hasattr(estimator, '_get_fitted_attr_html') and (not est_block.names == 'passthrough') and (is_fitted_css_class == 'fitted'):
            fitted_attrs = estimator._get_fitted_attr_html(doc_link)
            attrs = fitted_attrs._repr_html_inner() if len(fitted_attrs) > 0 else ''
        else:
            attrs = ''
        _write_label_html(out, params, attrs, est_block.names, est_block.name_details, est_block.name_caption, est_block.doc_link_label, outer_class='sk-item', inner_class='sk-estimator', checked=first_call, doc_link=doc_link, features=output_features, is_fitted_css_class=is_fitted_css_class, is_fitted_icon=is_fitted_icon, param_prefix=param_prefix)

def lagval(x, c, tensor=True):
    c = np.array(c, ndmin=1, copy=None)
    if c.dtype.char in '?bBhHiIlLqQpP':
        c = c.astype(np.double)
    if isinstance(x, (tuple, list)):
        x = np.asarray(x)
    if isinstance(x, np.ndarray) and tensor:
        c = c.reshape(c.shape + (1,) * x.ndim)
    if len(c) == 1:
        c0 = c[0]
        c1 = 0
    elif len(c) == 2:
        c0 = c[0]
        c1 = c[1]
    else:
        nd = len(c)
        c0 = c[-2]
        c1 = c[-1]
        for i in range(3, len(c) + 1):
            tmp = c0
            nd = nd - 1
            c0 = c[-i] - c1 * (nd - 1) / nd
            c1 = tmp + c1 * (2 * nd - 1 - x) / nd
    return c0 + c1 * (1 - x)

