def device(x: _ArrayApiObj, /) -> Device:
    if is_numpy_array(x):
        return 'cpu'
    elif is_dask_array(x):
        if is_numpy_array(x._meta):
            return 'cpu'
        return _DASK_DEVICE
    elif is_jax_array(x):
        x_device = getattr(x, 'device', None)
        if inspect.ismethod(x_device):
            return x_device()
        else:
            return x_device
    elif is_pydata_sparse_array(x):
        x_device = getattr(x, 'device', None)
        if x_device is not None:
