def loss_gradient(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, index=None):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    if index is None:
        weights, intercept, index = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    loss, grad_pointwise = self.base_loss.loss_gradient(y_true=y, raw_prediction=index, sample_weight=sample_weight, n_threads=n_threads)
    xp, _ = get_namespace(X, y, sample_weight)
    sw_sum = n_samples if sample_weight is None else xp.sum(sample_weight)
    loss = float(xp.sum(loss) / sw_sum)
    loss += self.l2_penalty(weights, l2_reg_strength)
    grad_pointwise /= sw_sum
    if not self.base_loss.is_multiclass:
        grad = np.empty_like(coef, dtype=weights.dtype)
        X_grad = X.T @ grad_pointwise
        grad[:n_features] = move_to(X_grad, xp=np, device='cpu') + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = xp.sum(grad_pointwise)
    else:
        grad = np.empty((n_classes, n_dof), dtype=weights.dtype, order='F')
        grad_X = grad_pointwise.T @ X
        grad[:, :n_features] = move_to(grad_X, xp=np, device='cpu') + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = move_to(xp.sum(grad_pointwise, axis=0), xp=np, device='cpu')
        if coef.ndim == 1:
            grad = grad.ravel(order='F')
    return (loss, grad)

@bottleneck_switch()
def nanmedian(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, mask=None) -> float | np.ndarray:
    using_nan_sentinel = values.dtype.kind == 'f' and mask is None

    def get_median(x: np.ndarray, _mask=None):
        if _mask is None:
            _mask = notna(x)
        else:
            _mask = ~_mask
        if not skipna and (not _mask.all()):
            return np.nan
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
            warnings.filterwarnings('ignore', 'Mean of empty slice', RuntimeWarning)
            res = np.nanmedian(x[_mask])
        return res
    dtype = values.dtype
    values, mask = _get_values(values, skipna, mask=mask, fill_value=None)
    if values.dtype.kind != 'f':
        if values.dtype == object:
            inferred = lib.infer_dtype(values)
            if inferred in ['string', 'mixed']:
                raise TypeError(f'Cannot convert {values} to numeric')
        try:
            values = values.astype('f8')
        except ValueError as err:
            raise TypeError(str(err)) from err
    if not using_nan_sentinel and mask is not None:
        if not values.flags.writeable:
            values = values.copy()
        values[mask] = np.nan
    notempty = values.size
    res: float | np.ndarray
    if values.ndim > 1 and axis is not None:
        if notempty:
            if not skipna:
                res = np.apply_along_axis(get_median, axis, values)
            else:
                with warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
                    if values.shape[1] == 1 and axis == 0 or (values.shape[0] == 1 and axis == 1):
                        res = np.nanmedian(np.squeeze(values), keepdims=True)
                    else:
                        res = np.nanmedian(values, axis=axis)
        else:
            res = _get_empty_reduction_result(values.shape, axis)
    else:
        res = get_median(values, mask) if notempty else np.nan
    return _wrap_results(res, dtype)

def _predict_proba_lr(self, X):
    xp, _ = get_namespace(X)
    prob = self.decision_function(X)
    prob = _expit(prob, out=prob, xp=xp)
    if prob.ndim == 1:
        return xp.stack([1 - prob, prob], axis=1)
    else:
        prob_sum = prob.sum(axis=1)
        all_zero = prob_sum == 0
        if xp.any(all_zero):
            prob[all_zero, :] = 1
            prob_sum[all_zero] = prob.shape[1]
        prob /= xp.reshape(prob_sum, (prob.shape[0], -1))
        return prob

