def create_index(self, columns=None, optlevel=None, kind: str | None=None) -> None:
    if not self.infer_axes():
        return
    if columns is False:
        return
    if columns is None or columns is True:
        columns = [a.cname for a in self.axes if a.is_data_indexable]
    if not isinstance(columns, (tuple, list)):
        columns = [columns]
    kw = {}
    if optlevel is not None:
        kw['optlevel'] = optlevel
    if kind is not None:
        kw['kind'] = kind
    table = self.table
    for c in columns:
        v = getattr(table.cols, c, None)
        if v is not None:
            if v.is_indexed:
                index = v.index
                cur_optlevel = index.optlevel
                cur_kind = index.kind
                if kind is not None and cur_kind != kind:
                    v.remove_index()
                else:
                    kw['kind'] = cur_kind
                if optlevel is not None and cur_optlevel != optlevel:
                    v.remove_index()
                else:
                    kw['optlevel'] = cur_optlevel
            if not v.is_indexed:
                if v.type.startswith('complex'):
                    raise TypeError('Columns containing complex values can be stored but cannot be indexed when using table format. Either use fixed format, set index=False, or do not include the columns containing complex values to data_columns when initializing the table.')
                v.create_index(**kw)
        elif c in self.non_index_axes[0][1]:
            raise AttributeError(f'column {c} is not a data_column.\nIn order to read column {c} you must reload the dataframe \ninto HDFStore and include {c} with the data_columns argument.')

def transform(self, X):
    check_is_fitted(self)
    X, Xt, mask_missing_values, complete_mask = self._initial_imputation(X, in_fit=False)
    X_indicator = super()._transform_indicator(complete_mask)
    if self.n_iter_ == 0 or np.all(mask_missing_values):
        return super()._concatenate_indicator(Xt, X_indicator)
    imputations_per_round = len(self.imputation_sequence_) // self.n_iter_
    i_rnd = 0
    if self.verbose > 0:
        print('[IterativeImputer] Completing matrix with shape %s' % (X.shape,))
    start_t = time()
    for it, estimator_triplet in enumerate(self.imputation_sequence_):
        Xt, _ = self._impute_one_feature(Xt, mask_missing_values, estimator_triplet.feat_idx, estimator_triplet.neighbor_feat_idx, estimator=estimator_triplet.estimator, fit_mode=False)
        if not (it + 1) % imputations_per_round:
            if self.verbose > 1:
                print('[IterativeImputer] Ending imputation round %d/%d, elapsed time %0.2f' % (i_rnd + 1, self.n_iter_, time() - start_t))
            i_rnd += 1
    _assign_where(Xt, X, cond=~mask_missing_values)
    return super()._concatenate_indicator(Xt, X_indicator)

