def param_parse(d, params):
    if '(' in d:
        dname = d[:d.find('(')]
        ddims = d[d.find('(') + 1:d.rfind(')')]
        index = int(param_parse(ddims, params))
        return d
    elif d in params:
        return str(params[d])
    else:
        for p in params:
            re_1 = re.compile('(?P<before>.*?)\\b' + p + '\\b(?P<after>.*)', re.I)
            m = re_1.match(d)
            while m:
                d = m.group('before') + str(params[p]) + m.group('after')
                m = re_1.match(d)
        return d

@classmethod
def _get_atom(cls, values: ArrayLike) -> Col:
    dtype = values.dtype
    if isinstance(dtype, ExtensionDtype) and (not isinstance(dtype, (CategoricalDtype, DatetimeTZDtype, PeriodDtype))):
        raise NotImplementedError(f'Cannot store a column with dtype {dtype} in an HDF5 file. HDFStore supports NumPy dtypes, datetime64 with timezone, categorical, and string extension types.')
    itemsize = dtype.itemsize
    shape = values.shape
    if values.ndim == 1:
        shape = (1, values.size)
    if isinstance(values, Categorical):
        codes = values.codes
        atom = cls.get_atom_data(shape, kind=codes.dtype.name)
    elif lib.is_np_dtype(dtype, 'M') or isinstance(dtype, DatetimeTZDtype):
        atom = cls.get_atom_datetime64(shape)
    elif lib.is_np_dtype(dtype, 'm'):
        atom = cls.get_atom_timedelta64(shape)
    elif is_complex_dtype(dtype):
        atom = _tables().ComplexCol(itemsize=itemsize, shape=shape[0])
    elif is_string_dtype(dtype):
        atom = cls.get_atom_string(shape, itemsize)
    else:
        atom = cls.get_atom_data(shape, kind=dtype.name)
    return atom

