        if attr[0] in attribute_names:
            raise BadObject('Trying to use attribute name "%s" for the second time.' % str(attr[0]))
        else:
            attribute_names.add(attr[0])
        yield self._encode_attribute(attr[0], attr[1])
    yield ''
    attributes = obj['attributes']
    yield _TK_DATA
    if 'data' in obj:
        data = _get_data_object_for_encoding(obj.get('data'))
        yield from data.encode_data(obj.get('data'), attributes)
    yield ''

def _get_n_samples_bootstrap(n_samples, max_samples, sample_weight):
    if max_samples is None:
        return n_samples
    elif isinstance(max_samples, Integral):
        return max_samples
    if sample_weight is None:
        weighted_n_samples = n_samples
        weighted_n_samples_msg = f'the number of samples is {weighted_n_samples} '
    else:
        weighted_n_samples = sample_weight.sum()
        weighted_n_samples_msg = f'the total sum of sample weights is {weighted_n_samples} '
    n_samples_bootstrap = max(int(max_samples * weighted_n_samples), 1)
    if n_samples_bootstrap < max(10, n_samples ** (1 / 3)):
        warn(f'Using the fractional value max_samples={max_samples!r} when {weighted_n_samples_msg}results in a low number ({n_samples_bootstrap}) of bootstrap samples. We recommend passing `max_samples` as an integer instead.')
    return n_samples_bootstrap

def take(self, indices: TakeIndexer, allow_fill: bool=False, fill_value: Any=None) -> ArrowExtensionArray:
    indices_array = np.asanyarray(indices)
    if len(self._pa_array) == 0 and (indices_array >= 0).any():
        raise IndexError('cannot do a non-empty take')
    if indices_array.size > 0 and indices_array.max() >= len(self._pa_array):
        raise IndexError("out of bounds value in 'indices'.")
    if allow_fill:
        fill_mask = indices_array < 0
        if fill_mask.any():
            validate_indices(indices_array, len(self._pa_array))
            indices_array = pa.array(indices_array, mask=fill_mask)
            result = self._pa_array.take(indices_array)
            if isna(fill_value):
                return self._from_pyarrow_array(result)
            result = self._from_pyarrow_array(result)
            result[fill_mask] = fill_value
            return result
        else:
            return self._from_pyarrow_array(self._pa_array.take(indices))
    else:
        if (indices_array < 0).any():
            indices_array = np.copy(indices_array)
            indices_array[indices_array < 0] += len(self._pa_array)
        return self._from_pyarrow_array(self._pa_array.take(indices_array))

def equals(self, item: object) -> bool:
    if self.is_(item):
        return True
    if not isinstance(item, Index):
        return False
    if len(self) != len(item):
        return False
    if not isinstance(item, MultiIndex):
        if not self._should_compare(item):
            return False
        return array_equivalent(self._values, item._values)
    if self.nlevels != item.nlevels:
        return False
    for i in range(self.nlevels):
        self_codes = self.codes[i]
        other_codes = item.codes[i]
        self_mask = self_codes == -1
        other_mask = other_codes == -1
        if not lib.array_equivalent_bytes(self_mask, other_mask):
            return False
        self_level = self.levels[i]
        other_level = item.levels[i]
        new_codes = recode_for_categories(other_codes, other_level, self_level, copy=False)
        if not array_equivalent(self_codes, new_codes):
            return False
        if not self_level[:0].equals(other_level[:0]):
            return False
    return True

