def to_sql(self, frame, name: str, if_exists: Literal['fail', 'replace', 'append', 'delete_rows']='fail', index: bool=True, index_label=None, schema: str | None=None, chunksize: int | None=None, dtype: DtypeArg | None=None, method: Literal['multi'] | Callable | None=None, engine: str='auto', **engine_kwargs) -> int | None:
    pa = import_optional_dependency('pyarrow')
    from adbc_driver_manager import Error
    if index_label:
        raise NotImplementedError("'index_label' is not implemented for ADBC drivers")
    if chunksize:
        raise NotImplementedError("'chunksize' is not implemented for ADBC drivers")
    if dtype:
        raise NotImplementedError("'dtype' is not implemented for ADBC drivers")
    if method:
        raise NotImplementedError("'method' is not implemented for ADBC drivers")
    if engine != 'auto':
        raise NotImplementedError("engine != 'auto' not implemented for ADBC drivers")
    quoted_name = _quote_identifier(name)
    if schema:
        quoted_schema = _quote_identifier(schema)
        quoted_table_name = f'{quoted_schema}.{quoted_name}'
    else:
        quoted_table_name = quoted_name
    mode = 'create'
    if self.has_table(name, schema):
        if if_exists == 'fail':
            raise ValueError(f"Table '{name}' already exists.")
        elif if_exists == 'replace':
            sql_statement = f'DROP TABLE {quoted_table_name}'
            self.execute(sql_statement).close()
        elif if_exists == 'append':
            mode = 'append'
        elif if_exists == 'delete_rows':
            mode = 'append'
            self.delete_rows(name, schema)
    try:
        tbl = pa.Table.from_pandas(frame, preserve_index=index)
    except pa.ArrowNotImplementedError as exc:
        raise ValueError('datatypes not supported') from exc
    with self.con.cursor() as cur:
        try:
            total_inserted = cur.adbc_ingest(table_name=name, data=tbl, mode=mode, db_schema_name=schema)
        except Error as exc:
            raise DatabaseError(f'Failed to insert records on table={name} with mode={mode!r}') from exc
    self.con.commit()
    return total_inserted

