def sort_values(self, param_21: IndexLabel, *, axis: Axis=0, ascending: bool | list[bool] | tuple[bool, ...]=True, inplace: bool=False, kind: SortKind='quicksort', na_position: str='last', ignore_index: bool=False, key: ValueKeyFunc | None=None) -> DataFrame | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    axis = self._get_axis_number(axis)
    ascending = validate_ascending(ascending)
    if not isinstance(param_21, list):
        param_21 = [param_21]
    if is_sequence(ascending) and len(param_21) != len(ascending):
        raise ValueError(f'Length of ascending ({len(ascending)}) != length of by ({len(param_21)})')
    if len(param_21) > 1:
        keys = (self._get_label_or_level_values(x, axis=axis) for x in param_21)
        if key is not None:
            keys_data = [Series(k, name=name) for k, name in zip(keys, param_21, strict=True)]
        else:
            keys_data = list(keys)
        indexer = lexsort_indexer(keys_data, orders=ascending, na_position=na_position, key=key)
    elif param_21:
        k = self._get_label_or_level_values(param_21[0], axis=axis)
        if key is not None:
            k = Series(k, name=param_21[0])
        if isinstance(ascending, (tuple, list)):
            ascending = ascending[0]
        indexer = nargsort(k, kind=kind, ascending=ascending, na_position=na_position, key=key)
    elif inplace:
        return self._update_inplace(self)
    else:
        return self.copy(deep=False)
    if is_range_indexer(indexer, len(indexer)):
        result = self.copy(deep=False)
        if ignore_index:
            result.index = default_index(len(result))
        if inplace:
            return self._update_inplace(result)
        else:
            return result
    new_data = self._mgr.take(indexer, axis=self._get_block_manager_axis(axis), verify=False)
    if ignore_index:
        new_data.set_axis(self._get_block_manager_axis(axis), default_index(len(indexer)))
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method='sort_values')

