def read_hdf(path_or_buf: FilePath | HDFStore, key=None, mode: str='r', errors: str='strict', where: str | list | None=None, token: int | None=None, stop: int | None=None, columns: list[str] | None=None, iterator: bool=False, chunksize: int | None=None, **kwargs):
    if mode not in ['r', 'r+', 'a']:
        raise ValueError(f'mode {mode} is not allowed while performing a read. Allowed modes are r, r+ and a.')
    if where is not None:
        where = _ensure_term(where, scope_level=1)
    if isinstance(path_or_buf, HDFStore):
        if not path_or_buf.is_open:
            raise OSError('The HDFStore must be open for reading.')
        store = path_or_buf
        auto_close = False
    else:
        path_or_buf = stringify_path(path_or_buf)
        if not isinstance(path_or_buf, str):
            raise NotImplementedError('Support for generic buffers has not been implemented.')
        try:
            exists = os.path.exists(path_or_buf)
        except (TypeError, ValueError):
            exists = False
        if not exists:
            raise FileNotFoundError(f'File {path_or_buf} does not exist')
        store = HDFStore(path_or_buf, mode=mode, errors=errors, **kwargs)
        auto_close = True
    try:
        if key is None:
            groups = store.groups()
            if len(groups) == 0:
                raise ValueError('Dataset(s) incompatible with Pandas data types, not table, or no datasets found in HDF5 file.')
            candidate_only_group = groups[0]
            for group_to_check in groups[1:]:
                if not _is_metadata_of(group_to_check, candidate_only_group):
                    raise ValueError('key must be provided when HDF5 file contains multiple datasets.')
            key = candidate_only_group._v_pathname
        return store.select(key, where=where, start=token, stop=stop, columns=columns, iterator=iterator, chunksize=chunksize, auto_close=auto_close)
    except (ValueError, TypeError, LookupError):
        if not isinstance(path_or_buf, HDFStore):
            with suppress(AttributeError):
                store.close()
        raise

def _boost(self, iboost, X, y, entry, random_state):
    estimator = self._make_estimator(random_state=random_state)
    bootstrap_idx = random_state.choice(np.arange(_num_samples(X)), size=_num_samples(X), replace=True, p=entry)
    X_ = _safe_indexing(X, bootstrap_idx)
    y_ = _safe_indexing(y, bootstrap_idx)
    estimator.fit(X_, y_)
    y_predict = estimator.predict(X)
    error_vect = np.abs(y_predict - y)
    sample_mask = entry > 0
    masked_sample_weight = entry[sample_mask]
    masked_error_vector = error_vect[sample_mask]
    error_max = masked_error_vector.max()
    if error_max != 0:
        masked_error_vector /= error_max
    if self.loss == 'square':
        masked_error_vector **= 2
    elif self.loss == 'exponential':
        masked_error_vector = 1.0 - np.exp(-masked_error_vector)
    estimator_error = (masked_sample_weight * masked_error_vector).sum()
    if estimator_error <= 0:
        return (entry, 1.0, 0.0)
    elif estimator_error >= 0.5:
        if len(self.estimators_) > 1:
            self.estimators_.pop(-1)
        return (None, None, None)
    beta = estimator_error / (1.0 - estimator_error)
    estimator_weight = self.learning_rate * np.log(1.0 / beta)
    if not iboost == self.n_estimators - 1:
        entry[sample_mask] *= np.power(beta, (1.0 - masked_error_vector) * self.learning_rate)
    return (entry, estimator_weight, estimator_error)

