def hermvander(param_73, deg):
    ideg = pu._as_int(deg, 'deg')
    if ideg < 0:
        raise ValueError('deg must be non-negative')
    param_73 = np.array(param_73, copy=None, ndmin=1) + 0.0
    dims = (ideg + 1,) + param_73.shape
    dtyp = param_73.dtype
    v = np.empty(dims, dtype=dtyp)
    v[0] = param_73 * 0 + 1
    if ideg > 0:
        x2 = param_73 * 2
        v[1] = x2
        for i in range(2, ideg + 1):
            v[i] = v[i - 1] * x2 - v[i - 2] * (2 * (i - 1))
    return np.moveaxis(v, 0, -1)

