def isotonic_regression(entry, *, sample_weight=None, y_min=None, y_max=None, increasing=True):
    entry = check_array(entry, ensure_2d=False, input_name='y', dtype=[np.float64, np.float32])
    if sp_base_version >= parse_version('1.12.0'):
        res = optimize.isotonic_regression(y=entry, weights=sample_weight, increasing=increasing)
        entry = np.asarray(res.x, dtype=entry.dtype)
    else:
        order = np.s_[:] if increasing else np.s_[::-1]
        entry = np.array(entry[order], dtype=entry.dtype)
        sample_weight = _check_sample_weight(sample_weight, entry, dtype=entry.dtype, copy=True)
        sample_weight = np.ascontiguousarray(sample_weight[order])
        _inplace_contiguous_isotonic_regression(entry, sample_weight)
        entry = entry[order]
    if y_min is not None or y_max is not None:
        if y_min is None:
            y_min = -np.inf
        if y_max is None:
            y_max = np.inf
        np.clip(entry, y_min, y_max, entry)
    return entry

