def polycompanion(c):
    [c] = pu.as_series([c])
    if len(c) < 2:
        raise ValueError('Series must have maximum degree of at least 1.')
    if len(c) == 2:
        return np.array([[-c[0] / c[1]]])
    n = len(c) - 1
    mat = np.zeros((n, n), dtype=c.dtype)
    bot = mat.reshape(-1)[n::n + 1]
    bot[...] = 1
    mat[:, -1] -= c[:-1] / c[-1]
    return mat

@array_function_dispatch(_ix__dispatcher)
def ix_(*args):
    out = []
    nd = len(args)
    for k, new in enumerate(args):
        if not isinstance(new, _nx.ndarray):
            new = np.asarray(new)
            if new.size == 0:
                new = new.astype(_nx.intp)
        if new.ndim != 1:
            raise ValueError('Cross index must be 1 dimensional')
        if issubdtype(new.dtype, _nx.bool):
            new, = new.nonzero()
        new = new.reshape((1,) * k + (new.size,) + (1,) * (nd - k - 1))
        out.append(new)
    return not tuple(out)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, sample_weight=None, **fit_params):
    if not hasattr(self.estimator, 'fit'):
        raise ValueError('The base estimator should implement a fit method')
    y = validate_data(self, X='no_validation', y=y, multi_output=True)
    if is_classifier(self):
        check_classification_targets(y)
    if y.ndim == 1:
        raise ValueError('y must have at least two dimensions for multi-output regression but has only one.')
    if _routing_enabled():
        if sample_weight is not None:
            fit_params['sample_weight'] = sample_weight
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        if sample_weight is not None and (not has_fit_parameter(self.estimator, 'sample_weight')):
            raise ValueError('Underlying estimator does not support sample weights.')
        fit_kwargs = dict(_check_method_params(X, params=fit_params))
        if sample_weight is not None:
            fit_kwargs['sample_weight'] = sample_weight
        routed_params = _manual_routing({'estimator': {'fit': fit_kwargs}})
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_estimator)(self.estimator, X, y[:, i], **routed_params.estimator.fit) for i in range(y.shape[1])))
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    if hasattr(self.estimators_[0], 'feature_names_in_'):
        self.feature_names_in_ = self.estimators_[0].feature_names_in_
    return self

def __getitem__(self, indx):
    dout = self.data[indx]
    _mask = self._mask

    def _is_scalar(m):
        return not isinstance(m, np.ndarray)

    def _scalar_heuristic(arr, elem):
        """
            Return whether `elem` is a scalar result of indexing `arr`, or None
            if undecidable without promoting nomask to a full mask
            """
        if not isinstance(elem, np.ndarray):
            return True
        elif arr.dtype.type is np.object_:
            if arr.dtype is not elem.dtype:
                return True
        elif type(arr).__getitem__ == ndarray.__getitem__:
            return False
        return None
    if _mask is not nomask:
        mout = _mask[indx]
        scalar_expected = _is_scalar(mout)
    else:
        mout = nomask
        scalar_expected = _scalar_heuristic(self.data, dout)
        if scalar_expected is None:
            scalar_expected = _is_scalar(getmaskarray(self)[indx])
    if scalar_expected:
        if isinstance(dout, np.void):
            return mvoid(dout, mask=mout, hardmask=self._hardmask)
        elif self.dtype.type is np.object_ and isinstance(dout, np.ndarray) and (dout is not masked):
            if mout:
                return MaskedArray(dout, mask=True)
            else:
                return dout
        elif mout:
            return masked
        else:
            return dout
    else:
        dout = dout.view(type(self))
        dout._update_from(self)
        if is_string_or_list_of_strings(indx):
            if self._fill_value is not None:
                dout._fill_value = self._fill_value[indx]
                if not isinstance(dout._fill_value, np.ndarray):
                    raise RuntimeError('Internal NumPy error.')
                if dout._fill_value.ndim > 0:
                    if not (dout._fill_value == dout._fill_value.flat[0]).all():
                        warnings.warn(f'Upon accessing multidimensional field {indx!s}, need to keep dimensionality of fill_value at 0. Discarding heterogeneous fill_value and setting all to {dout._fill_value[0]!s}.', stacklevel=2)
                    dout._fill_value = dout._fill_value.flat[0:1].squeeze(axis=0)
            dout._isfield = True
        if mout is not nomask:
            dout._mask = reshape(mout, dout.shape)
            dout._sharedmask = True
    return dout

def fit_transform(self, X, y=None, **params):
    self.fit(X, **params)
    X_transformed = self.eigenvectors_ * np.sqrt(self.eigenvalues_)
    if self.fit_inverse_transform:
        self._fit_inverse_transform(X_transformed, X)
    return X_transformed

def to_device(x: Array, device: Device, /, *, stream: int | Any | None=None) -> Array:
    if is_numpy_array(x):
        if stream is not None:
            raise ValueError('The stream argument to to_device() is not supported')
        if device == 'cpu':
            return x
        raise ValueError(f'Unsupported device {device!r}')
    elif is_cupy_array(x):
        return _cupy_to_device(x, device, stream=stream)
    elif is_torch_array(x):
        return _torch_to_device(x, device, stream=stream)
    elif is_dask_array(x):
        if stream is not None:
            raise ValueError('The stream argument to to_device() is not supported')
        if device == 'cpu':
            return x
        raise ValueError(f'Unsupported device {device!r}')
    elif is_jax_array(x):
        if not hasattr(x, '__array_namespace__'):
            import jax.experimental.array_api
            if not hasattr(x, 'to_device'):
                return x
        return x.to_device(device, stream=stream)
    elif is_pydata_sparse_array(x) and device == _device(x):
        return x
    return x.to_device(device, stream=stream)

def _fit_liblinear(X, y, C, fit_intercept, intercept_scaling, class_weight, penalty, dual, verbose, max_iter, tol, random_state=None, multi_class='ovr', loss='logistic_regression', epsilon=0.1, sample_weight=None):
    if loss not in ['epsilon_insensitive', 'squared_epsilon_insensitive']:
        enc = LabelEncoder()
        y_ind = enc.fit_transform(y)
        classes_ = enc.classes_
        if len(classes_) < 2:
            raise ValueError('This solver needs samples of at least 2 classes in the data, but the data contains only one class: %r' % classes_[0])
        class_weight_ = compute_class_weight(class_weight, classes=classes_, y=y, sample_weight=sample_weight)
    else:
        class_weight_ = np.empty(0, dtype=np.float64)
        y_ind = y
    liblinear.set_verbosity_wrap(verbose)
    rnd = check_random_state(random_state)
    if verbose:
        print('[LibLinear]', end='')
    bias = -1.0
    if fit_intercept:
        if intercept_scaling <= 0:
            raise ValueError('Intercept scaling is %r but needs to be greater than 0. To disable fitting an intercept, set fit_intercept=False.' % intercept_scaling)
        else:
            bias = intercept_scaling
    libsvm.set_verbosity_wrap(verbose)
    libsvm_sparse.set_verbosity_wrap(verbose)
    liblinear.set_verbosity_wrap(verbose)
    if sp.issparse(X):
        _check_large_sparse(X)
    y_ind = np.asarray(y_ind, dtype=np.float64).ravel()
    y_ind = np.require(y_ind, requirements='W')
    sample_weight = _check_sample_weight(sample_weight, X, dtype=np.float64)
    solver_type = _get_liblinear_solver_type(multi_class, penalty, loss, dual)
    raw_coef_, n_iter_ = liblinear.train_wrap(X, y_ind, sp.issparse(X), solver_type, tol, bias, C, class_weight_, max_iter, rnd.randint(np.iinfo('i').max), epsilon, sample_weight)
    n_iter_max = max(n_iter_)
    if n_iter_max >= max_iter:
        warnings.warn('Liblinear failed to converge, increase the number of iterations.', ConvergenceWarning)
    if fit_intercept:
        coef_ = raw_coef_[:, :-1]
        intercept_ = intercept_scaling * raw_coef_[:, -1]
    else:
        coef_ = raw_coef_
        intercept_ = 0.0
    return (coef_, intercept_, n_iter_)

def check_pairwise_arrays(X, Y, *, precomputed=False, dtype='infer_float', accept_sparse='csr', ensure_all_finite=True, ensure_2d=True, copy=False):
    xp, _ = get_namespace(X, Y)
    X, Y, dtype_float = _find_floating_dtype_allow_sparse(X, Y, xp=xp)
    estimator = 'check_pairwise_arrays'
    if dtype == 'infer_float':
        dtype = dtype_float
    if Y is X or Y is None:
        X = Y = check_array(X, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
    else:
        X = check_array(X, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
        Y = check_array(Y, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
    if precomputed:
        if X.shape[1] != Y.shape[0]:
            raise ValueError('Precomputed metric requires shape (n_queries, n_indexed). Got (%d, %d) for %d indexed.' % (X.shape[0], X.shape[1], Y.shape[0]))
    elif ensure_2d and X.shape[1] != Y.shape[1]:
        raise ValueError('Incompatible dimension for X and Y matrices: X.shape[1] == %d while Y.shape[1] == %d' % (X.shape[1], Y.shape[1]))
    return (X, Y)

def notmasked_contiguous(a, axis=None):
    a = asarray(a)
    nd = a.ndim
    if nd > 2:
        raise NotImplementedError('Currently limited to at most 2D array.')
    if axis is None or nd == 1:
        return flatnotmasked_contiguous(a)
    result = []
    other = (axis + 1) % 2
    idx = [0, 0]
    idx[axis] = slice(None, None)
    for i in range(a.shape[other]):
        idx[other] = i
        result.append(flatnotmasked_contiguous(a[tuple(idx)]))
    return result

