@setupmethod
def template_test(self, name: T_template_test | str | None=None) -> T_template_test | t.Callable[[T_template_test], T_template_test]:
    if callable(name):
        self.add_template_test(name)
        return name

    def decorator(f: T_template_test) -> T_template_test:
