def _perplexity_precomp_distr(self, X, doc_topic_distr=None, sub_sampling=False):
    if doc_topic_distr is None:
        doc_topic_distr = self._unnormalized_transform(X)
    else:
        n_samples, n_components = doc_topic_distr.shape
        if n_samples != X.shape[0]:
            raise ValueError('Number of samples in X and doc_topic_distr do not match.')
        if n_components != self.n_components:
            raise ValueError('Number of topics does not match.')
    current_samples = X.shape[0]
    bound = self._approx_bound(X, doc_topic_distr, sub_sampling)
    if sub_sampling:
        word_cnt = X.sum() * (float(self.total_samples) / current_samples)
    else:
        word_cnt = X.sum()
    perword_bound = bound / word_cnt
    return np.exp(-1.0 * perword_bound)

def init_gradient_and_hessian(self, n_samples, dtype=np.float64, order='F'):
    if dtype not in (np.float32, np.float64):
        raise ValueError(f"Valid options for 'dtype' are np.float32 and np.float64. Got dtype={dtype} instead.")
    if self.is_multiclass:
        shape = (n_samples, self.n_classes)
    else:
        shape = (n_samples,)
    gradient = np.empty(shape=shape, dtype=dtype, order=order)
    if self.constant_hessian:
        hessian = np.ones(shape=(1,), dtype=dtype)
    else:
        hessian = np.empty(shape=shape, dtype=dtype, order=order)
    return (gradient, hessian)

def get_values_for_csv(values: ArrayLike, *, date_format: str_t | None, na_rep: str='nan', quoting: int | None=None, float_format: str_t | None=None, decimal: str='.') -> npt.NDArray[np.object_]:
    if isinstance(values, Categorical) and values.categories.dtype.kind in 'Mm':
        values = algos.take_nd(values.categories._values, ensure_platform_int(values._codes))
    values = ensure_wrapped_if_datetimelike(values)
    if isinstance(values, (DatetimeArray, TimedeltaArray, PeriodArray)):
        if values.ndim == 1:
            result = values._format_native_types(na_rep=na_rep, date_format=date_format)
            result = result.astype(object, copy=False)
            return result
        results_converted = []
        for i in range(len(values)):
            result = values[i, :]._format_native_types(na_rep=na_rep, date_format=date_format)
            results_converted.append(result.astype(object, copy=False))
        return np.vstack(results_converted)
    elif isinstance(values.dtype, IntervalDtype):
        values = cast('IntervalArray', values)
        mask = values.isna()
        if not quoting:
            result = np.asarray(values).astype(str)
        else:
            result = np.array(values, dtype=object, copy=True)
        result[mask] = na_rep
        return result
    elif values.dtype.kind == 'f' and (not isinstance(values.dtype, SparseDtype)):
        if float_format is None and decimal == '.':
            mask = isna(values)
            if not quoting:
                if isinstance(values, ExtensionArray) and values.ndim == 2:
                    values = np.asarray(values.to_numpy(), dtype=str)
                else:
                    values = values.astype(str)
            else:
                values = np.array(values, dtype='object')
            values[mask] = na_rep
            values = values.astype(object, copy=False)
            return values
        from pandas.io.formats.format import FloatArrayFormatter
        formatter = FloatArrayFormatter(values, na_rep=na_rep, float_format=float_format, decimal=decimal, quoting=quoting, fixed_width=False)
        res = formatter.get_result_as_array()
        res = res.astype(object, copy=False)
        return res
    elif isinstance(values, ExtensionArray):
        mask = isna(values)
        new_values = np.asarray(values.astype(object))
        new_values[mask] = na_rep
        return new_values
    else:
        mask = isna(values)
        itemsize = writers.word_len(na_rep)
        if values.dtype != _dtype_obj and (not quoting) and itemsize:
            values = values.astype(str)
            if values.dtype.itemsize / np.dtype('U1').itemsize < itemsize:
                values = values.astype(f'<U{itemsize}')
        else:
            values = np.array(values, dtype='object')
        values[mask] = na_rep
        values = values.astype(object, copy=False)
        return values

@validate_params({'X': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})], 'with_mean': ['boolean'], 'with_std': ['boolean'], 'copy': ['boolean']}, prefer_skip_nested_validation=True)
def scale(X, *, axis=0, with_mean=True, with_std=True, copy=True):
    X = check_array(X, accept_sparse='csc', copy=copy, ensure_2d=False, estimator='the scale function', dtype=FLOAT_DTYPES, ensure_all_finite='allow-nan', input_name='X')
    if sparse.issparse(X):
        if with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead See docstring for motivation and alternatives.')
        if axis != 0:
            raise ValueError('Can only scale sparse matrix on axis=0,  got axis=%d' % axis)
        if with_std:
            _, var = mean_variance_axis(X, axis=0)
            var = _handle_zeros_in_scale(var, copy=False)
            inplace_column_scale(X, 1 / np.sqrt(var))
    else:
        X = np.asarray(X)
        if with_mean:
            mean_ = np.nanmean(X, axis)
        if with_std:
            scale_ = np.nanstd(X, axis)
        Xr = np.rollaxis(X, axis)
        if with_mean:
            Xr -= mean_
            mean_1 = np.nanmean(Xr, axis=0)
            if not np.allclose(mean_1, 0):
                warnings.warn('Numerical issues were encountered when centering the data and might not be solved. Dataset may contain too large values. You may need to prescale your features.')
                Xr -= mean_1
        if with_std:
            scale_ = _handle_zeros_in_scale(scale_, copy=False)
            Xr /= scale_
            if with_mean:
                mean_2 = np.nanmean(Xr, axis=0)
                if not np.allclose(mean_2, 0):
                    warnings.warn('Numerical issues were encountered when scaling the data and might not be solved. The standard deviation of the data is probably very close to 0. ')
                    Xr -= mean_2
    return None

@validate_params({'estimator': [HasMethods(['fit', 'predict'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', 'sparse matrix', None], 'groups': ['array-like', None], 'cv': ['cv_object'], 'n_jobs': [Integral, None], 'verbose': ['verbose'], 'params': [dict, None], 'pre_dispatch': [Integral, str, None], 'method': [StrOptions({'predict', 'predict_proba', 'predict_log_proba', 'decision_function'})]}, prefer_skip_nested_validation=False)
def cross_val_predict(estimator, X, y=None, *, groups=None, cv=None, n_jobs=None, verbose=0, params=None, pre_dispatch='2*n_jobs', method='predict'):
    _check_groups_routing_disabled(groups)
    X, y = indexable(X, y)
    params = {} if params is None else params
    if _routing_enabled():
        router = MetadataRouter(owner='cross_val_predict').add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('cross_val_predict.fit', 'cross_val_predict'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'splitter': {'split': {'groups': groups}}, 'estimator': {'fit': params}})
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    splits = list(cv.split(X, y, **routed_params.splitter.split))
    test_indices = np.concatenate([test for _, test in splits])
    if not _check_is_permutation(test_indices, _num_samples(X)):
        raise ValueError('cross_val_predict only works for partitions')
    encode = method in ['decision_function', 'predict_proba', 'predict_log_proba'] and y is not None
    xp, is_array_api, device_ = get_namespace_and_device(X)
    xp_y, _ = get_namespace(y)
    if encode:
        y = xp_y.asarray(y)
        if y.ndim == 1:
            le = LabelEncoder()
            y = le.fit_transform(y)
        elif y.ndim == 2:
            y_enc = np.zeros_like(y, dtype=int)
            for i_label in range(y.shape[1]):
                y_enc[:, i_label] = LabelEncoder().fit_transform(y[:, i_label])
            y = y_enc
    y = move_to(y, xp=xp, device=device_)
    parallel = Parallel(n_jobs=n_jobs, verbose=verbose, pre_dispatch=pre_dispatch)
    predictions = parallel((delayed(_fit_and_predict)(clone(estimator), X, y, train, test, routed_params.estimator.fit, method) for train, test in splits))
    inv_test_indices = np.empty(len(test_indices), dtype=int)
    inv_test_indices[test_indices] = np.arange(len(test_indices))
    if sp.issparse(predictions[0]):
        predictions = sp.vstack(predictions, format=predictions[0].format)
    elif encode and isinstance(predictions[0], list):
        n_labels = y.shape[1]
        concat_pred = []
        for i_label in range(n_labels):
            label_preds = np.concatenate([p[i_label] for p in predictions])
            concat_pred.append(label_preds)
        predictions = concat_pred
    else:
        inv_test_indices = xp.asarray(inv_test_indices, device=device(X))
        predictions = xp.concat(predictions)
    if isinstance(predictions, list):
        return [p[inv_test_indices] for p in predictions]
    elif is_array_api:
        return xp.take(predictions, inv_test_indices, axis=0)
    else:
        return predictions[inv_test_indices]

def _check_early_stopping_scorer(self, X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=None, raw_predictions_val=None):
    if is_classifier(self):
        y_small_train = self.classes_[y_small_train.astype(int)]
    self.train_score_.append(self._score_with_raw_predictions(X_binned_small_train, y_small_train, sample_weight_small_train, raw_predictions_small_train))
    if self._use_validation_data:
        if is_classifier(self):
            y_val = self.classes_[y_val.astype(int)]
        self.validation_score_.append(self._score_with_raw_predictions(X_binned_val, y_val, sample_weight_val, raw_predictions_val))
        return self._should_stop(self.validation_score_)
    else:
        return self._should_stop(self.train_score_)

