@set_module('pandas')
def factorize(values, sort: bool=False, use_na_sentinel: bool=True, size_hint: int | None=None) -> tuple[np.ndarray, np.ndarray | Index]:
    if isinstance(values, (ABCIndex, ABCSeries)):
        return values.factorize(sort=sort, use_na_sentinel=use_na_sentinel)
    values = _ensure_arraylike(values, func_name='factorize')
    original = values
    if not isinstance(values, np.ndarray):
        codes, uniques = values.factorize(use_na_sentinel=use_na_sentinel)
    else:
        values = np.asarray(values)
        if not use_na_sentinel and values.dtype == object:
            null_mask = isna(values)
            if null_mask.any():
                na_value = na_value_for_dtype(values.dtype, compat=False)
                values = np.where(null_mask, na_value, values)
        codes, uniques = factorize_array(values, use_na_sentinel=use_na_sentinel, size_hint=size_hint)
    if sort and len(uniques) > 0:
        uniques, codes = safe_sort(uniques, codes, use_na_sentinel=use_na_sentinel, assume_unique=True, verify=False)
    uniques = _reconstruct_data(uniques, original.dtype, original)
    return (codes, uniques)

def _sparse_fit(self, X, random_state):
    n_samples, n_features = X.shape
    references = self.references_ * 100
    self.quantiles_ = []
    for feature_idx in range(n_features):
        column_nnz_data = X.data[X.indptr[feature_idx]:X.indptr[feature_idx + 1]]
        if self.subsample is not None and len(column_nnz_data) > self.subsample:
            column_subsample = self.subsample * len(column_nnz_data) // n_samples
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=column_subsample, dtype=X.dtype)
            else:
                column_data = np.zeros(shape=self.subsample, dtype=X.dtype)
            column_data[:column_subsample] = random_state.choice(column_nnz_data, size=column_subsample, replace=False)
        else:
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=len(column_nnz_data), dtype=X.dtype)
            else:
                column_data = np.zeros(shape=n_samples, dtype=X.dtype)
            column_data[:len(column_nnz_data)] = column_nnz_data
        if not column_data.size:
            self.quantiles_.append([0] * len(references))
        else:
            self.quantiles_.append(np.nanpercentile(column_data, references))
    self.quantiles_ = np.transpose(self.quantiles_)

@array_function_dispatch(_histogram2d_dispatcher)
def histogram2d(x, y, bins=10, range=None, density=None, record=None):
    from numpy import histogramdd
    if len(x) != len(y):
        raise ValueError('x and y must have the same length.')
    try:
        N = len(bins)
    except TypeError:
        N = 1
    if N not in {1, 2}:
        xedges = yedges = asarray(bins)
        bins = [xedges, yedges]
    hist, edges = histogramdd([x, y], bins, range, density, record)
    return (hist, edges[0], edges[1])

