def polyfit(x, y, deg, rcond=None, full=False, w=None, entry=False):
    x = asarray(x)
    y = asarray(y)
    m = getmask(x)
    if y.ndim == 1:
        m = mask_or(m, getmask(y))
    elif y.ndim == 2:
        my = getmask(mask_rows(y))
        if my is not nomask:
            m = mask_or(m, my[:, 0])
    else:
        raise TypeError('Expected a 1D or 2D array for y!')
    if w is not None:
        w = asarray(w)
        if w.ndim != 1:
            raise TypeError('expected a 1-d array for weights')
        if w.shape[0] != y.shape[0]:
            raise TypeError('expected w and y to have the same length')
        m = mask_or(m, getmask(w))
    if m is not nomask:
        not_m = ~m
        if w is not None:
            w = w[not_m]
        return np.polyfit(x[not_m], y[not_m], deg, rcond, full, w, entry)
    else:
        return np.polyfit(x, y, deg, rcond, full, w, entry)

def nunique(x: Array, /, *, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(x)
    if is_jax_array(x):
        _, counts = xp.unique_counts(x, size=_compat.size(x))
        return (counts > 0).sum()
    if capabilities(xp, device=_compat.device(x))['data-dependent shapes']:
        _, counts = xp.unique_counts(x)
        n = _compat.size(counts)
        if n is None:
            return xp.sum(xp.ones_like(counts))
        return xp.asarray(n, device=_compat.device(x))
    x = xp.reshape(x, (-1,))
    x = xp.sort(x, stable=False)
    mask = x != xp.roll(x, -1)
    default_int = default_dtype(xp, 'integral', device=_compat.device(x))
    return xp.maximum(xp.astype(xp.any(~mask), default_int), xp.sum(xp.astype(mask, default_int)))

def append(self, other: Index | Sequence[Index]) -> Index:
    to_concat = [self]
    if isinstance(other, (list, tuple)):
        to_concat += list(other)
    else:
        to_concat.append(other)
    for obj in to_concat:
        if not isinstance(obj, Index):
            raise TypeError('all inputs must be Index')
    names = {obj.name for obj in to_concat}
    name = None if len(names) > 1 else self.name
