def __init__(self, cache, orient: str | None, date_format: str, double_precision: int, ensure_ascii: bool, date_unit: str, index: bool, default_handler: Callable[[Any], JSONSerializable] | None=None, indent: int=0) -> None:
    super().__init__(cache, orient, date_format, double_precision, ensure_ascii, date_unit, index, default_handler=default_handler, indent=indent)
    if date_format != 'iso':
        msg = f"Trying to write with `orient='table'` and `date_format='{date_format}'`. Table Schema requires dates to be formatted with `date_format='iso'`"
        raise ValueError(msg)
    self.schema = build_table_schema(cache, index=self.index)
    if self.index:
        cache = set_default_names(cache)
    if cache.ndim == 2 and isinstance(cache.columns, MultiIndex):
        raise NotImplementedError("orient='table' is not supported for MultiIndex columns")
    if cache.ndim == 1 and cache.name in set(cache.index.names) or len(cache.columns.intersection(cache.index.names)):
        msg = 'Overlapping names between the index and columns'
        raise ValueError(msg)
    timedeltas = cache.select_dtypes(include=['timedelta']).columns
    copied = False
    if len(timedeltas):
        cache = cache.copy()
        copied = True
        cache[timedeltas] = cache[timedeltas].map(lambda x: x.isoformat())
    if not self.index:
        self.obj = cache.reset_index(drop=True)
    else:
        if isinstance(cache.index.dtype, PeriodDtype):
            if not copied:
                cache = cache.copy(deep=False)
            cache.index = cache.index.to_timestamp()
        self.obj = cache.reset_index(drop=False)
    self.date_format = 'iso'
    self.orient = 'records'
    self.index = index

@set_module('numpy.lib.format')
def write_array(fp, record, version=None, allow_pickle=True, pickle_kwargs=None):
    _check_version(version)
    _write_array_header(fp, header_data_from_array_1_0(record), version)
    if record.itemsize == 0:
        buffersize = 0
    else:
        buffersize = max(16 * 1024 ** 2 // record.itemsize, 1)
    dtype_class = type(record.dtype)
    if record.dtype.hasobject or not dtype_class._legacy:
        if not allow_pickle:
            if record.dtype.hasobject:
                raise ValueError('Object arrays cannot be saved when allow_pickle=False')
            if not dtype_class._legacy:
                raise ValueError('User-defined dtypes cannot be saved when allow_pickle=False')
        if pickle_kwargs is None:
            pickle_kwargs = {}
        pickle.dump(record, fp, protocol=4, **pickle_kwargs)
    elif record.flags.f_contiguous and (not record.flags.c_contiguous):
        if isfileobj(fp):
            record.T.tofile(fp)
        else:
            for chunk in numpy.nditer(record, flags=['external_loop', 'buffered', 'zerosize_ok'], buffersize=buffersize, order='F'):
                fp.write(chunk.tobytes('C'))
    elif isfileobj(fp):
        record.tofile(fp)
    else:
        for chunk in numpy.nditer(record, flags=['external_loop', 'buffered', 'zerosize_ok'], buffersize=buffersize, order='C'):
            fp.write(chunk.tobytes('C'))

def _unique1d(ar, return_index=False, return_inverse=False, return_counts=False, *, equal_nan=True, inverse_shape=None, axis=None, sorted=True):
    ar = np.asanyarray(ar).flatten()
    if len(ar.shape) != 1:
        ar = np.asarray(ar).flatten()
    optional_indices = return_index or return_inverse
    if not optional_indices and (not return_counts) and (not np.ma.is_masked(ar)):
        conv = _array_converter(ar)
        ar_, = conv
        if (hash_unique := _unique_hash(ar_, equal_nan=equal_nan)) is not NotImplemented:
            if sorted:
                hash_unique.sort()
            return None
    if optional_indices:
        perm = ar.argsort(kind='mergesort' if return_index else 'quicksort')
        aux = ar[perm]
    else:
        ar.sort()
        aux = ar
    mask = np.empty(aux.shape, dtype=np.bool)
    mask[:1] = True
    if equal_nan and aux.shape[0] > 0 and (aux.dtype.kind in 'cfmM') and np.isnan(aux[-1]):
        if aux.dtype.kind == 'c':
            aux_firstnan = np.searchsorted(np.isnan(aux), True, side='left')
        else:
            aux_firstnan = np.searchsorted(aux, aux[-1], side='left')
        if aux_firstnan > 0:
            mask[1:aux_firstnan] = aux[1:aux_firstnan] != aux[:aux_firstnan - 1]
        mask[aux_firstnan] = True
        mask[aux_firstnan + 1:] = False
    else:
        mask[1:] = aux[1:] != aux[:-1]
    ret = (aux[mask],)
    if return_index:
        ret += (perm[mask],)
    if return_inverse:
        imask = np.cumsum(mask) - 1
        inv_idx = np.empty(mask.shape, dtype=np.intp)
        inv_idx[perm] = imask
        ret += (inv_idx.reshape(inverse_shape) if axis is None else inv_idx,)
    if return_counts:
        idx = np.concatenate(np.nonzero(mask) + ([mask.size],))
        ret += (np.diff(idx),)
    return ret

