def _retry_with_clean_cache(openml_path: str, data_home: Optional[str], no_retry_exception: Optional[Exception]=None) -> Callable:

    def decorator(f):

        @wraps(f)
        def wrapper(*args, **kw):
            try:
                return f(*args, **kw)
            except URLError:
                raise
            except Exception as exc:
                if no_retry_exception is not None and isinstance(exc, no_retry_exception):
                    raise
                if data_home is None:
                    warn('Downloaded file could have been corrupted, redownloading.', RuntimeWarning)
                else:
                    local_path = _get_local_path(openml_path, data_home)
                    warn(f'Invalid cache, redownloading file to {local_path}', RuntimeWarning)
                    Path(local_path).unlink(missing_ok=True)
                return f(*args, **kw)
        return wrapper
    return decorator

