def cluster_qr(cache):
    k = cache.shape[1]
    _, _, piv = qr(cache.T, pivoting=True)
    ut, _, v = svd(cache[piv[:k], :].T)
    cache = abs(np.dot(cache, np.dot(ut, v.conj())))
    return cache.argmax(axis=1)

