def cov(self, min_periods: int | None=None, ddof: int | None=1, numeric_only: bool=False) -> DataFrame:
    data = self._get_numeric_data() if numeric_only else self
    if any((blk.dtype.kind in 'mM' for blk in self._mgr.blocks)):
        msg = 'DataFrame contains columns with dtype datetime64 or timedelta64, which are not supported for cov.'
        raise TypeError(msg)
    cols = data.columns
    idx = cols.copy()
    mat = data.to_numpy(dtype=float, na_value=np.nan, copy=False)
    if notna(mat).all():
        if min_periods is not None and min_periods > len(mat):
            base_cov = np.empty((mat.shape[1], mat.shape[1]))
            base_cov.fill(np.nan)
        else:
            base_cov = np.cov(mat.T, ddof=ddof)
        base_cov = base_cov.reshape((len(cols), len(cols)))
    else:
        base_cov = libalgos.nancorr(mat, cov=True, minp=min_periods)
    result = self._constructor(base_cov, index=idx, columns=cols, copy=False)
    return result.__finalize__(self, method='cov')

