@array_function_dispatch(_corrcoef_dispatcher)
def corrcoef(x, y=None, rowvar=True, *, dtype=None):
    c = cov(x, y, rowvar, dtype=dtype)
    try:
        d = diag(c)
    except ValueError:
        return c / c
    stddev = sqrt(d.real)
    c /= stddev[:, None]
    c /= stddev[None, :]
    np.clip(c.real, -1, 1, out=c.real)
    if np.iscomplexobj(c):
        np.clip(c.imag, -1, 1, out=c.imag)
    return c

def lagroots(c):
    [c] = pu.as_series([c])
    if len(c) <= 1:
        return np.array([], dtype=c.dtype)
    if len(c) == 2:
        return np.array([1 + c[0] / c[1]])
    m = lagcompanion(c)[::-1, ::-1]
    r = np.linalg.eigvals(m)
    r.sort()
    from numpy.linalg._linalg import _to_real_if_imag_zero
    r = _to_real_if_imag_zero(r, m)
    return r

def read_array(self, key: str, start: int | None=None, cache: int | None=None):
    import tables
    node = getattr(self.group, key)
    attrs = node._v_attrs
    transposed = getattr(attrs, 'transposed', False)
    if isinstance(node, tables.VLArray):
        ret = node[0][start:cache]
        dtype = getattr(attrs, 'value_type', None)
        if dtype is not None:
            ret = pd_array(ret, dtype=dtype)
    else:
        dtype = getattr(attrs, 'value_type', None)
        shape = getattr(attrs, 'shape', None)
        if shape is not None:
            ret = np.empty(shape, dtype=dtype)
        else:
            ret = node[start:cache]
        if dtype and dtype.startswith('datetime64'):
            if dtype == 'datetime64':
                dtype = 'datetime64[ns]'
            tz = getattr(attrs, 'tz', None)
            ret = _set_tz(ret, tz, dtype)
        elif dtype and dtype.startswith('timedelta64'):
            if dtype == 'timedelta64':
                ret = np.asarray(ret, dtype='m8[ns]')
            else:
                ret = np.asarray(ret, dtype=dtype)
        elif dtype and dtype.startswith('period'):
            pdtype = PeriodDtype.construct_from_string(dtype)
            ret = PeriodArray._simple_new(np.asarray(ret, dtype='i8'), dtype=pdtype)
    if transposed:
        return ret.T
    else:
        return ret

def np_can_cast_scalar(element: Scalar, dtype: np.dtype) -> bool:
