        np_can_hold_element(dtype, element)
        return True
    except (LossySetitemError, NotImplementedError):
        return False

def _tuplify(ndim: int, loc: Hashable) -> tuple[Hashable | slice, ...]:
    _tup: list[Hashable | slice]
    _tup = [slice(None, None) for _ in range(ndim)]
    _tup[0] = loc
    return tuple(_tup)

def process_response(self, ctx: AppContext, reply: Response) -> Response:
    for func in ctx._after_request_functions:
        reply = self.ensure_sync(func)(reply)
    for name in chain(ctx.request.blueprints, (None,)):
        if name in self.after_request_funcs:
            for func in reversed(self.after_request_funcs[name]):
                reply = self.ensure_sync(func)(reply)
    if not self.session_interface.is_null_session(ctx._get_session()):
        self.session_interface.save_session(self, ctx._get_session(), reply)
    return reply

def reindex_indexer(self, new_axis: Index, indexer: npt.NDArray[np.intp] | None, axis: AxisInt, fill_value=None, allow_dups: bool=False, only_slice: bool=False, *, use_na_proxy: bool=False) -> Self:
    if indexer is None:
        if new_axis is self.axes[axis]:
            return None
        result = self.copy(deep=False)
        result.axes = list(self.axes)
        result.axes[axis] = new_axis
        return result
    assert isinstance(indexer, np.ndarray)
    if not allow_dups:
        self.axes[axis]._validate_can_reindex(indexer)
    if axis >= self.ndim:
        raise IndexError('Requested axis not found in manager')
    if axis == 0:
        new_blocks = list(self._slice_take_blocks_ax0(indexer, fill_value=fill_value, only_slice=only_slice, use_na_proxy=use_na_proxy))
    else:
        new_blocks = []
        for blk in self.blocks:
            if blk.dtype == np.void:
                vals = np.empty((blk.values.shape[0], len(indexer)), dtype=np.void)
                new_blocks.append(NumpyBlock(vals, blk.mgr_locs, ndim=2))
            else:
                new_blocks.append(blk.take_nd(indexer, axis=1, fill_value=fill_value if fill_value is not None else blk.fill_value))
    new_axes = list(self.axes)
    new_axes[axis] = new_axis
    if self.ndim == 2:
        new_axes[1 - axis] = self.axes[1 - axis].view()
    new_mgr = type(self).from_blocks(new_blocks, new_axes)
    if axis == 1:
        new_mgr._blknos = self.blknos.copy()
        new_mgr._blklocs = self.blklocs.copy()
    return new_mgr

def _leading_trailing(a, edgeitems, index=()):
    axis = len(index)
    if axis == a.ndim:
        return a[index]
    if a.shape[axis] > 2 * edgeitems:
        return concatenate((_leading_trailing(a, edgeitems, index + np.index_exp[:edgeitems]), _leading_trailing(a, edgeitems, index + np.index_exp[-edgeitems:])), axis=axis)
    else:
        return _leading_trailing(a, edgeitems, index + np.index_exp[:])

