@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], ensure_min_features=2)
    random_state = check_random_state(self.random_state)
    if self.algorithm == 'arpack':
        v0 = _init_arpack_v0(min(X.shape), random_state)
        U, Sigma, VT = svds(X, k=self.n_components, tol=self.tol, v0=v0)
        Sigma = Sigma[::-1]
        U, VT = svd_flip(U[:, ::-1], VT[::-1], u_based_decision=False)
    elif self.algorithm == 'randomized':
        if self.n_components > X.shape[1]:
            raise ValueError(f'n_components({self.n_components}) must be <= n_features({X.shape[1]}).')
        U, Sigma, VT = _randomized_svd(X, self.n_components, n_iter=self.n_iter, n_oversamples=self.n_oversamples, power_iteration_normalizer=self.power_iteration_normalizer, random_state=random_state, flip_sign=False)
        U, VT = svd_flip(U, VT, u_based_decision=False)
    self.components_ = VT
    if self.algorithm == 'randomized' or (self.algorithm == 'arpack' and self.tol > 0):
        X_transformed = safe_sparse_dot(X, self.components_.T)
    else:
        X_transformed = U * Sigma
    self.explained_variance_ = exp_var = np.var(X_transformed, axis=0)
    if sp.issparse(X):
        _, full_var = mean_variance_axis(X, axis=0)
        full_var = full_var.sum()
    else:
        full_var = np.var(X, axis=0).sum()
    self.explained_variance_ratio_ = exp_var / full_var
    self.singular_values_ = Sigma
    return X_transformed

