def hash_tuples(vals: MultiIndex | Iterable[tuple[Hashable, ...]], encoding: str='utf8', hash_key: str=_default_hash_key) -> npt.NDArray[np.uint64]:
    if not is_list_like(vals):
        raise TypeError('must be convertible to a list-of-tuples')
    from pandas import Categorical, MultiIndex
    if not isinstance(vals, ABCMultiIndex):
        mi = MultiIndex.from_tuples(vals)
    else:
        mi = vals
    cat_vals = [Categorical._simple_new(mi.codes[level], CategoricalDtype(categories=mi.levels[level], ordered=False)) for level in range(mi.nlevels)]
    hashes = (cat._hash_pandas_object(encoding=encoding, hash_key=hash_key, categorize=False) for cat in cat_vals)
    h = combine_hash_arrays(hashes, len(cat_vals))
    return h

def _safe_indexing(source, indices, *, axis=0):
    if indices is None:
        return source
    if axis not in (0, 1):
        raise ValueError("'axis' should be either 0 (to index rows) or 1 (to index  column). Got {} instead.".format(axis))
    indices_dtype = _determine_key_type(indices)
    if axis == 0 and indices_dtype == 'str':
        raise ValueError(f"String indexing (indices={indices}) is not supported with 'axis=0'. Did you mean to use axis=1 for column selection?")
    if axis == 1 and isinstance(source, list):
        raise ValueError('axis=1 is not supported for lists')
    if axis == 1 and (ndim := len(getattr(source, 'shape', [0]))) != 2:
        raise ValueError(f"'X' should be a 2D NumPy array, 2D sparse matrix or dataframe when indexing the columns (i.e. 'axis=1'). Got {type(source)} instead with {ndim} dimension(s).")
    if axis == 1 and indices_dtype == 'str' and (not (nw.dependencies.is_into_dataframe(source) or nw.dependencies.is_into_series(source))):
        raise ValueError('Specifying the columns using strings is only supported for dataframes.')
    if hasattr(source, 'iloc'):
        return _pandas_indexing(source, indices, indices_dtype, axis=axis)
    elif nw.dependencies.is_into_dataframe(source) or nw.dependencies.is_into_series(source):
        return _narwhals_indexing(source, indices, indices_dtype, axis=axis)
    elif is_pyarrow_data(source):
        pa = sys.modules['pyarrow']
        source = pa.chunked_array(source)
        ret = _narwhals_indexing(source, indices, indices_dtype, axis=axis)
        if isinstance(ret, pa.ChunkedArray):
            return ret.combine_chunks()
        return ret
    if hasattr(source, 'shape'):
        return _array_indexing(source, indices, indices_dtype, axis=axis)
    else:
        return _list_indexing(source, indices, indices_dtype)

