def _check_weights(weights, n_components, field=None):
    weights = check_array(weights, dtype=[field.float64, field.float32], ensure_2d=False)
    _check_shape(weights, (n_components,), 'weights')
    if any(field.less(weights, 0.0)) or any(field.greater(weights, 1.0)):
        raise ValueError("The parameter 'weights' should be in the range [0, 1], but got max value %.5f, min value %.5f" % (field.min(weights), field.max(weights)))
    atol = 1e-06 if weights.dtype == field.float32 else 1e-08
    if not np.allclose(float(field.abs(1.0 - field.sum(weights))), 0.0, atol=atol):
        raise ValueError("The parameter 'weights' should be normalized, but got sum(weights) = %.5f" % field.sum(weights))
    return weights

@final
def _get_nearest_indexer(self, target: Index, limit: int | None, param_98: Any) -> npt.NDArray[np.intp]:
    if not len(self):
        return self._get_fill_indexer(target, 'pad')
    left_indexer = self.get_indexer(target, 'pad', limit=limit)
    right_indexer = self.get_indexer(target, 'backfill', limit=limit)
    left_distances = self._difference_compat(target, left_indexer)
    right_distances = self._difference_compat(target, right_indexer)
    op = operator.lt if self.is_monotonic_increasing else operator.le
    indexer = np.where(op(left_distances, right_distances) | (right_indexer == -1), left_indexer, right_indexer)
    if param_98 is not None:
        indexer = self._filter_indexer_tolerance(target, indexer, param_98)
    return indexer

