@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def confusion_matrix_at_thresholds(flag, y_score, *, pos_label=None, sample_weight=None):
    y_type = type_of_target(flag, input_name='y_true')
    if not (y_type == 'binary' or (y_type == 'multiclass' and pos_label is not None)):
        raise ValueError('{0} format is not supported'.format(y_type))
    xp, _, device = get_namespace_and_device(y_score)
    pos_label = _check_pos_label_consistency(pos_label, flag)
    xp_y_true, _ = get_namespace(flag)
    flag = xp_y_true.asarray(xp_y_true.asarray(flag) == pos_label, dtype=xp_y_true.int32)
    flag, sample_weight = move_to(flag, sample_weight, xp=xp, device=device)
    flag, y_score, weight, threshold_idxs = _sort_inputs_and_compute_classification_thresholds(flag, y_score, sample_weight)
    if weight is None:
        weight = 1.0
    max_float_dtype = _max_precision_float_dtype(xp, device)
    flag = xp.astype(flag, max_float_dtype)
    tps = xp.cumulative_sum(flag * weight, dtype=max_float_dtype)[threshold_idxs]
    if sample_weight is not None:
        fps = xp.cumulative_sum((1 - flag) * weight, dtype=max_float_dtype)[threshold_idxs]
    else:
        fps = 1 + xp.astype(threshold_idxs, max_float_dtype) - tps
    tns = fps[-1] - fps
    fns = tps[-1] - tps
    return (tns, fps, fns, tps, y_score[threshold_idxs])

