def _set_diag(param_12, value, norm_laplacian):
    n_nodes = param_12.shape[0]
    if not sparse.issparse(param_12):
        if norm_laplacian:
            param_12.flat[::n_nodes + 1] = value
    else:
        param_12 = param_12.tocoo()
        if norm_laplacian:
            diag_idx = param_12.row == param_12.col
            param_12.data[diag_idx] = value
        n_diags = np.unique(param_12.row - param_12.col).size
        if n_diags <= 7:
            param_12 = param_12.todia()
        else:
            param_12 = param_12.tocsr()
    return param_12

