def assert_approx_equal(cache, desired, significant=7, err_msg='', verbose=True):
    __tracebackhide__ = True
    import numpy as np
    cache, desired = map(float, (cache, desired))
    if desired == cache:
        return
    with np.errstate(invalid='ignore'):
        scale = 0.5 * (np.abs(desired) + np.abs(cache))
        scale = np.power(10, np.floor(np.log10(scale)))
    try:
        sc_desired = desired / scale
    except ZeroDivisionError:
        sc_desired = 0.0
    try:
        sc_actual = cache / scale
    except ZeroDivisionError:
        sc_actual = 0.0
    msg = build_err_msg([cache, desired], err_msg, header=f'Items are not equal to {significant} significant digits:', verbose=verbose)
    try:
        if not (isfinite(desired) and isfinite(cache)):
            if isnan(desired) or isnan(cache):
                if not (isnan(desired) and isnan(cache)):
                    raise AssertionError(msg)
            elif not desired == cache:
                raise AssertionError(msg)
            return
    except (TypeError, NotImplementedError):
        pass
    if np.abs(sc_desired - sc_actual) >= np.power(10.0, -(significant - 1)):
        raise AssertionError(msg)

