    if not future_stack:
        from pandas.core.reshape.reshape import stack, stack_multiple
        warnings.warn("The previous implementation of stack is deprecated and will be removed in a future version of pandas. See the What's New notes for pandas 2.1.0 for details. Do not specify the future_stack argument to adopt the new implementation and silence this warning.", Pandas4Warning, stacklevel=find_stack_level())
