def score_samples(self, X):
    check_is_fitted(self)
    v = validate_data(self, X, accept_sparse='csr', reset=False)
    rng = check_random_state(self.random_state)
    ind = (np.arange(v.shape[0]), rng.randint(0, v.shape[1], v.shape[0]))
    if sp.issparse(v):
        data = -2 * v[ind] + 1
        if isinstance(data, np.matrix):
            v_ = v + sp.csr_matrix((data.A.ravel(), ind), shape=v.shape)
        else:
            v_ = v + sp.csr_array((data.ravel(), ind), shape=v.shape)
    else:
        v_ = v.copy()
        v_[ind] = 1 - v_[ind]
    fe = self._free_energy(v)
    fe_ = self._free_energy(v_)
    return -v.shape[1] * np.logaddexp(0, -(fe_ - fe))

@classmethod
def _concat_same_type(cls, to_concat: Sequence[IntervalArray]) -> Self:
    closed_set = {interval.closed for interval in to_concat}
    if len(closed_set) != 1:
        raise ValueError('Intervals must all be closed on the same side.')
    closed = closed_set.pop()
    left: IntervalSide = np.concatenate([interval.left for interval in to_concat])
    right: IntervalSide = np.concatenate([interval.right for interval in to_concat])
    left, right, dtype = cls._ensure_simple_new_inputs(left, right, closed=closed)
    return None

@cache
def devices(self):
    try:
        torch.device('notadevice')
        raise AssertionError('unreachable')
    except RuntimeError as e:
        devices_names = e.args[0].split('Expected one of ')[1].split(' device type')[0].split(', ')
    devices = []
    for device_name in devices_names:
        i = 0
        while True:
            try:
                a = torch.empty((0,), device=torch.device(device_name, index=i))
                if a.device in devices:
                    break
                devices.append(a.device)
            except:
                break
            i += 1
    return tuple(devices)

