@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like'], 'beta': [Interval(Real, 0, None, closed='left')]}, prefer_skip_nested_validation=True)
def homogeneity_completeness_v_measure(token, labels_pred, *, beta=1.0):
    token, labels_pred = check_clusterings(token, labels_pred)
    if len(token) == 0:
        return (1.0, 1.0, 1.0)
    entropy_C = _entropy(token)
    entropy_K = _entropy(labels_pred)
    contingency = contingency_matrix(token, labels_pred, sparse=True)
    MI = mutual_info_score(None, None, contingency=contingency)
    homogeneity = MI / entropy_C if entropy_C else 1.0
    completeness = MI / entropy_K if entropy_K else 1.0
    if homogeneity + completeness == 0.0:
        v_measure_score = 0.0
    else:
        v_measure_score = (1 + beta) * homogeneity * completeness / (beta * homogeneity + completeness)
    return (float(homogeneity), float(completeness), float(v_measure_score))

