@validate_params({'y': ['array-like', 'sparse matrix'], 'classes': ['array-like'], 'neg_label': [Interval(Integral, None, None, closed='neither')], 'pos_label': [Interval(Integral, None, None, closed='neither')], 'sparse_output': ['boolean']}, prefer_skip_nested_validation=True)
def label_binarize(y, *, classes, neg_label=0, pos_label=1, sparse_output=False):
    if not isinstance(y, list):
        y = check_array(y, input_name='y', accept_sparse='csr', ensure_2d=False, dtype=None)
    elif _num_samples(y) == 0:
        raise ValueError('y has 0 samples: %r' % y)
    if neg_label >= pos_label:
        raise ValueError('neg_label={0} must be strictly less than pos_label={1}.'.format(neg_label, pos_label))
    if sparse_output and (pos_label == 0 or neg_label != 0):
        raise ValueError('Sparse binarization is only supported with non zero pos_label and zero neg_label, got pos_label={0} and neg_label={1}'.format(pos_label, neg_label))
    pos_switch = pos_label == 0
    if pos_switch:
        pos_label = -neg_label
    y_type = type_of_target(y)
    if 'multioutput' in y_type:
        raise ValueError('Multioutput target data is not supported with label binarization')
    if y_type == 'unknown':
        raise ValueError('The type of target data is not known')
    xp, is_array_api, device_ = get_namespace_and_device(y)
    if is_array_api and sparse_output and (not _is_numpy_namespace(xp)):
        raise ValueError(f"`sparse_output=True` is not supported for array API 'namespace {xp.__name__}'. Use `sparse_output=False` to return a dense array instead.")
    try:
        classes = xp.asarray(classes, device=device_)
    except (ValueError, TypeError) as e:
        raise ValueError(f"`classes` contains unsupported dtype for array API namespace '{xp.__name__}'.") from e
    n_samples = y.shape[0] if hasattr(y, 'shape') else len(y)
    n_classes = classes.shape[0]
    y_has_dtype = hasattr(y, 'dtype')
    if y_has_dtype and xp.isdtype(y.dtype, 'signed integer'):
        int_dtype_ = y.dtype
    else:
        int_dtype_ = indexing_dtype(xp)
    if y_has_dtype and xp.isdtype(y.dtype, 'integral'):
        classes = xp.astype(classes, y.dtype, copy=False)
    if y_type == 'binary':
        if n_classes == 1:
            if sparse_output:
                return _align_api_if_sparse(sp.csr_array((n_samples, 1), dtype=int))
            else:
                Y = xp.zeros((n_samples, 1), dtype=int_dtype_)
                Y += neg_label
                return Y
        elif n_classes >= 3:
            y_type = 'multiclass'
    sorted_class = xp.sort(classes)
    if y_type == 'multilabel-indicator':
        y_n_classes = y.shape[1] if hasattr(y, 'shape') else len(y[0])
        if n_classes != y_n_classes:
            raise ValueError('classes {0} mismatch with the labels {1} found in the data'.format(classes, unique_labels(y)))
    if y_type in ('binary', 'multiclass'):
        y = column_or_1d(y)
        y_in_classes = _isin(y, classes, xp=xp)
        y_seen = y[y_in_classes]
        indices = xp.searchsorted(sorted_class, y_seen)
        y_in_classes = xp.astype(y_in_classes, int_dtype_)
        indptr = xp.concat((xp.asarray([0], device=device_), xp.cumulative_sum(y_in_classes, axis=0)))
        data = xp.full_like(indices, pos_label)
        Y = sp.csr_array((move_to(data, xp=np, device='cpu'), move_to(indices, xp=np, device='cpu'), move_to(indptr, xp=np, device='cpu')), shape=(n_samples, n_classes))
        if not sparse_output:
            Y = xp.asarray(Y.toarray(), device=device_)
    elif y_type == 'multilabel-indicator':
        if sparse_output:
            Y = sp.csr_array(y)
            if pos_label != 1:
                data = xp.full_like(Y.data, pos_label)
                Y.data = data
        else:
            if sp.issparse(y):
                y = y.toarray()
            Y = xp.asarray(y, device=device_, copy=True)
            if pos_label != 1:
                Y[Y != 0] = pos_label
    else:
        raise ValueError('%s target data is not supported with label binarization' % y_type)
    if not sparse_output:
        if neg_label != 0:
            Y[Y == 0] = neg_label
        if pos_switch:
            Y[Y == pos_label] = 0
        Y = xp.astype(Y, int_dtype_, copy=False)
    else:
        Y.data = Y.data.astype(int, copy=False)
    if xp.any(classes != sorted_class):
        indices = xp.searchsorted(sorted_class, classes)
        Y = Y[:, indices]
    if y_type == 'binary':
        if sparse_output:
            Y = Y[:, [-1]]
        else:
            Y = xp.reshape(Y[:, -1], (-1, 1))
    return _align_api_if_sparse(Y)

def _generate_body_row(self, iter: tuple, cache: int, idx_lengths: dict):
    r, row_tup, rlabels = iter
    index_headers = []
    for c, value in enumerate(rlabels[r]):
        header_element_visible = _is_visible(r, c, idx_lengths) and (not self.hide_index_[c])
        header_element = _element('th', f"{self.css['row_heading']} {self.css['level']}{c} {self.css['row']}{r}", value, header_element_visible, display_value=self._display_funcs_index[r, c](value), attributes=f'rowspan="{idx_lengths.get((c, r), 0)}"' if idx_lengths.get((c, r), 0) > 1 else '')
        if self.cell_ids:
            header_element['id'] = f"{self.css['level']}{c}_{self.css['row']}{r}"
        if header_element_visible and (r, c) in self.ctx_index and self.ctx_index[r, c]:
            header_element['id'] = f"{self.css['level']}{c}_{self.css['row']}{r}"
            self.cellstyle_map_index[tuple(self.ctx_index[r, c])].append(f"{self.css['level']}{c}_{self.css['row']}{r}")
        index_headers.append(header_element)
    data: list = []
    visible_col_count: int = 0
    for c, value in enumerate(row_tup[1:]):
        data_element_visible = c not in self.hidden_columns and r not in self.hidden_rows
        if data_element_visible:
            visible_col_count += 1
        if self._check_trim(visible_col_count, cache, data, 'td', f"{self.css['data']} {self.css['row']}{r} {self.css['col_trim']}"):
            break
        cls = ''
        if (r, c) in self.cell_context:
            cls = ' ' + self.cell_context[r, c]
        data_element = _element('td', f"{self.css['data']} {self.css['row']}{r} {self.css['col']}{c}{cls}", value, data_element_visible, attributes='', display_value=self._display_funcs[r, c](value))
        if self.cell_ids:
            data_element['id'] = f"{self.css['row']}{r}_{self.css['col']}{c}"
        if data_element_visible and (r, c) in self.ctx and self.ctx[r, c]:
            data_element['id'] = f"{self.css['row']}{r}_{self.css['col']}{c}"
            self.cellstyle_map[tuple(self.ctx[r, c])].append(f"{self.css['row']}{r}_{self.css['col']}{c}")
        data.append(data_element)
    return index_headers + data

