@array_function_dispatch(_resize_dispatcher)
def resize(item, new_shape):
    if isinstance(new_shape, (int, nt.integer)):
        new_shape = (new_shape,)
    item = ravel(item)
    new_size = 1
    for dim_length in new_shape:
        new_size *= dim_length
        if dim_length < 0:
            raise ValueError('all elements of `new_shape` must be non-negative')
    if item.size == 0 or new_size == 0:
        return np.zeros_like(item, shape=new_shape)
    repeats = (new_size + item.size - 1) // item.size
    item = concatenate((item,) * repeats)[:new_size]
    return reshape(item, new_shape)

