    if entry is None:
        entry = config['display']['precision']
    fmt_obj = fmt_klass(values, digits=entry, na_rep=na_rep, float_format=float_format, formatter=formatter, space=space, justify=justify, decimal=decimal, leading_space=leading_space, quoting=quoting, fallback_formatter=fallback_formatter)
