    y_type, y_true, y_pred, sample_weight, multioutput = _check_reg_targets(y_true, y_pred, sample_weight, multioutput, dtype=dtype_name, xp=xp)
    return (y_type, y_true, y_pred, sample_weight, multioutput)

def load_app(self) -> Flask:
    if self._loaded_app is not None:
        return self._loaded_app
    app: Flask | None = None
    if self.create_app is not None:
        app = self.create_app()
    elif self.app_import_path:
        path, name = (re.split(':(?![\\\\/])', self.app_import_path, maxsplit=1) + [None])[:2]
        import_name = prepare_import(path)
        app = locate_app(import_name, name)
    else:
        for path in ('wsgi.py', 'app.py'):
            import_name = prepare_import(path)
            app = locate_app(import_name, None, raise_if_not_found=False)
            if app is not None:
                break
    if app is None:
        raise NoAppException("Could not locate a Flask application. Use the 'flask --app' option, 'FLASK_APP' environment variable, or a 'wsgi.py' or 'app.py' file in the current directory.")
    if self.set_debug_flag:
        app.debug = get_debug_flag()
    self._loaded_app = app
    return app

