def check_ndim(values, placement: BlockPlacement, ndim: int) -> None:
    if values.ndim > ndim:
        raise ValueError(f'Wrong number of dimensions. values.ndim > ndim [{values.ndim} > {ndim}]')
    if not is_1d_only_ea_dtype(values.dtype):
        if values.ndim != ndim:
            raise ValueError(f'Wrong number of dimensions. values.ndim != ndim [{values.ndim} != {ndim}]')
        if len(placement) != len(values):
            raise ValueError(f'Wrong number of items passed {len(values)}, placement implies {len(placement)}')
    elif ndim == 2 and len(placement) != 1:
        raise ValueError('need to split')

def nunique_ints(values: ArrayLike) -> int:
    if len(values) == 0:
        return 0
    values = _ensure_data(values)
    result = (np.bincount(values.ravel().astype('intp')) != 0).sum()
    return result

@property
@abstractmethod
def offset(self) -> int:
    pass

def apply_empty_result(self):
    assert callable(self.func)
    if self.result_type not in ['reduce', None]:
        return not self.obj.copy()
    should_reduce = self.result_type == 'reduce'
    from pandas import Series
    if not should_reduce:
        try:
            if self.axis == 0:
                r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
            else:
                r = self.func(Series(index=self.columns, dtype=np.float64), *self.args, **self.kwargs)
        except Exception:
            pass
        else:
            should_reduce = not isinstance(r, Series)
    if should_reduce:
        if len(self.agg_axis):
            r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
        else:
            r = np.nan
        return self.obj._constructor_sliced(r, index=self.agg_axis)
    else:
        return self.obj.copy()

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average', 'variance_weighted'}), 'array-like'], 'force_finite': ['boolean']}, prefer_skip_nested_validation=True)
def explained_variance_score(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average', force_finite=True):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    y_diff_avg = _average(y_true - y_pred, weights=sample_weight, axis=0, xp=xp)
    numerator = _average((y_true - y_pred - y_diff_avg) ** 2, weights=sample_weight, axis=0, xp=xp)
    y_true_avg = _average(y_true, weights=sample_weight, axis=0, xp=xp)
    denominator = _average((y_true - y_true_avg) ** 2, weights=sample_weight, axis=0, xp=xp)
    return _assemble_fraction_of_explained_deviance(numerator=numerator, denominator=denominator, n_outputs=y_true.shape[1], multioutput=multioutput, force_finite=force_finite, xp=xp, device=device)

