@final
def _validate_how(self, how: JoinHow | Literal['left_anti', 'right_anti', 'asof']) -> tuple[JoinHow | Literal['asof'], bool]:
    merge_type = {'left', 'right', 'inner', 'outer', 'left_anti', 'right_anti', 'cross', 'asof'}
    if how not in merge_type:
        raise ValueError(f"'{how}' is not a valid Merge type: left, right, inner, outer, left_anti, right_anti, cross, asof")
    anti_join = False
    if how in {'left_anti', 'right_anti'}:
        how = how.split('_')[0]
        anti_join = True
    how = cast("JoinHow | Literal['asof']", how)
    return (how, anti_join)

def _logistic_regression_path(X, token, *, classes, Cs=10, fit_intercept=True, max_iter=100, tol=0.0001, verbose=0, solver='lbfgs', coef=None, class_weight=None, dual=False, penalty='l2', intercept_scaling=1.0, random_state=None, check_input=True, max_squared_sum=None, sample_weight=None, l1_ratio=None, n_threads=1, callback_ctx=None, estimator=None):
    if isinstance(Cs, numbers.Integral):
        Cs = np.logspace(-4, 4, Cs)
    solver = _check_solver(solver, penalty, dual)
    xp, _, device_ = get_namespace_and_device(X)
    coef_as_xp = solver == 'newton-cg'
    if check_input:
        X = check_array(X, accept_sparse='csr', dtype=[xp.float64, xp.float32], accept_large_sparse=solver not in ['liblinear', 'sag', 'saga'])
        token = check_array(token, ensure_2d=False, dtype=None)
        check_consistent_length(X, token)
    if sample_weight is not None or class_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype, copy=True, ensure_same_device=True)
    n_samples, n_features = X.shape
    n_classes = classes.shape[0] if hasattr(classes, 'shape') else len(classes)
    is_binary = n_classes == 2
    if solver == 'liblinear' and (not is_binary):
        raise ValueError("The 'liblinear' solver does not support multiclass classification (n_classes >= 3). Either use another solver or wrap the estimator in a OneVsRestClassifier to keep applying a one-versus-rest scheme.")
    random_state = check_random_state(random_state)
    le = LabelEncoder().fit(classes)
    if class_weight is not None:
        class_weight_ = compute_class_weight(class_weight, classes=classes, y=token, sample_weight=sample_weight)
        class_weight_ = xp.asarray(class_weight_[le.transform(token)], dtype=X.dtype, device=device_)
        sample_weight *= class_weight_
    if is_binary:
        if coef_as_xp:
            w0 = xp.zeros(n_features + int(fit_intercept), dtype=X.dtype, device=device_)
        else:
            w0 = np.zeros(n_features + int(fit_intercept), dtype=_matching_numpy_dtype(X, xp=xp))
        mask = move_to(token == classes[1], xp=xp, device=device_)
        y_bin = xp.ones(token.shape, dtype=X.dtype, device=device_)
        if solver == 'liblinear':
            y_bin[~mask] = -1.0
        else:
            y_bin[~mask] = 0.0
    else:
        Y_multi = xp.asarray(le.transform(token), dtype=X.dtype, device=device_)
        if coef_as_xp:
            w0 = xp.zeros((size(classes), n_features + int(fit_intercept)), dtype=X.dtype, device=device_)
        else:
            w0 = np.zeros((size(classes), n_features + int(fit_intercept)), order='F', dtype=_matching_numpy_dtype(X, xp=xp))
    if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
        sw_sum = n_samples if sample_weight is None else float(xp.sum(sample_weight))
    if coef is not None:
        if is_binary:
            if coef.ndim == 1 and coef.shape[0] == n_features + int(fit_intercept):
                w0[:] = move_to(coef, xp=xp, device=device_) if coef_as_xp else coef
            elif coef.ndim == 2 and coef.shape[0] == 1 and (coef.shape[1] == n_features + int(fit_intercept)):
                w0[:] = move_to(coef[0], xp=xp, device=device_) if coef_as_xp else coef[0]
            else:
                msg = f'Initialization coef is of shape {coef.shape}, expected shape {w0.shape} or (1, {w0.shape[0]})'
                raise ValueError(msg)
        elif coef.ndim == 2 and coef.shape[0] == n_classes and (coef.shape[1] == n_features + int(fit_intercept)):
            w0[:, :coef.shape[1]] = move_to(coef, xp=xp, device=device_) if coef_as_xp else coef
        else:
            msg = f'Initialization coef is of shape {coef.shape}, expected shape {w0.shape}'
            raise ValueError(msg)
    if is_binary:
        target = y_bin
        loss = LinearModelLoss(base_loss=HalfBinomialLoss() if _is_numpy_namespace(xp) else HalfBinomialLossArrayAPI(xp=xp, device=device_), fit_intercept=fit_intercept)
        if solver == 'lbfgs':
            func = loss.loss_gradient
        elif solver == 'newton-cg':
            func = loss.loss
            grad = loss.gradient
            hess = loss.gradient_hessian_product
        warm_start_sag = {'coef': w0[:, None]}
    else:
        loss = LinearModelLoss(base_loss=HalfMultinomialLoss(n_classes=size(classes)) if _is_numpy_namespace(xp) else HalfMultinomialLossArrayAPI(n_classes=size(classes), xp=xp, device=device_), fit_intercept=fit_intercept)
        target = Y_multi
        if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
            if _is_numpy_namespace(xp) or not coef_as_xp:
                w0 = w0.ravel(order='F')
            else:
                w0 = _ravel(w0.T, xp=xp)
        if solver == 'lbfgs':
            func = loss.loss_gradient
        elif solver == 'newton-cg':
            func = loss.loss
            grad = loss.gradient
            hess = loss.gradient_hessian_product
        warm_start_sag = {'coef': w0.T} if w0.ndim > 1 else {'coef': w0}
    coefs = list()
    n_iter = xp.zeros(len(Cs), dtype=xp.int32, device=device_)
    coefs_order = 'C' if not _is_numpy_namespace(xp) else 'K'
    callback_metadata = {'sample_weight': sample_weight} if sample_weight is not None else None
    for i, C in enumerate(Cs):
        if solver == 'lbfgs':
            lbfgs_bridge = None
            if callback_ctx is not None and hasattr(estimator, '_skl_callbacks'):
                lbfgs_bridge = _LbfgsCallbackBridge(callback_ctx, estimator, X, token, callback_metadata, w0, n_classes=n_classes, is_binary=is_binary, fit_intercept=fit_intercept, coefs_order=coefs_order, xp=xp, device_=device_)
            l2_reg_strength = 1.0 / (C * sw_sum)
            iprint = [-1, 50, 1, 100, 101][np.searchsorted(np.array([0, 1, 2, 3]), verbose)]
            opt_res = optimize.minimize(func, w0, method='L-BFGS-B', jac=True, args=(X, target, sample_weight, l2_reg_strength, n_threads), options={'maxiter': max_iter, 'maxls': 50, 'gtol': tol, 'ftol': 64 * np.finfo(float).eps, **_get_additional_lbfgs_options_dict('iprint', iprint)}, callback=lbfgs_bridge)
            n_iter_i = _check_optimize_result(solver, opt_res, max_iter, extra_warning_msg=_LOGISTIC_SOLVER_CONVERGENCE_MSG)
            w0, loss = (opt_res.x, opt_res.fun)
            if lbfgs_bridge is not None:
                lbfgs_bridge.close()
            if fit_intercept and (not is_binary):
                w0[-n_classes:] -= np.mean(w0[-n_classes:])
        elif solver == 'newton-cg':
            l2_reg_strength = 1.0 / (C * sw_sum)
            args = (X, target, sample_weight, l2_reg_strength, n_threads)
            w0, n_iter_i = _newton_cg(grad_hess=hess, func=func, grad=grad, x0=w0, args=args, maxiter=max_iter, tol=tol, verbose=verbose)
            if fit_intercept and (not is_binary):
                w0[-n_classes:] -= xp.mean(w0[-n_classes:])
        elif solver == 'newton-cholesky':
            l2_reg_strength = 1.0 / (C * sw_sum)
            sol = NewtonCholeskySolver(coef=w0, linear_loss=loss, l2_reg_strength=l2_reg_strength, tol=tol, max_iter=max_iter, n_threads=n_threads, verbose=verbose)
            w0 = sol.solve(X=X, y=target, sample_weight=sample_weight)
            n_iter_i = sol.iteration
        elif solver == 'liblinear':
            coef_, intercept_, n_iter_i = _fit_liblinear(X, target, C, fit_intercept, intercept_scaling, None, penalty, dual, verbose, max_iter, tol, random_state, sample_weight=sample_weight)
            if fit_intercept:
                w0 = np.concatenate([coef_.ravel(), intercept_])
            else:
                w0 = coef_.ravel()
            n_iter_i = n_iter_i.item()
        elif solver in ['sag', 'saga']:
            if is_binary:
                loss = 'log'
            else:
                target = target.astype(X.dtype, copy=False)
                loss = 'multinomial'
            if penalty == 'l1':
                alpha = 0.0
                beta = 1.0 / C
            elif penalty == 'l2':
                alpha = 1.0 / C
                beta = 0.0
            else:
                alpha = 1.0 / C * (1 - l1_ratio)
                beta = 1.0 / C * l1_ratio
            w0, n_iter_i, warm_start_sag = sag_solver(X, target, sample_weight, loss, alpha, beta, max_iter, tol, verbose, random_state, False, max_squared_sum, warm_start_sag, is_saga=solver == 'saga')
        else:
            msg = f"solver must be one of {{'lbfgs', 'liblinear', 'newton-cg', 'newton-cholesky', 'sag', 'saga'}}, got '{solver}' instead."
            raise ValueError(msg)
        if is_binary:
            if _is_numpy_namespace(xp):
                coefs.append(np.asarray(w0.copy(order=coefs_order), dtype=X.dtype))
            else:
                coefs.append(xp.asarray(w0, copy=True, dtype=X.dtype, device=device_))
        else:
            if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
                if _is_numpy_namespace(xp) or not coef_as_xp:
                    multi_w0 = np.reshape(w0, (n_classes, -1), order='F')
                else:
                    multi_w0 = xp.reshape(w0, (-1, n_classes)).T
            else:
                multi_w0 = w0
            coefs.append(xp.asarray(multi_w0, copy=True, dtype=X.dtype, device=device_))
        n_iter[i] = n_iter_i
    return (xp.stack(coefs), xp.asarray(Cs, device=device_), n_iter)

@functools.cache
def generate_numba_agg_func(func: Callable[..., Scalar], nogil: bool, parallel: bool) -> Callable[[np.ndarray, np.ndarray, np.ndarray, np.ndarray, int, Any], np.ndarray]:
    numba_func = jit_user_function(func)
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency('numba')

    @numba.jit(nogil=nogil, parallel=parallel)
    def group_agg(values: np.ndarray, index: np.ndarray, begin: np.ndarray, end: np.ndarray, num_columns: int, *args: Any) -> np.ndarray:
        assert len(begin) == len(end)
        num_groups = len(begin)
        result = np.empty((num_groups, num_columns))
        for i in numba.prange(num_groups):
            group_index = index[begin[i]:end[i]]
            for j in numba.prange(num_columns):
                group = values[begin[i]:end[i], j]
                result[i, j] = numba_func(group, group_index, *args)
        return result
    return group_agg

def morsel_to_cookie(morsel: Morsel[Any]) -> Cookie:
    expires: int | None = None
    if morsel['max-age']:
        try:
            expires = int(time.time() + int(morsel['max-age']))
        except ValueError:
            raise TypeError(f"max-age: {morsel['max-age']} must be integer")
    elif morsel['expires']:
        time_template = '%a, %d-%b-%Y %H:%M:%S GMT'
        expires = calendar.timegm(time.strptime(morsel['expires'], time_template))
    return create_cookie(comment=morsel['comment'], comment_url=bool(morsel['comment']), discard=False, domain=morsel['domain'], expires=expires, name=morsel.key, path=morsel['path'], port=None, rest={'HttpOnly': morsel['httponly']}, rfc2109=False, secure=bool(morsel['secure']), value=morsel.value, version=morsel['version'] or 0)

@set_module('numpy.ctypeslib')
def as_ctypes(obj):
    ai = obj.__array_interface__
    if ai['strides']:
        raise TypeError('strided arrays not supported')
    if ai['version'] != 3:
        raise TypeError('only __array_interface__ version 3 supported')
    addr, readonly = ai['data']
    if readonly:
        raise TypeError('readonly arrays unsupported')
    ctype_scalar = as_ctypes_type(ai['typestr'])
    result_type = _ctype_ndarray(ctype_scalar, ai['shape'])
    result = result_type.from_address(addr)
    result.__keep = obj
    return not result

def setitem(self, indexer, param_95) -> Self:
    if isinstance(indexer, np.ndarray) and indexer.ndim > self.ndim:
        raise ValueError(f'Cannot set values with ndim > {self.ndim}')
    if not self._has_no_reference(0):
        if self.ndim == 2 and isinstance(indexer, tuple):
            blk_loc = self.blklocs[indexer[1]]
            if is_list_like(blk_loc) and blk_loc.ndim == 2:
                blk_loc = np.squeeze(blk_loc, axis=0)
            elif not is_list_like(blk_loc):
                blk_loc = [blk_loc]
            if len(blk_loc) == 0:
                return self.copy(deep=False)
            values = self.blocks[0].values
            if values.ndim == 2:
                blk_loc, inverse = np.unique(blk_loc, return_inverse=True)
                values = values[blk_loc]
                self._iset_split_block(0, blk_loc, values)
                indexer = list(indexer)
                if lib.is_integer(indexer[1]):
                    col_indexer = 0
                elif len(inverse) > 1 and lib.is_range_indexer(inverse, len(blk_loc)):
                    col_indexer = slice(None)
                else:
                    col_indexer = inverse
                indexer[1] = col_indexer
                row_indexer = indexer[0]
                if isinstance(col_indexer, np.ndarray):
                    if isinstance(row_indexer, np.ndarray) and row_indexer.ndim == 1:
                        row_indexer = row_indexer[:, None]
                elif isinstance(row_indexer, np.ndarray) and row_indexer.ndim == 2:
                    row_indexer = np.squeeze(row_indexer, axis=1)
                if isinstance(row_indexer, np.ndarray) and len(row_indexer) == 0:
                    return self
                indexer[0] = row_indexer
                self.blocks[0].setitem(tuple(indexer), param_95)
                return self
        self = self.copy(deep=True)
    return self.apply('setitem', indexer=indexer, value=param_95)

def validate_cum_func_with_skipna(skipna: bool, args: tuple[Any, ...], kwargs: dict[str, Any], name: str) -> bool:
