@set_module('numpy')
def triu_indices(n, k=0, m=None):
    try:
        k = operator.index(k)
    except TypeError:
        if not isinstance(k, type(k - 1)):
            warnings.warn(f'Cannot convert {type(k).__name__} safely to an integer.This will raise an error in future versions (Deprecated NumPy 2.5)', DeprecationWarning, skip_file_prefixes=(os.path.dirname(__file__),))
    tri_ = ~tri(n, m, k=k - 1, dtype=bool)
    return tuple((broadcast_to(inds, tri_.shape)[tri_] for inds in indices(tri_.shape, sparse=True)))

