    return self._fill_value

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    for _, name, trans in self._iter(with_final=False, filter_passthrough=True):
        method_mapping = MethodMapping()
        if hasattr(trans, 'fit_transform'):
            method_mapping.add(caller='fit', callee='fit_transform').add(caller='fit_transform', callee='fit_transform').add(caller='fit_predict', callee='fit_transform')
        else:
            method_mapping.add(caller='fit', callee='fit').add(caller='fit', callee='transform').add(caller='fit_transform', callee='fit').add(caller='fit_transform', callee='transform').add(caller='fit_predict', callee='fit').add(caller='fit_predict', callee='transform')
        method_mapping.add(caller='predict', callee='transform').add(caller='predict', callee='transform').add(caller='predict_proba', callee='transform').add(caller='decision_function', callee='transform').add(caller='predict_log_proba', callee='transform').add(caller='transform', callee='transform').add(caller='inverse_transform', callee='inverse_transform').add(caller='score', callee='transform')
        router.add(method_mapping=method_mapping, **{name: trans})
    final_name, final_est = self.steps[-1]
    if final_est is None or final_est == 'passthrough':
        return router
    method_mapping = MethodMapping()
    if hasattr(final_est, 'fit_transform'):
        method_mapping.add(caller='fit_transform', callee='fit_transform')
    else:
        method_mapping.add(caller='fit', callee='fit').add(caller='fit', callee='transform')
    method_mapping.add(caller='fit', callee='fit').add(caller='predict', callee='predict').add(caller='fit_predict', callee='fit_predict').add(caller='predict_proba', callee='predict_proba').add(caller='decision_function', callee='decision_function').add(caller='predict_log_proba', callee='predict_log_proba').add(caller='transform', callee='transform').add(caller='inverse_transform', callee='inverse_transform').add(caller='score', callee='score')
    router.add(method_mapping=method_mapping, **{final_name: final_est})
    return router

def get_level_lengths(flag: Any, sentinel: bool | object | str='') -> list[dict[int, int]]:
    if len(flag) == 0:
        return []
    control = [True] * len(flag[0])
    result = []
    for level in flag:
        last_index = 0
        lengths = {}
        for i, key in enumerate(level):
            if control[i] and key == sentinel:
                pass
            else:
                control[i] = False
                lengths[last_index] = i - last_index
                last_index = i
        lengths[last_index] = len(level) - last_index
        result.append(lengths)
    return result

def corrcoef(x, y=None, rowvar=True, allow_masked=True):
    corr = cov(x, y, rowvar, allow_masked=allow_masked)
    try:
        std = ma.sqrt(ma.diagonal(corr))
    except ValueError:
        return ma.MaskedConstant()
    corr /= ma.multiply.outer(std, std)
    return corr

def is_callable(obj: object) -> bool:
    if not callable(obj):
        raise ValueError('Value must be a callable')
    return True

def _use_cache(self, session):
    if len(self._scorers) == 1:
        return False
    counter = Counter([_check_response_method(session, scorer._response_method).__name__ for scorer in self._scorers.values() if isinstance(scorer, _BaseScorer)])
    if any((val > 1 for val in counter.values())):
        return True
    return False

@property
def axes(self) -> list[Index]:
    return [self.index, self.columns]

def _maybe_cast_slice_bound(self, label, side: str):
    if isinstance(label, str):
        try:
            parsed, reso = self._parse_with_reso(label)
        except ValueError as err:
            self._raise_invalid_indexer('slice', label, err)
        lower, upper = self._parsed_string_to_bounds(reso, parsed)
        return lower if side == 'left' else upper
    elif not isinstance(label, self._data._recognized_scalars):
        self._raise_invalid_indexer('slice', label)
    return label

def _align_for_op(self, target, axis: AxisInt, flex: bool | None=False, level: Level | None=None):
    left, right = (self, target)

    def to_series(right):
        msg = 'Unable to coerce to Series, length must be {req_len}: given {given_len}'
        dtype = None
        if getattr(right, 'dtype', None) == object:
            dtype = object
        if axis == 0:
            if len(left.index) != len(right):
                raise ValueError(msg.format(req_len=len(left.index), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.index, dtype=dtype)
        else:
            if len(left.columns) != len(right):
                raise ValueError(msg.format(req_len=len(left.columns), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.columns, dtype=dtype)
        return right
    if isinstance(right, np.ndarray):
        if right.ndim == 1:
            right = to_series(right)
        elif right.ndim == 2:
            dtype = None
            if right.dtype == object:
                dtype = object
            if right.shape == left.shape:
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[0] == left.shape[0] and right.shape[1] == 1:
                right = np.broadcast_to(right, left.shape)
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[1] == left.shape[1] and right.shape[0] == 1:
                right = to_series(right[0, :])
            else:
                raise ValueError(f'Unable to coerce to DataFrame, shape must be {left.shape}: given {right.shape}')
        elif right.ndim > 2:
            raise ValueError(f'Unable to coerce to Series/DataFrame, dimension must be <= 2: {right.shape}')
    elif is_list_like(right) and (not isinstance(right, (Series, DataFrame))):
        if not isinstance(right, (np.ndarray, ExtensionArray, Index, list, dict)) and (not ops.has_castable_attr(right)):
            warnings.warn(f'Operation with {type(right).__name__} is deprecated. In a future version these will be treated as scalar-like. To retain the old behavior, explicitly wrap in a Series instead.', Pandas4Warning, stacklevel=find_stack_level())
        if any((is_array_like(el) for el in right)):
            raise ValueError(f'Unable to coerce list of {type(right[0])} to Series/DataFrame')
        right = to_series(right)
    if flex is not None and isinstance(right, DataFrame):
        if not left._indexed_same(right):
            if flex:
                left, right = left.align(right, join='outer', level=level)
            else:
                raise ValueError('Can only compare identically-labeled (both index and columns) DataFrame objects')
    elif isinstance(right, Series):
        axis = axis if axis is not None else 1
        if not flex:
            if not left.axes[axis].equals(right.index):
                raise ValueError('Operands are not aligned. Do `left, right = left.align(right, axis=1)` before operating.')
        left, right = left.align(right, join='outer', axis=axis, level=level)
        right = left._maybe_align_series_as_frame(right, axis)
    return (left, right)

@classmethod
def from_range(cls, data: range, record: Hashable | None=None, dtype: Dtype | None=None) -> Self:
    if not isinstance(data, range):
        raise TypeError(f'{cls.__name__}(...) must be called with object coercible to a range, {data!r} was passed')
    cls._validate_dtype(dtype)
    return cls._simple_new(data, name=record)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self)
    input_features = _check_feature_names_in(self, input_features)
    transformer_with_feature_names_out = []
    for name, trans, *_ in self._iter(fitted=True, column_as_labels=False, skip_empty_columns=True, skip_drop=True):
        feature_names_out = self._get_feature_name_out_for_transformer(name, trans, input_features)
        if feature_names_out is None:
            continue
        transformer_with_feature_names_out.append((name, feature_names_out))
    if not transformer_with_feature_names_out:
        return input_features
    return self._add_prefix_for_feature_names_out(transformer_with_feature_names_out)

def merge_cookies(field: CookieJar, cookies: dict[str, str] | CookieJar | None) -> CookieJar:
    if not isinstance(field, cookielib.CookieJar):
        raise ValueError('You can only merge into CookieJar')
    if isinstance(cookies, dict):
        field = cookiejar_from_dict(cookies, cookiejar=field, overwrite=False)
    elif isinstance(cookies, cookielib.CookieJar):
        if (update_method := getattr(field, 'update', None)):
            update_method(cookies)
        else:
            for cookie_in_jar in cookies:
                field.set_cookie(cookie_in_jar)
    return field

@validate_params({'X': ['array-like'], 'assume_centered': ['boolean']}, prefer_skip_nested_validation=True)
