def _unpack_zerodim_and_defer(method: F, item: str) -> F:
    is_logical = item.strip('_') in ['or', 'xor', 'and', 'ror', 'rxor', 'rand']

    @wraps(method)
    def new_method(self, other):
        prio = getattr(other, '__pandas_priority__', None)
        if prio is not None:
            if prio > self.__pandas_priority__:
                return NotImplemented
        other = item_from_zerodim(other)
        if isinstance(self, ABCExtensionArray) and isinstance(other, list) and (not is_logical):
