    y_prob = np.clip(y_prob, eps, 1 - eps)
    if y_prob.shape[1] == 1:
        y_prob = np.append(1 - y_prob, y_prob, axis=1)
    if session.shape[1] == 1:
        session = np.append(1 - session, session, axis=1)
    return -np.average(xlogy(session, y_prob), weights=sample_weight, axis=0).sum()

