def compute_dict_like(self, op_name: Literal['agg', 'apply'], selected_obj: Series | DataFrame, selection: Hashable | Sequence[Hashable], kwargs: dict[str, Any]) -> tuple[list[Hashable], list[Any]]:
    from pandas.core.groupby.generic import DataFrameGroupBy, SeriesGroupBy
    obj = self.obj
    is_groupby = isinstance(obj, (DataFrameGroupBy, SeriesGroupBy))
    func = cast('AggFuncTypeDict', self.func)
    func = self.normalize_dictlike_arg(op_name, selected_obj, func)
    is_non_unique_col = selected_obj.ndim == 2 and selected_obj.columns.nunique() < len(selected_obj.columns)
    if selected_obj.ndim == 1:
        colg = obj._gotitem(selection, ndim=1)
        results = [getattr(colg, op_name)(how, **kwargs) for _, how in func.items()]
        keys = list(func.keys())
    elif not is_groupby and is_non_unique_col:
        results = []
        keys = []
        for key, how in func.items():
            indices = selected_obj.columns.get_indexer_for([key])
            labels = selected_obj.columns.take(indices)
            label_to_indices = defaultdict(list)
            for index, label in zip(indices, labels, strict=True):
                label_to_indices[label].append(index)
            key_data = [getattr(selected_obj._ixs(indice, axis=1), op_name)(how, **kwargs) for label, indices in label_to_indices.items() for indice in indices]
            keys += [key] * len(key_data)
            results += key_data
    elif is_groupby:
        df = selected_obj
        results, keys = ([], [])
        for key, how in func.items():
            cols = df[key]
            if cols.ndim == 1:
                series = obj._gotitem(key, ndim=1, subset=cols)
                results.append(getattr(series, op_name)(how, **kwargs))
                keys.append(key)
            else:
                for _, col in cols.items():
                    series = obj._gotitem(key, ndim=1, subset=col)
                    results.append(getattr(series, op_name)(how, **kwargs))
                    keys.append(key)
    else:
        results = [getattr(obj._gotitem(key, ndim=1), op_name)(how, **kwargs) for key, how in func.items()]
        keys = list(func.keys())
    return (keys, results)

def url_for(self, /, endpoint: str, *, _anchor: str | None=None, _method: str | None=None, _scheme: str | None=None, _external: bool | None=None, **values: t.Any) -> str:
    if (ctx := _cv_app.get(None)) is not None and ctx.has_request:
        url_adapter = ctx.url_adapter
        blueprint_name = ctx.request.blueprint
        if endpoint[:1] == '.':
            if blueprint_name is not None:
                endpoint = f'{blueprint_name}{endpoint}'
            else:
                endpoint = endpoint[1:]
        if _external is None:
            _external = _scheme is not None
    else:
        if ctx is not None:
            url_adapter = ctx.url_adapter
        else:
            url_adapter = self.create_url_adapter(None)
        if url_adapter is None:
            raise RuntimeError("Unable to build URLs outside an active request without 'SERVER_NAME' configured. Also configure 'APPLICATION_ROOT' and 'PREFERRED_URL_SCHEME' as needed.")
        if _external is None:
            _external = True
    if _scheme is not None and (not _external):
        raise ValueError("When specifying '_scheme', '_external' must be True.")
    self.inject_url_defaults(endpoint, values)
    try:
        rv = url_adapter.build(endpoint, values, method=_method, url_scheme=_scheme, force_external=_external)
    except BuildError as error:
        values.update(_anchor=_anchor, _method=_method, _scheme=_scheme, _external=_external)
        return self.handle_url_build_error(error, endpoint, values)
    if _anchor is not None:
        _anchor = _url_quote(_anchor, safe="%!#$&'()*+,/:;=?@")
        rv = f'{rv}#{_anchor}'
    return rv

