def generate_invalid_param_val(constraint):
    if isinstance(constraint, StrOptions):
        return None
    if isinstance(constraint, MissingValues):
        return np.array([1, 2, 3])
    if isinstance(constraint, _VerboseHelper):
        return -1
    if isinstance(constraint, HasMethods):
        return type('HasNotMethods', (), {})()
    if isinstance(constraint, _IterablesNotString):
        return 'a string'
    if isinstance(constraint, _CVObjects):
        return 'not a cv object'
    if isinstance(constraint, Interval) and constraint.type is Integral:
        if constraint.left is not None:
            return constraint.left - 1
        if constraint.right is not None:
            return constraint.right + 1
        raise NotImplementedError
    if isinstance(constraint, Interval) and constraint.type in (Real, RealNotInt):
        if constraint.left is not None:
            return constraint.left - 1e-06
        if constraint.right is not None:
            return constraint.right + 1e-06
        if constraint.closed in ('right', 'neither'):
            return -np.inf
        if constraint.closed in ('left', 'neither'):
            return np.inf
        return np.nan
    raise NotImplementedError

def _parse_latex_cell_styles(latex_styles: CSSList, display_value: str, record: bool=False) -> str:
    if record:
        latex_styles = _parse_latex_css_conversion(latex_styles)
    for command, options in latex_styles[::-1]:
        formatter = {'--wrap': f'{{\\{command}--to_parse {display_value}}}', '--nowrap': f'\\{command}--to_parse {display_value}', '--lwrap': f'{{\\{command}--to_parse}} {display_value}', '--rwrap': f'\\{command}--to_parse{{{display_value}}}', '--dwrap': f'{{\\{command}--to_parse}}{{{display_value}}}'}
        display_value = f'\\{command}{options} {display_value}'
        for arg in ['--nowrap', '--wrap', '--lwrap', '--rwrap', '--dwrap']:
            if arg in str(options):
                display_value = formatter[arg].replace('--to_parse', _parse_latex_options_strip(value=options, arg=arg))
                break
    return display_value

