def max(self, axis: AxisInt | None=None, skipna: bool=True, *args: Any, **kwargs: Any) -> object:
    nv.validate_max(args, kwargs)
    nv.validate_minmax_axis(axis)
    if not len(self):
        return self._na_value
    if len(self) and self.is_monotonic_increasing:
        last = self[-1]
        if not isna(last):
            return maybe_unbox_numpy_scalar(last)
    if not self._is_multi and self.hasnans:
        mask = self._isnan
        if not skipna or mask.all():
            return maybe_unbox_numpy_scalar(self._na_value)
    if not self._is_multi and (not isinstance(self._values, np.ndarray)):
        return self._values._reduce(name='max', skipna=skipna)
    return maybe_unbox_numpy_scalar(nanops.nanmax(self._values, skipna=skipna))

def _generate_string(self, entry):
    linewidth = np.get_printoptions().get('linewidth', 75)
    if linewidth < 1:
        linewidth = 1
    out = pu.format_float(self.coef[0])
    off, scale = self.mapparms()
    scaled_symbol, needs_parens = self._format_term(pu.format_float, off, scale)
    if needs_parens:
        scaled_symbol = '(' + scaled_symbol + ')'
    for i, coef in enumerate(self.coef[1:]):
        out += ' '
        power = str(i + 1)
        try:
            if coef >= 0:
                next_term = '+ ' + pu.format_float(coef, parens=True)
            else:
                next_term = '- ' + pu.format_float(-coef, parens=True)
        except TypeError:
            next_term = f'+ {coef}'
        next_term += entry(power, scaled_symbol)
        line_len = len(out.split('\n')[-1]) + len(next_term)
        if i < len(self.coef[1:]) - 1:
            line_len += 2
        if line_len >= linewidth:
            next_term = next_term.replace(' ', '\n', 1)
        out += next_term
    return out

def open(self, mode: str='a', **kwargs) -> None:
    tables = _tables()
    if self._mode != mode:
        if self._mode in ['a', 'w'] and mode in ['r', 'r+']:
            pass
        elif mode in ['w']:
            if self.is_open:
                raise PossibleDataLossError(f'Re-opening the file [{self._path}] with mode [{self._mode}] will delete the current file!')
        self._mode = mode
    if self.is_open:
        self.close()
    if self._complevel and self._complevel > 0:
        self._filters = _tables().Filters(self._complevel, self._complib, fletcher32=self._fletcher32)
    if _table_file_open_policy_is_strict and self.is_open:
        msg = 'Cannot open HDF5 file, which is already opened, even in read-only mode.'
        raise ValueError(msg)
    self._handle = tables.open_file(self._path, self._mode, **kwargs)

