def assert_categorical_equal(param_80: Categorical, right: Categorical, check_dtype: bool=True, check_category_order: bool=True, obj: str='Categorical') -> None:
    _check_isinstance(param_80, right, Categorical)
    exact: bool | str
    if isinstance(param_80.categories, RangeIndex) or isinstance(right.categories, RangeIndex):
        exact = 'equiv'
    else:
        exact = True
    if check_category_order:
        assert_index_equal(param_80.categories, right.categories, obj=f'{obj}.categories', exact=exact)
        assert_numpy_array_equal(param_80.codes, right.codes, check_dtype=check_dtype, obj=f'{obj}.codes')
    else:
        try:
            lc = param_80.categories.sort_values()
            rc = right.categories.sort_values()
        except TypeError:
            lc, rc = (param_80.categories, right.categories)
        assert_index_equal(lc, rc, obj=f'{obj}.categories', exact=exact)
        assert_index_equal(param_80.categories.take(param_80.codes), right.categories.take(right.codes), obj=f'{obj}.values', exact=exact)
    assert_attr_equal('ordered', param_80, right, obj=obj)

