def __call__(self, x, source: int | None=0) -> str:
    fmt = '%H:%M:%S.%f'
    s = int(x)
    msus = round((x - s) * 10 ** 6)
    ms = msus // 1000
    us = msus % 1000
    m, s = divmod(s, 60)
    h, m = divmod(m, 60)
    _, h = divmod(h, 24)
    if us != 0:
        return pydt.time(h, m, s, msus).strftime(fmt)
    elif ms != 0:
        return pydt.time(h, m, s, msus).strftime(fmt)[:-3]
    elif s != 0:
        return pydt.time(h, m, s).strftime('%H:%M:%S')
    return pydt.time(h, m).strftime('%H:%M')

def _num2excel(self, index: int) -> str:
    if index < 0:
        raise ValueError(f'Index cannot be negative: {index}')
    column_name = ''
    while index > 0 or not column_name:
        index, remainder = divmod(index, 26)
        column_name = chr(65 + remainder) + column_name
    return column_name

