        _fill_diagonal(ret, 0, xp=xp)
    return ret.T

@staticmethod
def _make_ea_row_builder(col_arrays: list, dtype: ExtensionDtype, cls: type[ExtensionArray]) -> Callable[[int], ExtensionArray]:
    homogeneous = all((col_arr.dtype == dtype for col_arr in col_arrays))
    if homogeneous and isinstance(dtype, BaseMaskedDtype):
        col_data = [col_arr._data for col_arr in col_arrays]
        col_masks = [col_arr._mask for col_arr in col_arrays]
        np_dtype = dtype.numpy_dtype
        masked_cls = cast('type[BaseMaskedArray]', cls)

        def build_row(row_idx: int) -> ExtensionArray:
            data = np.array([cd[row_idx] for cd in col_data], dtype=np_dtype)
            mask = np.array([cm[row_idx] for cm in col_masks], dtype=np.bool_)
            return masked_cls._simple_new(data, mask)
    elif homogeneous and isinstance(dtype, ArrowDtype):
        import pyarrow as pa
        pa_arrays = [col_arr._pa_array for col_arr in col_arrays]
        pa_type = dtype.pyarrow_dtype
        arrow_cls = cast('type[ArrowExtensionArray]', cls)

        def build_row(row_idx: int) -> ExtensionArray:
            pa_scalars = [pa_col[row_idx] for pa_col in pa_arrays]
            return arrow_cls(pa.array(pa_scalars, type=pa_type))
    else:

        def build_row(row_idx: int) -> ExtensionArray:
            row_data = np.array([col_arr[row_idx] for col_arr in col_arrays], dtype=object)
            return cls._from_sequence(row_data, dtype=dtype)
    return build_row

def inplace_swap_row_csr(X, m, n):
    for t in [m, n]:
        if isinstance(t, np.ndarray):
            raise TypeError('m and n should be valid integers')
    if m < 0:
        m += X.shape[0]
    if n < 0:
        n += X.shape[0]
    if m > n:
        m, n = (n, m)
    indptr = X.indptr
    m_start = indptr[m]
    m_stop = indptr[m + 1]
    n_start = indptr[n]
    n_stop = indptr[n + 1]
    nz_m = m_stop - m_start
    nz_n = n_stop - n_start
    if nz_m != nz_n:
        X.indptr[m + 2:n] += nz_n - nz_m
        X.indptr[m + 1] = m_start + nz_n
        X.indptr[n] = n_stop - nz_m
    X.indices = np.concatenate([X.indices[:m_start], X.indices[n_start:n_stop], X.indices[m_stop:n_start], X.indices[m_start:m_stop], X.indices[n_stop:]])
    X.data = np.concatenate([X.data[:m_start], X.data[n_start:n_stop], X.data[m_stop:n_start], X.data[m_start:m_stop], X.data[n_stop:]])

def _normed_hermite_n(param_65, n):
    if n == 0:
        return np.full(param_65.shape, 1 / np.sqrt(np.sqrt(np.pi)))
    c0 = 0.0
    c1 = 1.0 / np.sqrt(np.sqrt(np.pi))
    nd = float(n)
    for i in range(n - 1):
        tmp = c0
        c0 = -c1 * np.sqrt((nd - 1.0) / nd)
        c1 = tmp + c1 * param_65 * np.sqrt(2.0 / nd)
        nd = nd - 1.0
    return c0 + c1 * param_65 * np.sqrt(2)

