def to_orc(df: DataFrame, file_path: FilePath | WriteBuffer[bytes] | None=None, *, engine: Literal['pyarrow']='pyarrow', index: bool | None=None, engine_kwargs: dict[str, Any] | None=None) -> bytes | None:
    if index is None:
        index = df.index.names[0] is not None
    if engine_kwargs is None:
        engine_kwargs = {}
    if not df.index.equals(default_index(len(df))):
        raise ValueError('orc does not support serializing a non-default index for the index; you can .reset_index() to make the index into column(s)')
    if df.index.name is not None:
        raise ValueError('orc does not serialize index meta-data on a default index')
    if engine != 'pyarrow':
        raise ValueError("engine must be 'pyarrow'")
    pa = import_optional_dependency('pyarrow')
    orc = import_optional_dependency('pyarrow.orc')
    was_none = file_path is None
    if was_none:
        file_path = io.BytesIO()
    assert file_path is not None
    with get_handle(file_path, 'wb', is_text=False) as handles:
        try:
            orc.write_table(pa.Table.from_pandas(df, preserve_index=index), handles.handle, **engine_kwargs)
        except (TypeError, pa.ArrowNotImplementedError) as e:
            raise NotImplementedError('The dtype of one or more columns is not supported yet.') from e
    if was_none:
        assert isinstance(file_path, io.BytesIO)
        return file_path.getvalue()
    return None

