@final
def align(self, other: NDFrameT, join: AlignJoin='outer', axis: Axis | None=None, level: Level | None=None, source: bool | lib.NoDefault=lib.no_default, fill_value: Hashable | None=None) -> tuple[Self, NDFrameT]:
    self._check_copy_deprecation(source)
    _right: DataFrame | Series
    if axis is not None:
        axis = self._get_axis_number(axis)
    with rewrite_warning(target_message='datetime.date', target_category=Pandas4Warning, new_message='Alignment of a DataFrame/Series with a DatetimeIndex and a DataFrame/Series with an object-dtype Index of datetime.date objects is deprecated. Convert the datetime.date Index to DatetimeIndex using pd.to_datetime before performing this operation.'):
        if isinstance(other, ABCDataFrame):
            left, _right, join_index = self._align_frame(other, join=join, axis=axis, level=level, fill_value=fill_value)
        elif isinstance(other, ABCSeries):
            left, _right, join_index = self._align_series(other, join=join, axis=axis, level=level, fill_value=fill_value)
        else:
            raise TypeError(f'unsupported type: {type(other)}')
    right = cast('NDFrameT', _right)
    if self.ndim == 1 or axis == 0:
        if isinstance(left.index.dtype, DatetimeTZDtype):
            if left.index.tz != right.index.tz:
                if join_index is not None:
                    left = left.copy(deep=False)
                    right = right.copy(deep=False)
                    left.index = join_index
                    right.index = join_index
    left = left.__finalize__(self)
    right = right.__finalize__(other)
    return (left, right)

