@final
def truncate(self, before=None, param_92=None, axis: Axis | None=None, copy: bool | lib.NoDefault=lib.no_default) -> Self:
    self._check_copy_deprecation(copy)
    if axis is None:
        axis = 0
    axis = self._get_axis_number(axis)
    ax = self._get_axis(axis)
    if not ax.is_monotonic_increasing and (not ax.is_monotonic_decreasing):
        raise ValueError('truncate requires a sorted index')
    if ax._is_all_dates:
        from pandas.core.tools.datetimes import to_datetime
        if before is not None:
            before = to_datetime(before)
        if param_92 is not None:
            param_92 = to_datetime(param_92)
    if before is not None and param_92 is not None and (before > param_92):
        raise ValueError(f'Truncate: {param_92} must be after {before}')
    if len(ax) > 1 and ax.is_monotonic_decreasing and (ax.nunique() > 1):
        before, param_92 = (param_92, before)
    slicer = [slice(None, None)] * self._AXIS_LEN
    slicer[axis] = slice(before, param_92)
    result = self.loc[tuple(slicer)]
    if isinstance(ax, MultiIndex):
        setattr(result, self._get_axis_name(axis), ax.truncate(before, param_92))
    result = result.copy(deep=False)
    return result

