    if fit_dataframe_and_transform_dataframe:
        named_transformers = self.named_transformers_
        non_dropped_indices = [ind for name, ind in self._transformer_to_input_indices.items() if name in named_transformers and named_transformers[name] != 'drop']
        all_indices = set(chain(*non_dropped_indices))
        all_names = set((self.feature_names_in_[ind] for ind in all_indices))
        diff = all_names - set(column_names)
        if diff:
            raise ValueError(f'columns are missing: {diff}')
    else:
        _check_n_features(self, X, reset=False)
    routed_params = process_routing(self, 'transform', **params)
    Xs = self._call_func_on_transformers(X, None, _transform_one, column_as_labels=fit_dataframe_and_transform_dataframe, routed_params=routed_params)
    self._validate_output(Xs)
    if not Xs:
        return np.zeros((n_samples, 0))
    return self._hstack(list(Xs), n_samples=n_samples)

@staticmethod
def maintainers_add_info(context):
    repeated = set(context['maintainers']['active']) & set(context['maintainers']['inactive'])
    if repeated:
        raise ValueError(f'Maintainers {repeated} are both active and inactive')
    maintainers_info = {}
    for user in context['maintainers']['active'] + context['maintainers']['inactive'] + context['maintainers']['pandasstubs']:
        resp = requests.get(f'https://api.github.com/users/{user}', headers=GITHUB_API_HEADERS, timeout=5)
        if resp.status_code == 403:
            sys.stderr.write('WARN: GitHub API quota exceeded when fetching maintainers\n')
            resp_bkp = requests.get(context['main']['production_url'] + 'maintainers.json', timeout=5)
            resp_bkp.raise_for_status()
            maintainers_info = resp_bkp.json()
            break
        resp.raise_for_status()
        maintainers_info[user] = resp.json()
    context['maintainers']['github_info'] = maintainers_info
    with open(pathlib.Path(context['target_path']) / 'maintainers.json', 'w', encoding='utf-8') as f:
        json.dump(maintainers_info, f)
    return context

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, item, y=None):
    item = self._check_non_neg_array(item, reset_n_features=True, whom='LatentDirichletAllocation.fit')
    n_samples, n_features = item.shape
    max_iter = self.max_iter
    evaluate_every = self.evaluate_every
    learning_method = self.learning_method
    batch_size = self.batch_size
    self._init_latent_vars(n_features, dtype=item.dtype)
    last_bound = None
    n_jobs = effective_n_jobs(self.n_jobs)
    with Parallel(n_jobs=n_jobs, verbose=max(0, self.verbose - 1)) as parallel:
        for i in range(max_iter):
            if learning_method == 'online':
                for idx_slice in gen_batches(n_samples, batch_size):
                    self._em_step(item[idx_slice, :], total_samples=n_samples, batch_update=False, parallel=parallel)
            else:
                self._em_step(item, total_samples=n_samples, batch_update=True, parallel=parallel)
            if evaluate_every > 0 and (i + 1) % evaluate_every == 0:
                doc_topics_distr, _ = self._e_step(item, cal_sstats=False, random_init=False, parallel=parallel)
                bound = self._perplexity_precomp_distr(item, doc_topics_distr, sub_sampling=False)
                if self.verbose:
                    print('iteration: %d of max_iter: %d, perplexity: %.4f' % (i + 1, max_iter, bound))
                if last_bound and abs(last_bound - bound) < self.perp_tol:
                    break
                last_bound = bound
            elif self.verbose:
                print('iteration: %d of max_iter: %d' % (i + 1, max_iter))
            self.n_iter_ += 1
    doc_topics_distr, _ = self._e_step(item, cal_sstats=False, random_init=False, parallel=parallel)
    self.bound_ = self._perplexity_precomp_distr(item, doc_topics_distr, sub_sampling=False)
    return self

