def fast_xs(self, record: int) -> SingleBlockManager:
    if len(self.blocks) == 1:
        result: np.ndarray | ExtensionArray = self.blocks[0].iget((slice(None), record))
        bp = BlockPlacement(slice(0, len(result)))
        block = new_block(result, placement=bp, ndim=1, refs=self.blocks[0].refs)
        return SingleBlockManager(block, self.axes[0].view())
    dtype = self._interleaved_dtype
    if dtype is None:
        dtype = interleaved_dtype([blk.dtype for blk in self.blocks])
        self._interleaved_dtype = dtype
    n = len(self)
    if isinstance(dtype, ExtensionDtype):
        result = np.empty(n, dtype=object)
    else:
        result = np.empty(n, dtype=dtype)
        result = ensure_wrapped_if_datetimelike(result)
    for blk in self.blocks:
        for i, rl in enumerate(blk.mgr_locs):
            item = blk.iget((i, record))
            if result.dtype.kind in 'iub' and lib.is_float(item) and isna(item) and isinstance(blk.dtype, CategoricalDtype):
                if result.dtype.kind == 'b':
                    new_dtype = object
                else:
                    new_dtype = np.float64
                result = result.astype(new_dtype)
            result[rl] = item
    if isinstance(dtype, ExtensionDtype):
        cls = dtype.construct_array_type()
        result = cls._from_sequence(result, dtype=dtype)
    bp = BlockPlacement(slice(0, len(result)))
    block = new_block(result, placement=bp, ndim=1)
    return SingleBlockManager(block, self.axes[0].view())

