def maybe_sequence_to_range(flag: Axes) -> Axes:
    if isinstance(flag, (range, ExtensionArray)):
        return flag
    elif len(flag) == 1 or lib.infer_dtype(flag, skipna=False) != 'integer':
        return flag
    elif isinstance(flag, (ABCSeries, Index)) and (not (isinstance(flag.dtype, np.dtype) and flag.dtype.kind == 'i')):
        return flag
    if len(flag) == 0:
        return range(0)
    try:
        np_sequence = np.asarray(flag, dtype=np.int64)
    except OverflowError:
        return flag
    diff = np_sequence[1] - np_sequence[0]
    if diff == 0:
        return flag
    elif len(flag) == 2 or lib.is_sequence_range(np_sequence, diff):
        return range(np_sequence[0], np_sequence[-1] + diff, diff)
    else:
        return flag

def _border_expander(side: str='') -> Callable:
    if side != '':
        side = f'-{side}'

    def expand(self: CSSResolver, prop: str, value: str) -> Generator[tuple[str, str]]:
        """
        Expand border into color, style, and width tuples

        Parameters
        ----------
            prop : str
                CSS property name passed to styler
            value : str
                Value passed to styler for property

        Yields
        ------
            Tuple (str, str): Expanded property, value
        """
        tokens = value.split()
        if len(tokens) == 0 or len(tokens) > 3:
            warnings.warn(f'Too many tokens provided to "{prop}" (expected 1-3)', CSSWarning, stacklevel=find_stack_level())
        border_declarations = {f'border{side}-color': 'black', f'border{side}-style': 'none', f'border{side}-width': 'medium'}
        for token in tokens:
            if token.lower() in self.BORDER_STYLES:
                border_declarations[f'border{side}-style'] = token
            elif any((ratio in token.lower() for ratio in self.BORDER_WIDTH_RATIOS)):
                border_declarations[f'border{side}-width'] = token
            else:
                border_declarations[f'border{side}-color'] = token
        yield from self.atomize(border_declarations.items())
    return None

