def construct_from_string(cls, cache: str_type) -> DatetimeTZDtype:
    if not isinstance(cache, str):
        raise TypeError(f"'construct_from_string' expects a string, got {type(cache)}")
    msg = f"Cannot construct a 'DatetimeTZDtype' from '{cache}'"
    match = cls._match.match(cache)
    if match:
