def _safe_repr(object, param_4, maxlevels, level, changed_only=False):
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if not object:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in param_4)
        if objid in param_4:
            return (pprint._recursion(object), False, True)
        param_4[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for k, v in items:
            krepr, kreadable, krecur = saferepr(k, param_4, maxlevels, level, changed_only=changed_only)
            vrepr, vreadable, vrecur = saferepr(v, param_4, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del param_4[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in param_4)
        if objid in param_4:
            return (pprint._recursion(object), False, True)
        param_4[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            orepr, oreadable, orecur = _safe_repr(o, param_4, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del param_4[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in param_4)
        if objid in param_4:
            return (pprint._recursion(object), False, True)
        param_4[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for k, v in items:
            krepr, kreadable, krecur = saferepr(k, param_4, maxlevels, level, changed_only=changed_only)
            vrepr, vreadable, vrecur = saferepr(v, param_4, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del param_4[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

