        if hyperparameter.n_elements > 1:
            params[hyperparameter.name] = np.exp(index[i:i + hyperparameter.n_elements])
            i += hyperparameter.n_elements
        else:
            params[hyperparameter.name] = np.exp(index[i])
            i += 1
    if i != len(index):
        raise ValueError('theta has not the correct number of entries. Should be %d; given are %d' % (i, len(index)))
    self.set_params(**params)

