    out_shape = (len(row_idx), len(col_idx))
    out = np.empty(out_shape, dtype=dtype)
    func = _take_2d_multi_dict.get((arr.dtype.name, out.dtype.name), None)
    if func is None and arr.dtype != out.dtype:
        func = _take_2d_multi_dict.get((out.dtype.name, out.dtype.name), None)
        if func is not None:
            func = _convert_wrapper(func, out.dtype)
    if func is None and arr.dtype.kind in 'mM' and (arr.dtype == out.dtype):
        func = _view_wrapper(libalgos.take_2d_multi_int64_int64, np.int64, np.int64, fill_wrap=np.int64)
    if mask_info is not None:
        _, (row_needs, col_needs) = mask_info
        needs_fill = row_needs or col_needs
    else:
        needs_fill = True
    if func is not None:
        func(arr, indexer, out=out, fill_value=fill_value, allow_fill=needs_fill)
    else:
        _take_2d_multi_object(arr, indexer, out, fill_value=fill_value, mask_info=mask_info)
