@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    X, y = validate_data(self, X, y, copy=False, accept_sparse=['csr'], y_numeric=True, dtype=[np.float64, np.float32])
    sample_weight = _check_sample_weight(sample_weight, X)
    if self.warm_start and hasattr(self, 'coef_'):
        parameters = np.concatenate((self.coef_, [self.intercept_, self.scale_]))
    else:
        if self.fit_intercept:
            parameters = np.zeros(X.shape[1] + 2)
        else:
            parameters = np.zeros(X.shape[1] + 1)
        parameters[-1] = 1
    bounds = np.tile([-np.inf, np.inf], (parameters.shape[0], 1))
    bounds[-1][0] = np.finfo(np.float64).eps * 10
    opt_res = optimize.minimize(_huber_loss_and_gradient, parameters, method='L-BFGS-B', jac=True, args=(X, y, self.epsilon, self.alpha, sample_weight), options={'maxiter': self.max_iter, 'gtol': self.tol, **_get_additional_lbfgs_options_dict('iprint', -1)}, bounds=bounds)
    parameters = opt_res.x
    if opt_res.status == 2:
        raise ValueError('HuberRegressor convergence failed: l-BFGS-b solver terminated with %s' % opt_res.message)
    self.n_iter_ = _check_optimize_result('lbfgs', opt_res, self.max_iter)
    self.scale_ = parameters[-1]
    if self.fit_intercept:
        self.intercept_ = parameters[-2]
    else:
        self.intercept_ = 0.0
    self.coef_ = parameters[:X.shape[1]]
    residual = np.abs(y - safe_sparse_dot(X, self.coef_) - self.intercept_)
    self.outliers_ = residual > self.scale_ * self.epsilon
    return self

