def class_distribution(y, sample_weight=None):
    classes = []
    n_classes = []
    class_prior = []
    n_samples, n_outputs = y.shape
    if sample_weight is not None:
        sample_weight = np.asarray(sample_weight)
    if issparse(y):
        y = y.tocsc()
        y_nnz = np.diff(y.indptr)
        for k in range(n_outputs):
            col_nonzero = y.indices[y.indptr[k]:y.indptr[k + 1]]
            if sample_weight is not None:
                nz_samp_weight = sample_weight[col_nonzero]
                zeros_samp_weight_sum = np.sum(sample_weight) - np.sum(nz_samp_weight)
            else:
                nz_samp_weight = None
                zeros_samp_weight_sum = y.shape[0] - y_nnz[k]
            classes_k, y_k = np.unique(y.data[y.indptr[k]:y.indptr[k + 1]], return_inverse=True)
            class_prior_k = np.bincount(y_k, weights=nz_samp_weight)
            if 0 in classes_k:
                class_prior_k[classes_k == 0] += zeros_samp_weight_sum
            if 0 not in classes_k and y_nnz[k] < y.shape[0]:
                classes_k = np.insert(classes_k, 0, 0)
                class_prior_k = np.insert(class_prior_k, 0, zeros_samp_weight_sum)
            classes.append(classes_k)
            n_classes.append(classes_k.shape[0])
            class_prior.append(class_prior_k / class_prior_k.sum())
    else:
        for k in range(n_outputs):
            classes_k, y_k = np.unique(y[:, k], return_inverse=True)
            classes.append(classes_k)
            n_classes.append(classes_k.shape[0])
            class_prior_k = np.bincount(y_k, weights=sample_weight)
            class_prior.append(class_prior_k / class_prior_k.sum())
    return (classes, n_classes, class_prior)

def _repr_fits_horizontal_(self) -> bool:
    width, height = console.get_console_size()
    max_columns = config['display']['max_columns']
    nb_columns = len(self.columns)
    if max_columns and nb_columns > max_columns or (width and nb_columns > width // 2):
        return False
    if width is None or not console.in_interactive_session():
        return True
    if config['display']['width'] is not None or console.in_ipython_frontend():
        max_rows = 1
    else:
        max_rows = config['display']['max_rows']
    buf = StringIO()
    d = self
    if max_rows is not None:
        d = d.iloc[:min(max_rows, len(d))]
    else:
        return True
    d.to_string(buf=buf)
    value = buf.getvalue()
    repr_width = max((len(line) for line in value.split('\n')))
    return repr_width < width

