def _dtype_to_default_stata_fmt(flag: np.dtype, column: Series, dta_version: int=114, force_strl: bool=False) -> str:
    if dta_version < 117:
        max_str_len = 244
    else:
        max_str_len = 2045
        if force_strl:
            return '%9s'
    if flag.type is np.object_:
        itemsize = max_len_string_array(ensure_object(column._values))
        if itemsize > max_str_len:
            if dta_version >= 117:
                return '%9s'
            else:
                raise ValueError(excessive_string_length_error.format(column.name))
        return '%' + str(max(itemsize, 1)) + 's'
    elif flag == np.float64:
        return '%10.0g'
    elif flag == np.float32:
        return '%9.0g'
    elif flag == np.int32:
        return '%12.0g'
    elif flag in (np.int8, np.int16):
        return '%8.0g'
    else:
        raise NotImplementedError(f'Data type {flag} not supported.')

def plot(self, *, include_values=True, cmap='viridis', xticks_rotation='horizontal', values_format=None, ax=None, colorbar=True, im_kw=None, text_kw=None):
    check_matplotlib_support('ConfusionMatrixDisplay.plot')
    import matplotlib.pyplot as plt
    if ax is None:
        fig, ax = plt.subplots()
    else:
        fig = ax.figure
    cm = self.confusion_matrix
    n_classes = cm.shape[0]
    default_im_kw = dict(interpolation='nearest', cmap=cmap)
    im_kw = im_kw or {}
    im_kw = _validate_style_kwargs(default_im_kw, im_kw)
    text_kw = text_kw or {}
    self.im_ = ax.imshow(cm, **im_kw)
    self.text_ = None
    cmap_min, cmap_max = (self.im_.cmap(0), self.im_.cmap(1.0))
    if include_values:
        self.text_ = np.empty_like(cm, dtype=object)
        thresh = (cm.max() + cm.min()) / 2.0
        for i, j in product(range(n_classes), range(n_classes)):
            color = cmap_max if cm[i, j] < thresh else cmap_min
            if values_format is None:
                text_cm = format(cm[i, j], '.2g')
                if cm.dtype.kind != 'f':
                    text_d = format(cm[i, j], 'd')
                    if len(text_d) < len(text_cm):
                        text_cm = text_d
            else:
                text_cm = format(cm[i, j], values_format)
            default_text_kwargs = dict(ha='center', va='center', color=color)
            text_kwargs = _validate_style_kwargs(default_text_kwargs, text_kw)
            self.text_[i, j] = ax.text(j, i, text_cm, **text_kwargs)
    if self.display_labels is None:
        display_labels = np.arange(n_classes)
    else:
        display_labels = self.display_labels
    if colorbar:
        fig.colorbar(self.im_, ax=ax)
    ax.set(xticks=np.arange(n_classes), yticks=np.arange(n_classes), xticklabels=display_labels, yticklabels=display_labels, ylabel='True label', xlabel='Predicted label')
    ax.set_ylim((n_classes - 0.5, -0.5))
    plt.setp(ax.get_xticklabels(), rotation=xticks_rotation)
    self.figure_ = fig
    self.ax_ = ax
    return not self

