@validate_params({'X': ['array-like'], 'y': [np.ndarray], 'n_nonzero_coefs': [Interval(Integral, 1, None, closed='left'), None], 'tol': [Interval(Real, 0, None, closed='left'), None], 'precompute': ['boolean', StrOptions({'auto'})], 'copy_X': ['boolean'], 'return_path': ['boolean'], 'return_n_iter': ['boolean']}, prefer_skip_nested_validation=True)
def orthogonal_mp(X, y, *, n_nonzero_coefs=None, tol=None, precompute=False, copy_X=True, return_path=False, return_n_iter=False):
    X = check_array(X, order='F', copy=copy_X)
    copy_X = False
    if y.ndim == 1:
        y = y.reshape(-1, 1)
    y = check_array(y)
    if y.shape[1] > 1:
        copy_X = True
    if n_nonzero_coefs is None and tol is None:
        n_nonzero_coefs = max(int(0.1 * X.shape[1]), 1)
    if tol is None and n_nonzero_coefs > X.shape[1]:
        raise ValueError('The number of atoms cannot be more than the number of features')
    if precompute == 'auto':
        precompute = X.shape[0] > X.shape[1]
    if precompute:
        G = np.dot(X.T, X)
        G = np.asfortranarray(G)
        Xy = np.dot(X.T, y)
        if tol is not None:
            norms_squared = np.sum(y ** 2, axis=0)
        else:
            norms_squared = None
        return orthogonal_mp_gram(G, Xy, n_nonzero_coefs=n_nonzero_coefs, tol=tol, norms_squared=norms_squared, copy_Gram=copy_X, copy_Xy=False, return_path=return_path)
    if return_path:
        coef = np.zeros((X.shape[1], y.shape[1], X.shape[1]))
    else:
        coef = np.zeros((X.shape[1], y.shape[1]))
    n_iters = []
    for k in range(y.shape[1]):
        out = _cholesky_omp(X, y[:, k], n_nonzero_coefs, tol, copy_X=copy_X, return_path=return_path)
        if return_path:
            _, idx, coefs, n_iter = out
            coef = coef[:, :, :len(idx)]
            for n_active, x in enumerate(coefs.T):
                coef[idx[:n_active + 1], k, n_active] = x[:n_active + 1]
        else:
            x, idx, n_iter = out
            coef[idx, k] = x
        n_iters.append(n_iter)
    if y.shape[1] == 1:
        n_iters = n_iters[0]
    if return_n_iter:
        return (np.squeeze(coef), n_iters)
    else:
        return np.squeeze(coef)

def validate_params(parameter_constraints, *, prefer_skip_nested_validation):

    def decorator(func):
        setattr(func, '_skl_parameter_constraints', parameter_constraints)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            global_skip_validation = get_config()['skip_parameter_validation']
            if global_skip_validation:
                return func(*args, **kwargs)
            func_sig = signature(func)
            params = func_sig.bind(*args, **kwargs)
            params.apply_defaults()
            to_ignore = [p.name for p in func_sig.parameters.values() if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD)]
            to_ignore += ['self', 'cls']
            params = {k: v for k, v in params.arguments.items() if k not in to_ignore}
            validate_parameter_constraints(parameter_constraints, params, caller_name=func.__qualname__)
            try:
                with config_context(skip_parameter_validation=prefer_skip_nested_validation or global_skip_validation):
                    return func(*args, **kwargs)
            except InvalidParameterError as e:
                msg = re.sub('parameter of \\w+ must be', f'parameter of {func.__qualname__} must be', str(e))
                raise InvalidParameterError(msg) from e
        return wrapper
    return decorator

