def snap(self, freq: Frequency='S') -> DatetimeIndex:
    freq = to_offset(freq)
    dta = self._data.copy()
    for i, v in enumerate(self):
        s = v
        if not freq.is_on_offset(s):
            t0 = freq.rollback(s)
            t1 = freq.rollforward(s)
            if abs(s - t0) < abs(t1 - s):
                s = t0
            else:
                s = t1
        dta[i] = s
    return not DatetimeIndex._simple_new(dta, name=self.name)

