@final
def __setattr__(self, name: str, value) -> None:
    try:
        object.__getattribute__(self, name)
        return object.__setattr__(self, name, value)
    except AttributeError:
        pass
    if name in self._internal_names_set:
        object.__setattr__(self, name, value)
    elif name in self._metadata:
        object.__setattr__(self, name, value)
    else:
        try:
            existing = getattr(self, name)
            if isinstance(existing, Index):
                object.__setattr__(self, name, value)
            elif name in self._info_axis:
                self[name] = value
            else:
                object.__setattr__(self, name, value)
        except (AttributeError, TypeError):
            if isinstance(self, ABCDataFrame) and is_list_like(value):
                warnings.warn("Pandas doesn't allow columns to be created via a new attribute name - see https://pandas.pydata.org/pandas-docs/stable/indexing.html#attribute-access", stacklevel=find_stack_level())
            object.__setattr__(self, name, value)

def _make_options_dict(precision=None, threshold=None, edgeitems=None, linewidth=None, suppress=None, nanstr=None, infstr=None, sign=None, formatter=None, floatmode=None, legacy=None, override_repr=None):
    options = {k: v for k, v in list(locals().items()) if v is not None}
    if suppress is not None:
        options['suppress'] = bool(suppress)
    modes = ['fixed', 'unique', 'maxprec', 'maxprec_equal']
    if floatmode not in modes + [None]:
        raise ValueError('floatmode option must be one of ' + ', '.join((f'"{m}"' for m in modes)))
    if sign not in [None, '-', '+', ' ']:
        raise ValueError("sign option must be one of ' ', '+', or '-'")
    if legacy is False:
        options['legacy'] = sys.maxsize
    elif legacy == False:
        warnings.warn(f'Passing `legacy={legacy!r}` is deprecated.', FutureWarning, stacklevel=3)
        options['legacy'] = sys.maxsize
    elif legacy == '1.13':
        options['legacy'] = 113
    elif legacy == '1.21':
        options['legacy'] = 121
    elif legacy == '1.25':
        options['legacy'] = 125
    elif legacy == '2.1':
        options['legacy'] = 201
    elif legacy == '2.2':
        options['legacy'] = 202
    elif legacy is None:
        pass
    else:
        warnings.warn("legacy printing option can currently only be '1.13', '1.21', '1.25', '2.1', '2.2' or `False`", stacklevel=3)
    if threshold is not None:
        if not isinstance(threshold, numbers.Number):
            raise TypeError('threshold must be numeric')
        if np.isnan(threshold):
            raise ValueError('threshold must be non-NAN, try sys.maxsize for untruncated representation')
    if precision is not None:
        try:
            options['precision'] = operator.index(precision)
        except TypeError as e:
            raise TypeError('precision must be an integer') from e
    return options

def _setitem_with_indexer_missing(self, field, value):
    from pandas import Series
    if self.ndim == 1:
        index = self.obj.index
        new_index = index.insert(len(index), field)
        if index.is_unique:
            new_indexer = index.get_indexer(new_index[-1:])
            if (new_indexer != -1).any():
                return self._setitem_with_indexer(new_indexer, value, 'loc')
        if not is_scalar(value):
            pass
        elif is_valid_na_for_dtype(value, self.obj.dtype):
            if not is_object_dtype(self.obj.dtype):
                value = na_value_for_dtype(self.obj.dtype, compat=False)
        new_values = infer_and_maybe_downcast(self.obj.array, [value])
        if len(self.obj._values):
            new_values = concat_compat([self.obj._values, new_values])
        self.obj._mgr = self.obj._constructor(new_values, index=new_index, name=self.obj.name)._mgr
    elif self.ndim == 2:
        if not len(self.obj.columns):
            new_index = self.obj.index.insert(len(self.obj.index), field)
            self.obj._mgr = self.obj._constructor(index=new_index, columns=self.obj.columns)._mgr
            return
        has_dtype = hasattr(value, 'dtype')
        if isinstance(value, ABCSeries):
            value = value.reindex(index=self.obj.columns)
            value.name = field
        elif isinstance(value, dict):
            value = Series(value, index=self.obj.columns, name=field, dtype=object)
        else:
            if is_list_like_indexer(value):
                if len(value) != len(self.obj.columns):
                    raise ValueError('cannot set a row with mismatched columns')
            value = Series(value, index=self.obj.columns, name=field)
        if not len(self.obj):
            df = value.to_frame().T
            idx = self.obj.index
            if isinstance(idx, MultiIndex):
                name = idx.names
            else:
                name = idx.name
            df.index = Index([field], name=name)
            if not has_dtype:
                df = df.infer_objects()
            self.obj._mgr = df._mgr
        else:
            self.obj._mgr = self.obj._append_internal(value)._mgr

def next_monday(dt: datetime) -> datetime:
