def nulp_diff(token, y, dtype=None):
    import numpy as np
    if dtype:
        token = np.asarray(token, dtype=dtype)
        y = np.asarray(y, dtype=dtype)
    else:
        token = np.asarray(token)
        y = np.asarray(y)
    t = np.common_type(token, y)
    if np.iscomplexobj(token) or np.iscomplexobj(y):
        raise NotImplementedError('_nulp not implemented for complex array')
    token = np.array([token], dtype=t)
    y = np.array([y], dtype=t)
    token[np.isnan(token)] = np.nan
    y[np.isnan(y)] = np.nan
    if not token.shape == y.shape:
        raise ValueError(f'Arrays do not have the same shape: {token.shape} - {y.shape}')

    def _diff(rx, ry, vdt):
        diff = np.asarray(rx - ry, dtype=vdt)
        return np.abs(diff)
    rx = integer_repr(token)
    ry = integer_repr(y)
    return _diff(rx, ry, t)

