        assert_index_equal(left, item, **kwargs)
        if isinstance(left, (DatetimeIndex, TimedeltaIndex)):
            assert left.freq == item.freq, (left.freq, item.freq)
    elif isinstance(left, Series):
        assert_series_equal(left, item, **kwargs)
    elif isinstance(left, DataFrame):
        assert_frame_equal(left, item, **kwargs)
    elif isinstance(left, IntervalArray):
        assert_interval_array_equal(left, item, **kwargs)
    elif isinstance(left, PeriodArray):
        assert_period_array_equal(left, item, **kwargs)
    elif isinstance(left, DatetimeArray):
        assert_datetime_array_equal(left, item, **kwargs)
    elif isinstance(left, TimedeltaArray):
        assert_timedelta_array_equal(left, item, **kwargs)
    elif isinstance(left, ExtensionArray):
        assert_extension_array_equal(left, item, **kwargs)
    elif isinstance(left, np.ndarray):
        assert_numpy_array_equal(left, item, **kwargs)
    elif isinstance(left, str):
        assert kwargs == {}
        assert left == item
    else:
        assert kwargs == {}
        assert_almost_equal(left, item)

