@set_module('numpy')
def binary_repr(num, width=None):

    def err_if_insufficient(width, binwidth):
        if width is not None and width < binwidth:
            raise ValueError(f'Insufficient bit width={width!r} provided for binwidth={binwidth!r}')
    num = operator.index(num)
    if num == 0:
        return '0' * (width or 1)
    elif num > 0:
        binary = f'{num:b}'
        binwidth = len(binary)
        outwidth = binwidth if width is None else builtins.max(binwidth, width)
        err_if_insufficient(width, binwidth)
        return binary.zfill(outwidth)
    elif width is None:
        return f'-{-num:b}'
    else:
        poswidth = len(f'{-num:b}')
        if 2 ** (poswidth - 1) == -num:
            poswidth -= 1
        twocomp = 2 ** (poswidth + 1) + num
        binary = f'{twocomp:b}'
        binwidth = len(binary)
        outwidth = builtins.max(binwidth, width)
        err_if_insufficient(width, binwidth)
        return '1' * (outwidth - binwidth) + binary

@array_function_dispatch(_trapezoid_dispatcher)
def trapezoid(target, x=None, dx=1.0, axis=-1):
    target = asanyarray(target)
    if x is None:
        d = dx
    else:
        x = asanyarray(x)
        if x.ndim == 1:
            d = diff(x)
            shape = [1] * target.ndim
            shape[axis] = d.shape[0]
            d = d.reshape(shape)
        else:
            d = diff(x, axis=axis)
    nd = target.ndim
    slice1 = [slice(None)] * nd
    slice2 = [slice(None)] * nd
    slice1[axis] = slice(1, None)
    slice2[axis] = slice(None, -1)
    try:
        ret = (d * (target[tuple(slice1)] + target[tuple(slice2)]) / 2.0).sum(axis)
    except ValueError:
        d = np.asarray(d)
        target = np.asarray(target)
        ret = add.reduce(d * (target[tuple(slice1)] + target[tuple(slice2)]) / 2.0, axis)
    return ret

