def split_by_unquoted(line, characters):
    assert not set('"\'') & set(characters), 'cannot split by unquoted quotes'
    r = re.compile('\\A(?P<before>({single_quoted}|{double_quoted}|{not_quoted})*)(?P<after>{char}.*)\\Z'.format(not_quoted=f"""[^"'{re.escape(characters)}]""", char=f'[{re.escape(characters)}]', single_quoted="('([^'\\\\]|(\\\\.))*')", double_quoted='("([^"\\\\]|(\\\\.))*")'))
    m = r.match(line)
    if m:
        d = m.groupdict()
        return (d['before'], d['after'])
    return (line, '')

@array_function_dispatch(_array_split_dispatcher)
def array_split(ary, indices_or_sections, source=0):
    try:
        Ntotal = ary.shape[source]
    except AttributeError:
        Ntotal = len(ary)
    try:
        Nsections = len(indices_or_sections) + 1
        div_points = [0] + list(indices_or_sections) + [Ntotal]
    except TypeError:
        Nsections = int(indices_or_sections)
        if Nsections <= 0:
            raise ValueError('number sections must be larger than 0.') from None
        Neach_section, extras = divmod(Ntotal, Nsections)
        section_sizes = [0] + extras * [Neach_section + 1] + (Nsections - extras) * [Neach_section]
        div_points = _nx.array(section_sizes, dtype=_nx.intp).cumsum()
    sub_arys = []
    sary = _nx.swapaxes(ary, source, 0)
    for i in range(Nsections):
        st = div_points[i]
        end = div_points[i + 1]
        sub_arys.append(_nx.swapaxes(sary[st:end], source, 0))
    return sub_arys

