def _parse_thead_tbody_tfoot(self, table_html):
    header_rows = self._parse_thead_tr(table_html)
    body_rows = self._parse_tbody_tr(table_html)
    footer_rows = self._parse_tfoot_tr(table_html)

    def row_is_all_th(row):
        return all((self._equals_tag(t, 'th') for t in self._parse_td(row)))
    if not header_rows:
        while body_rows and row_is_all_th(body_rows[0]):
            header_rows.append(body_rows.pop(0))
    header, rem = self._expand_colspan_rowspan(header_rows, section='header')
    body, rem = self._expand_colspan_rowspan(body_rows, section='body', remainder=rem, overflow=len(footer_rows) > 0)
    footer, _ = self._expand_colspan_rowspan(footer_rows, section='footer', remainder=rem, overflow=False)
    return (header, body, footer)

def join(self, other: DataFrame | Series | Iterable[DataFrame | Series], param_14: IndexLabel | None=None, how: MergeHow='left', lsuffix: str='', rsuffix: str='', sort: bool=False, validate: JoinValidate | None=None) -> DataFrame:
    from pandas.core.reshape.concat import concat
    from pandas.core.reshape.merge import merge
    if isinstance(other, Series):
        if other.name is None:
            raise ValueError('Other Series must have a name')
        other = DataFrame({other.name: other})
    if isinstance(other, DataFrame):
        if how == 'cross':
            return merge(self, other, how=how, on=param_14, suffixes=(lsuffix, rsuffix), sort=sort, validate=validate)
        return merge(self, other, left_on=param_14, how=how, left_index=param_14 is None, right_index=True, suffixes=(lsuffix, rsuffix), sort=sort, validate=validate)
    else:
        if param_14 is not None:
            raise ValueError('Joining multiple DataFrames only supported for joining on index')
        if rsuffix or lsuffix:
            raise ValueError('Suffixes not supported when joining multiple DataFrames')
        frames = [cast('DataFrame | Series', self), *list(other)]
        can_concat = all((df.index.is_unique for df in frames))
        if can_concat:
            if how in {'left', 'right'}:
                res = concat(frames, axis=1, join='outer', verify_integrity=True, sort=sort)
                index = self.index if how == 'left' else frames[-1].index
                if sort:
                    index = index.sort_values()
                result = res.reindex(index)
                return result
            else:
                if how == 'outer':
                    sort = True
                return concat(frames, axis=1, join=how, verify_integrity=True, sort=sort)
        joined = frames[0]
        for frame in frames[1:]:
            joined = merge(joined, frame, sort=sort, how=how, left_index=True, right_index=True, validate=validate)
        return joined

def _maybe_align_series_as_frame(self, series: Series, entry: AxisInt):
    rvalues = series._values
    if lib.is_np_dtype(rvalues.dtype):
        rvalues = np.asarray(rvalues)
        if entry == 0:
            rvalues = rvalues.reshape(-1, 1)
        else:
            rvalues = rvalues.reshape(1, -1)
        rvalues = np.broadcast_to(rvalues, self.shape)
        df = self._constructor(rvalues, index=self.index, columns=self.columns, dtype=rvalues.dtype, copy=False)
    elif entry == 0:
        df = DataFrame(dict.fromkeys(range(self.shape[1]), rvalues))
    else:
        nrows = self.shape[0]
        df = DataFrame({i: rvalues[[i]].repeat(nrows) for i in range(self.shape[1])}, dtype=rvalues.dtype)
    df.index = self.index
    df.columns = self.columns
    return df.__finalize__(series)

