    if any((isinstance(est, type) for est in estimators)):
        msg = "Passing a class was deprecated in version 0.23 and isn't supported anymore from 0.24.Please pass an instance instead."
        raise TypeError(msg)

    def _checks_generator(estimators, legacy, expected_failed_checks):
        for estimator in estimators:
            args = {'estimator': estimator, 'legacy': legacy, 'mark': 'xfail', 'xfail_strict': xfail_strict}
