def _warn_if_unreliable_or(self) -> None:
    table = getattr(self.table, 'table', None)
    if table is None or table.chunkshape is None:
        return
    if table.chunkshape[0] >= self.table.nrows:
        return
    cols = _or_of_ands_columns(self.condition)
    if not any((table.colinstances[name].is_indexed for name in cols if name in table.colnames)):
        return
    warnings.warn("Reading with a nested 'where' that ORs AND-ed conditions over indexed columns (e.g. '(A & B) | (C & D)') can return incorrect results due to an upstream PyTables bug (GH#50598). To get correct results, write the table with 'index=False', or run each OR branch as a separate query and concatenate the results.", UserWarning, stacklevel=find_stack_level())

