def validate(self, names, defaultfmt='f%i', nbfields=None):
    if names is None:
        if nbfields is None:
            return None
        names = []
    if isinstance(names, str):
        names = [names]
    if nbfields is not None:
        nbnames = len(names)
        if nbnames < nbfields:
            names = list(names) + [''] * (nbfields - nbnames)
        elif nbnames > nbfields:
            names = names[:nbfields]
    deletechars = self.deletechars
    excludelist = self.excludelist
    case_converter = self.case_converter
    replace_space = self.replace_space
    validatednames = []
    seen = {}
    nbempty = 0
    for item in names:
        item = case_converter(item).strip()
        if replace_space:
            item = item.replace(' ', replace_space)
        item = ''.join([c for c in item if c not in deletechars])
        if item == '':
            item = defaultfmt % nbempty
            while item in names:
                nbempty += 1
                item = defaultfmt % nbempty
            nbempty += 1
        elif item in excludelist:
            item += '_'
        cnt = seen.get(item, 0)
        if cnt > 0:
            validatednames.append(f'{item}_{cnt}')
        else:
            validatednames.append(item)
        seen[item] = cnt + 1
    return tuple(validatednames)

def choose(cache, choices, out=None, mode='raise'):

    def fmask(x):
        """Returns the filled array, or True if masked."""
        if x is masked:
            return True
        return filled(x)

    def nmask(x):
        """Returns the mask, True if ``masked``, False if ``nomask``."""
        if x is masked:
            return True
        return getmask(x)
    c = filled(cache, 0)
    masks = [nmask(x) for x in choices]
    data = [fmask(x) for x in choices]
    outputmask = np.choose(c, masks, mode=mode)
    outputmask = make_mask(mask_or(outputmask, getmask(cache)), copy=False, shrink=True)
    d = np.choose(c, data, mode=mode, out=out).view(MaskedArray)
    if out is not None:
        if isinstance(out, MaskedArray):
            out.__setmask__(outputmask)
        return out
    d.__setmask__(outputmask)
    return d

