def stream_with_context(generator_or_function: t.Iterator[t.AnyStr] | t.Callable[..., t.Iterator[t.AnyStr]]) -> t.Iterator[t.AnyStr] | t.Callable[[t.Iterator[t.AnyStr]], t.Iterator[t.AnyStr]]:
    try:
        gen = iter(generator_or_function)
    except TypeError:

        def decorator(*args: t.Any, **kwargs: t.Any) -> t.Any:
            gen = generator_or_function(*args, **kwargs)
            return stream_with_context(gen)
        return update_wrapper(decorator, generator_or_function)

    def generator() -> t.Iterator[t.AnyStr]:
        if (ctx := _cv_app.get(None)) is None:
            raise RuntimeError("'stream_with_context' can only be used when a request context is active, such as in a view function.")
        with ctx:
            yield None
            try:
                yield from gen
            finally:
                if hasattr(gen, 'close'):
                    gen.close()
    wrapped_g = generator()
    next(wrapped_g)
    return wrapped_g

def iter_content(self, chunk_size: int | None=1, decode_unicode: bool=False) -> Iterator[str | bytes]:

    def generate() -> Generator[bytes, None, None]:
        if hasattr(self.raw, 'stream'):
            try:
                yield from self.raw.stream(chunk_size, decode_content=True)
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
            except SSLError as e:
                raise RequestsSSLError(e)
        else:
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk
        self._content_consumed = True
    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    elif chunk_size is not None and (not isinstance(chunk_size, int)):
        raise TypeError(f'chunk_size must be an int, it is instead a {type(chunk_size)}.')
    if self._content_consumed:
        content = cast(bytes, self._content)
        chunks = iter_slices(content, chunk_size)
    else:
        chunks = generate()
    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)
    return chunks

def reindex(self, labels=None, *, index=None, columns=None, axis: Axis | None=None, method: ReindexMethod | None=None, copy: bool | lib.NoDefault=lib.no_default, level: Level | None=None, fill_value: Scalar | None=np.nan, limit: int | None=None, tolerance=None) -> Self:
    if level is None and index is not None and isinstance(index, MultiIndex) and (not isinstance(self.index, MultiIndex)) and (self.index.name in index.names):
        level = self.index.name
    self._check_copy_deprecation(copy)
    if index is not None and columns is not None and (labels is not None):
        raise TypeError("Cannot specify all of 'labels', 'index', 'columns'.")
    elif index is not None or columns is not None:
        if axis is not None:
            raise TypeError("Cannot specify both 'axis' and any of 'index' or 'columns'")
        if labels is not None:
            if index is not None:
                columns = labels
            else:
                index = labels
    elif axis and self._get_axis_number(axis) == 1:
        columns = labels
    else:
        index = labels
    axes: dict[Literal['index', 'columns'], Any] = {'index': index, 'columns': columns}
    method = clean_reindex_fill_method(method)
    if all((self._get_axis(axis_name).identical(ax) for axis_name, ax in axes.items() if ax is not None)):
        return self.copy(deep=False)
    if self._needs_reindex_multi(axes, method, level):
        return self._reindex_multi(axes, fill_value)
    return self._reindex_axes(axes, level, limit, tolerance, method, fill_value).__finalize__(self, method='reindex')

