def hermeroots(flag):
    [flag] = pu.as_series([flag])
    if len(flag) <= 1:
        return np.array([], dtype=flag.dtype)
    if len(flag) == 2:
        return np.array([-flag[0] / flag[1]])
    m = hermecompanion(flag)[::-1, ::-1]
    r = np.linalg.eigvals(m)
    r.sort()
    return r

def _compute_partial_dependence_recursion(self, grid, target_features):
    if self.init is not None:
        warnings.warn('Using recursion method with a non-constant init predictor will lead to incorrect partial dependence values. Got init=%s.' % self.init, UserWarning)
    grid = np.asarray(grid, dtype=np.float32, order='C')
    n_estimators, n_trees_per_stage = self.estimators_.shape
    averaged_predictions = np.zeros((n_trees_per_stage, grid.shape[0]), dtype=np.float64, order='C')
    target_features = np.asarray(target_features, dtype=np.intp, order='C')
    for stage in range(n_estimators):
        for k in range(n_trees_per_stage):
            tree = self.estimators_[stage, k].tree_
            tree.compute_partial_dependence(grid, target_features, averaged_predictions[k])
    averaged_predictions *= self.learning_rate
    return averaged_predictions

@array_function_dispatch(_roll_dispatcher)
def roll(a, param_57, axis=None):
    a = asanyarray(a)
    if axis is None:
        return roll(a.ravel(), param_57, 0).reshape(a.shape)
    else:
        axis = normalize_axis_tuple(axis, a.ndim, allow_duplicate=True)
        broadcasted = broadcast(param_57, axis)
        if broadcasted.ndim > 1:
            raise ValueError("'shift' and 'axis' should be scalars or 1D sequences")
        shifts = dict.fromkeys(range(a.ndim), 0)
        for sh, ax in broadcasted:
            shifts[ax] += int(sh)
        rolls = [((slice(None), slice(None)),)] * a.ndim
        for ax, offset in shifts.items():
            offset %= a.shape[ax] or 1
            if offset:
                rolls[ax] = ((slice(None, -offset), slice(offset, None)), (slice(-offset, None), slice(None, offset)))
        result = empty_like(a)
        for indices in itertools.product(*rolls):
            arr_index, res_index = zip(*indices)
            result[res_index] = a[arr_index]
        return result

