def func(*args, **kw):
    if not _routing_enabled():
        raise RuntimeError('This method is only available when metadata routing is enabled. You can enable it using sklearn.set_config(enable_metadata_routing=True).')
    if self.validate_keys and set(kw) - set(self.keys):
        raise TypeError(f'Unexpected args: {set(kw) - set(self.keys)} in {self.name}. Accepted arguments are: {set(self.keys)}')
    if instance is None:
        _instance = args[0]
        args = args[1:]
    else:
        _instance = instance
    if args:
        raise TypeError(f'set_{self.name}_request() takes 0 positional argument but {len(args)} were given')
    requests = _instance._get_metadata_request()
    method_metadata_request = getattr(requests, self.name)
    for prop, alias in kw.items():
        if alias is not UNCHANGED:
            method_metadata_request.add_request(param=prop, alias=alias)
    _instance._metadata_request = requests
    return None

def reconstruct_func(source: AggFuncType | None, **kwargs) -> tuple[bool, AggFuncType, tuple[str, ...] | None, npt.NDArray[np.intp] | None]:
    from pandas.core.groupby.generic import NamedAgg
    relabeling = source is None and (is_multi_agg_with_relabel(**kwargs) or any((isinstance(v, NamedAgg) for v in kwargs.values())))
    columns: tuple[str, ...] | None = None
    order: npt.NDArray[np.intp] | None = None
    if not relabeling:
        if isinstance(source, list) and len(source) > len(set(source)):
            raise SpecificationError('Function names must be unique if there is no new column names assigned')
        if source is None:
            raise TypeError("Must provide 'func' or tuples of '(column, aggfunc).")
    if relabeling:
        normalization_needed = False
        converted_kwargs = {}
        for key, val in kwargs.items():
            if isinstance(val, NamedAgg):
                column = val.column
                aggfunc = val.aggfunc
                if val.args or val.kwargs:
                    aggfunc = lambda x, source=aggfunc, a=val.args, kw=val.kwargs: source(x, *a, **kw)
            else:
                column, aggfunc = val
            if column != key:
                normalization_needed = True
            converted_kwargs[key] = (column, aggfunc)
        if normalization_needed:
            source, columns, order = normalize_keyword_aggregation(converted_kwargs)
        else:
            source = {column: aggfunc for key, (column, aggfunc) in converted_kwargs.items()}
            relabeling = False
    assert source is not None
    return (relabeling, source, columns, order)

