def _route_params(self, *, params, method, parent, caller):
    res = Bunch()
    if self._self_request:
        res.update(self._self_request._route_params(params=params, method=method, parent=parent, caller=caller))
    param_names = self._get_param_names(method=method, return_alias=True, ignore_self_request=True)
    child_params = {key: value for key, value in params.items() if key in param_names}
    for key in set(res.keys()).intersection(child_params.keys()):
        if child_params[key] is not res[key]:
            raise ValueError(f"In {_routing_repr(self.owner)}, there is a conflict on {key} between what is requested for this estimator and what is requested by its children. You can resolve this conflict by using an alias for the child estimators' requested metadata.")
    res.update(child_params)
    return res

