def create_subplots(naxes: int, sharex: bool=False, sharey: bool=False, squeeze: bool=True, subplot_kw=None, ax=None, layout=None, layout_type: str='box', **fig_kw):
    import matplotlib.pyplot as plt
    if subplot_kw is None:
        subplot_kw = {}
    if ax is None:
        fig = plt.figure(**fig_kw)
    else:
        if is_list_like(ax):
            if squeeze:
                ax = np.fromiter(flatten_axes(ax), dtype=object)
            if layout is not None:
                warnings.warn('When passing multiple axes, layout keyword is ignored.', UserWarning, stacklevel=find_stack_level())
            if sharex or sharey:
                warnings.warn('When passing multiple axes, sharex and sharey are ignored. These settings must be specified when creating axes.', UserWarning, stacklevel=find_stack_level())
            if ax.size == naxes:
                fig = ax.flat[0].get_figure()
                return (fig, ax)
            else:
                raise ValueError(f'The number of passed axes must be {naxes}, the same as the output plot')
        fig = ax.get_figure()
        if naxes == 1:
            if squeeze:
                return (fig, ax)
            else:
                return (fig, np.fromiter(flatten_axes(ax), dtype=object))
        else:
            warnings.warn('To output multiple subplots, the figure containing the passed axes is being cleared.', UserWarning, stacklevel=find_stack_level())
            fig.clear()
    nrows, ncols = _get_layout(naxes, layout=layout, layout_type=layout_type)
    nplots = nrows * ncols
    axarr = np.empty(nplots, dtype=object)
    ax0 = fig.add_subplot(nrows, ncols, 1, **subplot_kw)
    if sharex:
        subplot_kw['sharex'] = ax0
    if sharey:
        subplot_kw['sharey'] = ax0
    axarr[0] = ax0
    for i in range(1, nplots):
        kwds = subplot_kw.copy()
        if i >= naxes:
            kwds['sharex'] = None
            kwds['sharey'] = None
        ax = fig.add_subplot(nrows, ncols, i + 1, **kwds)
        axarr[i] = ax
    if naxes != nplots:
        for ax in axarr[naxes:]:
            ax.set_visible(False)
    handle_shared_axes(axarr, nplots, naxes, nrows, ncols, sharex, sharey)
    if squeeze:
        if nplots == 1:
            axes = axarr[0]
        else:
            axes = axarr.reshape(nrows, ncols).squeeze()
    else:
        axes = axarr.reshape(nrows, ncols)
    return (fig, axes)

def get_indexer_non_unique(self, target: Axes) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    target = self._maybe_cast_listlike_indexer(target)
    if not self._should_compare(target) and (not self._should_partial_index(target)):
        return self._get_indexer_non_comparable(target, method=None, unique=False)
    pself, ptarget = self._maybe_downcast_for_indexing(target)
    if pself is not self or ptarget is not target:
        return pself.get_indexer_non_unique(ptarget)
    if self.dtype != target.dtype:
        dtype = self._find_common_type_compat(target)
        this = self.astype(dtype, copy=False)
        that = target.astype(dtype, copy=False)
        return this.get_indexer_non_unique(that)
    if self._is_multi and target._is_multi:
        engine = self._engine
        tgt_values = engine._extract_level_codes(target)
    else:
        tgt_values = target._get_engine_target()
    indexer, missing = self._engine.get_indexer_non_unique(tgt_values)
    return (ensure_platform_int(indexer), ensure_platform_int(missing))

def apply(self, func: AggFuncType, axis: Axis=0, raw: bool=False, result_type: Literal['expand', 'reduce', 'broadcast'] | None=None, args=(), by_row: Literal[False, 'compat']='compat', engine: Callable | None | Literal['python', 'numba']=None, engine_kwargs: dict[str, bool] | None=None, **kwargs):
    if engine is None or isinstance(engine, str):
        from pandas.core.apply import frame_apply
        if engine is None:
            engine = 'python'
        if engine not in ['python', 'numba']:
            raise ValueError(f"Unknown engine '{engine}'")
        op = frame_apply(self, func=func, axis=axis, raw=raw, result_type=result_type, by_row=by_row, engine=engine, engine_kwargs=engine_kwargs, args=args, kwargs=kwargs)
        return op.apply().__finalize__(self, method='apply')
    elif hasattr(engine, '__pandas_udf__'):
        if result_type is not None:
            raise NotImplementedError(f'result_type={result_type!r} only implemented for the default engine')
        agg_axis = self._get_agg_axis(self._get_axis_number(axis))
        if not all(self.shape):
            func = cast('Callable', func)
            try:
                if axis == 0:
                    r = func(Series([], dtype=np.float64), *args, **kwargs)
                else:
                    r = func(Series(index=self.columns, dtype=np.float64), *args, **kwargs)
            except Exception:
                pass
            else:
                if not isinstance(r, Series):
                    if len(agg_axis):
                        r = func(Series([], dtype=np.float64), *args, **kwargs)
                    else:
                        r = np.nan
                    return self._constructor_sliced(r, index=agg_axis)
            return self.copy()
        data: DataFrame | np.ndarray = self
        if raw:
            data = self.values
        result = engine.__pandas_udf__.apply(data=data, func=func, args=args, kwargs=kwargs, decorator=engine, axis=axis)
        if raw:
            if result.ndim == 2:
                return self._constructor(result, index=self.index, columns=self.columns)
            else:
                return self._constructor_sliced(result, index=agg_axis)
        return result
    else:
        raise ValueError(f'Unknown engine {engine}')

