def get_group_index(labels: Sequence[npt.NDArray[np.signedinteger]], shape: Shape, sort: bool, xnull: bool) -> npt.NDArray[np.int64]:

    def _int64_cut_off(shape: list[int]) -> int:
        acc = 1
        for i, mul in enumerate(shape):
            acc *= int(mul)
            if not acc < lib.i8max:
                return i
        return len(shape)

    def maybe_lift(lab: np.ndarray, size: int) -> tuple[np.ndarray, int]:
        return (lab + 1, size + 1) if lib.has_sentinel(lab, -1) else (lab, size)
    labels = [ensure_int64(x) for x in labels]
    lshape = list(shape)
    if not xnull:
        for i, (lab, size) in enumerate(zip(labels, shape, strict=True)):
            labels[i], lshape[i] = maybe_lift(lab, size)
    while True:
        nlev = _int64_cut_off(lshape)
        stride = np.prod(lshape[1:nlev], dtype='i8')
        out = stride * labels[0].astype('i8', subok=False, copy=False)
        for i in range(1, nlev):
            if lshape[i] == 0:
                stride = np.int64(0)
            else:
                stride //= lshape[i]
            out += labels[i] * stride
        if xnull:
            mask = labels[0] == -1
            for lab in labels[1:nlev]:
                mask |= lab == -1
            out[mask] = -1
        if nlev == len(lshape):
            break
        comp_ids, obs_ids = compress_group_index(out, sort=sort)
        labels = [comp_ids, *labels[nlev:]]
        lshape = [len(obs_ids), *lshape[nlev:]]
    return out

@array_function_dispatch(_binary_op_dispatcher)
def polyadd(a1, source):
    truepoly = isinstance(a1, poly1d) or isinstance(source, poly1d)
    a1 = atleast_1d(a1)
    source = atleast_1d(source)
    diff = len(source) - len(a1)
    if diff == 0:
        val = a1 + source
    elif diff > 0:
        zr = NX.zeros(diff, a1.dtype)
        val = NX.concatenate((zr, a1)) + source
    else:
        zr = NX.zeros(abs(diff), source.dtype)
        val = a1 + NX.concatenate((zr, source))
    if truepoly:
        val = poly1d(val)
    return val

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    self._fit(X)
    n_samples = self.n_samples_fit_
    if self.n_neighbors > n_samples:
        warnings.warn('n_neighbors (%s) is greater than the total number of samples (%s). n_neighbors will be set to (n_samples - 1) for estimation.' % (self.n_neighbors, n_samples))
    self.n_neighbors_ = max(1, min(self.n_neighbors, n_samples - 1))
    self._distances_fit_X_, _neighbors_indices_fit_X_ = self.kneighbors(n_neighbors=self.n_neighbors_)
    if self._fit_X.dtype == np.float32:
        self._distances_fit_X_ = self._distances_fit_X_.astype(self._fit_X.dtype, copy=False)
    self._lrd = self._local_reachability_density(self._distances_fit_X_, _neighbors_indices_fit_X_)
    lrd_ratios_array = self._lrd[_neighbors_indices_fit_X_] / self._lrd[:, np.newaxis]
    self.negative_outlier_factor_ = -np.mean(lrd_ratios_array, axis=1)
    if self.contamination == 'auto':
        self.offset_ = -1.5
    else:
        self.offset_ = np.percentile(self.negative_outlier_factor_, 100.0 * self.contamination)
    if np.min(self.negative_outlier_factor_) < -10000000.0 and (not self.novelty):
        warnings.warn('Duplicate values are leading to incorrect results. Increase the number of neighbors for more accurate results.')
    return self

def _expand_colspan_rowspan(self, rows, section: Literal['header', 'footer', 'body'], remainder: list[tuple[int, str | tuple, int]] | None=None, overflow: bool=True) -> tuple[list[list], list[tuple[int, str | tuple, int]]]:
    all_texts = []
    text: str | tuple
    remainder = remainder if remainder is not None else []
    for tr in rows:
        texts = []
        next_remainder = []
        index = 0
        tds = self._parse_td(tr)
        for td in tds:
            while remainder and remainder[0][0] <= index:
                prev_i, prev_text, prev_rowspan = remainder.pop(0)
                texts.append(prev_text)
                if prev_rowspan > 1:
                    next_remainder.append((prev_i, prev_text, prev_rowspan - 1))
                index += 1
            text = _remove_whitespace(self._text_getter(td))
            if self.extract_links in ('all', section):
                href = self._href_getter(td)
                text = (text, href)
            rowspan = int(self._attr_getter(td, 'rowspan') or 1)
            colspan = int(self._attr_getter(td, 'colspan') or 1)
            for _ in range(colspan):
                texts.append(text)
                if rowspan > 1:
                    next_remainder.append((index, text, rowspan - 1))
                index += 1
        for prev_i, prev_text, prev_rowspan in remainder:
            texts.append(prev_text)
            if prev_rowspan > 1:
                next_remainder.append((prev_i, prev_text, prev_rowspan - 1))
        all_texts.append(texts)
        remainder = next_remainder
    if not overflow:
        while remainder:
            next_remainder = []
            texts = []
            for prev_i, prev_text, prev_rowspan in remainder:
                texts.append(prev_text)
                if prev_rowspan > 1:
                    next_remainder.append((prev_i, prev_text, prev_rowspan - 1))
            all_texts.append(texts)
            remainder = next_remainder
    return (all_texts, remainder)

