def assert_close(actual: Array, desired: Array, *, rtol: float | Array | None=None, atol: float | Array=0, equal_nan: bool=True, err_msg: str='', verbose: bool=True, check_dtype: bool=True, check_shape: bool=True, check_scalar: bool=False, xp: ModuleType | None=None) -> None:
    actual, desired, xp, np = _check_ns_shape_dtype(actual, desired, check_dtype, check_shape, check_scalar, xp)
    if not _is_materializable(actual):
        return
    if rtol is None:
        if xp.isdtype(actual.dtype, ('real floating', 'complex floating')):
            rtol = xp.finfo(actual.dtype).eps ** 0.5 * 4
        else:
            rtol = 1e-07
    else:
        rtol = float(rtol)
    atol = float(atol)
    actual_np = _as_numpy_array(actual, xp=xp)
    desired_np = _as_numpy_array(desired, xp=xp)
    np.testing.assert_allclose(actual_np, desired_np, rtol=rtol, atol=atol, equal_nan=equal_nan, err_msg=err_msg, verbose=verbose)

