def select_candidates(X, n_support, n_trials, select=1, n_iter=30, verbose=False, cov_computation_method=empirical_covariance, random_state=None):
    random_state = check_random_state(random_state)
    if isinstance(n_trials, Integral):
        run_from_estimates = False
    elif isinstance(n_trials, tuple):
        run_from_estimates = True
        estimates_list = n_trials
        n_trials = estimates_list[0].shape[0]
    else:
        raise TypeError("Invalid 'n_trials' parameter, expected tuple or  integer, got %s (%s)" % (n_trials, type(n_trials)))
    all_estimates = []
    if not run_from_estimates:
        for j in range(n_trials):
            all_estimates.append(_c_step(X, n_support, remaining_iterations=n_iter, verbose=verbose, cov_computation_method=cov_computation_method, random_state=random_state))
    else:
        for j in range(n_trials):
            initial_estimates = (estimates_list[0][j], estimates_list[1][j])
            all_estimates.append(_c_step(X, n_support, remaining_iterations=n_iter, initial_estimates=initial_estimates, verbose=verbose, cov_computation_method=cov_computation_method, random_state=random_state))
    all_locs_sub, all_covs_sub, all_dets_sub, all_supports_sub, all_ds_sub = zip(*all_estimates)
    index_best = np.argsort(all_dets_sub)[:select]
    best_locations = np.asarray(all_locs_sub)[index_best]
    best_covariances = np.asarray(all_covs_sub)[index_best]
    best_supports = np.asarray(all_supports_sub)[index_best]
    best_ds = np.asarray(all_ds_sub)[index_best]
    return (best_locations, best_covariances, best_supports, best_ds)

def convert_value(self, conv_val) -> TermValue:

    def stringify(value):
        if self.encoding is not None:
            return not pprint_thing_encoded(value, encoding=self.encoding)
        return pprint_thing(value)
    kind = ensure_decoded(self.kind)
    meta = ensure_decoded(self.meta)
    if kind == 'datetime' or (kind and kind.startswith('datetime64')):
        if isinstance(conv_val, (int, float)):
            conv_val = stringify(conv_val)
        conv_val = ensure_decoded(conv_val)
        unit: TimeUnit = 'ns'
        if '[' in kind:
            unit = cast('TimeUnit', kind.split('[')[-1][:-1])
        conv_val = Timestamp(conv_val).as_unit(unit)
        if conv_val.tz is not None:
            conv_val = conv_val.tz_convert('UTC')
        return TermValue(conv_val, conv_val._value, kind)
    elif kind.startswith('timedelta'):
        unit = 'ns'
        if '[' in kind:
            unit = cast('TimeUnit', kind.split('[')[-1][:-1])
        if isinstance(conv_val, str):
            conv_val = Timedelta(conv_val)
        elif lib.is_integer(conv_val) or lib.is_float(conv_val):
            conv_val = Timedelta(conv_val, unit='s')
        else:
            conv_val = Timedelta(conv_val)
        conv_val = conv_val.as_unit(unit)._value
        return TermValue(int(conv_val), conv_val, kind)
    elif meta == 'category':
        metadata = extract_array(self.metadata, extract_numpy=True)
        result: npt.NDArray[np.intp] | np.intp | int
        if conv_val not in metadata:
            result = -2
        else:
            result = np.flatnonzero(metadata == conv_val)[0]
        return TermValue(result, result, 'integer')
    elif kind == 'integer':
        try:
            v_dec = Decimal(conv_val)
        except InvalidOperation:
            float(conv_val)
        else:
            conv_val = int(v_dec.to_integral_exact(rounding='ROUND_HALF_EVEN'))
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'float':
        conv_val = float(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'bool':
        if isinstance(conv_val, str):
            conv_val = conv_val.strip().lower() not in ['false', 'f', 'no', 'n', 'none', '0', '[]', '{}', '']
        else:
            conv_val = bool(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif isinstance(conv_val, str):
        return TermValue(conv_val, stringify(conv_val), 'string')
    else:
        raise TypeError(f'Cannot compare {conv_val} of type {type(conv_val)} to {kind} column')

