def get_chunks(self, source: int | None=None):
    if source and source > 1:
        size = len(self._col)
        step = size // source
        if size % source != 0:
            step += 1
        for start in range(0, step * source, step):
            yield PandasColumn(self._col.iloc[start:start + step], self._allow_copy)
    else:
        yield self

