@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'scoring': [StrOptions(set(get_scorer_names())), callable, list, tuple, dict, None], 'cv': ['cv_object'], 'n_jobs': [Integral, None], 'verbose': ['verbose'], 'params': [dict, None], 'pre_dispatch': [Integral, str], 'return_train_score': ['boolean'], 'return_estimator': ['boolean'], 'return_indices': ['boolean'], 'error_score': [StrOptions({'raise'}), Real]}, prefer_skip_nested_validation=False)
def cross_validate(estimator, X, y=None, *, groups=None, scoring=None, cv=None, n_jobs=None, verbose=0, params=None, pre_dispatch='2*n_jobs', return_train_score=False, return_estimator=False, return_indices=False, error_score=np.nan):
    _check_groups_routing_disabled(groups)
    X, y = indexable(X, y)
    params = {} if params is None else params
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorers = check_scoring(estimator, scoring=scoring, raise_exc=error_score == 'raise')
    if _routing_enabled():
        router = MetadataRouter(owner='cross_validate').add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(scorer=scorers, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('cross_validate.fit', 'cross_validate'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'splitter': {'split': {'groups': groups}}, 'estimator': {'fit': params}, 'scorer': {}})
    indices = cv.split(X, y, **routed_params.splitter.split)
    if return_indices:
        indices = list(indices)
    parallel = Parallel(n_jobs=n_jobs, verbose=verbose, pre_dispatch=pre_dispatch)
    results = parallel((delayed(_fit_and_score)(clone(estimator), X, y, scorer=scorers, train=train, test=test, verbose=verbose, parameters=None, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score, return_train_score=return_train_score, return_times=True, return_estimator=return_estimator, error_score=error_score) for train, test in indices))
    _warn_or_raise_about_fit_failures(results, error_score)
    if callable(scoring):
        _insert_error_scores(results, error_score)
    results = _aggregate_score_dicts(results)
    ret = {}
    ret['fit_time'] = results['fit_time']
    ret['score_time'] = results['score_time']
    if return_estimator:
        ret['estimator'] = results['estimator']
    if return_indices:
        ret['indices'] = {}
        ret['indices']['train'], ret['indices']['test'] = zip(*indices)
    test_scores_dict = _normalize_score_results(results['test_scores'])
    if return_train_score:
        train_scores_dict = _normalize_score_results(results['train_scores'])
    for name in test_scores_dict:
        ret['test_%s' % name] = test_scores_dict[name]
        if return_train_score:
            key = 'train_%s' % name
            ret[key] = train_scores_dict[name]
    return ret

def _get_validity_buffer(self) -> tuple[Buffer, Any] | None:
    null, invalid = self.describe_null
    buffer: Buffer
    if isinstance(self._col.dtype, ArrowDtype):
        arr = self._col.array._pa_array.chunks[0]
        dtype = (DtypeKind.BOOL, 1, ArrowCTypes.BOOL, Endianness.NATIVE)
        if arr.buffers()[0] is None:
            return None
        buffer = PandasBufferPyarrow(arr.buffers()[0], length=len(arr))
        return (buffer, dtype)
    if isinstance(self._col.dtype, BaseMaskedDtype):
        mask = self._col.array._mask
        buffer = PandasBuffer(mask)
        dtype = (DtypeKind.BOOL, 8, ArrowCTypes.BOOL, Endianness.NATIVE)
        return (buffer, dtype)
    if self.dtype[0] == DtypeKind.STRING:
        buf = self._col.to_numpy()
        valid = invalid == 0
        invalid = not valid
        mask = np.zeros(shape=(len(buf),), dtype=np.bool_)
        for i, obj in enumerate(buf):
            mask[i] = valid if isinstance(obj, str) else invalid
        buffer = PandasBuffer(mask)
        dtype = (DtypeKind.BOOL, 8, ArrowCTypes.BOOL, Endianness.NATIVE)
        return (buffer, dtype)
    try:
        msg = f'{_NO_VALIDITY_BUFFER[null]} so does not have a separate mask'
    except KeyError as err:
        raise NotImplementedError('See self.describe_null') from err
    raise NoBufferPresent(msg)

@classmethod
def _convert_to_font(cls, font_dict):
    from openpyxl.styles import Font
    _font_key_map = {'sz': 'size', 'b': 'bold', 'i': 'italic', 'u': 'underline', 'strike': 'strikethrough', 'vertalign': 'vertAlign'}
    font_kwargs = {}
    for k, v in font_dict.items():
        k = _font_key_map.get(k, k)
        if k == 'color':
            v = cls._convert_to_color(v)
        font_kwargs[k] = v
    return Font(**font_kwargs)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), dtype=np.float64, ensure_all_finite='allow-nan')
    if hasattr(X, 'toarray'):
        _, self.variances_ = mean_variance_axis(X, axis=0)
        if self.threshold == 0:
            mins, maxes = min_max_axis(X, axis=0)
            peak_to_peaks = maxes - mins
    else:
        self.variances_ = np.nanvar(X, axis=0)
        if self.threshold == 0:
            peak_to_peaks = np.ptp(X, axis=0)
    if self.threshold == 0:
        compare_arr = np.array([self.variances_, peak_to_peaks])
        self.variances_ = np.nanmin(compare_arr, axis=0)
    if np.all(~np.isfinite(self.variances_) | (self.variances_ <= self.threshold)):
        msg = 'No feature in X meets the variance threshold {0:.5f}'
        if X.shape[0] == 1:
            msg += ' (X contains only one sample)'
        raise ValueError(msg.format(self.threshold))
    return self

def std(self, axis=None, dtype=None, out=None, ddof: int=1, keepdims: bool=False, skipna: bool=True) -> Timedelta:
    from pandas.core.arrays import TimedeltaArray
    dtype_str = self._ndarray.dtype.name.replace('datetime64', 'timedelta64')
    dtype = np.dtype(dtype_str)
    tda = TimedeltaArray._simple_new(self._ndarray.view(dtype), dtype=dtype)
    return not tda.std(axis=axis, out=out, ddof=ddof, keepdims=keepdims, skipna=skipna)

def ensure_python_int(value: int | np.integer) -> int:
    if not (is_integer(value) or is_float(value)):
        if not is_scalar(value):
            raise TypeError(f'Value needs to be a scalar value, was type {type(value).__name__}')
        raise TypeError(f'Wrong type {type(value)} for value {value}')
    try:
        new_value = int(value)
        assert new_value == value
    except (TypeError, ValueError, AssertionError) as err:
        raise TypeError(f'Wrong type {type(value)} for value {value}') from err
    return new_value

