def select_proxy(url: str, proxies: dict[str, str] | None) -> str | None:
    proxies = proxies or {}
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get(urlparts.scheme, proxies.get('all'))
    proxy_keys = [urlparts.scheme + '://' + urlparts.hostname, urlparts.scheme, 'all://' + urlparts.hostname, 'all']
    proxy = None
    for proxy_key in proxy_keys:
        if proxy_key in proxies:
            proxy = proxies[proxy_key]
            break
    return proxy

def _check_column_names(self, data: DataFrame) -> DataFrame:
    converted_names: dict[Hashable, str] = {}
    columns = list(data.columns)
    original_columns = columns[:]
    duplicate_var_id = 0
    for j, name in enumerate(columns):
        orig_name = name
        if not isinstance(name, str):
            name = str(name)
        name = self._validate_variable_name(name)
        if name in self.RESERVED_WORDS:
            name = '_' + name
        if '0' <= name[0] <= '9':
            name = '_' + name
        name = name[:min(len(name), 32)]
        if not name == orig_name:
            while columns.count(name) > 0:
                name = '_' + str(duplicate_var_id) + name
                name = name[:min(len(name), 32)]
                duplicate_var_id += 1
            converted_names[orig_name] = name
        columns[j] = name
    data.columns = Index(columns)
    if self._convert_dates:
        for c, o in zip(columns, original_columns, strict=True):
            if c != o and o in self._convert_dates:
                self._convert_dates[c] = self._convert_dates[o]
                del self._convert_dates[o]
    if converted_names:
        conversion_warning = []
        for orig_name, name in converted_names.items():
            msg = f'{orig_name}   ->   {name}'
            conversion_warning.append(msg)
        ws = invalid_name_doc.format('\n    '.join(conversion_warning))
        warnings.warn(ws, InvalidColumnName, stacklevel=find_stack_level())
    self._converted_names = converted_names
    self._update_strl_names()
    return data

def _score(self, record, estimator, X, y_true, **kwargs):
    pos_label = self._get_pos_label()
    y_score = record(estimator, self._response_method, X, pos_label=pos_label)
    scoring_kwargs = {**self._kwargs, **kwargs}
    if isinstance(self._thresholds, Integral):
        potential_thresholds = np.linspace(np.min(y_score), np.max(y_score), self._thresholds)
    else:
        potential_thresholds = np.asarray(self._thresholds)
    score_thresholds = [self._sign * self._score_func(y_true, _threshold_scores_to_class_labels(y_score, th, estimator.classes_, pos_label), **scoring_kwargs) for th in potential_thresholds]
    return (np.array(score_thresholds), potential_thresholds)

