    if max_width == 0:
        return '[' + ', '.join(record) + ']'
    parts = ['[']
    cur_col_len = 1
    start = True
    for val in record:
        if not start:
            if cur_col_len + 2 + len(val) > max_width:
                parts.append(',\n ')
                cur_col_len = 1
            else:
                parts.append(', ')
                cur_col_len += 2
        parts.append(val)
        cur_col_len += len(val)
        start = False
    parts.append(']')
    return ''.join(parts)

