def shift(self, periods: int=1, freq=None) -> Self:
    if freq is not None and freq != self.freq:
        if isinstance(freq, str):
            freq = to_offset(freq)
        offset = periods * freq
        return self + offset
    if periods == 0 or len(self) == 0:
        return self.copy()
    if self.freq is None:
        raise NullFrequencyError('Cannot shift with no freq')
    start = self[0] + periods * self.freq
    end = self[-1] + periods * self.freq
    arr = self._data._generate_range(start=start, end=end, periods=None, freq=self.freq, unit=self.unit)
    result = type(self)._simple_new(arr, name=self.name)
    result._freq = self.freq
    return result

def check_scalar(x, name, target_type, *, min_val=None, max_val=None, include_boundaries='both'):

    def type_name(t):
        """Convert type into humman readable string."""
        module = t.__module__
        qualname = t.__qualname__
        if module == 'builtins':
            return qualname
        elif t == numbers.Real:
            return 'float'
        elif t == numbers.Integral:
            return 'int'
        return f'{module}.{qualname}'
    if not isinstance(x, target_type):
        if isinstance(target_type, tuple):
            types_str = ', '.join((type_name(t) for t in target_type))
            target_type_str = f'{{{types_str}}}'
        else:
            target_type_str = type_name(target_type)
        raise TypeError(f'{name} must be an instance of {target_type_str}, not {type(x).__qualname__}.')
    expected_include_boundaries = ('left', 'right', 'both', 'neither')
    if include_boundaries not in expected_include_boundaries:
        raise ValueError(f'Unknown value for `include_boundaries`: {include_boundaries!r}. Possible values are: {expected_include_boundaries}.')
    if max_val is None and include_boundaries == 'right':
        raise ValueError("`include_boundaries`='right' without specifying explicitly `max_val` is inconsistent.")
    if min_val is None and include_boundaries == 'left':
        raise ValueError("`include_boundaries`='left' without specifying explicitly `min_val` is inconsistent.")
    comparison_operator = operator.lt if include_boundaries in ('left', 'both') else operator.le
    if min_val is not None and comparison_operator(x, min_val):
        raise ValueError(f"{name} == {x}, must be {('>=' if include_boundaries in ('left', 'both') else '>')} {min_val}.")
    comparison_operator = operator.gt if include_boundaries in ('right', 'both') else operator.ge
    if max_val is not None and comparison_operator(x, max_val):
        raise ValueError(f"{name} == {x}, must be {('<=' if include_boundaries in ('right', 'both') else '<')} {max_val}.")
    return x

def from_file(self, filename: str | os.PathLike[str], load: t.Callable[[t.IO[t.Any]], t.Mapping[str, t.Any]], silent: bool=False, text: bool=True) -> bool:
    filename = os.path.join(self.root_path, filename)
    try:
        with open(filename, 'r' if text else 'rb') as f:
            obj = load(f)
    except OSError as e:
        if silent and e.errno in (errno.ENOENT, errno.EISDIR):
            return False
        e.strerror = f'Unable to load configuration file ({e.strerror})'
        raise
    return self.from_mapping(obj)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'target_names': ['array-like', None], 'sample_weight': ['array-like', None], 'digits': [Interval(Integral, 0, None, closed='left')], 'output_dict': ['boolean'], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def classification_report(y_true, y_pred, *, labels=None, target_names=None, sample_weight=None, digits=2, output_dict=False, zero_division='warn'):
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, unique_labels_, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    if labels is None:
        labels = unique_labels_
        labels_given = False
    else:
        labels = np.asarray(labels)
        labels_given = True
    micro_is_accuracy = (y_type == 'multiclass' or y_type == 'binary') and (not labels_given or set(labels) >= set(unique_labels(y_true, y_pred)))
    if target_names is not None and len(labels) != len(target_names):
        if labels_given:
            warnings.warn('labels size, {0}, does not match size of target_names, {1}'.format(len(labels), len(target_names)))
        else:
            raise ValueError('Number of classes, {0}, does not match size of target_names, {1}. Try specifying the labels parameter'.format(len(labels), len(target_names)))
    if target_names is None:
        target_names = ['%s' % l for l in labels]
    headers = ['precision', 'recall', 'f1-score', 'support']
    p, r, f1, s = precision_recall_fscore_support(y_true, y_pred, labels=labels, average=None, sample_weight=sample_weight, zero_division=zero_division)
    rows = zip(target_names, p, r, f1, s)
    if y_type.startswith('multilabel'):
        average_options = ('micro', 'macro', 'weighted', 'samples')
    else:
        average_options = ('micro', 'macro', 'weighted')
    if output_dict:
        report_dict = {label[0]: label[1:] for label in rows}
        for label, scores in report_dict.items():
            report_dict[label] = dict(zip(headers, [float(i) for i in scores]))
    else:
        longest_last_line_heading = 'weighted avg'
        name_width = max((len(cn) for cn in target_names))
        width = max(name_width, len(longest_last_line_heading), digits)
        head_fmt = '{:>{width}s} ' + ' {:>9}' * len(headers)
        report = head_fmt.format('', *headers, width=width)
        report += '\n\n'
        row_fmt = '{:>{width}s} ' + ' {:>9.{digits}f}' * 3 + ' {:>9}\n'
        for row in rows:
            report += row_fmt.format(*row, width=width, digits=digits)
        report += '\n'
    for average in average_options:
        if average.startswith('micro') and micro_is_accuracy:
            line_heading = 'accuracy'
        else:
            line_heading = average + ' avg'
        avg_p, avg_r, avg_f1, _ = precision_recall_fscore_support(y_true, y_pred, labels=labels, average=average, sample_weight=sample_weight, zero_division=zero_division)
        avg = [avg_p, avg_r, avg_f1, np.sum(s)]
        if output_dict:
            report_dict[line_heading] = dict(zip(headers, [float(i) for i in avg]))
        elif line_heading == 'accuracy':
            row_fmt_accuracy = '{:>{width}s} ' + ' {:>9.{digits}}' * 2 + ' {:>9.{digits}f}' + ' {:>9}\n'
            report += row_fmt_accuracy.format(line_heading, '', '', *avg[2:], width=width, digits=digits)
        else:
            report += row_fmt.format(line_heading, *avg, width=width, digits=digits)
    if output_dict:
        if 'accuracy' in report_dict.keys():
            report_dict['accuracy'] = report_dict['accuracy']['precision']
        return report_dict
    else:
        return report

