def _select_colors(mpl, item, n_classes):
    if item is None:
        if n_classes <= 10:
            item = PETROFF_COLORS[:n_classes]
        else:
            item = 'gist_rainbow'
    if isinstance(item, str):
        if item not in mpl.pyplot.colormaps():
            raise ValueError(f"When 'target_colors' is a string, it must be a valid Matplotlib colormap. Got: {item}")
        cmap = mpl.pyplot.get_cmap(item)
        if cmap.N < n_classes:
            raise ValueError(f"Colormap '{item}' only has {cmap.N} colors, but {n_classes} classes are to be displayed. Please specify a different colormap or provide a list of colors via 'target_colors'.")
        return cmap(np.linspace(0, 1, n_classes))
    elif isinstance(item, list):
        if len(item) != n_classes:
            raise ValueError(f"When 'target_colors' is a list, it must be of the same length as the classes or labels to plot ({n_classes}), got: {len(item)}.")
        elif any((not mpl.colors.is_color_like(col) for col in item)):
            raise ValueError(f"When 'target_colors' is a list, it can only contain valid Matplotlib color names. Got: {item}")
        return mpl.colors.to_rgba_array(item)
    else:
        raise TypeError("'target_colors' must be a list or a str.")

def fillna(self, value, limit: int | None=None, inplace: bool=False) -> list[Block]:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if not self._can_hold_na:
        return None
    if is_scalar(value) and self.dtype in (np.dtype('float64'), np.dtype('float32'), np.dtype('object')) and (limit is not None or inplace):
        values = cast('np.ndarray', self.values)
        try:
            casted = np_can_hold_element(values.dtype, value)
        except (LossySetitemError, NotImplementedError):
            pass
        else:
            copy, refs = self._get_refs_and_copy(inplace)
            new_values = values.copy() if copy else values
            if new_values.ndim == 1:
                filled = libalgos.scalar_fillna_inplace(new_values, casted, limit=limit)
            else:
                filled = libalgos.scalar_fillna_2d_inplace(new_values, casted, limit=limit)
            if filled == 0:
                return [self.copy(deep=False)]
            return [self.make_block_same_class(new_values, refs=refs)]
    mask = isna(self.values)
    mask, noop = validate_putmask(self.values, mask)
    if noop:
        return [self.copy(deep=False)]
    if limit is not None:
        mask[mask.cumsum(self.values.ndim - 1) > limit] = False
    if inplace:
        nbs = self.putmask(mask.T, value)
    else:
        nbs = self.where(value, ~mask.T)
    return extend_blocks(nbs)

