def _value_with_fmt(self, source) -> tuple[int | float | bool | str | datetime.datetime | datetime.date, str | None]:
    fmt = None
    if is_integer(source):
        source = int(source)
    elif is_float(source):
        source = float(source)
    elif is_bool(source):
        source = bool(source)
    elif is_decimal(source):
        source = Decimal(source)
    elif isinstance(source, datetime.datetime):
        fmt = self._datetime_format
    elif isinstance(source, datetime.date):
        fmt = self._date_format
    elif isinstance(source, datetime.timedelta):
        source = source.total_seconds() / 86400
        fmt = '0'
    else:
        source = str(source)
        if len(source) > 32767:
            warnings.warn(f'Cell contents too long ({len(source)}), truncated to 32767 characters', UserWarning, stacklevel=find_stack_level())
    return (source, fmt)

