def to_arrays(data, columns: Index | None, dtype: DtypeObj | None=None) -> tuple[list[ArrayLike], Index]:
    if not len(data):
        if isinstance(data, np.ndarray):
            if data.dtype.names is not None:
                columns = ensure_index(data.dtype.names)
                arrays = [data[name] for name in columns]
                if len(data) == 0:
                    for i, arr in enumerate(arrays):
                        if arr.ndim == 2:
                            arrays[i] = arr[:, 0]
                return (arrays, columns)
            elif data.ndim == 2:
                arrays = [data[:, idx] for idx in range(data.shape[1])]
                if columns is None:
                    columns = default_index(data.shape[1])
                return (arrays, columns)
        return ([], ensure_index([]))
    elif isinstance(data, np.ndarray) and data.dtype.names is not None:
        if columns is None:
            columns = Index(data.dtype.names)
        arrays = [data[k] for k in columns]
        return (arrays, columns)
    elif isinstance(data, np.ndarray) and data.ndim == 2:
        arrays = [data[:, idx] for idx in range(data.shape[1])]
        if columns is None:
            columns = default_index(data.shape[1])
        return (arrays, columns)
    if isinstance(data[0], (list, tuple)):
        arr = _list_to_arrays(data)
    elif isinstance(data[0], abc.Mapping):
        arr, columns = _list_of_dict_to_arrays(data, columns)
    elif isinstance(data[0], ABCSeries):
        arr, columns = _list_of_series_to_arrays(data, columns)
    else:
        row_dtypes = {row.dtype for row in data if hasattr(row, 'dtype')}
        if len(row_dtypes) == 1 and all((hasattr(row, 'dtype') for row in data)) and (len({len(row) for row in data}) == 1):
            common_dtype = row_dtypes.pop()
            ncols = len(data[0])
            arrays = [pd_array([row[col_idx] for row in data], dtype=common_dtype) for col_idx in range(ncols)]
            columns = _validate_or_indexify_columns(arrays, columns)
            return (arrays, columns)
        data = [tuple(x) for x in data]
        arr = _list_to_arrays(data)
    content, columns = _finalize_columns_and_data(arr, columns, dtype)
    return (content, columns)

