def mahalanobis(self, X):
    xp, _, device_ = get_namespace_and_device(X)
    X = validate_data(self, X, reset=False, dtype=supported_float_dtypes(xp, device_))
    precision = self.get_precision()
    if _is_numpy_namespace(xp):
        with config_context(assume_finite=True):
            dist = pairwise_distances(X, self.location_[np.newaxis, :], metric='mahalanobis', VI=precision)
        return np.reshape(dist, (len(X),)) ** 2
    else:
        X_centered = X - self.location_
        return xp.sum(X_centered @ precision * X_centered, axis=1)

