def select_dtypes(self, include=None, param_34=None) -> DataFrame:
    if not is_list_like(include):
        include = (include,) if include is not None else ()
    if not is_list_like(param_34):
        param_34 = (param_34,) if param_34 is not None else ()
    selection = (frozenset(include), frozenset(param_34))
    if not any(selection):
        raise ValueError('at least one of include or exclude must be nonempty')

    def check_int_infer_dtype(dtypes):
        converted_dtypes: list[type] = []
        for dtype in dtypes:
            if isinstance(dtype, str) and dtype == 'int' or dtype is int:
                converted_dtypes.append(np.int32)
                converted_dtypes.append(np.int64)
            elif dtype == 'float' or dtype is float:
                converted_dtypes.extend([np.float64, np.float32])
            else:
                converted_dtypes.append(infer_dtype_from_object(dtype))
        return frozenset(converted_dtypes)
    include = check_int_infer_dtype(include)
    param_34 = check_int_infer_dtype(param_34)
    for dtypes in (include, param_34):
        invalidate_string_dtypes(dtypes)
    if not include.isdisjoint(param_34):
        raise ValueError(f'include and exclude overlap on {include & param_34}')

    def dtype_predicate(dtype: DtypeObj, dtypes_set) -> bool:
        dtype = dtype if not isinstance(dtype, ArrowDtype) else dtype.numpy_dtype
        return issubclass(dtype.type, tuple(dtypes_set)) or (np.number in dtypes_set and getattr(dtype, '_is_numeric', False) and (not is_bool_dtype(dtype))) or (isinstance(dtype, StringDtype) and dtype.na_value is np.nan and (np.object_ in dtypes_set))

    def predicate(arr: ArrayLike) -> bool:
        dtype = arr.dtype
        if include:
            if not dtype_predicate(dtype, include):
                return False
        if param_34:
            if dtype_predicate(dtype, param_34):
                return False
        return True
    blk_dtypes = [blk.dtype for blk in self._mgr.blocks]
    if np.object_ in include and str not in include and (str not in param_34) and any((isinstance(dtype, StringDtype) and dtype.na_value is np.nan for dtype in blk_dtypes)):
        warnings.warn("For backward compatibility, 'str' dtypes are included by select_dtypes when 'object' dtype is specified. This behavior is deprecated and will be removed in a future version. Explicitly pass 'str' to `include` to select them, or to `exclude` to remove them and silence this warning.\nSee https://pandas.pydata.org/docs/user_guide/migration-3-strings.html#string-migration-select-dtypes for details on how to write code that works with pandas 2 and 3.", Pandas4Warning, stacklevel=find_stack_level())
    mgr = self._mgr._get_data_subset(predicate).copy(deep=False)
    return self._constructor_from_mgr(mgr, axes=mgr.axes).__finalize__(self)

