def _safe_accumulator_op(op, x, *args, **kwargs):
    xp, _, x_device = get_namespace_and_device(x)
    max_float_dtype = _max_precision_float_dtype(xp, device=x_device)
    if xp.isdtype(x.dtype, 'real floating') and xp.finfo(x.dtype).bits < xp.finfo(max_float_dtype).bits:
        target_dtype = _max_precision_float_dtype(xp, device=x_device)

        def convert_dtype(arr):
            return x
        if 'dtype' in inspect.signature(op).parameters:
            return op(x, *args, **kwargs, dtype=target_dtype)
        else:
            x = convert_dtype(x)
            args = [convert_dtype(arg) if hasattr(arg, 'dtype') else arg for arg in args]
    return op(x, *args, **kwargs)

def dot(a, b, item=False, out=None):
    if item is True:
        if np.ndim(a) == 0 or np.ndim(b) == 0:
            pass
        elif b.ndim == 1:
            a = _mask_propagate(a, a.ndim - 1)
            b = _mask_propagate(b, b.ndim - 1)
        else:
            a = _mask_propagate(a, a.ndim - 1)
            b = _mask_propagate(b, b.ndim - 2)
    am = ~getmaskarray(a)
    bm = ~getmaskarray(b)
    if out is None:
        d = np.dot(filled(a, 0), filled(b, 0))
        m = ~np.dot(am, bm)
        if np.ndim(d) == 0:
            d = np.asarray(d)
        r = d.view(get_masked_subclass(a, b))
        r.__setmask__(m)
        return r
    else:
        d = np.dot(filled(a, 0), filled(b, 0), out._data)
        if out.mask.shape != d.shape:
            out._mask = np.empty(d.shape, MaskType)
        np.dot(am, bm, out._mask)
        np.logical_not(out._mask, out._mask)
        return out

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'power': [Interval(Real, None, 0, closed='right'), Interval(Real, 1, None, closed='left')]}, prefer_skip_nested_validation=True)
def mean_tweedie_deviance(y_true, y_pred, *, sample_weight=None, power=0):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_type, y_true, y_pred, sample_weight, _ = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput=None, xp=xp)
    if y_type == 'continuous-multioutput':
        raise ValueError('Multioutput not supported in mean_tweedie_deviance')
    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)
        sample_weight = sample_weight[:, np.newaxis]
    message = f'Mean Tweedie deviance error with power={power} can only be used on '
    if power < 0:
        if xp.any(y_pred <= 0):
            raise ValueError(message + 'strictly positive y_pred.')
    elif power == 0:
        pass
    elif 1 <= power < 2:
        if xp.any(y_true < 0) or xp.any(y_pred <= 0):
            raise ValueError(message + 'non-negative y and strictly positive y_pred.')
    elif power >= 2:
        if xp.any(y_true <= 0) or xp.any(y_pred <= 0):
            raise ValueError(message + 'strictly positive y and y_pred.')
    else:
