@staticmethod
def _has_unsupported_regex(pat: str | re.Pattern) -> bool:
    try:
        from re import _parser
        regex_parser = _parser.parse
    except Exception as err:
        raise type(err)('Incompatible version for regex; you will need to upgrade pandas or downgrade Python') from err

    def has_unsupported_code(tokens):
        for op_code, argument in tokens:
            if op_code == _parser.SUBPATTERN and has_unsupported_code(argument[3]) or (op_code == _parser.BRANCH and any((has_unsupported_code(tokens) for tokens in argument[1]))) or op_code in [_parser.ASSERT_NOT, _parser.ASSERT, _parser.GROUPREF]:
                return True
        return False
    str_pat = pat.pattern if isinstance(pat, re.Pattern) else pat
    try:
        tokens = regex_parser(str_pat)
    except re.error:
        return False
    return has_unsupported_code(tokens)

def sortlevel(self, level: IndexLabel=0, ascending: bool | list[bool]=True, sort_remaining: bool=True, na_position: str='first') -> tuple[MultiIndex, npt.NDArray[np.intp]]:
    if not is_list_like(level):
        level = [level]
    level = [self._get_level_number(lev) for lev in level]
    sortorder = None
    for lev_num in level:
        lev_values = self.levels[lev_num]
        if lev_values.dtype == object and (not lev_values.is_monotonic_increasing) and (not lev_values.is_monotonic_decreasing):
            lev_values.argsort()
    codes = [self.codes[lev] for lev in level]
    if isinstance(ascending, list):
        if not len(level) == len(ascending):
            raise ValueError('level must have same length as ascending')
    elif sort_remaining:
        codes.extend([self.codes[lev] for lev in range(len(self.levels)) if lev not in level])
    else:
        sortorder = level[0]
    indexer = lexsort_indexer(codes, orders=ascending, na_position=na_position, codes_given=True)
    indexer = ensure_platform_int(indexer)
    new_codes = [level_codes.take(indexer) for level_codes in self.codes]
    new_index = MultiIndex(codes=new_codes, levels=self.levels, names=self.names, sortorder=sortorder, verify_integrity=False)
    return (new_index, indexer)

