def jax_autojit(cache: Callable[P, T]) -> Callable[P, T]:
    import jax

    @jax.jit
    def inner(wargs: _AutoJITWrapper[Any]) -> _AutoJITWrapper[T]:
        args, kwargs = wargs.obj
        res = cache(*args, **kwargs)
        return _AutoJITWrapper(res)

    @wraps(cache)
    def outer(*args: P.args, **kwargs: P.kwargs) -> T:
        wargs = _AutoJITWrapper((args, kwargs))
