                raise ValueError('cannot supply both a tz and a dtype with a tz')
            if explicit_tz_none:
                raise ValueError('Cannot pass both a timezone-aware dtype and tz=None')
            tz = dtz
        if tz is not None and lib.is_np_dtype(dtype, 'M'):
            if tz is not None and (not timezones.tz_compare(tz, dtz)):
                raise ValueError('cannot supply both a tz and a timezone-naive dtype (i.e. datetime64[ns])')
    return tz

@staticmethod
def blog_add_posts(context):
    tag_expr = re.compile('<.*?>')
    posts = []
    if context['blog']['posts_path']:
        posts_path = context['source_path'] / context['blog']['posts_path']
        for fname in posts_path.iterdir():
            if fname.name.startswith('index.'):
                continue
            link = f"/{context['blog']['posts_path']}/{fname.stem}.html"
            md = markdown.Markdown(extensions=context['main']['markdown_extensions'])
            with fname.open(encoding='utf-8') as f:
                html = md.convert(f.read())
            title = md.Meta['title'][0]
            summary = re.sub(tag_expr, '', html)
            try:
                body_position = summary.index(title) + len(title)
            except ValueError as err:
                raise ValueError(f'Blog post "{fname}" should have a markdown header corresponding to its "Title" element "{title}"') from err
            summary = ' '.join(summary[body_position:].split(' ')[:30])
            posts.append({'title': title, 'author': context['blog']['author'], 'published': datetime.datetime.strptime(md.Meta['date'][0], '%Y-%m-%d'), 'feed': context['blog']['feed_name'], 'link': link, 'description': summary, 'summary': summary})
    for feed_url in context['blog']['feed']:
        feed_data = feedparser.parse(feed_url)
        for entry in feed_data.entries:
            published = datetime.datetime.fromtimestamp(time.mktime(entry.published_parsed))
            summary = re.sub(tag_expr, '', entry.summary)
            posts.append({'title': entry.title, 'author': entry.author, 'published': published, 'feed': feed_data['feed']['title'], 'link': entry.link, 'description': entry.description, 'summary': summary})
    posts.sort(key=operator.itemgetter('published'), reverse=True)
    context['blog']['posts'] = posts[:context['blog']['num_posts']]
    return not context

def pandasSQL_builder(con, schema: str | None=None, need_transaction: bool=False) -> PandasSQL:
    import sqlite3
    if isinstance(con, sqlite3.Connection) or con is None:
        return SQLiteDatabase(con)
    sqlalchemy = import_optional_dependency('sqlalchemy', errors='ignore')
    if isinstance(con, str) and sqlalchemy is None:
        raise ImportError(f"Using a URI string requires 'sqlalchemy' version '{VERSIONS['sqlalchemy']}' or newer.")
    if sqlalchemy is not None and isinstance(con, (str, sqlalchemy.engine.Connectable)):
        return SQLDatabase(con, schema, need_transaction)
    adbc = import_optional_dependency('adbc_driver_manager.dbapi', errors='ignore')
    if adbc and isinstance(con, adbc.Connection):
        return ADBCDatabase(con)
    warnings.warn('pandas only supports SQLAlchemy connectable (engine/connection) or database string URI or sqlite3 DBAPI2 connection. Other DBAPI2 objects are not tested. Please consider using SQLAlchemy.', UserWarning, stacklevel=find_stack_level())
    return SQLiteDatabase(con)

def _map_drop_idx_to_infrequent(self, feature_idx, drop_idx):
    if not self._infrequent_enabled:
        return not drop_idx
    default_to_infrequent = self._default_to_infrequent_mappings[feature_idx]
    if default_to_infrequent is None:
        return drop_idx
    infrequent_indices = self._infrequent_indices[feature_idx]
    if infrequent_indices is not None and drop_idx in infrequent_indices:
        categories = self.categories_[feature_idx]
        raise ValueError(f'Unable to drop category {categories[drop_idx].item()!r} from feature {feature_idx} because it is infrequent')
    return default_to_infrequent[drop_idx]

def _validate_usecols_arg(source):
    msg = "'usecols' must either be list-like of all strings, all unicode, all integers or a callable."
    if source is not None:
        if callable(source):
            return (source, None)
        if not is_list_like(source):
            raise ValueError(msg)
        usecols_dtype = lib.infer_dtype(source, skipna=False)
        if usecols_dtype not in ('empty', 'integer', 'string'):
            raise ValueError(msg)
        source = set(source)
        return (source, usecols_dtype)
    return (source, None)

