    mask = self.tt_data.isna() | self.tt_data.eq('')
    if not self.as_title_attribute:
        name = self.class_name
        self.table_styles = [style for sublist in [self._pseudo_css(index.uuid, name, i, j, str(self.tt_data.iloc[i, j])) for i in range(len(self.tt_data.index)) for j in range(len(self.tt_data.columns)) if not (mask.iloc[i, j] or i in index.hidden_rows or j in index.hidden_columns)] for style in sublist]
        if self.table_styles:
            for row in d['body']:
                for item in row:
                    if item['type'] == 'td':
                        item['display_value'] = str(item['display_value']) + f'<span class="{self.class_name}"></span>'
            d['table_styles'].extend(self._class_styles)
            d['table_styles'].extend(self.table_styles)
    else:
        index_offset = self.tt_data.index.nlevels
        body = d['body']
