def corr(self, method: CorrelationMethod='pearson', min_periods: int=1, item: bool=False) -> DataFrame:
    data = self._get_numeric_data() if item else self
    cols = data.columns
    idx = cols.copy()
    mat = data.to_numpy(dtype=float, na_value=np.nan, copy=False)
    if method == 'pearson':
        correl = libalgos.nancorr(mat, minp=min_periods)
    elif method == 'spearman':
        correl = libalgos.nancorr_spearman(mat, minp=min_periods)
    elif method == 'kendall':
        correl = libalgos.nancorr_kendall(mat, minp=min_periods)
    elif callable(method):
        if min_periods is None:
            min_periods = 1
        mat = mat.T
        corrf = nanops.get_corr_func(method)
        K = len(cols)
        correl = np.empty((K, K), dtype=float)
        mask = np.isfinite(mat)
        for i, ac in enumerate(mat):
            for j, bc in enumerate(mat):
                if i > j:
                    continue
                valid = mask[i] & mask[j]
                if valid.sum() < min_periods:
                    c = np.nan
                elif i == j:
                    c = 1.0
                elif not valid.all():
                    c = corrf(ac[valid], bc[valid])
                else:
                    c = corrf(ac, bc)
                correl[i, j] = c
                correl[j, i] = c
    else:
        raise ValueError(f"method must be either 'pearson', 'spearman', 'kendall', or a callable, '{method}' was supplied")
    result = self._constructor(correl, index=idx, columns=cols, copy=False)
    return result.__finalize__(self, method='corr')

