def _accumulate(self, name: str, *, skipna: bool=True, **kwargs) -> ArrowExtensionArray | ExtensionArray:
    if is_string_dtype(self):
        return self._str_accumulate(name=name, skipna=skipna, **kwargs)
    pyarrow_name = {'cummax': 'cumulative_max', 'cummin': 'cumulative_min', 'cumprod': 'cumulative_prod_checked', 'cumsum': 'cumulative_sum_checked'}.get(name, name)
    pyarrow_meth = getattr(pc, pyarrow_name, None)
    if pyarrow_meth is None:
        return super()._accumulate(name, skipna=skipna, **kwargs)
    data_to_accum = self._pa_array
    pa_dtype = data_to_accum.type
    convert_to_int = pa.types.is_temporal(pa_dtype) and name in ['cummax', 'cummin'] or (pa.types.is_duration(pa_dtype) and name == 'cumsum')
    if convert_to_int:
        if pa_dtype.bit_width == 32:
            data_to_accum = data_to_accum.cast(pa.int32())
        else:
            data_to_accum = data_to_accum.cast(pa.int64())
    try:
        result = pyarrow_meth(data_to_accum, skip_nulls=skipna, **kwargs)
    except pa.ArrowNotImplementedError as err:
        msg = f"operation '{name}' not supported for dtype '{self.dtype}'"
        raise TypeError(msg) from err
    if convert_to_int:
        result = result.cast(pa_dtype)
    return self._from_pyarrow_array(result)

def _get_feature_index(fx, feature_names=None):
    if isinstance(fx, str):
        if feature_names is None:
            raise ValueError(f'Cannot plot partial dependence for feature {fx!r} since the list of feature names was not provided, neither as column names of a pandas data-frame nor via the feature_names parameter.')
        try:
            return feature_names.index(fx)
        except ValueError as e:
            raise ValueError(f'Feature {fx!r} not in feature_names') from e
    return fx

def _check_feature_names(estimator, X, *, reset):
    if reset:
        feature_names_in = _get_feature_names(X)
        if feature_names_in is not None:
            estimator.feature_names_in_ = feature_names_in
        elif hasattr(estimator, 'feature_names_in_'):
            delattr(estimator, 'feature_names_in_')
        return
    fitted_feature_names = getattr(estimator, 'feature_names_in_', None)
    X_feature_names = _get_feature_names(X)
    if fitted_feature_names is None and X_feature_names is None:
        return
    if X_feature_names is not None and fitted_feature_names is None:
        warnings.warn(f'X has feature names, but {estimator.__class__.__name__} was fitted without feature names')
        return
    if X_feature_names is None and fitted_feature_names is not None:
        warnings.warn(f'X does not have valid feature names, but {estimator.__class__.__name__} was fitted with feature names')
        return
    if len(fitted_feature_names) != len(X_feature_names) or np.any(fitted_feature_names != X_feature_names):
        message = 'The feature names should match those that were passed during fit.\n'
        fitted_feature_names_set = set(fitted_feature_names)
        X_feature_names_set = set(X_feature_names)
        unexpected_names = sorted(X_feature_names_set - fitted_feature_names_set)
        missing_names = sorted(fitted_feature_names_set - X_feature_names_set)

        def add_names(names):
            output = ''
            max_n_names = 5
            for i, name in enumerate(names):
                if i >= max_n_names:
                    output += '- ...\n'
                    break
                output += f'- {name}\n'
            return output
        if unexpected_names:
            message += 'Feature names unseen at fit time:\n'
            message += add_names(unexpected_names)
        if missing_names:
            message += 'Feature names seen at fit time, yet now missing:\n'
            message += add_names(missing_names)
        if not missing_names and (not unexpected_names):
