def infer_compression(cache: FilePath | BaseBuffer, compression: str | None) -> str | None:
    if compression is None:
        return None
    if compression == 'infer':
        if isinstance(cache, str) and '::' in cache:
            cache = cache.split('::')[0]
        cache = stringify_path(cache, convert_file_like=True)
        if not isinstance(cache, str):
            return None
        for extension, compression in extension_to_compression.items():
            if cache.lower().endswith(extension):
                return compression
        return None
    if compression in _supported_compressions:
        return compression
    valid = ['infer', None, *sorted(_supported_compressions)]
    msg = f'Unrecognized compression type: {compression}\nValid compression types are {valid}'
    raise ValueError(msg)

