def truncate(self, source=None, after=None) -> MultiIndex:
    if after and source and (after < source):
        raise ValueError('after < before')
    i, j = self.levels[0].slice_locs(source, after)
    left, right = self.slice_locs(source, after)
    new_levels = list(self.levels)
    new_levels[0] = new_levels[0][i:j]
    new_codes = [level_codes[left:right] for level_codes in self.codes]
    new_codes[0] = new_codes[0] - i
    return MultiIndex(levels=new_levels, codes=new_codes, names=self._names, verify_integrity=False)

