def isin(self, entry: Series | DataFrame | Sequence | Mapping) -> DataFrame:
    if isinstance(entry, dict):
        from pandas.core.reshape.concat import concat
        entry = collections.defaultdict(list, entry)
        result = concat((self.iloc[:, [i]].isin(entry[col]) for i, col in enumerate(self.columns)), axis=1)
    elif isinstance(entry, Series):
        if not entry.index.is_unique:
            raise ValueError('cannot compute isin with a duplicate axis.')
        result = self.eq(entry.reindex_like(self), axis='index')
    elif isinstance(entry, DataFrame):
        if not (entry.columns.is_unique and entry.index.is_unique):
            raise ValueError('cannot compute isin with a duplicate axis.')
        result = self.eq(entry.reindex_like(self))
    else:
        if not is_list_like(entry):
            raise TypeError(f"only list-like or dict-like objects are allowed to be passed to DataFrame.isin(), you passed a '{type(entry).__name__}'")

        def isin_(x):
            result = algorithms.isin(x.ravel(), entry)
            return result.reshape(x.shape)
        res_mgr = self._mgr.apply(isin_)
        result = self._constructor_from_mgr(res_mgr, axes=res_mgr.axes)
    return result.__finalize__(self, method='isin')

def restore_dropped_levels_multijoin(left: MultiIndex, right: MultiIndex, dropped_level_names, join_index: Index, lindexer: npt.NDArray[np.intp], rindexer: npt.NDArray[np.intp]) -> tuple[FrozenList, FrozenList, FrozenList]:

    def _convert_to_multiindex(index: Index) -> MultiIndex:
        if isinstance(index, MultiIndex):
            return index
        else:
            return MultiIndex.from_arrays([index._values], names=[index.name])
    join_index = _convert_to_multiindex(join_index)
    join_levels = join_index.levels
    join_codes = join_index.codes
    join_names = join_index.names
    for dropped_level_name in dropped_level_names:
        if dropped_level_name in left.names:
            idx = left
            indexer = lindexer
        else:
            idx = right
            indexer = rindexer
        name_idx = idx.names.index(dropped_level_name)
        restore_levels = idx.levels[name_idx]
        codes = idx.codes[name_idx]
        if indexer is None:
            restore_codes = codes
        else:
            restore_codes = algos.take_nd(codes, indexer, fill_value=-1)
        join_levels = join_levels + [restore_levels]
        join_codes = join_codes + [restore_codes]
        join_names = join_names + [dropped_level_name]
    return (join_levels, join_codes, join_names)

@set_module('numpy.rec')
def array(obj, dtype=None, shape=None, offset=0, strides=None, formats=None, names=None, titles=None, aligned=False, byteorder=None, copy=True):
    if (isinstance(obj, (type(None), str)) or hasattr(obj, 'readinto')) and formats is None and (dtype is None):
        raise ValueError('Must define formats (or dtype) if object is None, string, or an open file')
    kwds = {}
    if dtype is not None:
        dtype = sb.dtype(dtype)
    elif formats is not None:
        dtype = format_parser(formats, names, titles, aligned, byteorder).dtype
    else:
        kwds = {'formats': formats, 'names': names, 'titles': titles, 'aligned': aligned, 'byteorder': byteorder}
    if obj is None:
        if shape is None:
            raise ValueError('Must define a shape if obj is None')
        return recarray(shape, dtype, buf=obj, offset=offset, strides=strides)
    elif isinstance(obj, bytes):
        return fromstring(obj, dtype, shape=shape, offset=offset, **kwds)
    elif isinstance(obj, (list, tuple)):
        if isinstance(obj[0], (tuple, list)):
            return fromrecords(obj, dtype=dtype, shape=shape, **kwds)
        else:
            return fromarrays(obj, dtype=dtype, shape=shape, **kwds)
    elif isinstance(obj, recarray):
        if dtype is not None and obj.dtype != dtype:
            new = obj.view(dtype)
        else:
            new = obj
        if copy:
            new = new.copy()
        return new
    elif hasattr(obj, 'readinto'):
        return fromfile(obj, dtype=dtype, shape=shape, offset=offset)
    elif isinstance(obj, ndarray):
        if dtype is not None and obj.dtype != dtype:
            new = obj.view(dtype)
        else:
            new = obj
        if copy:
            new = new.copy()
        return new.view(recarray)
    else:
        interface = getattr(obj, '__array_interface__', None)
        if interface is None or not isinstance(interface, dict):
            raise ValueError('Unknown input type')
        obj = sb.array(obj)
        if dtype is not None and obj.dtype != dtype:
            obj = obj.view(dtype)
        return obj.view(recarray)

