def _warn_if_expanding(self, identifier) -> None:
    if self.ndim == 2:
        if not isinstance(identifier, tuple) or len(identifier) != 2:
            return
        checks = [(identifier[0], self.obj.index), (identifier[1], self.obj.columns)]
    else:
        check_key = identifier
        if isinstance(identifier, tuple) and len(identifier) == 1:
            check_key = identifier[0]
        checks = [(check_key, self.obj.index)]
    for check_key, axis in checks:
        if isinstance(check_key, slice) or is_list_like_indexer(check_key):
            if not isinstance(check_key, tuple):
                continue
        try:
            is_expanding = check_key not in axis
        except (TypeError, InvalidIndexError):
            continue
        if is_expanding:
            obj_type = 'DataFrame' if self.ndim == 2 else 'Series'
            warnings.warn(f'Setting a value on a {obj_type} via .at with a key that does not exist in the index is deprecated and will raise a KeyError in a future version. Use .loc instead.', Pandas4Warning, stacklevel=find_stack_level())
            return

