def _generate_range_overflow_safe_signed(endpoint: int, periods: int, stride: int, flag: str) -> int:
    assert flag in ['start', 'end']
    if flag == 'end':
        stride *= -1
    with np.errstate(over='raise'):
        addend = np.int64(periods) * np.int64(stride)
        try:
            result = np.int64(endpoint) + addend
            if result == iNaT:
                raise OverflowError
            return int(result)
        except (FloatingPointError, OverflowError):
            pass
        assert stride > 0 and endpoint >= 0 or (stride < 0 and endpoint <= 0)
        if stride > 0:
            uresult = np.uint64(endpoint) + np.uint64(addend)
            i64max = np.uint64(i8max)
            assert uresult > i64max
            if uresult <= i64max + np.uint64(stride):
                return int(uresult)
    raise OutOfBoundsDatetime(f'Cannot generate range with {flag}={endpoint} and periods={periods}')

