def _kneighbors_from_graph(graph, n_neighbors, return_distance):
    n_samples = graph.shape[0]
    assert graph.format == 'csr'
    row_nnz = np.diff(graph.indptr)
    row_nnz_min = row_nnz.min()
    if n_neighbors is not None and row_nnz_min < n_neighbors:
        raise ValueError('%d neighbors per samples are required, but some samples have only %d neighbors in precomputed graph matrix. Decrease number of neighbors used or recompute the graph with more neighbors.' % (n_neighbors, row_nnz_min))

    def extract(a):
        if row_nnz.max() == row_nnz_min:
            return a.reshape(n_samples, -1)[:, :n_neighbors]
        else:
            idx = np.tile(np.arange(n_neighbors), (n_samples, 1))
            idx += graph.indptr[:-1, None]
            return a.take(idx, mode='clip').reshape(n_samples, n_neighbors)
    if return_distance:
        return (extract(graph.data), extract(graph.indices))
    else:
        return extract(graph.indices)

def set_index(self, param_5, *, drop: bool=True, append: bool=False, inplace: bool=False, verify_integrity: bool | lib.NoDefault=lib.no_default) -> DataFrame | None:
    if verify_integrity is not lib.no_default:
        warnings.warn("The 'verify_integrity' keyword in DataFrame.set_index is deprecated and will be removed in a future version. Directly check the result.index.is_unique instead.", Pandas4Warning, stacklevel=find_stack_level())
    else:
        verify_integrity = False
    inplace = validate_bool_kwarg(inplace, 'inplace')
    self._check_inplace_and_allows_duplicate_labels(inplace)
    if not isinstance(param_5, list):
        param_5 = [param_5]
    err_msg = 'The parameter "keys" may be a column key, one-dimensional array, or a list containing only valid column keys and one-dimensional arrays.'
    missing: list[Hashable] = []
    for col in param_5:
        if isinstance(col, (Index, Series, np.ndarray, list, abc.Iterator)):
            if getattr(col, 'ndim', 1) != 1:
                raise ValueError(err_msg)
        else:
            try:
                found = col in self.columns
            except TypeError as err:
                raise TypeError(f'{err_msg}. Received column of type {type(col)}') from err
            else:
                if not found:
                    missing.append(col)
    if missing:
        raise KeyError(f'None of {missing} are in the columns')
    if inplace:
        frame = self
    else:
        frame = self.copy(deep=False)
    arrays: list[Index] = []
    names: list[Hashable] = []
    if append:
        names = list(self.index.names)
        if isinstance(self.index, MultiIndex):
            arrays.extend((self.index._get_level_values(i) for i in range(self.index.nlevels)))
        else:
            arrays.append(self.index)
    to_remove: set[Hashable] = set()
    for col in param_5:
        if isinstance(col, MultiIndex):
            arrays.extend((col._get_level_values(n) for n in range(col.nlevels)))
            names.extend(col.names)
        elif isinstance(col, (Index, Series)):
            arrays.append(col)
            names.append(col.name)
        elif isinstance(col, (list, np.ndarray)):
            arrays.append(col)
            names.append(None)
        elif isinstance(col, abc.Iterator):
            arrays.append(list(col))
            names.append(None)
        else:
            arrays.append(frame[col])
            names.append(col)
            if drop:
                to_remove.add(col)
        if len(arrays[-1]) != len(self):
            raise ValueError(f'Length mismatch: Expected {len(self)} rows, received array of length {len(arrays[-1])}')
    index = ensure_index_from_sequences(arrays, names)
    if verify_integrity and (not index.is_unique):
        duplicates = index[index.duplicated()].unique()
        raise ValueError(f'Index has duplicate keys: {duplicates}')
    for c in to_remove:
        del frame[c]
    index._cleanup()
    frame.index = index
    if not inplace:
        return frame
    return None

def _add_prefix_for_feature_names_out(self, transformer_with_feature_names_out):
    feature_names_out_callable = None
    if callable(self.verbose_feature_names_out):
        feature_names_out_callable = self.verbose_feature_names_out
    elif isinstance(self.verbose_feature_names_out, str):
        feature_names_out_callable = partial(_feature_names_out_with_str_format, str_format=self.verbose_feature_names_out)
    elif self.verbose_feature_names_out is True:
        feature_names_out_callable = partial(_feature_names_out_with_str_format, str_format='{transformer_name}__{feature_name}')
    if feature_names_out_callable is not None:
        names = list(chain.from_iterable(((feature_names_out_callable(name, i) for i in feature_names_out) for name, feature_names_out in transformer_with_feature_names_out)))
        return np.asarray(names, dtype=object)
    feature_names_count = Counter(chain.from_iterable((s for _, s in transformer_with_feature_names_out)))
    top_6_overlap = [name for name, count in feature_names_count.most_common(6) if count > 1]
    top_6_overlap.sort()
    if top_6_overlap:
        if len(top_6_overlap) == 6:
            names_repr = str(top_6_overlap[:5])[:-1] + ', ...]'
        else:
            names_repr = str(top_6_overlap)
        raise ValueError(f'Output feature names: {names_repr} are not unique. Please set verbose_feature_names_out=True to add prefixes to feature names')
    return np.concatenate([name for _, name in transformer_with_feature_names_out])

