@validate_params({'y1': ['array-like'], 'y2': ['array-like'], 'labels': ['array-like', None], 'weights': [StrOptions({'linear', 'quadratic'}), None], 'sample_weight': ['array-like', None], 'replace_undefined_by': [Interval(Real, -1.0, 1.0, closed='both'), np.nan]}, prefer_skip_nested_validation=True)
def cohen_kappa_score(y1, y2, *, labels=None, weights=None, sample_weight=None, replace_undefined_by=np.nan):
    try:
        confusion = confusion_matrix(y1, y2, labels=labels, sample_weight=sample_weight)
    except ValueError as e:
        if 'At least one label specified must be in y_true' in str(e):
            msg = 'At least one label in `labels` must be present in `y1` (even though `cohen_kappa_score` is otherwise agnostic to the order of `y1` and `y2`).'
            raise ValueError(msg) from e
        raise
    xp, _, device_ = get_namespace_and_device(y1, y2)
    n_classes = confusion.shape[0]
    max_float_dtype = _max_precision_float_dtype(xp, device=device_)
    confusion = xp.astype(confusion, max_float_dtype, copy=False)
    sum0 = xp.sum(confusion, axis=0)
    sum1 = xp.sum(confusion, axis=1)
    numerator = xp.linalg.outer(sum0, sum1)
    denominator = xp.sum(sum0)
    msg_zero_division = f'`y2` contains no labels that are present in both `y1` and `labels`.`cohen_kappa_score` is undefined and set to the value defined by the `replace_undefined_by` param, which is set to {replace_undefined_by}.'
    if denominator == 0:
        warnings.warn(msg_zero_division, UndefinedMetricWarning, stacklevel=2)
        return replace_undefined_by
    expected = numerator / denominator
    if weights is None:
        w_mat = xp.ones([n_classes, n_classes], dtype=max_float_dtype, device=device_)
        _fill_diagonal(w_mat, 0, xp=xp)
    else:
        w_mat = xp.zeros([n_classes, n_classes], dtype=max_float_dtype, device=device_)
        w_mat += xp.arange(n_classes)
        if weights == 'linear':
            w_mat = xp.abs(w_mat - w_mat.T)
        else:
            w_mat = (w_mat - w_mat.T) ** 2
    numerator = xp.sum(w_mat * confusion)
    denominator = xp.sum(w_mat * expected)
    msg_zero_division = f'`y1`, `y2` and `labels` have only one label in common. `cohen_kappa_score` is undefined and set to the value defined by the the `replace_undefined_by` param, which is set to {replace_undefined_by}.'
    if denominator == 0:
        warnings.warn(msg_zero_division, UndefinedMetricWarning, stacklevel=2)
        return replace_undefined_by
    k = numerator / denominator
    return float(1 - k)

@set_module('numpy')
def mintypecode(typechars, typeset='GDFgdf', default='d'):
    typecodes = (isinstance(t, str) and t or asarray(t).dtype.char for t in typechars)
    intersection = {t for t in typecodes if t in typeset}
    if not intersection:
        return default
    if 'F' in intersection and 'd' in intersection:
        return 'D'
    return min(intersection, key=_typecodes_by_elsize.index)

