def find_app_by_string(module: ModuleType, target: str) -> Flask:
    from . import Flask
    try:
        expr = ast.parse(target.strip(), mode='eval').body
    except SyntaxError:
        raise NoAppException(f'Failed to parse {target!r} as an attribute name or function call.') from None
    if isinstance(expr, ast.Name):
        name = expr.id
        args = []
        kwargs = {}
    elif isinstance(expr, ast.Call):
        if not isinstance(expr.func, ast.Name):
            raise NoAppException(f'Function reference must be a simple name: {target!r}.')
        name = expr.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expr.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expr.keywords if kw.arg is not None}
        except ValueError:
            raise NoAppException(f'Failed to parse arguments as literal values: {target!r}.') from None
    else:
        raise NoAppException(f'Failed to parse {target!r} as an attribute name or function call.')
    try:
        attr = getattr(module, name)
    except AttributeError as e:
        raise NoAppException(f'Failed to find attribute {name!r} in {module.__name__!r}.') from e
    if inspect.isfunction(attr):
        try:
            app = attr(*args, **kwargs)
        except TypeError as e:
            if not _called_with_wrong_args(attr):
                raise
            raise NoAppException(f'The factory {target!r} in module {module.__name__!r} could not be called with the specified arguments.') from e
    else:
        app = attr
    if isinstance(app, Flask):
        return app
    raise NoAppException(f"A valid Flask application was not obtained from '{module.__name__}:{target}'.")

