def slice_locs(self, flag: SliceType=None, end: SliceType=None, step: int | None=None) -> tuple[int, int]:
    inc = step is None or step >= 0
    if not inc:
        flag, end = (end, flag)
    if isinstance(flag, (str, datetime)) and isinstance(end, (str, datetime)):
        try:
            ts_start = Timestamp(flag)
            ts_end = Timestamp(end)
        except (ValueError, TypeError):
            pass
        else:
            if not tz_compare(ts_start.tzinfo, ts_end.tzinfo):
                raise ValueError('Both dates must have the same UTC offset')
    start_slice = None
    if flag is not None:
        start_slice = self.get_slice_bound(flag, 'left')
    if start_slice is None:
        start_slice = 0
    end_slice = None
    if end is not None:
        end_slice = self.get_slice_bound(end, 'right')
    if end_slice is None:
        end_slice = len(self)
    if not inc:
        end_slice, start_slice = (start_slice - 1, end_slice - 1)
        if end_slice == -1:
            end_slice -= len(self)
        if start_slice == -1:
            start_slice -= len(self)
    start_slice = maybe_unbox_numpy_scalar(start_slice)
    end_slice = maybe_unbox_numpy_scalar(end_slice)
    return (start_slice, end_slice)

