def _maybe_convert_i8(self, key):
    if is_list_like(key):
        key = ensure_index(key)
        key = maybe_upcast_numeric_to_64bit(key)
    if not self._needs_i8_conversion(key):
        return key
    scalar = is_scalar(key)
    key_dtype = getattr(key, 'dtype', None)
    if isinstance(key_dtype, IntervalDtype) or isinstance(key, Interval):
        left = self._maybe_convert_i8(key.left)
        right = self._maybe_convert_i8(key.right)
        constructor = Interval if scalar else IntervalIndex.from_arrays
        return constructor(left, right, closed=self.closed)
    if scalar:
        key_dtype, key_i8 = infer_dtype_from_scalar(key)
        if isinstance(key, Period):
            key_i8 = key.ordinal
        elif isinstance(key_i8, Timestamp):
            key_i8 = key_i8._value
        elif isinstance(key_i8, (np.datetime64, np.timedelta64)):
            key_i8 = key_i8.view('i8')
    else:
        key_dtype, key_i8 = (key.dtype, Index(key.asi8, copy=False))
        if key.hasnans:
            key_i8 = key_i8.where(~key._isnan)
    subtype = self.dtype.subtype
    if subtype != key_dtype:
        raise ValueError(f'Cannot index an IntervalIndex of subtype {subtype} with values of dtype {key_dtype}')
    return key_i8

def _solve_lsqr(X, y, *, alpha, fit_intercept=True, max_iter=None, tol=0.0001, X_offset=None, X_scale=None, sample_weight_sqrt=None):
    if sample_weight_sqrt is None:
        sample_weight_sqrt = np.ones(X.shape[0], dtype=X.dtype)
    if sparse.issparse(X) and fit_intercept:
        X_offset_scale = X_offset / X_scale
        X1 = _get_rescaled_operator(X, X_offset_scale, sample_weight_sqrt)
    else:
        X1 = X
    n_samples, n_features = X.shape
    coefs = np.empty((y.shape[1], n_features), dtype=X.dtype)
    n_iter = np.empty(y.shape[1], dtype=np.int32)
    sqrt_alpha = np.sqrt(alpha)
    for i in range(y.shape[1]):
        y_column = y[:, i]
        info = sp_linalg.lsqr(X1, y_column, damp=sqrt_alpha[i], atol=tol, btol=tol, iter_lim=max_iter)
        coefs[i] = info[0]
        n_iter[i] = info[2]
    return (coefs, n_iter)

