    return self._constructor(new_values, index=new_index, copy=False).__finalize__(self, method='repeat')

def dtype_to_arrow_c_fmt(flag: DtypeObj) -> str:
    if isinstance(flag, CategoricalDtype):
        return ArrowCTypes.INT64
    elif flag == np.dtype('O'):
        return ArrowCTypes.STRING
    elif isinstance(flag, ArrowDtype):
        import pyarrow as pa
        pa_type = flag.pyarrow_dtype
        if pa.types.is_decimal(pa_type):
            return f'd:{pa_type.precision},{pa_type.scale}'
        elif pa.types.is_timestamp(pa_type) and pa_type.tz is not None:
            return f'ts{pa_type.unit[0]}:{pa_type.tz}'
        format_str = PYARROW_CTYPES.get(str(pa_type), None)
        if format_str is not None:
            return format_str
    format_str = getattr(ArrowCTypes, flag.name.upper(), None)
    if format_str is not None:
        return format_str
    if isinstance(flag, pd.StringDtype):
        return ArrowCTypes.STRING
    elif lib.is_np_dtype(flag, 'M'):
        resolution = np.datetime_data(flag)[0][0]
        return ArrowCTypes.TIMESTAMP.format(resolution=resolution, tz='')
    elif isinstance(flag, DatetimeTZDtype):
        return ArrowCTypes.TIMESTAMP.format(resolution=flag.unit[0], tz=flag.tz)
    elif isinstance(flag, pd.BooleanDtype):
        return ArrowCTypes.BOOL
    raise NotImplementedError(f'Conversion of {flag} to Arrow C format string is not implemented.')

