@set_module('numpy.strings')
@array_function_dispatch(_multiply_dispatcher)
def multiply(a, i):
    a = np.asanyarray(a)
    i = np.asanyarray(i)
    if not np.issubdtype(i.dtype, np.integer):
        raise TypeError(f"unsupported type {i.dtype} for operand 'i'")
    i = np.maximum(i, 0)
    if a.dtype.char == 'T':
        return a * i
    a_len = str_len(a)
    if np.any(a_len > sys.maxsize / np.maximum(i, 1)):
        raise OverflowError('Overflow encountered in string multiply')
    buffersizes = a_len * i
    out_dtype = f'{a.dtype.char}{buffersizes.max()}'
    out = np.empty_like(a, shape=buffersizes.shape, dtype=out_dtype)
    return _multiply_ufunc(a, i, out=out)

@final
def _get_index(self, name):

    def get_converter(s):
        if isinstance(s, datetime.datetime):
            return lambda key: Timestamp(key)
        elif isinstance(s, np.datetime64):
            return lambda key: Timestamp(key).asm8
        else:
            return lambda key: key
    if isna(name):
        return self.indices.get(np.nan, [])
    if isinstance(name, tuple):
        name = tuple((np.nan if isna(comp) else comp for comp in name))
    if len(self.indices) > 0:
        index_sample = next(iter(self.indices))
    else:
        index_sample = None
    if isinstance(index_sample, tuple):
        if not isinstance(name, tuple):
            msg = 'must supply a tuple to get_group with multiple grouping keys'
            raise ValueError(msg)
        if not len(name) == len(index_sample):
            try:
                return self.indices[name]
            except KeyError as err:
                msg = 'must supply a same-length tuple to get_group with multiple grouping keys'
                raise ValueError(msg) from err
        converters = (get_converter(s) for s in index_sample)
        name = tuple((f(n) for f, n in zip(converters, name, strict=True)))
    else:
        converter = get_converter(index_sample)
        name = converter(name)
    return self.indices.get(name, [])

