    X = validate_data(self, X, reset=False, accept_sparse='csr', copy=copy, dtype=supported_float_dtypes(xp, X_device), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead. See docstring for motivation and alternatives.')
