        proxy_manager = self.proxy_manager_for(proxy)
        conn = proxy_manager.connection_from_host(**host_params, pool_kwargs=pool_kwargs)
    else:
        conn = self.poolmanager.connection_from_host(**host_params, pool_kwargs=pool_kwargs)
    return conn

def between(self, left, right, inclusive: Literal['both', 'neither', 'left', 'right']='both') -> Series:
    if inclusive == 'both':
        lmask = self >= left
        rmask = self <= right
    elif inclusive == 'left':
        lmask = self >= left
        rmask = self < right
    elif inclusive == 'right':
        lmask = self > left
        rmask = self <= right
    elif inclusive == 'neither':
        lmask = self > left
        rmask = self < right
    else:
        raise ValueError("Inclusive has to be either string of 'both','left', 'right', or 'neither'.")
    return lmask & rmask

def _apply_tablewise(self, homogeneous_func: Callable[..., ArrayLike], name: str | None=None, numeric_only: bool=False) -> DataFrame | Series:
    if self._selected_obj.ndim == 1:
        raise ValueError("method='table' not applicable for Series objects.")
    obj = self._create_data(self._selected_obj, numeric_only)
    values = self._prep_values(obj.to_numpy())
    result = homogeneous_func(values)
    index = self._slice_axis_for_step(obj.index, result)
    columns = obj.columns if result.shape[1] == len(obj.columns) else obj.columns[::self.step]
    out = obj._constructor(result, index=index, columns=columns)
    return self._resolve_output(out, obj)

def get_loc(self, key):
    self._check_indexing_error(key)
    orig_key = key
    if is_valid_na_for_dtype(key, self.dtype):
        key = NaT
    if isinstance(key, self._data._recognized_scalars):
        self._disallow_mismatched_indexing(key)
        key = Timestamp(key)
    elif isinstance(key, str):
        try:
            parsed, reso = self._parse_with_reso(key)
        except ValueError as err:
            raise KeyError(key) from err
        self._disallow_mismatched_indexing(parsed)
        if self._can_partial_date_slice(reso):
            try:
                return self._partial_date_slice(reso, parsed)
            except KeyError as err:
                raise KeyError(key) from err
        key = parsed
    elif isinstance(key, dt.timedelta):
        raise TypeError(f'Cannot index {type(self).__name__} with {type(key).__name__}')
    elif isinstance(key, dt.time):
        return self.indexer_at_time(key)
    else:
        raise KeyError(key)
    try:
        return Index.get_loc(self, key)
    except KeyError as err:
        raise KeyError(orig_key) from err

def assert_numpy_array_equal(left: Any, right: Any, strict_nan: bool=False, check_dtype: bool | Literal['equiv']=True, err_msg: str | None=None, check_same: Literal['copy', 'same'] | None=None, obj: str='numpy array', index_values: Index | np.ndarray | None=None) -> None:
    __tracebackhide__ = True
    assert_class_equal(left, right, obj=obj)
    _check_isinstance(left, right, np.ndarray)

    def _get_base(obj: np.ndarray) -> Any:
        return obj.base if getattr(obj, 'base', None) is not None else obj
    left_base = _get_base(left)
    right_base = _get_base(right)
    if check_same == 'same':
        if left_base is not right_base:
            raise AssertionError(f'{left_base!r} is not {right_base!r}')
    elif check_same == 'copy':
        if left_base is right_base:
            raise AssertionError(f'{left_base!r} is {right_base!r}')

    def _raise(left: np.ndarray, right: np.ndarray, err_msg: str | None) -> NoReturn:
        if err_msg is None:
            if left.shape != right.shape:
                raise_assert_detail(obj, f'{obj} shapes are different', left.shape, right.shape)
            diff = 0.0
            for left_arr, right_arr in zip(left, right, strict=True):
                if not array_equivalent(left_arr, right_arr, strict_nan=strict_nan):
                    diff += 1
            diff = diff * 100.0 / left.size
            msg = f'{obj} values are different ({np.round(diff, 5)} %)'
            raise_assert_detail(obj, msg, left, right, index_values=index_values)
        raise AssertionError(err_msg)
    if not array_equivalent(left, right, strict_nan=strict_nan):
        _raise(left, right, err_msg)
    if check_dtype:
        if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
            assert_attr_equal('dtype', left, right, obj=obj)

