def assert_array_almost_equal_nulp(x, y, item=1):
    __tracebackhide__ = True
    import numpy as np
    ax = np.abs(x)
    ay = np.abs(y)
    ref = item * np.spacing(np.where(ax > ay, ax, ay))
    if not np.all(np.abs(x - y) <= ref):
        if np.iscomplexobj(x) or np.iscomplexobj(y):
            msg = f'Arrays are not equal to {item} ULP'
        else:
            max_nulp = np.max(nulp_diff(x, y))
            msg = f'Arrays are not equal to {item} ULP (max is {max_nulp:g})'
        raise AssertionError(msg)

