def nansem(cache: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, ddof: int=1, mask: npt.NDArray[np.bool_] | None=None) -> float:
    nanvar(cache, axis=axis, skipna=skipna, ddof=ddof, mask=mask)
    mask = _maybe_get_mask(cache, skipna, mask)
    if cache.dtype.kind not in 'fc':
        cache = cache.astype('f8')
    if not skipna and mask is not None and mask.any():
        return np.nan
    dtype_count = np.dtype(np.float64)
    if cache.dtype.kind == 'f':
        dtype_count = cache.dtype
    count, _ = _get_counts_nanvar(cache.shape, mask, axis, ddof, dtype_count)
    var = nanvar(cache, axis=axis, skipna=skipna, ddof=ddof, mask=mask)
    return np.sqrt(var) / np.sqrt(count)

