@set_module('numpy.lib.array_utils')
def byte_bounds(target):
    ai = target.__array_interface__
    a_data = ai['data'][0]
    astrides = ai['strides']
    ashape = ai['shape']
    bytes_a = asarray(target).dtype.itemsize
    a_low = a_high = a_data
    if astrides is None:
        a_high += target.size * bytes_a
    else:
        for shape, stride in zip(ashape, astrides):
            if stride < 0:
                a_low += (shape - 1) * stride
            else:
                a_high += (shape - 1) * stride
        a_high += bytes_a
    return (a_low, a_high)

