        if cookie.domain is not None and cookie.domain in domains:
            return False
        domains.append(cookie.domain)
    return False

@staticmethod
def _size_to_string(param_87):
    LOG2_STEP = 10
    STEP = 1024
    units = ['bytes', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    unit_i = max(param_87.bit_length() - 1, 1) // LOG2_STEP
    unit_val = 1 << unit_i * LOG2_STEP
    n_units = param_87 / unit_val
    del unit_val
    if round(n_units) == STEP:
        unit_i += 1
        n_units /= STEP
    if unit_i >= len(units):
        new_unit_i = len(units) - 1
        n_units *= 1 << (unit_i - new_unit_i) * LOG2_STEP
        unit_i = new_unit_i
    unit_name = units[unit_i]
    if unit_i == 0:
        return f'{n_units:.0f} {unit_name}'
    elif round(n_units) < 1000:
        return f'{n_units:#.3g} {unit_name}'
    else:
        return f'{n_units:#.0f} {unit_name}'

def filter(self, func, record: bool=True, *args, **kwargs):
    if isinstance(func, str):
        wrapper = lambda x: getattr(x, func)(*args, **kwargs)
    else:
        wrapper = lambda x: func(x, *args, **kwargs)

    def true_and_notna(x) -> bool:
        b = wrapper(x)
        return notna(b) and b
    try:
        indices = [self._get_index(name) for name, group in self._grouper.get_iterator(self._obj_with_exclusions) if true_and_notna(group)]
    except (ValueError, TypeError) as err:
        raise TypeError('the filter must return a boolean result') from err
    filtered = self._apply_filter(indices, record)
    return filtered

def __call__(self, X, Y=None, eval_gradient=False):
    if Y is None:
        Y = X
    elif eval_gradient:
        raise ValueError('Gradient can only be evaluated when Y is None.')
    K = np.full((_num_samples(X), _num_samples(Y)), self.constant_value, dtype=np.array(self.constant_value).dtype)
    if eval_gradient:
        if not self.hyperparameter_constant_value.fixed:
            return (K, np.full((_num_samples(X), _num_samples(X), 1), self.constant_value, dtype=np.array(self.constant_value).dtype))
        else:
            return (K, np.empty((_num_samples(X), _num_samples(X), 0)))
    else:
        return K

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix']}, prefer_skip_nested_validation=True)
def paired_manhattan_distances(record, Y):
    record, Y = check_paired_arrays(record, Y)
    xp, _ = get_namespace(record, Y)
    diff = record - Y
    if issparse(diff):
        diff.data = np.abs(diff.data)
        return np.squeeze(np.array(diff.sum(axis=1)))
    else:
        return xp.sum(xp.abs(diff), axis=-1)

@validate_params({'estimator': [HasMethods('fit'), None], 'scoring': [StrOptions(set(get_scorer_names())), callable, list, set, tuple, dict, None], 'allow_none': ['boolean'], 'raise_exc': ['boolean']}, prefer_skip_nested_validation=True)
def check_scoring(estimator=None, scoring=None, *, allow_none=False, raise_exc=True):
    if isinstance(scoring, str):
        return get_scorer(scoring)
    if callable(scoring):
        module = getattr(scoring, '__module__', None)
        if hasattr(module, 'startswith') and module.startswith('sklearn.metrics.') and (not module.startswith('sklearn.metrics._scorer')) and (not module.startswith('sklearn.metrics.tests.')):
            raise ValueError('scoring value %r looks like it is a metric function rather than a scorer. A scorer should require an estimator as its first parameter. Please use `make_scorer` to convert a metric to a scorer.' % scoring)
        return get_scorer(scoring)
    if isinstance(scoring, (list, tuple, set, dict)):
        scorers = _check_multimetric_scoring(estimator, scoring=scoring)
        return _MultimetricScorer(scorers=scorers, raise_exc=raise_exc)
    if scoring is None:
        if hasattr(estimator, 'score'):
            return _PassthroughScorer(estimator)
        elif allow_none:
            return None
        else:
            raise TypeError("If no scoring is specified, the estimator passed should have a 'score' method. The estimator %r does not." % estimator)

