@set_module('numpy')
def isdtype(dtype, kind):
    try:
        dtype = _preprocess_dtype(dtype)
    except _PreprocessDTypeError:
        raise TypeError(f'dtype argument must be a NumPy dtype, but it is a {type(dtype)}.') from None
    input_kinds = kind if isinstance(kind, tuple) else (kind,)
    processed_kinds = set()
    for kind in input_kinds:
        if kind == 'bool':
            processed_kinds.add(allTypes['bool'])
        elif kind == 'signed integer':
            processed_kinds.update(sctypes['int'])
        elif kind == 'unsigned integer':
            processed_kinds.update(sctypes['uint'])
        elif kind == 'integral':
            processed_kinds.update(sctypes['int'] + sctypes['uint'])
        elif kind == 'real floating':
            processed_kinds.update(sctypes['float'])
        elif kind == 'complex floating':
            processed_kinds.update(sctypes['complex'])
        elif kind == 'numeric':
            processed_kinds.update(sctypes['int'] + sctypes['uint'] + sctypes['float'] + sctypes['complex'])
        elif isinstance(kind, str):
            raise ValueError(f'kind argument is a string, but {kind!r} is not a known kind name.')
        else:
            try:
                kind = _preprocess_dtype(kind)
            except _PreprocessDTypeError:
                raise TypeError(f'kind argument must be comprised of NumPy dtypes or strings only, but is a {type(kind)}.') from None
            processed_kinds.add(kind)
    return dtype in processed_kinds

def _solve_eigen_gram(self, alpha, y, sqrt_sw, eigvals, Q, QT_y, QT_sqrt_sw, XT, record):
    D = 1.0 / (eigvals + alpha)
    c = Q @ self._diag_dot(D, QT_y)
    d = self._decomp_diag(D, Q)
    if self.fit_intercept:
        sw_sum = sqrt_sw @ sqrt_sw
        Ginv_sqrt_sw = Q @ self._diag_dot(D, QT_sqrt_sw)
        d -= Ginv_sqrt_sw * sqrt_sw / sw_sum
    if y.ndim == 2:
        d = d[:, None]
    XT_c = XT @ c
    if self.fit_intercept and sparse.issparse(XT):
        if y.ndim == 2:
            XT_c -= record[:, None] * (sqrt_sw @ c)
        else:
            XT_c -= record * (sqrt_sw @ c)
    looe = c / d
    coef = XT_c
    return (looe, coef)

