def get_loc(self, key):
    self._check_indexing_error(key)

    def _maybe_to_slice(loc):
        """convert integer indexer to boolean mask or slice if possible"""
        if not isinstance(loc, np.ndarray) or loc.dtype != np.intp:
            return loc
        loc = lib.maybe_indices_to_slice(loc, len(self))
        if isinstance(loc, slice):
            return loc
        mask = np.empty(len(self), dtype='bool')
        mask.fill(False)
        mask[loc] = True
        return mask
    if not isinstance(key, tuple):
        loc = self._get_level_indexer(key, level=0)
        return _maybe_to_slice(loc)
    keylen = len(key)
    if self.nlevels < keylen:
        raise KeyError(f'Key length ({keylen}) exceeds index depth ({self.nlevels})')
    if keylen == self.nlevels:
        try:
            return self._engine.get_loc(key)
        except KeyError as err:
            raise KeyError(key) from err
        except (TypeError, ValueError):
            loc, _ = self.get_loc_level(key, range(self.nlevels))
            return loc
    i = self._lexsort_depth
    lead_key, follow_key = (key[:i], key[i:])
    if not lead_key:
        start = 0
        stop = len(self)
    else:
        try:
            start, stop = self.slice_locs(lead_key, lead_key)
        except TypeError as err:
            raise KeyError(key) from err
    if start == stop:
        raise KeyError(key)
    if not follow_key:
        return slice(start, stop)
    if config['mode']['performance_warnings']:
        warnings.warn('indexing past lexsort depth may impact performance.', PerformanceWarning, stacklevel=find_stack_level())
    loc = np.arange(start, stop, dtype=np.intp)
    for i, k in enumerate(follow_key, len(lead_key)):
        level_idx = self._get_loc_single_level_index(self.levels[i], k)
        if is_integer(level_idx):
            mask = self.codes[i][loc] == level_idx
        else:
            level_mask = np.zeros(len(self.levels[i]), dtype=bool)
            level_mask[level_idx] = True
            mask = level_mask[self.codes[i][loc]]
        if not mask.all():
            loc = loc[mask]
        if not len(loc):
            raise KeyError(key)
    return _maybe_to_slice(loc) if len(loc) != stop - start else slice(start, stop)

def chebder(c, m=1, scl=1, axis=0):
    c = np.array(c, ndmin=1, copy=True)
    if c.dtype.char in '?bBhHiIlLqQpP':
        c = c.astype(np.double)
    cnt = pu._as_int(m, 'the order of derivation')
    iaxis = pu._as_int(axis, 'the axis')
    if cnt < 0:
        raise ValueError('The order of derivation must be non-negative')
    iaxis = np.lib.array_utils.normalize_axis_index(iaxis, c.ndim)
    if cnt == 0:
        return c
    c = np.moveaxis(c, iaxis, 0)
    n = len(c)
    if cnt >= n:
        c = c[:1] * 0
    else:
        for i in range(cnt):
            n = n - 1
            c *= scl
            der = np.empty((n,) + c.shape[1:], dtype=c.dtype)
            for j in range(n, 2, -1):
                der[j - 1] = 2 * j * c[j]
                c[j - 2] += j * c[j] / (j - 2)
            if n > 1:
                der[1] = 4 * c[2]
            der[0] = c[1]
            c = der
    c = np.moveaxis(c, 0, iaxis)
    return c

