@set_module('numpy.lib.array_utils')
def normalize_axis_tuple(axis, ndim, argname=None, allow_duplicate=False):
    if not isinstance(axis, (tuple, list)):
        try:
            axis = [operator.index(axis)]
        except TypeError:
            pass
    axis = tuple((normalize_axis_index(ax, ndim, argname) for ax in axis))
    if not allow_duplicate and len(set(axis)) != len(axis):
        if argname:
            raise ValueError(f'repeated axis in `{argname}` argument')
        else:
            raise ValueError('repeated axis')
    return axis

def sample_y(self, X, n_samples=1, random_state=0):
    rng = check_random_state(random_state)
    y_mean, y_cov = self.predict(X, return_cov=True)
    if y_mean.ndim == 1:
        y_samples = rng.multivariate_normal(y_mean, y_cov, n_samples).T
    else:
        y_samples = [rng.multivariate_normal(y_mean[:, target], y_cov[..., target], n_samples).T[:, np.newaxis] for target in range(y_mean.shape[1])]
        y_samples = np.hstack(y_samples)
    return y_samples

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like'], 'loss': [StrOptions({'squared_hinge', 'log'})], 'fit_intercept': ['boolean'], 'intercept_scaling': [Interval(Real, 0, None, closed='neither')]}, prefer_skip_nested_validation=True)
def l1_min_c(X, y, *, loss='squared_hinge', fit_intercept=True, intercept_scaling=1.0):
    X = check_array(X, accept_sparse='csc')
    check_consistent_length(X, y)
    Y = LabelBinarizer(neg_label=-1).fit_transform(y).T
    den = np.max(np.abs(safe_sparse_dot(Y, X)))
    if fit_intercept:
        bias = np.full((np.size(y), 1), intercept_scaling, dtype=np.array(intercept_scaling).dtype)
        den = max(den, abs(np.dot(Y, bias)).max())
    if den == 0.0:
        raise ValueError('Ill-posed l1_min_c calculation: l1 will always select zero coefficients for this data')
    if loss == 'squared_hinge':
        return 0.5 / den
    else:
        return 2.0 / den

def _score(estimator, X_test, y_test, scorer, score_params, error_score='raise'):
    score_params = {} if score_params is None else score_params
    try:
        if y_test is None:
            scores = scorer(estimator, X_test, **score_params)
        else:
            scores = scorer(estimator, X_test, y_test, **score_params)
    except Exception:
        if isinstance(scorer, _MultimetricScorer):
            raise
        elif error_score == 'raise':
            raise
        else:
            scores = error_score
            warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{format_exc()}', UserWarning)
    if isinstance(scorer, _MultimetricScorer):
        exception_messages = [(name, str_e) for name, str_e in scores.items() if isinstance(str_e, str)]
        if exception_messages:
            for name, str_e in exception_messages:
                scores[name] = error_score
                warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{str_e}', UserWarning)
    error_msg = 'scoring must return a number, got %s (%s) instead. (scorer=%s)'
    if isinstance(scores, dict):
        for name, score in scores.items():
            if hasattr(score, 'item'):
                with suppress(ValueError):
                    score = score.item()
            if not isinstance(score, numbers.Number):
                raise ValueError(error_msg % (score, type(score), name))
            scores[name] = score
    else:
        if hasattr(scores, 'item'):
            with suppress(ValueError):
                scores = scores.item()
        if not isinstance(scores, numbers.Number):
            raise ValueError(error_msg % (scores, type(scores), scorer))
    return scores

