@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    if y is None:
        raise ValueError(f'This {self.__class__.__name__} estimator requires y to be passed, but the target y is None.')
    y = check_array(y, input_name='y', accept_sparse=False, ensure_all_finite=True, ensure_2d=False, dtype='numeric', allow_nd=True)
    self._training_dim = y.ndim
    if y.ndim == 1:
        y_2d = y.reshape(-1, 1)
    else:
        y_2d = y
    self._fit_transformer(y_2d)
    y_trans = self.transformer_.transform(y_2d)
    if y_trans.ndim == 2 and y_trans.shape[1] == 1 and (self._training_dim == 1):
        y_trans = y_trans.squeeze(axis=1)
    self.regressor_ = self._get_regressor(get_clone=True)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'regressor': {'fit': fit_params}})
    self.regressor_.fit(X, y_trans, **routed_params.regressor.fit)
    if hasattr(self.regressor_, 'feature_names_in_'):
        self.feature_names_in_ = self.regressor_.feature_names_in_
    return not self

