def _align_series(self, indexer, ser: Series, multiindex_indexer: bool=False) -> ArrayLike | Series:
    if isinstance(indexer, (slice, np.ndarray, list, Index)):
        indexer = (indexer,)
    if isinstance(indexer, tuple):
        if len(indexer) == 2 and isinstance(indexer[1], np.ndarray) and (indexer[1].dtype == np.bool_):
            indexer = (indexer[0], np.where(indexer[1])[0])

        def ravel(i):
            return i.ravel() if isinstance(i, np.ndarray) else i
        indexer = tuple(map(ravel, indexer))
        aligners = [not com.is_null_slice(idx) for idx in indexer]
        sum_aligners = sum(aligners)
        single_aligner = sum_aligners == 1
        is_frame = self.ndim == 2
        obj = self.obj
        if is_frame:
            single_aligner = single_aligner and aligners[0]
        if all((is_sequence(_) or isinstance(_, slice) for _ in indexer)):
            ser_values = ser.reindex(obj.axes[0][indexer[0]])._values
            if len(indexer) > 1 and (not multiindex_indexer):
                if isinstance(indexer[1], slice):
                    len_indexer = len(obj.axes[1][indexer[1]])
                else:
                    len_indexer = len(indexer[1])
                ser_values = np.tile(ser_values, len_indexer).reshape(len_indexer, -1).T
            return ser_values
        for i, idx in enumerate(indexer):
            ax = obj.axes[i]
            if is_sequence(idx) or isinstance(idx, slice):
                if single_aligner and com.is_null_slice(idx):
                    continue
                new_ix = ax[idx]
                if not is_list_like_indexer(new_ix):
                    new_ix = Index([new_ix])
                else:
                    new_ix = Index(new_ix)
                if not len(new_ix) or ser.index.equals(new_ix):
                    return ser._values
                return ser.reindex(new_ix)._values
            elif single_aligner:
                ax = self.obj.axes[1]
                if ser.index.equals(ax) or not len(ax):
                    return ser._values.copy()
                return ser.reindex(ax)._values
    elif is_integer(indexer) and self.ndim == 1:
        if is_object_dtype(self.obj.dtype):
            return ser
        ax = self.obj._get_axis(0)
        if ser.index.equals(ax):
            return ser._values.copy()
        return ser.reindex(ax)._values[indexer]
    elif is_integer(indexer):
        ax = self.obj._get_axis(1)
        if ser.index.equals(ax):
            return ser._values.copy()
        return ser.reindex(ax)._values
    raise ValueError('Incompatible indexer with Series')

def _parse_latex_css_conversion(styles: CSSList) -> CSSList:

    def font_weight(value, arg) -> tuple[str, str] | None:
        if value in ('bold', 'bolder'):
            return ('bfseries', f'{arg}')
        return None

    def font_style(value, arg) -> tuple[str, str] | None:
        if value == 'italic':
            return ('itshape', f'{arg}')
        if value == 'oblique':
            return ('slshape', f'{arg}')
        return None

    def color(value, user_arg, command, comm_arg):
        """
        CSS colors have 5 formats to process:

         - 6 digit hex code: "#ff23ee"     --> [HTML]{FF23EE}
         - 3 digit hex code: "#f0e"        --> [HTML]{FF00EE}
         - rgba: rgba(128, 255, 0, 0.5)    --> [rgb]{0.502, 1.000, 0.000}
         - rgb: rgb(128, 255, 0,)          --> [rbg]{0.502, 1.000, 0.000}
         - string: red                     --> {red}

        Additionally rgb or rgba can be expressed in % which is also parsed.
        """
        arg = user_arg if user_arg != '' else comm_arg
        if value[0] == '#' and len(value) == 7:
            return (command, f'[HTML]{{{value[1:].upper()}}}{arg}')
        if value[0] == '#' and len(value) == 4:
            val = f'{value[1].upper() * 2}{value[2].upper() * 2}{value[3].upper() * 2}'
            return (command, f'[HTML]{{{val}}}{arg}')
        elif value[:3] == 'rgb':
            r = re.findall('(?<=\\()[0-9\\s%]+(?=,)', value)[0].strip()
            r = float(r[:-1]) / 100 if '%' in r else int(r) / 255
            g = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[0].strip()
            g = float(g[:-1]) / 100 if '%' in g else int(g) / 255
            if value[3] == 'a':
                b = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[1].strip()
            else:
                b = re.findall('(?<=,)[0-9\\s%]+(?=\\))', value)[0].strip()
            b = float(b[:-1]) / 100 if '%' in b else int(b) / 255
            return (command, f'[rgb]{{{r:.3f}, {g:.3f}, {b:.3f}}}{arg}')
        else:
            return (command, f'{{{value}}}{arg}')
    CONVERTED_ATTRIBUTES: dict[str, Callable] = {'font-weight': font_weight, 'background-color': partial(color, command='cellcolor', comm_arg='--lwrap'), 'color': partial(color, command='color', comm_arg=''), 'font-style': font_style}
    latex_styles: CSSList = []
    for attribute, value in styles:
        if isinstance(value, str) and '--latex' in value:
            latex_styles.append((attribute, value.replace('--latex', '')))
        if attribute in CONVERTED_ATTRIBUTES:
            arg = ''
            for x in ['--wrap', '--nowrap', '--lwrap', '--dwrap', '--rwrap']:
                if x in str(value):
                    arg, value = (x, _parse_latex_options_strip(value, x))
                    break
            latex_style = CONVERTED_ATTRIBUTES[attribute](value, arg)
            if latex_style is not None:
                latex_styles.extend([latex_style])
    return latex_styles

def move_to(*arrays, xp, device):
    if isinstance(device, str) and device == 'xpu':
        device += ':0'
    sparse_mask = [sp.issparse(array) for array in arrays]
    none_mask = [array is None for array in arrays]
    if any(sparse_mask) and (not _is_numpy_namespace(xp)):
        raise TypeError('Sparse arrays are only accepted (and passed through) when the target namespace is Numpy')
    arrays_ = arrays
    if _max_precision_float_dtype(xp, device) == xp.float32:
        arrays_ = []
        for array in arrays:
            xp_array, _ = get_namespace(array)
            if getattr(array, 'dtype', None) == xp_array.float64:
                arrays_.append(xp_array.astype(array, xp_array.float32))
            else:
                arrays_.append(array)
    converted_arrays = []
    for array, is_sparse, is_none in zip(arrays_, sparse_mask, none_mask):
        if is_none:
            converted_arrays.append(None)
        elif is_sparse:
            converted_arrays.append(array)
        else:
            xp_array, _, device_array = get_namespace_and_device(array)
            if xp == xp_array and device == device_array:
                converted_arrays.append(array)
            else:
                try:
                    array_converted = xp.from_dlpack(array, device=device)
                except (AttributeError, TypeError, NotImplementedError, BufferError, ValueError):
                    if _is_numpy_namespace(xp):
                        array_converted = _convert_to_numpy(array, xp_array)
                    elif _is_numpy_namespace(xp_array):
                        array_converted = xp.asarray(array, device=device)
                    else:
                        array_np = _convert_to_numpy(array, xp_array)
                        array_converted = xp.asarray(array_np, device=device)
                converted_arrays.append(array_converted)
    return converted_arrays[0] if len(converted_arrays) == 1 else tuple(converted_arrays)

def __call__(self, num: float) -> str:
    dnum = Decimal(str(num))
    if Decimal.is_nan(dnum):
        return 'NaN'
    if Decimal.is_infinite(dnum):
        return 'inf'
    sign = 1
    if dnum < 0:
        sign = -1
        dnum = -dnum
    if dnum != 0:
        pow10 = Decimal(int(math.floor(dnum.log10() / 3) * 3))
    else:
        pow10 = Decimal(0)
    pow10 = pow10.min(max(self.ENG_PREFIXES.keys()))
    pow10 = pow10.max(min(self.ENG_PREFIXES.keys()))
    int_pow10 = int(pow10)
    if self.use_eng_prefix:
        prefix = self.ENG_PREFIXES[int_pow10]
    elif int_pow10 < 0:
        prefix = f'E-{-int_pow10:02d}'
    else:
        prefix = f'E+{int_pow10:02d}'
    mant = sign * dnum / 10 ** pow10
    if self.accuracy is None:
        format_str = '{mant: g}{prefix}'
    else:
