def _isna(entry: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    if is_scalar(entry):
        return libmissing.checknull(entry)
    elif isinstance(entry, ABCMultiIndex):
        raise NotImplementedError('isna is not defined for MultiIndex')
    elif isinstance(entry, type):
        return False
    elif isinstance(entry, (np.ndarray, ABCExtensionArray)):
        return _isna_array(entry)
    elif isinstance(entry, ABCIndex):
        if not entry._can_hold_na:
            return entry.isna()
        return _isna_array(entry._values)
    elif isinstance(entry, ABCSeries):
        result = _isna_array(entry._values)
        result = entry._constructor(result, index=entry.index, name=entry.name, copy=False)
        return result
    elif isinstance(entry, ABCDataFrame):
        return entry.isna()
    elif isinstance(entry, list):
        return _isna_array(np.asarray(entry, dtype=object))
    elif hasattr(entry, '__array__'):
        return _isna_array(np.asarray(entry))
    else:
        return False

