def _get_loc_level(self, key, token: int | list[int]=0):

    def maybe_mi_droplevels(indexer, levels):
        """
            If level does not exist or all levels were dropped, the exception
            has to be handled outside.
            """
        if not levels:
            return self[indexer]
        drop_set = set(levels)
        kept = [i for i in range(self.nlevels) if i not in drop_set]
        if not kept:
            raise ValueError(f'Cannot remove {len(levels)} levels from an index with {self.nlevels} levels: at least one level must be left.')
        new_levels = [self.levels[i] for i in kept]
        new_codes = [self.codes[i][indexer] for i in kept]
        new_names = [self.names[i] for i in kept]
        return droplevel_result(new_levels, new_codes, new_names)
    if isinstance(token, (tuple, list)):
        if len(key) != len(token):
            raise AssertionError('Key for location must have same length as number of levels')
        result = None
        for lev, k in zip(token, key, strict=True):
            loc, new_index = self._get_loc_level(k, level=lev)
            if isinstance(loc, slice):
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask
            result = loc if result is None else result & loc
        try:
            mi = maybe_mi_droplevels(result, token)
        except ValueError:
            mi = self[result]
        return (result, mi)
    if isinstance(key, list):
        key = tuple(key)
    if isinstance(key, tuple) and token == 0:
        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=token)
                new_index = maybe_mi_droplevels(indexer, [0])
                return (indexer, new_index)
        except (TypeError, InvalidIndexError):
            pass
        if not any((isinstance(k, slice) for k in key)):
            if len(key) == self.nlevels:
                try:
                    loc = self._engine.get_loc(key)
                except KeyError as err:
                    raise KeyError(key) from err
                except (TypeError, ValueError):
                    loc = None
                if is_integer(loc):
                    return (loc, None)
            indexer = self.get_loc(key)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            if len(ilevels) == self.nlevels:
                if is_integer(indexer):
                    return (indexer, None)
                ilevels = [i for i in range(len(key)) if (not isinstance(key[i], str) or not self.levels[i]._supports_partial_string_indexing) and key[i] != slice(None, None)]
                if len(ilevels) == self.nlevels:
                    if isinstance(indexer, np.ndarray) and indexer.dtype == bool:
                        inds, = indexer.nonzero()
                        if len(inds) == 1:
                            return (inds[0].item(), None)
                    ilevels = []
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
        else:
            indexer = None
            for i, k in enumerate(key):
                if not isinstance(k, slice):
                    loc_level = self._get_level_indexer(k, level=i)
                    if isinstance(loc_level, slice):
                        if com.is_null_slice(loc_level) or com.is_full_slice(loc_level, len(self)):
                            continue
                        k_index = np.zeros(len(self), dtype=bool)
                        k_index[loc_level] = True
                    else:
                        k_index = loc_level
                elif com.is_null_slice(k):
                    continue
                else:
                    raise TypeError(f'Expected label or tuple of labels, got {key}')
                if indexer is None:
                    indexer = k_index
                else:
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
    else:
        indexer = self._get_level_indexer(key, level=token)
        if isinstance(key, str) and self.levels[token]._supports_partial_string_indexing:
            check = self.levels[token].get_loc(key)
            if not is_integer(check):
                return (indexer, self[indexer])
        try:
            result_index = maybe_mi_droplevels(indexer, [token])
        except ValueError:
            result_index = self[indexer]
        return (indexer, result_index)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, param_5=None, **params):
    _raise_for_params(params, self, 'fit')
    copy_X = self.copy_X and self.fit_intercept
    check_y_params = dict(copy=False, dtype=[np.float64, np.float32], ensure_2d=False)
    if isinstance(X, np.ndarray) or sparse.issparse(X):
        reference_to_old_X = X
        check_X_params = dict(accept_sparse='csc', dtype=[np.float64, np.float32], force_writeable=True, copy=False, accept_large_sparse=False)
        X, y = validate_data(self, X, y, validate_separately=(check_X_params, check_y_params))
        if sparse.issparse(X):
            if hasattr(reference_to_old_X, 'data') and (not np.may_share_memory(reference_to_old_X.data, X.data)):
                copy_X = False
        elif not np.may_share_memory(reference_to_old_X, X):
            copy_X = False
        del reference_to_old_X
    else:
        check_X_params = dict(accept_sparse='csc', dtype=[np.float64, np.float32], order='F', force_writeable=True, copy=copy_X)
        X, y = validate_data(self, X, y, validate_separately=(check_X_params, check_y_params))
        copy_X = False
    check_consistent_length(X, y)
    if not self._is_multitask():
        if y.ndim > 1 and y.shape[1] > 1:
            raise ValueError('For multi-task outputs, use MultiTask%s' % self.__class__.__name__)
        y = column_or_1d(y, warn=True)
    elif y.ndim == 1:
        raise ValueError('For mono-task outputs, use %sCV' % self.__class__.__name__[9:])
    if isinstance(param_5, numbers.Number):
        param_5 = None
    if param_5 is not None:
        param_5 = _check_sample_weight(param_5, X, dtype=X.dtype)
    model = self._get_estimator()
    path_params = self.get_params()
    path_params.pop('fit_intercept', None)
    if 'l1_ratio' in path_params:
        l1_ratios = np.atleast_1d(path_params['l1_ratio'])
        path_params['l1_ratio'] = l1_ratios[0]
    else:
        l1_ratios = [1]
    path_params.pop('cv', None)
    path_params.pop('n_jobs', None)
    n_l1_ratio = len(l1_ratios)
    check_scalar_alpha = partial(check_scalar, target_type=Real, min_val=0.0, include_boundaries='left')
    if isinstance(self.alphas, Integral):
        alphas = [_alpha_grid(X, y, l1_ratio=l1_ratio, fit_intercept=self.fit_intercept, positive=getattr(self, 'positive', False), eps=self.eps, n_alphas=self.alphas, sample_weight=param_5) for l1_ratio in l1_ratios]
    else:
        for index, alpha in enumerate(self.alphas):
            check_scalar_alpha(alpha, f'alphas[{index}]')
        alphas = np.tile(np.sort(self.alphas)[::-1], (n_l1_ratio, 1))
    path_params['copy_X'] = copy_X
    if effective_n_jobs(self.n_jobs) > 1:
        path_params['copy_X'] = False
    cv = check_cv(self.cv)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', sample_weight=param_5, **params)
    else:
        routed_params = _manual_routing({'splitter': {}})
    folds = list(cv.split(X, y, **routed_params.splitter.split))
    best_mse = np.inf
    jobs = (delayed(_path_residuals)(X, y, param_5, train, test, self.fit_intercept, self.path, path_params, alphas=this_alphas, l1_ratio=this_l1_ratio, X_order='F', dtype=X.dtype.type) for this_l1_ratio, this_alphas in zip(l1_ratios, alphas) for train, test in folds)
    mse_paths = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')(jobs)
    mse_paths = np.reshape(mse_paths, (n_l1_ratio, len(folds), -1))
    mean_mse = np.mean(mse_paths, axis=1)
    self.mse_path_ = np.squeeze(np.moveaxis(mse_paths, 2, 1))
    for l1_ratio, l1_alphas, mse_alphas in zip(l1_ratios, alphas, mean_mse):
        i_best_alpha = np.argmin(mse_alphas)
        this_best_mse = mse_alphas[i_best_alpha]
        if this_best_mse < best_mse:
            best_alpha = l1_alphas[i_best_alpha]
            best_l1_ratio = l1_ratio
            best_mse = this_best_mse
    self.l1_ratio_ = best_l1_ratio
    self.alpha_ = best_alpha
    if isinstance(self.alphas, Integral):
        self.alphas_ = np.asarray(alphas)
        if n_l1_ratio == 1:
            self.alphas_ = self.alphas_[0]
    else:
        self.alphas_ = np.asarray(alphas[0])
    common_params = {name: value for name, value in self.get_params().items() if name in model.get_params()}
    model.set_params(**common_params)
    model.alpha = best_alpha
    model.l1_ratio = best_l1_ratio
    model.copy_X = copy_X
    precompute = getattr(self, 'precompute', None)
    if isinstance(precompute, str) and precompute == 'auto':
        model.precompute = False
    if param_5 is None:
        model.fit(X, y)
    else:
        model.fit(X, y, sample_weight=param_5)
    if not hasattr(self, 'l1_ratio'):
        del self.l1_ratio_
    self.coef_ = model.coef_
    self.intercept_ = model.intercept_
    self.dual_gap_ = model.dual_gap_
    self.n_iter_ = model.n_iter_
    return self

def to_numpy(self, dtype: npt.DTypeLike | None=None, copy: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    original_na_value = na_value
    dtype, na_value = to_numpy_dtype_inference(self, dtype, na_value, self._hasna)
    pa_type = self._pa_array.type
    if not self._hasna or isna(na_value) or pa.types.is_null(pa_type):
        data = self
    else:
        data = self.fillna(na_value)
        copy = False
    if pa.types.is_timestamp(pa_type) or pa.types.is_duration(pa_type):
        if dtype != object and na_value is self.dtype.na_value:
            na_value = lib.no_default
        result = data._maybe_convert_datelike_array().to_numpy(dtype=dtype, na_value=na_value)
    elif pa.types.is_time(pa_type) or pa.types.is_date(pa_type):
        result = np.array(list(data), dtype=dtype)
        if data._hasna:
            result[data.isna()] = na_value
    elif pa.types.is_null(pa_type):
        if dtype is not None and isna(na_value):
            na_value = None
        result = np.full(len(data), fill_value=na_value, dtype=dtype)
    elif not data._hasna or (pa.types.is_floating(pa_type) and (na_value is np.nan or (original_na_value is lib.no_default and is_float_dtype(dtype) and is_nan_na()))):
        result = data._pa_array.to_numpy()
        if dtype is not None:
            result = result.astype(dtype, copy=False)
        if copy:
            result = result.copy()
    else:
        if dtype is None:
            empty = pa.array([], type=pa_type).to_numpy(zero_copy_only=False)
            if can_hold_element(empty, na_value):
                dtype = empty.dtype
            else:
                dtype = np.object_
        result = np.empty(len(data), dtype=dtype)
        mask = data.isna()
        result[mask] = na_value
        result[~mask] = data[~mask]._pa_array.to_numpy()
    return result

