def min(self, axis=None, target=None, fill_value=None, keepdims=np._NoValue):
    kwargs = {} if keepdims is np._NoValue else {'keepdims': keepdims}
    _mask = self._mask
    newmask = _check_mask_axis(_mask, axis, **kwargs)
    if fill_value is None:
        fill_value = minimum_fill_value(self)
    if target is None:
        result = self.filled(fill_value).min(axis=axis, out=target, **kwargs).view(type(self))
        if result.ndim:
            result.__setmask__(newmask)
            if newmask.ndim:
                np.copyto(result, result.fill_value, where=newmask)
        elif newmask:
            result = masked
        return result
    self.filled(fill_value).min(axis=axis, out=target, **kwargs)
    if isinstance(target, MaskedArray):
        outmask = getmask(target)
        if outmask is nomask:
            outmask = target._mask = make_mask_none(target.shape)
        outmask.flat = newmask
    else:
        if target.dtype.kind in 'biu':
            errmsg = 'Masked data information would be lost in one or more location.'
            raise MaskError(errmsg)
        np.copyto(target, np.nan, where=newmask)
    return target

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite='allow-nan')
    if not X.shape[1] == self.n_features_in_:
        raise ValueError(f'X has {X.shape[1]} features, but PowerTransformer is expecting {self.n_features_in_} features as input.')
    if self.standardize:
        X = self._scaler.inverse_transform(X)
    inv_fun = {'box-cox': inv_boxcox, 'yeo-johnson': self._yeo_johnson_inverse_transform}[self.method]
    for i, lmbda in enumerate(self.lambdas_):
        with warnings.catch_warnings(record=True) as captured_warnings:
            with np.errstate(invalid='warn'):
                X[:, i] = inv_fun(X[:, i], lmbda)
        if any(('invalid value encountered in power' in str(w.message) for w in captured_warnings)):
            warnings.warn(f'Some values in column {i} of the inverse-transformed data are NaN. This may be caused by numerical issues in the transformation process, e.g. extremely skewed data. Consider inspecting the input data or preprocessing it before applying the transformation.', UserWarning)
    return X

