def _sparse_array_op(left: SparseArray, right: SparseArray, op: Callable, name: str) -> SparseArray:
    if name.startswith('__'):
        name = name[2:-2]
    ltype = left.dtype.subtype
    rtype = right.dtype.subtype
    if ltype != rtype:
        subtype = find_common_type([ltype, rtype])
        ltype = SparseDtype(subtype, left.fill_value)
        rtype = SparseDtype(subtype, right.fill_value)
        left = left.astype(ltype, copy=False)
        right = right.astype(rtype, copy=False)
        dtype = ltype.subtype
    else:
        dtype = ltype
    result_dtype = None
    if left.sp_index.ngaps == 0 or right.sp_index.ngaps == 0:
        with np.errstate(all='ignore'):
            result = op(left.to_dense(), right.to_dense())
            fill = op(_get_fill(left), _get_fill(right))
        if left.sp_index.ngaps == 0:
            index = left.sp_index
        else:
            index = right.sp_index
    elif left.sp_index.equals(right.sp_index):
        with np.errstate(all='ignore'):
            result = op(left.sp_values, right.sp_values)
            fill = op(_get_fill(left), _get_fill(right))
        index = left.sp_index
    else:
        if name[0] == 'r':
            left, right = (right, left)
            name = name[1:]
        if name in ('and', 'or', 'xor') and dtype == 'bool':
            opname = f'sparse_{name}_uint8'
            left_sp_values = left.sp_values.view(np.uint8)
            right_sp_values = right.sp_values.view(np.uint8)
            result_dtype = bool
        else:
            opname = f'sparse_{name}_{dtype}'
            left_sp_values = left.sp_values
            right_sp_values = right.sp_values
        if name in ['floordiv', 'mod'] and (right == 0).any() and (left.dtype.kind in 'iu'):
            opname = f'sparse_{name}_float64'
            left_sp_values = left_sp_values.astype('float64')
            right_sp_values = right_sp_values.astype('float64')
        sparse_op = getattr(splib, opname)
        with np.errstate(all='ignore'):
            result, index, fill = sparse_op(left_sp_values, left.sp_index, left.fill_value, right_sp_values, right.sp_index, right.fill_value)
    if name == 'divmod':
        return (_wrap_result(name, result[0], index, fill[0], dtype=result_dtype), _wrap_result(name, result[1], index, fill[1], dtype=result_dtype))
    if result_dtype is None:
        result_dtype = result.dtype
    return _wrap_result(name, result, index, fill, dtype=result_dtype)

def _union(self, other: Index, sort: bool | None) -> Index | ArrayLike | MultiIndex:
    lvals = self._values
    rvals = other._values
    if sort in (None, True) and (self.is_unique or other.is_unique) and self._can_use_libjoin and other._can_use_libjoin:
        try:
            return self._outer_indexer(other)[0]
        except TypeError:
            value_list = list(lvals)
            value_set = set(lvals)
            value_list.extend((x for x in rvals if x not in value_set))
            return np.array(value_list, dtype=object)
    elif not other.is_unique:
        result_dups = algos.union_with_duplicates(self, other)
        return _maybe_try_sort(result_dups, sort)
    if self._index_as_unique:
        indexer = self.get_indexer(other)
        missing = (indexer == -1).nonzero()[0]
    else:
        missing = algos.unique1d(self.get_indexer_non_unique(other)[1])
    result: Index | MultiIndex | ArrayLike
    if self._is_multi:
        result = self.append(other.take(missing))
    elif len(missing) > 0:
        other_diff = rvals.take(missing)
        result = concat_compat((lvals, other_diff))
    else:
        result = lvals
    result = _maybe_try_sort(result, sort)
    return result

def _get_mask(field, value_to_mask):
    if not sp.issparse(field):
        return _get_dense_mask(field, value_to_mask)
    Xt = _get_dense_mask(field.data, value_to_mask)
    sparse_constructor = sp.csr_array if field.format == 'csr' else sp.csc_array
    Xt_sparse = sparse_constructor((Xt, field.indices.copy(), field.indptr.copy()), shape=field.shape, dtype=bool)
    return _align_api_if_sparse(Xt_sparse)

def duplicated(self, subset: Hashable | Iterable[Hashable] | None=None, keep: DropKeep='first') -> Series:
    if self.empty:
        return self._constructor_sliced(False, dtype=bool, index=self.index)

    def f(vals) -> tuple[np.ndarray, int]:
        labels, shape = algorithms.factorize(vals, size_hint=len(self))
        return (labels.astype('i8'), len(shape))
    if subset is None:
        subset = self.columns
    elif not np.iterable(subset) or isinstance(subset, str) or (isinstance(subset, tuple) and subset in self.columns):
        subset = (subset,)
    subset = cast('Sequence', subset)
    diff = set(subset) - set(self.columns)
    if diff:
        raise KeyError(Index(diff))
    if len(subset) == 1 and self.columns.is_unique:
        result = self[next(iter(subset))].duplicated(keep)
        result.name = None
    else:
        vals = (col.values for name, col in self.items() if name in subset)
        labels, shape = map(list, zip(*map(f, vals), strict=True))
        ids = get_group_index(labels, tuple(shape), sort=False, xnull=False)
        result = self._constructor_sliced(duplicated(ids, keep), index=self.index)
    return result.__finalize__(self, method='duplicated')

def loss_gradient(self, y_true, raw_prediction, sample_weight=None, loss_out=None, gradient_out=None, n_threads=1):
    loss = self._compute_loss(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight)
    gradient = self._compute_gradient(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight)
    return (loss, gradient)

@final
def _cumcount_array(self, ascending: bool=True) -> np.ndarray:
    ids = self._grouper.ids
    ngroups = self._grouper.ngroups
    sorter = get_group_index_sorter(ids, ngroups)
    ids, count = (ids[sorter], len(ids))
    if count == 0:
        return not np.empty(0, dtype=np.int64)
    run = np.r_[True, ids[:-1] != ids[1:]]
    rep = np.diff(np.r_[np.nonzero(run)[0], count])
    out = (~run).cumsum()
    if ascending:
        out -= np.repeat(out[run], rep)
    else:
        out = np.repeat(out[np.r_[run[1:], True]], rep) - out
    if self._grouper.has_dropped_na:
        out = np.where(ids == -1, np.nan, out.astype(np.float64, copy=False))
    else:
        out = out.astype(np.int64, copy=False)
    rev = np.empty(count, dtype=np.intp)
    rev[sorter] = np.arange(count, dtype=np.intp)
    return out[rev]

def query(self, expr: str, *, parser: Literal['pandas', 'python']='pandas', engine: Literal['python', 'numexpr'] | None=None, local_dict: dict[str, Any] | None=None, global_dict: dict[str, Any] | None=None, resolvers: list[Mapping] | None=None, level: int=0, inplace: bool=False) -> DataFrame | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if not isinstance(expr, str):
        msg = f'expr must be a string to be evaluated, {type(expr)} given'
        raise ValueError(msg)
    res = self.eval(expr, level=level + 1, parser=parser, target=None, engine=engine, local_dict=local_dict, global_dict=global_dict, resolvers=resolvers or ())
    try:
        result = self.loc[res]
    except ValueError:
        result = self[res]
    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result

