def gradient_hessian(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, gradient_out=None, hessian_out=None, grad_pointwise_out=None, hess_pointwise_out=None, raw_prediction=None):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    if raw_prediction is None:
        weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    sw_sum = n_samples if sample_weight is None else np.sum(sample_weight)
    if gradient_out is None:
        grad = np.empty_like(coef, dtype=weights.dtype, order='F')
    elif gradient_out.shape != coef.shape:
        raise ValueError(f'gradient_out is required to have shape coef.shape = {coef.shape}; got {gradient_out.shape}.')
    elif self.base_loss.is_multiclass and (not gradient_out.flags.f_contiguous):
        raise ValueError('gradient_out must be F-contiguous.')
    else:
        grad = gradient_out
    n = coef.size
    if hessian_out is None:
        hess = np.empty((n, n), dtype=weights.dtype)
    elif hessian_out.shape != (n, n):
        raise ValueError(f'hessian_out is required to have shape ({(n, n)}); got hessian_out.shape={hessian_out.shape!r}.')
    elif self.base_loss.is_multiclass and (not hessian_out.flags.c_contiguous and (not hessian_out.flags.f_contiguous)):
        raise ValueError('hessian_out must be contiguous.')
    else:
        hess = hessian_out
    if not self.base_loss.is_multiclass:
        grad_pointwise, hess_pointwise = self.base_loss.gradient_hessian(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=grad_pointwise_out, hessian_out=hess_pointwise_out, n_threads=n_threads)
        grad_pointwise /= sw_sum
        hess_pointwise /= sw_sum
        hessian_warning = np.average(hess_pointwise <= 0, weights=sample_weight) > 0.25
        hess_pointwise = np.abs(hess_pointwise)
        grad[:n_features] = X.T @ grad_pointwise + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = grad_pointwise.sum()
        if hessian_warning:
            return (grad, hess, hessian_warning)
        hess[:n_features, :n_features] = sandwich_dot(X, hess_pointwise)
        if l2_reg_strength > 0:
            order = 'C' if hess.flags.c_contiguous else 'F'
            hess.reshape(-1, order=order)[:n_features * n_dof:n_dof + 1] += l2_reg_strength
        if self.fit_intercept:
            Xh = X.T @ hess_pointwise
            hess[:-1, -1] = Xh
            hess[-1, :-1] = Xh
            hess[-1, -1] = hess_pointwise.sum()
    else:
        grad_pointwise, proba = self.base_loss.gradient_proba(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=grad_pointwise_out, proba_out=hess_pointwise_out, n_threads=n_threads)
        grad_pointwise /= sw_sum
        grad = grad.reshape((n_classes, n_dof), order='F')
        grad[:, :n_features] = grad_pointwise.T @ X + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = grad_pointwise.sum(axis=0)
        if coef.ndim == 1:
            grad = grad.ravel(order='F')
        if sample_weight is not None:
            sw = sample_weight / sw_sum
        else:
            sw = 1.0 / sw_sum
        for k in range(n_classes):
            h = proba[:, k] * (1 - proba[:, k]) * sw
            hess[k:n_classes * n_features:n_classes, k:n_classes * n_features:n_classes] = sandwich_dot(X, h)
            if self.fit_intercept:
                Xh = X.T @ h
                hess[k:n_classes * n_features:n_classes, n_classes * n_features + k] = Xh
                hess[n_classes * n_features + k, k:n_classes * n_features:n_classes] = Xh
                hess[n_classes * n_features + k, n_classes * n_features + k] = h.sum()
            for l in range(k + 1, n_classes):
                h = -proba[:, k] * proba[:, l] * sw
                hess[k:n_classes * n_features:n_classes, l:n_classes * n_features:n_classes] = sandwich_dot(X, h)
                if self.fit_intercept:
                    Xh = X.T @ h
                    hess[k:n_classes * n_features:n_classes, n_classes * n_features + l] = Xh
                    hess[n_classes * n_features + k, l:n_classes * n_features:n_classes] = Xh
                    hess[n_classes * n_features + k, n_classes * n_features + l] = h.sum()
                hess[l::n_classes, k::n_classes] = hess[k::n_classes, l::n_classes]
        if l2_reg_strength > 0:
            order = 'C' if hess.flags.c_contiguous else 'F'
            hess.reshape(-1, order=order)[:n_classes ** 2 * n_features * n_dof:n_classes * n_dof + 1] += l2_reg_strength
        hessian_warning = False
    return (grad, hess, hessian_warning)

def hermint(c, m=1, param_80=[], lbnd=0, scl=1, axis=0):
    c = np.array(c, ndmin=1, copy=True)
    if c.dtype.char in '?bBhHiIlLqQpP':
        c = c.astype(np.double)
    if not np.iterable(param_80):
        param_80 = [param_80]
    cnt = pu._as_int(m, 'the order of integration')
    iaxis = pu._as_int(axis, 'the axis')
    if cnt < 0:
        raise ValueError('The order of integration must be non-negative')
    if len(param_80) > cnt:
        raise ValueError('Too many integration constants')
    if np.ndim(lbnd) != 0:
        raise ValueError('lbnd must be a scalar.')
    if np.ndim(scl) != 0:
        raise ValueError('scl must be a scalar.')
    iaxis = np.lib.array_utils.normalize_axis_index(iaxis, c.ndim)
    if cnt == 0:
        return c
    c = np.moveaxis(c, iaxis, 0)
    param_80 = list(param_80) + [0] * (cnt - len(param_80))
    for i in range(cnt):
        n = len(c)
        c *= scl
        if n == 1 and np.all(c[0] == 0):
            c[0] += param_80[i]
        else:
            tmp = np.empty((n + 1,) + c.shape[1:], dtype=c.dtype)
            tmp[0] = c[0] * 0
            tmp[1] = c[0] / 2
            for j in range(1, n):
                tmp[j + 1] = c[j] / (2 * (j + 1))
            tmp[0] += param_80[i] - hermval(lbnd, tmp)
            c = tmp
    c = np.moveaxis(c, 0, iaxis)
    return c

