def _groupby_op(self, *, how: str, has_dropped_na: bool, min_count: int, ngroups: int, ids: npt.NDArray[np.intp], **kwargs) -> ArrayLike:
    if how in ['first', 'last']:
        return self._groupby_first_last(how=how, min_count=min_count, ngroups=ngroups, ids=ids, skipna=kwargs.get('skipna', True))
    from pandas.core.arrays.string_ import StringDtype
    from pandas.core.groupby.ops import WrappedCythonOp
    kind = WrappedCythonOp.get_kind_from_how(how)
    op = WrappedCythonOp(how=how, kind=kind, has_dropped_na=has_dropped_na)
    initial: Any = 0
    if isinstance(self.dtype, StringDtype):
        if op.how in ['prod', 'mean', 'median', 'cumsum', 'cumprod', 'std', 'sem', 'var', 'skew', 'kurt']:
            raise TypeError(f"dtype '{self.dtype}' does not support operation '{how}'")
        if op.how not in ['any', 'all']:
            op._get_cython_function(op.kind, op.how, np.dtype(object), False)
        arr = self
        if op.how == 'sum':
            initial = ''
            assert 'skipna' in kwargs
            if kwargs['skipna'] and min_count == 0:
                arr = arr.fillna('')
        npvalues = arr.to_numpy(object, na_value=np.nan)
    else:
        raise NotImplementedError(f'function is not implemented for this dtype: {self.dtype}')
    res_values = op._cython_op_ndim_compat(npvalues, min_count=min_count, ngroups=ngroups, comp_ids=ids, mask=None, initial=initial, **kwargs)
    if op.how in op.cast_blocklist:
        return res_values
    if isinstance(self.dtype, StringDtype):
        dtype = self.dtype
        string_array_cls = dtype.construct_array_type()
        return string_array_cls._from_sequence(res_values, dtype=dtype)
    else:
        raise NotImplementedError

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, source):
    if self.metric == 'manhattan':
        X, source = validate_data(self, X, source, accept_sparse=['csc'])
    else:
        ensure_all_finite = 'allow-nan' if get_tags(self).input_tags.allow_nan else True
        X, source = validate_data(self, X, source, ensure_all_finite=ensure_all_finite, accept_sparse=['csr', 'csc'])
    is_X_sparse = sp.issparse(X)
    check_classification_targets(source)
    n_samples, n_features = X.shape
    le = LabelEncoder()
    y_ind = le.fit_transform(source)
    self.classes_ = classes = le.classes_
    n_classes = classes.size
    if n_classes < 2:
        raise ValueError('The number of classes has to be greater than one; got %d class' % n_classes)
    if self.priors == 'empirical':
        _, class_counts = np.unique(source, return_inverse=True)
        self.class_prior_ = np.bincount(class_counts) / float(len(source))
    elif self.priors == 'uniform':
        self.class_prior_ = np.asarray([1 / n_classes] * n_classes)
    else:
        self.class_prior_ = np.asarray(self.priors)
    if (self.class_prior_ < 0).any():
        raise ValueError('priors must be non-negative')
    if not np.isclose(self.class_prior_.sum(), 1.0):
        warnings.warn('The priors do not sum to 1. Normalizing such that it sums to one.', UserWarning)
        self.class_prior_ = self.class_prior_ / self.class_prior_.sum()
    self.centroids_ = np.empty((n_classes, n_features), dtype=np.float64)
    nk = np.zeros(n_classes)
    for cur_class in range(n_classes):
        center_mask = y_ind == cur_class
        nk[cur_class] = np.sum(center_mask)
        if is_X_sparse:
            center_mask = np.where(center_mask)[0]
        if self.metric == 'manhattan':
            if not is_X_sparse:
                self.centroids_[cur_class] = np.median(X[center_mask], axis=0)
            else:
                self.centroids_[cur_class] = csc_median_axis_0(X[center_mask])
        else:
            self.centroids_[cur_class] = X[center_mask].mean(axis=0)
    variance = np.array(X - self.centroids_[y_ind], copy=False) ** 2
    self.within_class_std_dev_ = np.array(np.sqrt(variance.sum(axis=0) / (n_samples - n_classes)), copy=False)
    if any(self.within_class_std_dev_ == 0):
        warnings.warn('self.within_class_std_dev_ has at least 1 zero standard deviation.Inputs within the same classes for at least 1 feature are identical.')
    err_msg = 'All features have zero variance. Division by zero.'
    if is_X_sparse and np.all((X.max(axis=0) - X.min(axis=0)).toarray() == 0):
        raise ValueError(err_msg)
    elif not is_X_sparse and np.all(np.ptp(X, axis=0) == 0):
        raise ValueError(err_msg)
    dataset_centroid_ = X.mean(axis=0)
    m = np.sqrt(1.0 / nk - 1.0 / n_samples)
    s = self.within_class_std_dev_ + np.median(self.within_class_std_dev_)
    mm = m.reshape(len(m), 1)
    ms = mm * s
    self.deviations_ = np.array((self.centroids_ - dataset_centroid_) / ms, copy=False)
    if self.shrink_threshold:
        signs = np.sign(self.deviations_)
        self.deviations_ = np.abs(self.deviations_) - self.shrink_threshold
        np.clip(self.deviations_, 0, None, out=self.deviations_)
        self.deviations_ *= signs
        msd = ms * self.deviations_
        self.centroids_ = np.array(dataset_centroid_ + msd, copy=False)
    return self

def deprecate_kwarg(klass: type[Warning], old_arg_name: str, new_arg_name: str | None, mapping: Mapping[Any, Any] | Callable[[Any], Any] | None=None, stacklevel: int=2) -> Callable[[Callable[P, T]], Callable[P, T]]:
    if mapping is not None and (not hasattr(mapping, 'get')) and (not callable(mapping)):
        raise TypeError('mapping from old to new argument values must be dict or callable!')

    def _deprecate_kwarg(func: Callable[P, T]) -> Callable[P, T]:

        @wraps(func)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> T:
            __tracebackhide__ = True
            old_arg_value = kwargs.pop(old_arg_name, None)
            if old_arg_value is not None:
                if new_arg_name is None:
                    msg = f'the {old_arg_name!r} keyword is deprecated and will be removed in a future version. Please take steps to stop the use of {old_arg_name!r}'
                    warnings.warn(msg, klass, stacklevel=stacklevel)
                    kwargs[old_arg_name] = old_arg_value
                    return func(*args, **kwargs)
                elif mapping is not None:
                    if callable(mapping):
                        new_arg_value = mapping(old_arg_value)
                    else:
                        new_arg_value = mapping.get(old_arg_value, old_arg_value)
                    msg = f'the {old_arg_name}={old_arg_value!r} keyword is deprecated, use {new_arg_name}={new_arg_value!r} instead.'
                else:
                    new_arg_value = old_arg_value
                    msg = f'the {old_arg_name!r} keyword is deprecated, use {new_arg_name!r} instead.'
                warnings.warn(msg, klass, stacklevel=stacklevel)
                if kwargs.get(new_arg_name) is not None:
                    msg = f'Can only specify {old_arg_name!r} or {new_arg_name!r}, not both.'
                    raise TypeError(msg)
                kwargs[new_arg_name] = new_arg_value
            return func(*args, **kwargs)
        return wrapper
    return _deprecate_kwarg

@classmethod
def construct_from_string(cls, string: str) -> ArrowDtype:
    if not isinstance(string, str):
        raise TypeError(f"'construct_from_string' expects a string, got {type(string)}")
    if not string.endswith('[pyarrow]'):
        raise TypeError(f"'{string}' must end with '[pyarrow]'")
    if string in ('string[pyarrow]', 'str[pyarrow]'):
        raise TypeError('string[pyarrow] should be constructed by StringDtype')
    if not HAS_PYARROW:
        raise ImportError(f'pyarrow>={PYARROW_MIN_VERSION} is required for ArrowDtype')
    base_type = string[:-9]
    try:
        pa_dtype = pa.type_for_alias(base_type)
    except ValueError as err:
        has_parameters = re.search('[\\[\\(].*[\\]\\)]', base_type)
        if has_parameters:
            try:
                return cls._parse_temporal_dtype_string(base_type)
            except (NotImplementedError, ValueError):
                pass
            raise NotImplementedError(f'Passing pyarrow type specific parameters ({has_parameters.group()}) in the string is not supported. Please construct an ArrowDtype object with a pyarrow_dtype instance with specific parameters.') from err
        raise TypeError(f"'{base_type}' is not a valid pyarrow data type.") from err
    return cls(pa_dtype)

