def _stack_multi_column_index(item: MultiIndex) -> MultiIndex | Index:
    if len(item.levels) <= 2:
        return item.levels[0]._rename(name=item.names[0])
    levs = ([lev[c] if c >= 0 else None for c in codes] for lev, codes in zip(item.levels[:-1], item.codes[:-1], strict=True))
    tuples = zip(*levs, strict=True)
    unique_tuples = (key for key, _ in itertools.groupby(tuples))
    new_levs = zip(*unique_tuples, strict=True)
    return MultiIndex.from_arrays([Index(new_lev, dtype=lev.dtype) if None not in new_lev else new_lev for new_lev, lev in zip(new_levs, item.levels[:-1], strict=True)], names=item.names[:-1])

