@final
def xs(self, key: IndexLabel, axis: Axis=0, level: IndexLabel | None=None, drop_level: bool=True) -> Self:
    axis = self._get_axis_number(axis)
    labels = self._get_axis(axis)
    if isinstance(key, list):
        raise TypeError('list keys are not supported in xs, pass a tuple instead')
    if level is not None:
        if not isinstance(labels, MultiIndex):
            raise TypeError('Index must be a MultiIndex')
        loc, new_ax = labels.get_loc_level(key, level=level, drop_level=drop_level)
        _indexer = [slice(None)] * self.ndim
        _indexer[axis] = loc
        indexer = tuple(_indexer)
        result = self.iloc[indexer]
        setattr(result, result._get_axis_name(axis), new_ax)
        return result
    if axis == 1:
        if drop_level:
            return self[key]
        index = self.columns
    else:
        index = self.index
    if isinstance(index, MultiIndex):
        loc, new_index = index._get_loc_level(key, level=0)
        if not drop_level:
            if lib.is_integer(loc):
                new_index = index[loc:loc + 1]
            else:
                new_index = index[loc]
    else:
        loc = index.get_loc(key)
        if isinstance(loc, np.ndarray):
            if loc.dtype == np.bool_:
                inds, = loc.nonzero()
                return self.take(inds, axis=axis)
            else:
                return self.take(loc, axis=axis)
        if not is_scalar(loc):
            new_index = index[loc]
    if is_scalar(loc) and axis == 0:
        if self.ndim == 1:
            return self._values[loc]
        if not drop_level and isinstance(index, MultiIndex):
            result = self.iloc[loc:loc + 1]
            result.index = new_index
            return result
        result = self._ixs(loc, axis=0)
    elif is_scalar(loc):
        result = self.iloc[:, slice(loc, loc + 1)]
    elif axis == 1:
        result = self.iloc[:, loc]
    elif isinstance(loc, slice):
        result = self._slice(loc, new_index=new_index)
    else:
        result = self.iloc[loc]
        result.index = new_index
    return result

