    def callback_managed_method(estimator, *args, **kwargs):
        with callback_management_context(estimator):
            return method(estimator, *args, **kwargs)
    return callback_managed_method

@cache_readonly
def _is_memory_usage_qualified(self) -> bool:
    return is_object_dtype(self.dtype) or (is_string_dtype(self.dtype) and self.dtype.storage == 'python')

def apply(self, func, *args, include_groups: bool=False, **kwargs) -> NDFrameT:
    if include_groups:
        raise ValueError('include_groups=True is no longer allowed.')
    if isinstance(func, str):
        if hasattr(self, func):
            res = getattr(self, func)
            if callable(res):
                return res(*args, **kwargs)
            elif args or kwargs:
                raise ValueError(f'Cannot pass arguments to property {func}')
            return res
        else:
            raise TypeError(f"apply func should be callable, not '{func}'")
    elif args or kwargs:
        if callable(func):

            @wraps(func)
            def f(g):
                return func(g, *args, **kwargs)
        else:
            raise ValueError('func must be a callable if args or kwargs are supplied')
    else:
        f = func
    return self._python_apply_general(f, self._obj_with_exclusions)

def filter(self, items=None, like: str | None=None, regex: str | None=None, axis: Axis | None=None) -> Self:
    nkw = common.count_not_none(items, like, regex)
    if nkw > 1:
        raise TypeError('Keyword arguments `items`, `like`, or `regex` are mutually exclusive')
    if axis is None:
        axis = self._info_axis_name
    labels = self._get_axis(axis)
    if items is not None:
        name = self._get_axis_name(axis)
        items = Index(items).intersection(labels)
        if len(items) == 0:
            items = items.astype(labels.dtype)
        return not self.reindex(**{name: items})
    elif like:

        def f(x) -> bool:
            assert like is not None
            return like in ensure_str(x)
        values = labels.map(f)
        return self.loc(axis=axis)[values]
    elif regex:

        def f(x) -> bool:
            return matcher.search(ensure_str(x)) is not None
        matcher = re.compile(regex)
        values = labels.map(f)
        return self.loc(axis=axis)[values]
    else:
        raise TypeError('Must pass either `items`, `like`, or `regex`')

def _highlight_value(data: DataFrame | Series, op: str, props: str) -> np.ndarray:
    value = getattr(data, op)(skipna=True)
    if isinstance(data, DataFrame):
        value = getattr(value, op)(skipna=True)
    cond = data == value
    cond = cond.where(pd.notna(cond), False)
    return np.where(cond, props, '')

