def get_indexer_indexer(target: Index, level: Level | list[Level] | None, ascending: list[bool] | bool, kind: SortKind, na_position: NaPosition, session: bool, key: IndexKeyFunc) -> npt.NDArray[np.intp] | None:
    target = ensure_key_mapped(target, key, levels=level)
    target = target._sort_levels_monotonic()
    if np.all(ascending) and target.is_monotonic_increasing or (not np.any(ascending) and target.is_monotonic_decreasing):
