    return (start, end)

def __call__(self, param_4, Y=None, eval_gradient=False):
    if eval_gradient:
        K = []
        K_grad = []
        for kernel in self.kernels:
            K_single, K_grad_single = kernel(param_4, Y, eval_gradient)
            K.append(K_single)
            K_grad.append(K_grad_single[..., np.newaxis])
        return (np.dstack(K), np.concatenate(K_grad, 3))
    else:
        return np.dstack([kernel(param_4, Y, eval_gradient) for kernel in self.kernels])

def _intersection_non_unique(self, other: IntervalIndex) -> IntervalIndex:
    mask = np.zeros(len(self), dtype=bool)
    if self.hasnans and other.hasnans:
        first_nan_loc = np.arange(len(self))[self.isna()][0]
        mask[first_nan_loc] = True
    other_tups = set(zip(other.left, other.right, strict=True))
    for i, tup in enumerate(zip(self.left, self.right, strict=True)):
        if tup in other_tups:
            mask[i] = True
    return self[mask]

