def extract_patches_2d(image, patch_size, *, max_patches=None, random_state=None):
    i_h, i_w = image.shape[:2]
    p_h, p_w = patch_size
    if p_h > i_h:
        raise ValueError('Height of the patch should be less than the height of the image.')
    if p_w > i_w:
