def chebroots(cache):
    [cache] = pu.as_series([cache])
    if len(cache) < 2:
        return np.array([], dtype=cache.dtype)
    if len(cache) == 2:
        return np.array([-cache[0] / cache[1]])
    m = chebcompanion(cache)[::-1, ::-1]
    r = np.linalg.eigvals(m)
    r.sort()
    return r

