    for i, mapping in enumerate(self._default_to_infrequent_mappings):
        if mapping is None:
            continue
        if i in ignore_category_indices:
            rows_to_update = X_int[:, i] != ignore_category_indices[i]
        else:
            rows_to_update = slice(None)
        X_int[rows_to_update, i] = np.take(mapping, X_int[rows_to_update, i])

def check_symmetric(array, *, tol=1e-10, raise_warning=True, raise_exception=False):
    if array.ndim != 2 or array.shape[0] != array.shape[1]:
        raise ValueError('array must be 2-dimensional and square. shape = {0}'.format(array.shape))
    if sp.issparse(array):
        diff = array - array.T
        if diff.format not in ['csr', 'csc', 'coo']:
            diff = diff.tocsr()
        symmetric = np.all(abs(diff.data) < tol)
    else:
        symmetric = np.allclose(array, array.T, atol=tol)
    if not symmetric:
        if raise_exception:
            raise ValueError('Array must be symmetric')
        if raise_warning:
            warnings.warn('Array is not symmetric, and will be converted to symmetric by average with its transpose.', stacklevel=2)
        if sp.issparse(array):
            conversion = 'to' + array.format
            array = getattr(0.5 * (array + array.T), conversion)()
        else:
            array = 0.5 * (array + array.T)
    return array

def _fit_multiplicative_update(X, W, H, beta_loss='frobenius', max_iter=200, tol=0.0001, l1_reg_W=0, l1_reg_H=0, l2_reg_W=0, l2_reg_H=0, update_H=True, verbose=0):
    start_time = time.time()
    beta_loss = _beta_loss_to_float(beta_loss)
    if beta_loss < 1:
        gamma = 1.0 / (2.0 - beta_loss)
    elif beta_loss > 2:
        gamma = 1.0 / (beta_loss - 1.0)
    else:
        gamma = 1.0
    error_at_init = _beta_divergence(X, W, H, beta_loss, square_root=True)
    previous_error = error_at_init
    H_sum, HHt, XHt = (None, None, None)
    for n_iter in range(1, max_iter + 1):
        W, H_sum, HHt, XHt = _multiplicative_update_w(X, W, H, beta_loss=beta_loss, l1_reg_W=l1_reg_W, l2_reg_W=l2_reg_W, gamma=gamma, H_sum=H_sum, HHt=HHt, XHt=XHt, update_H=update_H)
        if beta_loss < 1:
            W[W < np.finfo(np.float64).eps] = 0.0
        if update_H:
            H = _multiplicative_update_h(X, W, H, beta_loss=beta_loss, l1_reg_H=l1_reg_H, l2_reg_H=l2_reg_H, gamma=gamma)
            H_sum, HHt, XHt = (None, None, None)
            if beta_loss <= 1:
                H[H < np.finfo(np.float64).eps] = 0.0
        if tol > 0 and n_iter % 10 == 0:
            error = _beta_divergence(X, W, H, beta_loss, square_root=True)
            if verbose:
                iter_time = time.time()
                print('Epoch %02d reached after %.3f seconds, error: %f' % (n_iter, iter_time - start_time, error))
            if (previous_error - error) / error_at_init < tol:
                break
            previous_error = error
    if verbose and (tol == 0 or n_iter % 10 != 0):
        end_time = time.time()
        print('Epoch %02d reached after %.3f seconds.' % (n_iter, end_time - start_time))
    return (W, H, n_iter)

def fill_binop(left, right, fill_value):
    if fill_value is not None:
        left_mask = isna(left)
        right_mask = isna(right)
        mask = left_mask ^ right_mask
        if left_mask.any():
            left = left.copy()
            left[left_mask & mask] = fill_value
        if right_mask.any():
            right = right.copy()
            right[right_mask & mask] = fill_value
    return (left, right)

