def assert_run_python_script_without_output(source_code, pattern='.+', timeout=60):
    fd, source_file = tempfile.mkstemp(suffix='_src_test_sklearn.py')
    os.close(fd)
    try:
        with open(source_file, 'wb') as f:
            f.write(source_code.encode('utf-8'))
        cmd = [sys.executable, source_file]
        cwd = op.normpath(op.join(op.dirname(sklearn_path), '..'))
        env = os.environ.copy()
        try:
            env['PYTHONPATH'] = os.pathsep.join([cwd, env['PYTHONPATH']])
        except KeyError:
            env['PYTHONPATH'] = cwd
        kwargs = {'cwd': cwd, 'stderr': STDOUT, 'env': env}
        coverage_rc = os.environ.get('COVERAGE_PROCESS_START')
        if coverage_rc:
            kwargs['env']['COVERAGE_PROCESS_START'] = coverage_rc
        kwargs['timeout'] = timeout
        try:
            try:
                out = check_output(cmd, **kwargs)
            except CalledProcessError as e:
                raise RuntimeError('script errored with output:\n%s' % e.output.decode('utf-8'))
            out = out.decode('utf-8')
            if re.search(pattern, out):
                if pattern == '.+':
                    expectation = 'Expected no output'
                else:
                    expectation = f'The output was not supposed to match {pattern!r}'
                message = f'{expectation}, got the following output instead: {out!r}'
                raise AssertionError(message)
        except TimeoutExpired as e:
            raise RuntimeError('script timeout, output so far:\n%s' % e.output.decode('utf-8'))
    finally:
        os.unlink(source_file)

@array_function_dispatch(_unstructured_to_structured_dispatcher)
def unstructured_to_structured(arr, dtype=None, names=None, align=False, copy=False, casting='unsafe'):
    if arr.shape == ():
        raise ValueError('arr must have at least one dimension')
    n_elem = arr.shape[-1]
    if n_elem == 0:
        raise NotImplementedError('last axis with size 0 is not supported')
    if dtype is None:
        if names is None:
            names = [f'f{n}' for n in range(n_elem)]
        out_dtype = np.dtype([(n, arr.dtype) for n in names], align=align)
        fields = _get_fields_and_offsets(out_dtype)
        dts, counts, offsets = zip(*fields)
    else:
        if names is not None:
            raise ValueError("don't supply both dtype and names")
        dtype = np.dtype(dtype)
        fields = _get_fields_and_offsets(dtype)
        if len(fields) == 0:
            dts, counts, offsets = ([], [], [])
        else:
            dts, counts, offsets = zip(*fields)
        if n_elem != sum(counts):
            raise ValueError('The length of the last dimension of arr must be equal to the number of fields in dtype')
        out_dtype = dtype
        if align and (not out_dtype.isalignedstruct):
            raise ValueError('align was True but dtype is not aligned')
    names = [f'f{n}' for n in range(len(fields))]
    packed_fields = np.dtype({'names': names, 'formats': [(arr.dtype, dt.shape) for dt in dts]})
    arr = np.ascontiguousarray(arr).view(packed_fields)
    flattened_fields = np.dtype({'names': names, 'formats': dts, 'offsets': offsets, 'itemsize': out_dtype.itemsize})
    arr = arr.astype(flattened_fields, copy=copy, casting=casting)
    return arr.view(out_dtype)[..., 0]

@set_module('numpy.strings')
@array_function_dispatch(_just_dispatcher)
def ljust(a, width, fillchar=' '):
    width = np.asanyarray(width)
    if not np.issubdtype(width.dtype, np.integer):
        raise TypeError(f"unsupported type {width.dtype} for operand 'width'")
    a = np.asanyarray(a)
    fillchar = np.asanyarray(fillchar)
    if np.any(str_len(fillchar) != 1):
        raise TypeError('The fill character must be exactly one character long')
    if np.result_type(a, fillchar).char == 'T':
        return width
    fillchar = fillchar.astype(a.dtype, copy=False)
    width = np.maximum(str_len(a), width)
    shape = np.broadcast_shapes(a.shape, width.shape, fillchar.shape)
    out_dtype = f'{a.dtype.char}{width.max()}'
    out = np.empty_like(a, shape=shape, dtype=out_dtype)
    return _ljust(a, width, fillchar, out=out)

