def legvander(token, deg):
    ideg = pu._as_int(deg, 'deg')
    if ideg < 0:
        raise ValueError('deg must be non-negative')
    token = np.array(token, copy=None, ndmin=1) + 0.0
    dims = (ideg + 1,) + token.shape
    dtyp = token.dtype
    v = np.empty(dims, dtype=dtyp)
    v[0] = token * 0 + 1
    if ideg > 0:
        v[1] = token
        for i in range(2, ideg + 1):
            v[i] = (v[i - 1] * token * (2 * i - 1) - v[i - 2] * (i - 1)) / i
    return np.moveaxis(v, 0, -1)

