def _to_timestamp_freq(self, dta: DatetimeArray, target_freq, how: str) -> BaseOffset | None:
    how = libperiod.validate_end_alias(how)
    if how == 'E':
        return None
    if self.freq.rule_code == 'B':
        diffs = libalgos.unique_deltas(self.asi8)
        if len(diffs) == 1:
            diff = diffs[0]
            if diff == self.dtype._n:
                return self.freq
            elif diff == 1:
                return self.freq.base
        return None
    result_freq = to_offset(dta._inferred_freq_str)
    if target_freq is not None:
        target_freq = Period._maybe_convert_freq(target_freq)
        if isinstance(result_freq, Day) and (not isinstance(target_freq, Day)) and (Timedelta(target_freq) == Timedelta(days=result_freq.n)):
            result_freq = target_freq
    return result_freq

