@final
def _partial_date_slice(self, reso: Resolution, item: datetime) -> slice | npt.NDArray[np.intp]:
    if not self._can_partial_date_slice(reso):
        raise ValueError
    t1, t2 = self._parsed_string_to_bounds(reso, item)
    vals = self._data._ndarray
    unbox = self._data._unbox
    if self.is_monotonic_increasing:
        if len(self) and (t1 < self[0] and t2 < self[0] or (t1 > self[-1] and t2 > self[-1])):
            raise KeyError
        left = vals.searchsorted(unbox(t1), side='left')
        right = vals.searchsorted(unbox(t2), side='right')
        return slice(left, right)
    elif self.is_monotonic_decreasing:
        if len(self) and (t1 > self[0] and t2 > self[0] or (t1 < self[-1] and t2 < self[-1])):
            raise KeyError
        reversed_vals = vals[::-1]
        nvals = len(vals)
        rev_left = reversed_vals.searchsorted(unbox(t1), side='left')
        rev_right = reversed_vals.searchsorted(unbox(t2), side='right')
        return slice(nvals - rev_right, nvals - rev_left)
    else:
        lhs_mask = vals >= unbox(t1)
        rhs_mask = vals <= unbox(t2)
        return (lhs_mask & rhs_mask).nonzero()[0]

