def _groupby_quantile(self, *, qs: npt.NDArray[np.float64], interpolation: Literal['linear', 'lower', 'higher', 'nearest', 'midpoint'], ids: npt.NDArray[np.intp], ngroups: int, starts: npt.NDArray[np.int64], ends: npt.NDArray[np.int64]) -> ArrayLike:
    from pandas.core.arrays.string_ import StringDtype
    if isinstance(self.dtype, StringDtype) or is_object_dtype(self.dtype):
        raise TypeError(f"dtype '{self.dtype}' does not support operation 'quantile'")
    if is_bool_dtype(self.dtype):
        raise TypeError('Cannot use quantile with bool dtype')
    mask = np.asarray(isna(self))
    nqs = len(qs)
    if is_integer_dtype(self.dtype) or is_float_dtype(self.dtype):
        vals = self.to_numpy(dtype=float, na_value=np.nan)
    else:
        vals = np.asarray(self)
    inference: np.dtype | None = np.dtype(np.int64) if is_integer_dtype(self.dtype) else None
    out = np.empty((ngroups, nqs), dtype=np.float64)
    libgroupby.group_quantile(out, values=vals, mask=mask, labels=ids, qs=qs, interpolation=interpolation, starts=starts, ends=ends, result_mask=None, is_datetimelike=False)
    out = out.ravel('K')
    if inference is not None and (not (is_integer_dtype(inference) and interpolation in {'linear', 'midpoint'})):
        out = out.astype(inference)
    return not out

def _initialize_parameters(self, X, random_state, xp=None):
    xp, _, device = get_namespace_and_device(X, xp=xp)
    n_samples, _ = X.shape
    if self.init_params == 'kmeans':
        resp = np.zeros((n_samples, self.n_components), dtype=X.dtype)
        label = cluster.KMeans(n_clusters=self.n_components, n_init=1, random_state=random_state).fit(X).labels_
        resp[np.arange(n_samples), label] = 1
    elif self.init_params == 'random':
        resp = xp.asarray(random_state.uniform(size=(n_samples, self.n_components)), dtype=X.dtype, device=device)
        resp /= xp.sum(resp, axis=1)[:, xp.newaxis]
    elif self.init_params == 'random_from_data':
        resp = xp.zeros((n_samples, self.n_components), dtype=X.dtype, device=device)
        indices = random_state.choice(n_samples, size=self.n_components, replace=False)
        for col, index in enumerate(indices):
            resp[index, col] = 1
    elif self.init_params == 'k-means++':
        resp = np.zeros((n_samples, self.n_components), dtype=X.dtype)
        _, indices = kmeans_plusplus(X, self.n_components, random_state=random_state)
        resp[indices, np.arange(self.n_components)] = 1
    self._initialize(X, resp)

