    import matplotlib.pyplot as plt
    if index not in ('contourf', 'contour', 'pcolormesh'):
        raise ValueError(f"plot_method must be 'contourf', 'contour', or 'pcolormesh'. Got {index} instead.")
    if ax is None:
        _, ax = plt.subplots()
    plot_func = getattr(ax, index)
    if self.n_classes == 2:
        self.surface_ = plot_func(self.xx0, self.xx1, self.response, **kwargs)
    else:
        for kwarg in ('cmap', 'colors'):
            if kwarg in kwargs:
