@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None, sample_weight=None):
    X = validate_data(self, X, accept_sparse=['csc'], dtype=np.float32, ensure_all_finite=False)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=None)
    if issparse(X):
        X.sort_indices()
    rnd = check_random_state(self.random_state)
    y = rnd.uniform(size=X.shape[0])
    n_samples = X.shape[0]
    if isinstance(self.max_samples, str) and self.max_samples == 'auto':
        max_samples = min(256, n_samples)
    elif isinstance(self.max_samples, numbers.Integral):
        if self.max_samples > n_samples:
            warn('max_samples (%s) is greater than the total number of samples (%s). max_samples will be set to n_samples for estimation.' % (self.max_samples, n_samples))
            max_samples = n_samples
        else:
            max_samples = self.max_samples
    else:
        max_samples = int(self.max_samples * X.shape[0])
    self.max_samples_ = max_samples
    max_depth = int(np.ceil(np.log2(max(max_samples, 2))))
    super()._fit(X, y, max_samples=max_samples, max_depth=max_depth, sample_weight=sample_weight, check_input=False)
    self._average_path_length_per_tree, self._decision_path_lengths = zip(*[(_average_path_length(tree.tree_.n_node_samples), tree.tree_.compute_node_depths()) for tree in self.estimators_])
    if self.contamination == 'auto':
        self.offset_ = -0.5
        return self
    if issparse(X):
        X = X.tocsr()
    self.offset_ = np.percentile(self._score_samples(X), 100.0 * self.contamination)
    return self

def update(self, record, join: UpdateJoin='left', overwrite: bool=True, filter_func=None, errors: IgnoreRaise='ignore') -> None:
    if not CHAINED_WARNING_DISABLED:
        if sys.getrefcount(self) <= REF_COUNT_METHOD and (not com.is_local_in_caller_frame(self)):
            warnings.warn(_chained_assignment_method_update_msg, ChainedAssignmentError, stacklevel=2)
    if join != 'left':
        raise NotImplementedError('Only left join is supported')
    if errors not in ['ignore', 'raise']:
        raise ValueError("The parameter errors must be either 'ignore' or 'raise'")
    if not isinstance(record, DataFrame):
        record = DataFrame(record)
    if record.index.has_duplicates:
        raise ValueError('Update not allowed with duplicate indexes on other.')
    index_intersection = record.index.intersection(self.index)
    if index_intersection.empty:
        return
    record = record.reindex(index_intersection)
    this_data = self.loc[index_intersection]
    for col in self.columns.intersection(record.columns):
        this = this_data[col]
        that = record[col]
        if filter_func is not None:
            mask = ~filter_func(this) | isna(that)
        else:
            if errors == 'raise':
                mask_this = notna(that)
                mask_that = notna(this)
                if any(mask_this & mask_that):
                    raise ValueError('Data overlaps.')
            if overwrite:
                mask = isna(that)
            else:
                mask = notna(this)
        if mask.all():
            continue
        self.loc[index_intersection, col] = this.where(mask, that)

