def parse_structure(session):
    spanlist = []
    ind = 0
    while True:
        m = routine_start_re.search(session, ind)
        if m is None:
            break
        start = m.start()
        if function_start_re.match(session, start, m.end()):
            while True:
                i = session.rfind('\n', ind, start)
                if i == -1:
                    break
                start = i
                if session[i:i + 7] != '\n     $':
                    break
        start += 1
        m = routine_end_re.search(session, m.end())
        ind = end = m and m.end() - 1 or len(session)
        spanlist.append((start, end))
    return spanlist

