def maybe_rechunk(series: pd.Series, *, allow_copy: bool) -> pd.Series | None:
    if not isinstance(series.dtype, pd.ArrowDtype):
        return None
    chunked_array = series.array._pa_array
    if len(chunked_array.chunks) == 1:
        return None
    if not allow_copy:
        raise RuntimeError('Found multi-chunk pyarrow array, but `allow_copy` is False. Please rechunk the array before calling this function, or set `allow_copy=True`.')
    arr = chunked_array.combine_chunks()
    return pd.Series(arr, dtype=series.dtype, name=series.name, index=series.index)

def graphical_lasso_path(X, alphas, cov_init=None, X_test=None, mode='cd', tol=0.0001, enet_tol=0.0001, max_iter=100, verbose=False, eps=np.finfo(np.float64).eps):
    inner_verbose = max(0, verbose - 1)
    emp_cov = empirical_covariance(X)
    if cov_init is None:
        covariance_ = emp_cov.copy()
    else:
        covariance_ = cov_init
    covariances_ = list()
    precisions_ = list()
    scores_ = list()
    if X_test is not None:
        test_emp_cov = empirical_covariance(X_test)
    for alpha in alphas:
        try:
            covariance_, precision_, _, _ = _graphical_lasso(emp_cov, alpha=alpha, cov_init=covariance_, mode=mode, tol=tol, enet_tol=enet_tol, max_iter=max_iter, verbose=inner_verbose, eps=eps)
            covariances_.append(covariance_)
            precisions_.append(precision_)
            if X_test is not None:
                this_score = log_likelihood(test_emp_cov, precision_)
        except FloatingPointError:
            this_score = -np.inf
            covariances_.append(np.nan)
            precisions_.append(np.nan)
        if X_test is not None:
            if not np.isfinite(this_score):
                this_score = -np.inf
            scores_.append(this_score)
        if verbose == 1:
            sys.stderr.write('.')
        elif verbose > 1:
            if X_test is not None:
                print('[graphical_lasso_path] alpha: %.2e, score: %.2e' % (alpha, this_score))
            else:
                print('[graphical_lasso_path] alpha: %.2e' % alpha)
    if X_test is not None:
        return (covariances_, precisions_, scores_)
    return (covariances_, precisions_)

def _check_multimetric_scoring(estimator, param_2):
    err_msg_generic = f'scoring is invalid (got {param_2!r}). Refer to the scoring glossary for details: https://scikit-learn.org/stable/glossary.html#term-scoring'
    if isinstance(param_2, (list, tuple, set)):
        err_msg = 'The list/tuple elements must be unique strings of predefined scorers. '
        try:
            keys = set(param_2)
        except TypeError as e:
            raise ValueError(err_msg) from e
        if len(keys) != len(param_2):
            raise ValueError(f'{err_msg} Duplicate elements were found in the given list. {param_2!r}')
        elif len(keys) > 0:
            if not all((isinstance(k, str) for k in keys)):
                if any((callable(k) for k in keys)):
                    raise ValueError(f'{err_msg} One or more of the elements were callables. Use a dict of score name mapped to the scorer callable. Got {param_2!r}')
                else:
                    raise ValueError(f'{err_msg} Non-string types were found in the given list. Got {param_2!r}')
            scorers = {scorer: check_scoring(estimator, scoring=scorer) for scorer in param_2}
        else:
            raise ValueError(f'{err_msg} Empty list was given. {param_2!r}')
    elif isinstance(param_2, dict):
        keys = set(param_2)
        if not all((isinstance(k, str) for k in keys)):
            raise ValueError(f'Non-string types were found in the keys of the given dict. scoring={param_2!r}')
        if len(keys) == 0:
            raise ValueError(f'An empty dict was passed. {param_2!r}')
        scorers = {key: check_scoring(estimator, scoring=scorer) for key, scorer in param_2.items()}
    else:
        raise ValueError(err_msg_generic)
    return scorers

