@set_module('pandas.api.types')
def union_categoricals(to_union: Sequence[CategoricalIndex | Series | Categorical], sort_categories: bool=False, ignore_order: bool=False) -> Categorical:
    from pandas import Categorical
    from pandas.core.arrays.categorical import recode_for_categories
    if len(to_union) == 0:
        raise ValueError('No Categoricals to union')

    def _maybe_unwrap(x: CategoricalIndex | Series | Categorical) -> Categorical:
        if isinstance(x, (ABCCategoricalIndex, ABCSeries)):
            return x._values
        elif isinstance(x, Categorical):
            return x
        else:
            raise TypeError('all components to combine must be Categorical')
    to_union = cast('list[Categorical]', [_maybe_unwrap(x) for x in to_union])
    first = to_union[0]
    if not lib.dtypes_all_equal([obj.categories.dtype for obj in to_union]):
        raise TypeError('dtype of categories must be the same')
    ordered: bool | None = False
    if all((first._categories_match_up_to_permutation(other) for other in to_union[1:])):
        categories = first.categories
        ordered = first.ordered
        all_codes = [first._encode_with_my_categories(x)._codes for x in to_union]
        new_codes = np.concatenate(all_codes)
        if sort_categories and (not ignore_order) and ordered:
            raise TypeError('Cannot use sort_categories=True with ordered Categoricals')
        if sort_categories and (not categories.is_monotonic_increasing):
            categories = categories.sort_values()
            indexer = categories.get_indexer(first.categories)
            from pandas.core.algorithms import take_nd
            new_codes = take_nd(indexer, new_codes, fill_value=-1)
    elif ignore_order or all((not c.ordered for c in to_union)):
        cats = first.categories.append([c.categories for c in to_union[1:]])
        categories = cats.unique()
        if sort_categories:
            categories = categories.sort_values()
        all_codes = [recode_for_categories(c.codes, c.categories, categories, copy=False) for c in to_union]
        new_codes = np.concatenate(all_codes)
    else:
        if all((c.ordered for c in to_union)):
            msg = 'to union ordered Categoricals, all categories must be the same'
            raise TypeError(msg)
        raise TypeError('Categorical.ordered must be the same')
    if ignore_order:
        ordered = False
    dtype = CategoricalDtype(categories=categories, ordered=ordered)
    return Categorical._simple_new(new_codes, dtype=dtype)

