@_fit_context(prefer_skip_nested_validation=False)
def fit_transform(self, X, y=None, **params):
    _raise_for_params(params, self, 'fit')
    routed_params = process_routing(self, 'fit', **params)
    self.random_state_ = getattr(self, 'random_state_', check_random_state(self.random_state))
    if self.estimator is None:
        from sklearn.linear_model import BayesianRidge
        self._estimator = BayesianRidge()
    else:
        self._estimator = clone(self.estimator)
    self.imputation_sequence_ = []
    self.initial_imputer_ = None
    X, Xt, mask_missing_values, complete_mask = self._initial_imputation(X, in_fit=True)
    super()._fit_indicator(complete_mask)
    X_indicator = super()._transform_indicator(complete_mask)
    if self.max_iter == 0 or np.all(mask_missing_values):
        self.n_iter_ = 0
        return super()._concatenate_indicator(Xt, X_indicator)
    if Xt.shape[1] == 1:
        self.n_iter_ = 0
        return super()._concatenate_indicator(Xt, X_indicator)
    self._min_value = self._validate_limit(self.min_value, 'min', X.shape[1], self._is_empty_feature, self.keep_empty_features)
    self._max_value = self._validate_limit(self.max_value, 'max', X.shape[1], self._is_empty_feature, self.keep_empty_features)
    if not np.all(np.greater(self._max_value, self._min_value)):
        raise ValueError('One (or more) features have min_value >= max_value.')
    ordered_idx = self._get_ordered_idx(mask_missing_values)
    self.n_features_with_missing_ = len(ordered_idx)
    abs_corr_mat = self._get_abs_corr_mat(Xt)
    n_samples, n_features = Xt.shape
    if self.verbose > 0:
        print('[IterativeImputer] Completing matrix with shape %s' % (X.shape,))
    start_t = time()
    if not self.sample_posterior:
        Xt_previous = Xt.copy()
        normalized_tol = self.tol * np.max(np.abs(X[~mask_missing_values]))
    for self.n_iter_ in range(1, self.max_iter + 1):
        if self.imputation_order == 'random':
            ordered_idx = self._get_ordered_idx(mask_missing_values)
        for feat_idx in ordered_idx:
            neighbor_feat_idx = self._get_neighbor_feat_idx(n_features, feat_idx, abs_corr_mat)
            Xt, estimator = self._impute_one_feature(Xt, mask_missing_values, feat_idx, neighbor_feat_idx, estimator=None, fit_mode=True, params=routed_params.estimator.fit)
            estimator_triplet = _ImputerTriplet(feat_idx, neighbor_feat_idx, estimator)
            self.imputation_sequence_.append(estimator_triplet)
        if self.verbose > 1:
            print('[IterativeImputer] Ending imputation round %d/%d, elapsed time %0.2f' % (self.n_iter_, self.max_iter, time() - start_t))
        if not self.sample_posterior:
            inf_norm = np.linalg.norm(Xt - Xt_previous, ord=np.inf, axis=None)
            if self.verbose > 0:
                print('[IterativeImputer] Change: {}, scaled tolerance: {} '.format(inf_norm, normalized_tol))
            if inf_norm < normalized_tol:
                if self.verbose > 0:
                    print('[IterativeImputer] Early stopping criterion reached.')
                break
            Xt_previous = Xt.copy()
    _assign_where(Xt, X, cond=~mask_missing_values)
    return super()._concatenate_indicator(Xt, X_indicator)

