def _minibatch_step(self, X, W, H, record):
    batch_size = X.shape[0]
    l1_reg_W, l1_reg_H, l2_reg_W, l2_reg_H = self._compute_regularization(X)
    if self.fresh_restarts or W is None:
        W = self._solve_W(X, H, self.fresh_restarts_max_iter)
    else:
        W, *_ = _multiplicative_update_w(X, W, H, self._beta_loss, l1_reg_W, l2_reg_W, self._gamma)
    if self._beta_loss < 1:
        W[W < np.finfo(np.float64).eps] = 0.0
    batch_cost = (_beta_divergence(X, W, H, self._beta_loss) + l1_reg_W * W.sum() + l1_reg_H * H.sum() + l2_reg_W * (W ** 2).sum() + l2_reg_H * (H ** 2).sum()) / batch_size
    if record:
        H[:] = _multiplicative_update_h(X, W, H, beta_loss=self._beta_loss, l1_reg_H=l1_reg_H, l2_reg_H=l2_reg_H, gamma=self._gamma, A=self._components_numerator, B=self._components_denominator, rho=self._rho)
        if self._beta_loss <= 1:
            H[H < np.finfo(np.float64).eps] = 0.0
    return batch_cost

def as_series(alist, trim=True):
    arrays = [np.array(a, ndmin=1, copy=None) for a in alist]
    for a in arrays:
        if a.size == 0:
            raise ValueError('Coefficient array is empty')
        if a.ndim != 1:
            raise ValueError('Coefficient array is not 1-d')
    if trim:
        arrays = [trimseq(a) for a in arrays]
    try:
        dtype = np.common_type(*arrays)
    except Exception as e:
        object_dtype = np.dtypes.ObjectDType()
        has_one_object_type = False
        ret = []
        for a in arrays:
            if a.dtype != object_dtype:
                tmp = np.empty(len(a), dtype=object_dtype)
                tmp[:] = a[:]
                ret.append(tmp)
            else:
                has_one_object_type = True
                ret.append(a.copy())
        if not has_one_object_type:
            raise ValueError('Coefficient arrays have no common type') from e
    else:
        ret = [np.array(a, copy=True, dtype=dtype) for a in arrays]
    return ret

@final
def _replace_regex(self, to_replace, value, inplace: bool=False, mask=None) -> list[Block]:
    if not is_re(to_replace) and (not self._can_hold_element(to_replace)):
        return [self.copy(deep=False)]
    if is_re(to_replace) and self.dtype not in [object, 'string']:
        return [self.copy(deep=False)]
    if not (self._can_hold_element(value) or (self.dtype == 'string' and is_re(value))):
        block = self.astype(np.dtype(object))
        if astype_is_view(self.dtype, np.dtype(object)):
            block = block._maybe_copy(inplace=True)
    else:
        block = self._maybe_copy(inplace)
    rx = re.compile(to_replace)
    replace_regex(block.values, rx, value, mask)
    return [block]

