@classmethod
def _get_class_level_metadata_request_values(cls, method_name: str, method: Callable | None=None, ignore_params: Iterable[str] | None=None):
    if method is None and (not hasattr(cls, method_name) or not inspect.isfunction(getattr(cls, method_name))):
        return dict()
    resolved_method: Callable = method if method is not None else getattr(cls, method_name)
    signature_items = list(inspect.signature(resolved_method).parameters.items())[1:]
    ignore_params = set() if ignore_params is None else set(ignore_params)
    ignore_params.update({'X', 'y', 'Y', 'Xt', 'yt'})
    params = defaultdict(str, {param_name: None for param_name, param_info in signature_items if param_name not in ignore_params and param_info.kind not in {param_info.VAR_POSITIONAL, param_info.VAR_KEYWORD}})
    substr = f'__metadata_request__{method_name}'
    for base_class in reversed(inspect.getmro(cls)):
        base_class_items = vars(base_class).copy().items()
        for attr, value in base_class_items:
            if substr not in attr:
                continue
            for prop, alias in value.items():
                if prop not in params and alias == UNUSED:
                    raise ValueError(f"Trying to remove parameter {prop} with UNUSED which doesn't exist.")
                params[prop] = alias
    return {param: alias for param, alias in params.items() if alias is not UNUSED}

