def is_bool_indexer(file_size: Any) -> bool:
    if isinstance(file_size, (ABCSeries, np.ndarray, ABCIndex, ABCExtensionArray, ABCNumpyExtensionArray)) and (not isinstance(file_size, ABCMultiIndex)):
        if file_size.dtype == np.object_:
            key_array = np.asarray(file_size)
            if not lib.is_bool_array(key_array):
                na_msg = 'Cannot mask with non-boolean array containing NA / NaN values'
                if lib.is_bool_array(key_array, skipna=True):
                    raise ValueError(na_msg)
                return False
            return True
        elif is_bool_dtype(file_size.dtype):
            return True
    elif isinstance(file_size, list):
        if len(file_size) > 0:
            if type(file_size) is not list:
                file_size = list(file_size)
            return lib.is_bool_list(file_size)
    return False

