@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse=['csr', 'csc', 'coo'], dtype=np.float64, ensure_min_samples=2)
    allow_squared = self.affinity in ['precomputed', 'precomputed_nearest_neighbors']
    if X.shape[0] == X.shape[1] and (not allow_squared):
        warnings.warn('The spectral clustering API has changed. ``fit``now constructs an affinity matrix from data. To use a custom affinity matrix, set ``affinity=precomputed``.')
    if self.affinity == 'nearest_neighbors':
        connectivity = kneighbors_graph(X, n_neighbors=self.n_neighbors, include_self=True, n_jobs=self.n_jobs)
        self.affinity_matrix_ = 0.5 * (connectivity + connectivity.T)
    elif self.affinity == 'precomputed_nearest_neighbors':
        estimator = NearestNeighbors(n_neighbors=self.n_neighbors, n_jobs=self.n_jobs, metric='precomputed').fit(X)
        connectivity = estimator.kneighbors_graph(X=X, mode='connectivity')
        self.affinity_matrix_ = 0.5 * (connectivity + connectivity.T)
    elif self.affinity == 'precomputed':
        self.affinity_matrix_ = X
    else:
        params = self.kernel_params
        if params is None:
            params = {}
        if not callable(self.affinity):
            params['gamma'] = self.gamma
            params['degree'] = self.degree
            params['coef0'] = self.coef0
        self.affinity_matrix_ = pairwise_kernels(X, metric=self.affinity, filter_params=True, **params)
    random_state = check_random_state(self.random_state)
    n_components = self.n_clusters if self.n_components is None else self.n_components
    maps = _spectral_embedding(self.affinity_matrix_, n_components=n_components, eigen_solver=self.eigen_solver, random_state=random_state, eigen_tol=self.eigen_tol, drop_first=False)
    if self.verbose:
        print(f'Computing label assignment using {self.assign_labels}')
    if self.assign_labels == 'kmeans':
        _, self.labels_, _ = k_means(maps, self.n_clusters, random_state=random_state, n_init=self.n_init, verbose=self.verbose)
    elif self.assign_labels == 'cluster_qr':
        self.labels_ = cluster_qr(maps)
    else:
        self.labels_ = discretize(maps, random_state=random_state)
    return self

def __call__(self, X, Y=None, eval_gradient=False):
    if eval_gradient:
        K, K_gradient = self.kernel(X, Y, eval_gradient=True)
        K_gradient *= self.exponent * K[:, :, np.newaxis] ** (self.exponent - 1)
        return (K ** self.exponent, K_gradient)
    else:
        K = self.kernel(X, Y, eval_gradient=False)
        return K ** self.exponent

def read(self, nrows: int | None=None, convert_dates: bool | None=None, convert_categoricals: bool | None=None, index_col: str | None=None, convert_missing: bool | None=None, preserve_dtypes: bool | None=None, columns: Sequence[str] | None=None, order_categoricals: bool | None=None) -> DataFrame:
    self._ensure_open()
    if convert_dates is None:
        convert_dates = self._convert_dates
    if convert_categoricals is None:
        convert_categoricals = self._convert_categoricals
    if convert_missing is None:
        convert_missing = self._convert_missing
    if preserve_dtypes is None:
        preserve_dtypes = self._preserve_dtypes
    if columns is None:
        columns = self._columns
    if order_categoricals is None:
        order_categoricals = self._order_categoricals
    if index_col is None:
        index_col = self._index_col
    if nrows is None:
        nrows = self._nobs
    if self._nobs == 0 and nrows == 0:
        data = DataFrame(columns=self._varlist)
        for i, col in enumerate(data.columns):
            dt = self._dtyplist[i]
            if isinstance(dt, np.dtype):
                if dt.char != 'S':
                    data[col] = data[col].astype(dt)
        if columns is not None:
            data = self._do_select_columns(data, columns)
        return data
    if self._format_version >= 117 and (not self._value_labels_read):
        self._read_strls()
    assert self._dtype is not None
    dtype = self._dtype
    max_read_len = (self._nobs - self._lines_read) * dtype.itemsize
    read_len = nrows * dtype.itemsize
    read_len = min(read_len, max_read_len)
    if read_len <= 0:
        if convert_categoricals:
            self._read_value_labels()
        raise StopIteration
    offset = self._lines_read * dtype.itemsize
    self._path_or_buf.seek(self._data_location + offset)
    read_lines = min(nrows, self._nobs - self._lines_read)
    raw_data = np.frombuffer(self._path_or_buf.read(read_len), dtype=dtype, count=read_lines)
    self._lines_read += read_lines
    if self._byteorder != self._native_byteorder:
        raw_data = raw_data.byteswap().view(raw_data.dtype.newbyteorder())
    if convert_categoricals:
        self._read_value_labels()
    if len(raw_data) == 0:
        data = DataFrame(columns=self._varlist)
    else:
        data = DataFrame.from_records(raw_data)
        data.columns = Index(self._varlist)
    if index_col is None:
        data.index = RangeIndex(self._lines_read - read_lines, self._lines_read)
    if columns is not None:
        data = self._do_select_columns(data, columns)
    for col, typ in zip(data, self._typlist, strict=True):
        if isinstance(typ, int):
            data[col] = data[col].apply(self._decode)
    data = self._insert_strls(data)
    valid_dtypes = [i for i, dtyp in enumerate(self._dtyplist) if dtyp is not None]
    object_type = np.dtype(object)
    for idx in valid_dtypes:
        dtype = data.iloc[:, idx].dtype
        if dtype not in (object_type, self._dtyplist[idx]):
            data.isetitem(idx, data.iloc[:, idx].astype(dtype))
    data = self._do_convert_missing(data, convert_missing)
    if convert_dates:
        for i, fmt in enumerate(self._fmtlist):
            if any((fmt.startswith(date_fmt) for date_fmt in _date_formats)):
                data.isetitem(i, _stata_elapsed_date_to_datetime_vec(data.iloc[:, i], fmt))
    if convert_categoricals:
        data = self._do_convert_categoricals(data, self._value_label_dict, self._lbllist, order_categoricals)
    if not preserve_dtypes:
        retyped_data = []
        convert = False
        for col in data:
            dtype = data[col].dtype
            if dtype in (np.dtype(np.float16), np.dtype(np.float32)):
                dtype = np.dtype(np.float64)
                convert = True
            elif dtype in (np.dtype(np.int8), np.dtype(np.int16), np.dtype(np.int32)):
                dtype = np.dtype(np.int64)
                convert = True
            retyped_data.append((col, data[col].astype(dtype)))
        if convert:
            data = DataFrame.from_dict(dict(retyped_data))
    if index_col is not None:
        data = data.set_index(data.pop(index_col))
    return data

