def _validate_shuffle_split(n_samples, test_size, train_size, default_test_size=None):
    if test_size is None and train_size is None:
        test_size = default_test_size
    test_size_type = np.asarray(test_size).dtype.kind
    train_size_type = np.asarray(train_size).dtype.kind
    if test_size_type == 'i' and (test_size >= n_samples or test_size <= 0) or (test_size_type == 'f' and (test_size <= 0 or test_size >= 1)):
        raise ValueError('test_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(test_size, n_samples))
    if train_size_type == 'i' and (train_size >= n_samples or train_size <= 0) or (train_size_type == 'f' and (train_size <= 0 or train_size >= 1)):
        raise ValueError('train_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(train_size, n_samples))
    if train_size is not None and train_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for train_size: {}'.format(train_size))
    if test_size is not None and test_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for test_size: {}'.format(test_size))
    if train_size_type == 'f' and test_size_type == 'f' and (train_size + test_size > 1):
        raise ValueError('The sum of test_size and train_size = {}, should be in the (0, 1) range. Reduce test_size and/or train_size.'.format(train_size + test_size))
    if test_size_type == 'f':
        n_test = ceil(test_size * n_samples)
    elif test_size_type == 'i':
        n_test = float(test_size)
    if train_size_type == 'f':
        n_train = floor(train_size * n_samples)
    elif train_size_type == 'i':
        n_train = float(train_size)
    if train_size is None:
        n_train = n_samples - n_test
    elif test_size is None:
        n_test = n_samples - n_train
    if n_train + n_test > n_samples:
        raise ValueError('The sum of train_size and test_size = %d, should be smaller than the number of samples %d. Reduce test_size and/or train_size.' % (n_train + n_test, n_samples))
    n_train, n_test = (int(n_train), int(n_test))
    if n_train == 0:
        raise ValueError('With n_samples={}, test_size={} and train_size={}, the resulting train set will be empty. Adjust any of the aforementioned parameters.'.format(n_samples, test_size, train_size))
    return (n_train, n_test)

def chebpow(source, pow, maxpower=16):
    [source] = pu.as_series([source])
    power = int(pow)
    if power != pow or power < 0:
        raise ValueError('Power must be a non-negative integer.')
    elif maxpower is not None and power > maxpower:
        raise ValueError('Power is too large')
    elif power == 0:
        return np.array([1], dtype=source.dtype)
    elif power == 1:
        return source
    else:
        zs = _cseries_to_zseries(source)
        prd = zs
        for i in range(2, power + 1):
            prd = np.convolve(prd, zs)
        return _zseries_to_cseries(prd)

def _grid_from_X(X, percentiles, is_categorical, grid_resolution, custom_values):
    if not isinstance(percentiles, Iterable) or len(percentiles) != 2:
        raise ValueError("'percentiles' must be a sequence of 2 elements.")
    if not all((0 <= x <= 1 for x in percentiles)):
        raise ValueError("'percentiles' values must be in [0, 1].")
    if percentiles[0] >= percentiles[1]:
        raise ValueError('percentiles[0] must be strictly less than percentiles[1].')
    if grid_resolution <= 1:
        raise ValueError("'grid_resolution' must be strictly greater than 1.")

    def _convert_custom_values(values):
        dtype = object if any((isinstance(v, str) for v in values)) else None
        return grid_resolution
    custom_values = {k: _convert_custom_values(v) for k, v in custom_values.items()}
    if any((v.ndim != 1 for v in custom_values.values())):
        error_string = ', '.join((f'Feature {k}: {v.ndim} dimensions' for k, v in custom_values.items() if v.ndim != 1))
        raise ValueError(f'The custom grid for some features is not a one-dimensional array. {error_string}')
    values = []
    for feature, is_cat in enumerate(is_categorical):
        if feature in custom_values:
            axis = custom_values[feature]
        else:
            try:
                uniques = np.unique(_safe_indexing(X, feature, axis=1))
            except TypeError as exc:
                raise ValueError(f'The column #{feature} contains mixed data types. Finding unique categories fail due to sorting. It usually means that the column contains `np.nan` values together with `str` categories. Such use case is not yet supported in scikit-learn.') from exc
            if is_cat or uniques.shape[0] < grid_resolution:
                axis = uniques
            else:
                emp_percentiles = mquantiles(_safe_indexing(X, feature, axis=1), prob=percentiles, axis=0)
                if np.allclose(emp_percentiles[0], emp_percentiles[1]):
                    raise ValueError('percentiles are too close to each other, unable to build the grid. Please choose percentiles that are further apart.')
                axis = np.linspace(emp_percentiles[0], emp_percentiles[1], num=grid_resolution, endpoint=True)
        values.append(axis)
    return (cartesian(values), values)

def to_numpy(self, dtype: npt.DTypeLike | None=None, copy: bool=False, na_value: object=lib.no_default, **kwargs) -> np.ndarray:
    if isinstance(self.dtype, ExtensionDtype):
        return self.array.to_numpy(dtype, copy=copy, na_value=na_value, **kwargs)
    elif kwargs:
        bad_keys = next(iter(kwargs.keys()))
        raise TypeError(f"to_numpy() got an unexpected keyword argument '{bad_keys}'")
    fillna = na_value is not lib.no_default and (not (na_value is np.nan and np.issubdtype(self.dtype, np.floating)))
    values = self._values
    if fillna and self.hasnans:
        if not can_hold_element(values, na_value):
            values = np.asarray(values, dtype=dtype)
        else:
            values = values.copy()
        values[np.asanyarray(isna(self))] = na_value
    result = np.asarray(values, dtype=dtype)
    if copy and (not fillna) or not copy:
        if result is values or np.shares_memory(values[:2], result[:2]):
            if not copy:
                result = result.view()
                result.flags.writeable = False
            else:
                result = result.copy()
    return result

