def union_indexes(indexes, sort: bool | lib.NoDefault=True) -> Index:
    if len(indexes) == 0:
        raise AssertionError('Must have at least 1 Index to union')
    if len(indexes) == 1:
        result = indexes[0]
        if isinstance(result, list):
            if not sort or sort is lib.no_default:
                result = Index(result)
            else:
                result = Index(sorted(result))
        return result
    indexes, kind = _sanitize_and_check(indexes)
    if kind == 'special':
        result = indexes[0]
        num_dtis = 0
        num_dti_tzs = 0
        for idx in indexes:
            if isinstance(idx, DatetimeIndex):
                num_dtis += 1
                if idx.tz is not None:
                    num_dti_tzs += 1
        if num_dti_tzs not in [0, num_dtis]:
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
        if num_dtis == len(indexes):
            if sort is lib.no_default:
                sort = True
            result = indexes[0]
        elif num_dtis > 1:
            sort = False
            indexes = [x.astype(object, copy=False) for x in indexes]
            result = indexes[0]
        for other in indexes[1:]:
            result = result.union(other, sort=None if sort else False)
        return result
    elif kind == 'array':
        if not all_indexes_same(indexes):
            dtype = find_common_type([idx.dtype for idx in indexes])
            inds = [ind.astype(dtype, copy=False) for ind in indexes]
            index = inds[0].unique()
            other = inds[1].append(inds[2:])
            diff = other[index.get_indexer_for(other) == -1]
            if len(diff):
                index = index.append(diff.unique())
            if sort:
                index = index.sort_values()
        else:
            index = indexes[0]
        name = get_unanimous_names(*indexes)[0]
        if name != index.name:
            index = index.rename(name)
        return index
    elif kind == 'list':
        dtypes = [idx.dtype for idx in indexes if isinstance(idx, Index)]
        if dtypes:
            dtype = find_common_type(dtypes)
        else:
            dtype = None
        all_lists = (idx.tolist() if isinstance(idx, Index) else idx for idx in indexes)
        return Index(lib.fast_unique_multiple_list_gen(all_lists, sort=bool(sort)), dtype=dtype)
    else:
        raise ValueError(f"kind={kind!r} must be 'special', 'array' or 'list'.")

def inverse_transform(self, X):
    check_is_fitted(self)
    if 'onehot' in self.encode:
        X = self._encoder.inverse_transform(X)
    Xinv = check_array(X, copy=True, dtype=(np.float64, np.float32))
    n_features = self.n_bins_.shape[0]
    if Xinv.shape[1] != n_features:
        raise ValueError('Incorrect number of features. Expecting {}, received {}.'.format(n_features, Xinv.shape[1]))
    for jj in range(n_features):
        bin_edges = self.bin_edges_[jj]
        bin_centers = (bin_edges[1:] + bin_edges[:-1]) * 0.5
        Xinv[:, jj] = bin_centers[Xinv[:, jj].astype(np.int64)]
    return Xinv

@set_module('pandas')
def timedelta_range(start=None, end=None, periods: int | None=None, item=None, name=None, closed=None, *, unit: TimeUnit | None=None) -> TimedeltaIndex:
    if item is None and com.any_none(periods, start, end):
        item = 'D'
    item = to_offset(item)
    if com.count_not_none(start, end, periods, item) != 3:
        raise ValueError('Of the four parameters: start, end, periods, and freq, exactly three must be specified')
    if unit is None:
        if start is not None and end is not None:
            start = Timedelta(start)
            end = Timedelta(end)
            start = cast('Timedelta', start)
            end = cast('Timedelta', end)
            if abbrev_to_npy_unit(start.unit) > abbrev_to_npy_unit(end.unit):
                unit = cast('TimeUnit', start.unit)
            else:
                unit = cast('TimeUnit', end.unit)
        elif start is not None:
            start = Timedelta(start)
            start = cast('Timedelta', start)
            unit = cast('TimeUnit', start.unit)
        else:
            end = Timedelta(end)
            end = cast('Timedelta', end)
            unit = cast('TimeUnit', end.unit)
        if item is not None:
            item = cast('Tick | Day', item)
            creso = abbrev_to_npy_unit(unit)
            if item._creso > creso:
                unit = cast('TimeUnit', item.base.freqstr)
    tdarr = TimedeltaArray._generate_range(start, end, periods, item, closed=closed, unit=unit)
    result = TimedeltaIndex._simple_new(tdarr, name=name)
    result._freq = item
    return result

