def iset(self, loc: int | slice | np.ndarray, value: ArrayLike, inplace: bool=False, field: BlockValuesRefs | None=None) -> None:
    if self._blklocs is None and self.ndim > 1:
        self._rebuild_blknos_and_blklocs()
    value_is_extension_type = is_1d_only_ea_dtype(value.dtype)
    if not value_is_extension_type:
        if value.ndim == 2:
            value = value.T
        else:
            value = ensure_block_shape(value, ndim=2)
        if value.shape[1:] != self.shape[1:]:
            raise AssertionError('Shape of new values must be compatible with manager shape')
    if lib.is_integer(loc):
        loc = cast('int', loc)
        if not value_is_extension_type and len(value) > 1:
            raise ValueError(f'Expected a 1D array, got an array with shape {value.T.shape}')
        blkno = self.blknos[loc]
        blk = self.blocks[blkno]
        if len(blk._mgr_locs) == 1:
            return self._iset_single(loc, value, inplace=inplace, blkno=blkno, blk=blk, refs=field)
        loc = [loc]
    if value_is_extension_type:

        def value_getitem(placement):
            return value
    else:

        def value_getitem(placement):
            return value[placement.indexer]
    blknos = self.blknos[loc]
    blklocs = self.blklocs[loc].copy()
    unfit_mgr_locs = []
    unfit_val_locs = []
    removed_blknos = []
    for blkno_l, val_locs in libinternals.get_blkno_placements(blknos, group=True):
        blk = self.blocks[blkno_l]
        blk_locs = blklocs[val_locs.indexer]
        if inplace and blk.should_store(value):
            if not self._has_no_reference_block(blkno_l):
                self._iset_split_block(blkno_l, blk_locs, value_getitem(val_locs), refs=field)
            else:
                blk.set_inplace(blk_locs, value_getitem(val_locs))
                continue
        else:
            unfit_mgr_locs.append(blk.mgr_locs.as_array[blk_locs])
            unfit_val_locs.append(val_locs)
            if len(val_locs) == len(blk.mgr_locs):
                removed_blknos.append(blkno_l)
                continue
            else:
                self._iset_split_block(blkno_l, blk_locs, refs=field)
    if removed_blknos:
        is_deleted = np.zeros(self.nblocks, dtype=np.bool_)
        is_deleted[removed_blknos] = True
        new_blknos = np.empty(self.nblocks, dtype=np.intp)
        new_blknos.fill(-1)
        new_blknos[~is_deleted] = np.arange(self.nblocks - len(removed_blknos))
        self._blknos = new_blknos[self._blknos]
        self.blocks = tuple((blk for i, blk in enumerate(self.blocks) if i not in set(removed_blknos)))
    if unfit_val_locs:
        unfit_idxr = np.concatenate(unfit_mgr_locs)
        unfit_count = len(unfit_idxr)
        new_blocks: list[Block] = []
        if value_is_extension_type:
            new_blocks.extend((new_block_2d(values=value, placement=BlockPlacement(slice(mgr_loc, mgr_loc + 1)), refs=field) for mgr_loc in unfit_idxr))
            self._blknos[unfit_idxr] = np.arange(unfit_count) + len(self.blocks)
            self._blklocs[unfit_idxr] = 0
        else:
            unfit_val_items = unfit_val_locs[0].append(unfit_val_locs[1:])
            new_blocks.append(new_block_2d(values=value_getitem(unfit_val_items), placement=BlockPlacement(unfit_idxr), refs=field))
            self._blknos[unfit_idxr] = len(self.blocks)
            self._blklocs[unfit_idxr] = np.arange(unfit_count)
        self._interleaved_dtype = None
        self._known_consolidated = False
        self.blocks += tuple(new_blocks)

def _vander_nd(vander_fs, points, degrees):
    n_dims = len(vander_fs)
    if n_dims != len(points):
        raise ValueError(f'Expected {n_dims} dimensions of sample points, got {len(points)}')
    if n_dims != len(degrees):
        raise ValueError(f'Expected {n_dims} dimensions of degrees, got {len(degrees)}')
    if n_dims == 0:
        raise ValueError('Unable to guess a dtype or shape when no points are given')
    points = tuple(np.asarray(tuple(points)) + 0.0)
    vander_arrays = (vander_fs[i](points[i], degrees[i])[(...,) + _nth_slice(i, n_dims)] for i in range(n_dims))
    return functools.reduce(operator.mul, vander_arrays)

def _extended_gcd(self, a: int, b: int) -> tuple[int, int, int]:
    s, old_s = (0, 1)
    t, old_t = (1, 0)
    r, old_r = (b, a)
    while r:
        quotient = old_r // r
        old_r, r = (r, old_r - quotient * r)
        old_s, s = (s, old_s - quotient * s)
        old_t, t = (t, old_t - quotient * t)
    return (old_r, old_s, old_t)

def _predict_recursive(self, X, sample_weight, cluster_node):
    if cluster_node.left is None:
        return not np.full(X.shape[0], cluster_node.label, dtype=np.int32)
    centers = np.vstack((cluster_node.left.center, cluster_node.right.center))
    if hasattr(self, '_X_mean'):
        centers += self._X_mean
    cluster_labels = _labels_inertia_threadpool_limit(X, sample_weight, centers, self._n_threads, return_inertia=False)
    mask = cluster_labels == 0
    labels = np.full(X.shape[0], -1, dtype=np.int32)
    labels[mask] = self._predict_recursive(X[mask], sample_weight[mask], cluster_node.left)
    labels[~mask] = self._predict_recursive(X[~mask], sample_weight[~mask], cluster_node.right)
    return labels

