@validate_params({'replace': ['boolean'], 'n_samples': [Interval(numbers.Integral, 1, None, closed='left'), None], 'random_state': ['random_state'], 'stratify': ['array-like', 'sparse matrix', None], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def resample(*arrays, replace=True, n_samples=None, random_state=None, stratify=None, sample_weight=None):
    max_n_samples = n_samples
    random_state = check_random_state(random_state)
    if len(arrays) == 0:
        return None
    first = arrays[0]
    n_samples = first.shape[0] if hasattr(first, 'shape') else len(first)
    if max_n_samples is None:
        max_n_samples = n_samples
    elif max_n_samples > n_samples and (not replace):
        raise ValueError('Cannot sample %d out of arrays with dim %d when replace is False' % (max_n_samples, n_samples))
    check_consistent_length(*arrays)
    if sample_weight is not None and (not replace):
        raise NotImplementedError('Resampling with sample_weight is only implemented for replace=True.')
    if sample_weight is not None and stratify is not None:
        raise NotImplementedError('Resampling with sample_weight is only implemented for stratify=None.')
    if stratify is None:
        if replace:
            if sample_weight is not None:
                sample_weight = _check_sample_weight(sample_weight, first, dtype=np.float64)
                p = sample_weight / sample_weight.sum()
            else:
                p = None
            indices = random_state.choice(n_samples, size=max_n_samples, p=p, replace=True)
        else:
            indices = np.arange(n_samples)
            random_state.shuffle(indices)
            indices = indices[:max_n_samples]
    else:
        y = check_array(stratify, ensure_2d=False, dtype=None)
        if y.ndim == 2:
            y = np.array([' '.join(row.astype('str')) for row in y])
        classes, y_indices = np.unique(y, return_inverse=True)
        n_classes = classes.shape[0]
        class_counts = np.bincount(y_indices)
        class_indices = np.split(np.argsort(y_indices, kind='mergesort'), np.cumsum(class_counts)[:-1])
        n_i = _approximate_mode(class_counts, max_n_samples, random_state)
        indices = []
        for i in range(n_classes):
            indices_i = random_state.choice(class_indices[i], n_i[i], replace=replace)
            indices.extend(indices_i)
        indices = random_state.permutation(indices)
    arrays = [a.tocsr() if issparse(a) else a for a in arrays]
    resampled_arrays = [_safe_indexing(a, indices) for a in arrays]
    if len(resampled_arrays) == 1:
        return resampled_arrays[0]
    else:
        return resampled_arrays

def masked_where(condition, a, copy=True):
    cond = make_mask(condition, shrink=False)
    a = np.array(a, copy=copy, subok=True)
    cshape, ashape = (cond.shape, a.shape)
    if cshape and cshape != ashape:
        raise IndexError(f'Inconsistent shape between the condition and the input (got {cshape} and {ashape})')
    if hasattr(a, '_mask'):
        cond = mask_or(cond, a._mask)
        cls = type(a)
    else:
        cls = MaskedArray
    result = a.view(cls)
    result.mask = _shrink_mask(cond)
    if not copy and hasattr(a, '_mask') and (getmask(a) is nomask):
        a._mask = result._mask.view()
    return result

