def _get_time_micros(self) -> npt.NDArray[np.int64]:
    values = self._data._local_timestamps()
    ppd = periods_per_day(self._data._creso)
    frac = values % ppd
    if self.unit == 'ns':
        micros = frac // 1000
    elif self.unit == 'us':
        micros = frac
    elif self.unit == 'ms':
        micros = frac * 1000
    elif self.unit == 's':
        micros = frac * 1000000
    else:
        raise NotImplementedError(self.unit)
    micros[self._isnan] = -1
    return micros

