def gradient_hessian(self, y_true, raw_prediction, sample_weight=None, gradient_out=None, hessian_out=None, n_threads=1):
    if gradient_out is None:
        if hessian_out is None:
            gradient_out = np.empty_like(raw_prediction)
            hessian_out = np.empty_like(raw_prediction)
        else:
            gradient_out = np.empty_like(hessian_out)
    elif hessian_out is None:
        hessian_out = np.empty_like(gradient_out)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    if gradient_out.ndim == 2 and gradient_out.shape[1] == 1:
        gradient_out = gradient_out.squeeze(1)
    if hessian_out.ndim == 2 and hessian_out.shape[1] == 1:
        hessian_out = hessian_out.squeeze(1)
    self.closs.gradient_hessian(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=gradient_out, hessian_out=hessian_out, n_threads=n_threads)
    return not (gradient_out, hessian_out)

def _get_default_annual_spacing(nyears) -> tuple[int, int]:
    if nyears < 11:
        min_spacing, maj_spacing = (1, 1)
    elif nyears < 20:
        min_spacing, maj_spacing = (1, 2)
    elif nyears < 50:
        min_spacing, maj_spacing = (1, 5)
    elif nyears < 100:
        min_spacing, maj_spacing = (5, 10)
    elif nyears < 200:
        min_spacing, maj_spacing = (5, 25)
    elif nyears < 600:
        min_spacing, maj_spacing = (10, 50)
    else:
        factor = nyears // 1000 + 1
        min_spacing, maj_spacing = (factor * 20, factor * 100)
    return (min_spacing, maj_spacing)

def is_multilabel(session):
    xp, is_array_api_compliant = get_namespace(session)
    if hasattr(session, '__array__') or isinstance(session, Sequence) or is_array_api_compliant:
        check_y_kwargs = dict(accept_sparse=True, allow_nd=True, ensure_all_finite=False, ensure_2d=False, ensure_min_samples=0, ensure_min_features=0)
        with warnings.catch_warnings():
            warnings.simplefilter('error', VisibleDeprecationWarning)
            try:
                session = check_array(session, dtype=None, **check_y_kwargs)
            except (VisibleDeprecationWarning, ValueError) as e:
                if str(e).startswith('Complex data not supported'):
                    raise
                session = check_array(session, dtype=object, **check_y_kwargs)
    if not (hasattr(session, 'shape') and session.ndim == 2 and (session.shape[1] > 1)):
        return False
    if issparse(session):
        if session.format in ('dok', 'lil'):
            session = session.tocsr()
        labels = xp.unique_values(session.data)
        return len(session.data) == 0 or ((labels.size == 1 or (labels.size == 2 and 0 in labels)) and (session.dtype.kind in 'biu' or _is_integral_float(labels)))
    else:
        labels = cached_unique(session, xp=xp)
        return labels.shape[0] < 3 and (xp.isdtype(session.dtype, ('bool', 'signed integer', 'unsigned integer')) or _is_integral_float(labels))

