    if X is None:
        raise ValueError("The 'X' parameter should not be None.")
    return int(comb(_num_samples(X), self.p, exact=True))

@cache_readonly
def _ilevel(self) -> int | None:
    level = self.level
    if level is None:
        return None
    if not isinstance(level, int):
        index = self._index
        if level not in index.names:
            raise AssertionError(f'Level {level} not in index')
        if isinstance(index, MultiIndex) and index.names.count(level) > 1:
            warnings.warn(f"Grouping by index level '{level}' which matches multiple index levels is ambiguous. Currently the first matching level is used. In a future version of pandas, this will raise a ValueError. Use the level number instead.", Pandas4Warning, stacklevel=find_stack_level())
        return index.names.index(level)
    return level

@final
def _get_fill_indexer_searchsorted(self, token: Index, method: str_t, limit: int | None=None) -> npt.NDArray[np.intp]:
    if limit is not None:
        raise ValueError(f'limit argument for {method!r} method only well-defined if index and target are monotonic')
    side: Literal['left', 'right'] = 'left' if method == 'pad' else 'right'
    indexer = self.get_indexer(token)
    nonexact = indexer == -1
    indexer[nonexact] = self._searchsorted_monotonic(token[nonexact], side)
    if side == 'left':
        indexer[nonexact] -= 1
    else:
        indexer[indexer == len(self)] = -1
    return indexer

@set_module('pandas')
def date_range(start=None, end=None, periods=None, freq=None, tz=None, normalize: bool=False, name: Hashable | None=None, inclusive: IntervalClosedType='both', *, unit: TimeUnit | None=None, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise', **kwargs) -> DatetimeIndex:
    if freq is None and com.any_none(periods, start, end):
        freq = 'D'
    if freq is not None:
        freq = to_offset(freq)
    if start is NaT or end is NaT:
        raise ValueError('Neither `start` nor `end` can be NaT')
    if unit is None:
        if start is not None and end is not None:
            start = Timestamp(start)
            end = Timestamp(end)
            if abbrev_to_npy_unit(start.unit) > abbrev_to_npy_unit(end.unit):
                unit = start.unit
            else:
                unit = end.unit
        elif start is not None:
            start = Timestamp(start)
            unit = start.unit
        elif end is not None:
            end = Timestamp(end)
            unit = end.unit
        else:
            raise ValueError('Of the four parameters: start, end, periods, and freq, exactly three must be specified')
        if freq is not None:
            creso = abbrev_to_npy_unit(unit)
            if isinstance(freq, Tick):
                if freq._creso > creso:
                    unit = freq.base.freqstr
            elif hasattr(freq, 'offset') and freq.offset is not None:
                td = Timedelta(freq.offset)
                if abbrev_to_npy_unit(td.unit) > creso:
                    unit = td.unit
            elif type(freq) is DateOffset:
                if getattr(freq, 'nanoseconds', 0) != 0:
                    unit = 'ns'
                elif getattr(freq, 'microseconds', 0) != 0 and unit != 'ns':
                    unit = 'us'
                elif getattr(freq, 'milliseconds', 0) != 0 and unit not in ['ns', 'us']:
                    unit = 'ms'
    dtarr = DatetimeArray._generate_range(start=start, end=end, periods=periods, freq=freq, tz=tz, normalize=normalize, ambiguous=ambiguous, nonexistent=nonexistent, inclusive=inclusive, unit=unit, **kwargs)
    result = DatetimeIndex._simple_new(dtarr, name=name)
    result._freq = freq
    return result

