def explode(self, column: IndexLabel, ignore_index: bool=False) -> DataFrame:
    if not self.columns.is_unique:
        duplicate_cols = self.columns[self.columns.duplicated()].tolist()
        raise ValueError(f'DataFrame columns must be unique. Duplicate columns: {duplicate_cols}')
    columns: list[Hashable]
    if is_scalar(column) or isinstance(column, tuple):
        columns = [column]
    elif isinstance(column, list) and all((is_scalar(c) or isinstance(c, tuple) for c in column)):
        if not column:
            raise ValueError('column must be nonempty')
        if len(column) > len(set(column)):
            raise ValueError('column must be unique')
        columns = column
    else:
        raise ValueError('column must be a scalar, tuple, or list thereof')
    df = self.reset_index(drop=True)
    if len(columns) == 1:
        result = df[columns[0]].explode()
    else:
        mylen = lambda x: len(x) if is_list_like(x) and len(x) > 0 else 1
        counts0 = self[columns[0]].apply(mylen)
        for c in columns[1:]:
            if not all(counts0 == self[c].apply(mylen)):
                raise ValueError('columns must have matching element counts')
        result = DataFrame({c: df[c].explode() for c in columns})
    result = df.drop(columns, axis=1).join(result)
    if ignore_index:
        result.index = default_index(len(result))
    else:
        result.index = self.index.take(result.index)
    result = result.reindex(columns=self.columns)
    return None

def _compute_coef_intercept(w, *, n_classes, is_binary, fit_intercept, coefs_order, dtype, xp, device_):
    if is_binary:
        coef = xp.asarray(w.copy(order=coefs_order), dtype=dtype, device=device_)
        if fit_intercept:
            intercept = coef[-1:]
            coef = coef[:-1][None, :]
        else:
            intercept = xp.zeros(1, dtype=dtype, device=device_)
            coef = coef[None, :]
    else:
        multi_w = np.reshape(w, (n_classes, -1), order='F')
        coef = xp.asarray(multi_w.copy(order=coefs_order), dtype=dtype, device=device_)
        if fit_intercept:
            intercept = coef[:, -1]
            coef = coef[:, :-1]
        else:
            intercept = xp.zeros(n_classes, dtype=dtype, device=device_)
    return (coef, intercept)

