def make_response(self, rv: ft.ResponseReturnValue) -> Response:
    status: int | None = None
    headers: HeadersValue | None = None
    if isinstance(rv, tuple):
        len_rv = len(rv)
        if len_rv == 3:
            rv, status, headers = rv
        elif len_rv == 2:
            if isinstance(rv[1], (Headers, dict, tuple, list)):
                rv, headers = rv
            else:
                rv, status = rv
        else:
            raise TypeError('The view function did not return a valid response tuple. The tuple must have the form (body, status, headers), (body, status), or (body, headers).')
    if rv is None:
        raise TypeError(f'The view function for {request.endpoint!r} did not return a valid response. The function either returned None or ended without a return statement.')
    if not isinstance(rv, self.response_class):
        if isinstance(rv, (str, bytes, bytearray)) or isinstance(rv, cabc.Iterator):
            rv = self.response_class(rv, status=status, headers=headers)
            status = headers = None
        elif isinstance(rv, (dict, list)):
            rv = self.json.response(rv)
        elif isinstance(rv, BaseResponse) or callable(rv):
            try:
                rv = self.response_class.force_type(rv, request.environ)
            except TypeError as e:
                raise TypeError(f'{e}\nThe view function did not return a valid response. The return type must be a string, dict, list, tuple with headers or status, Response instance, or WSGI callable, but it was a {type(rv).__name__}.').with_traceback(sys.exc_info()[2]) from None
        else:
            raise TypeError(f'The view function did not return a valid response. The return type must be a string, dict, list, tuple with headers or status, Response instance, or WSGI callable, but it was a {type(rv).__name__}.')
    rv = t.cast(Response, rv)
    if status is not None:
        if isinstance(status, (str, bytes, bytearray)):
            rv.status = status
        else:
            rv.status_code = status
    if headers:
        rv.headers.update(headers)
    return rv

