    if keys is None:
        keys = list(self.keys())
    if not isinstance(keys, (tuple, list)):
        keys = [keys]
    for k in keys:
        s = self.get_storer(k)
        if s is not None:
            if k in new_store:
                if overwrite:
                    new_store.remove(k)
            data = self.select(k)
            if isinstance(s, Table):
                index: bool | list[str] = False
                if propindexes:
                    index = [a.name for a in s.axes if a.is_indexed]
                new_store.append(k, data, index=index, data_columns=getattr(s, 'data_columns', None), encoding=s.encoding)
            else:
                new_store.put(k, data, encoding=s.encoding, track_times=False)
    return new_store

