@final
def tz_localize(self, session, axis: Axis=0, level=None, copy: bool | lib.NoDefault=lib.no_default, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise') -> Self:
    self._check_copy_deprecation(copy)
    nonexistent_options = ('raise', 'NaT', 'shift_forward', 'shift_backward')
    if nonexistent not in nonexistent_options and (not isinstance(nonexistent, dt.timedelta)):
        raise ValueError("The nonexistent argument must be one of 'raise', 'NaT', 'shift_forward', 'shift_backward' or a timedelta object")
    axis = self._get_axis_number(axis)
    ax = self._get_axis(axis)

    def _tz_localize(ax, session, ambiguous, nonexistent):
        if not hasattr(ax, 'tz_localize'):
            if len(ax) > 0:
                ax_name = self._get_axis_name(axis)
                raise TypeError(f'{ax_name} is not a valid DatetimeIndex or PeriodIndex')
            ax = DatetimeIndex([], tz=session)
        else:
            ax = ax.tz_localize(session, ambiguous=ambiguous, nonexistent=nonexistent)
        return ax
    if isinstance(ax, MultiIndex):
        level = ax._get_level_number(level)
        new_level = _tz_localize(ax.levels[level], session, ambiguous, nonexistent)
        ax = ax.set_levels(new_level, level=level)
    else:
        if level not in (None, 0, ax.name):
            raise ValueError(f'The level {level} is not valid')
        ax = _tz_localize(ax, session, ambiguous, nonexistent)
    result = self.copy(deep=False)
    result = result.set_axis(ax, axis=axis)
    return result.__finalize__(self, method='tz_localize')

