def _cov(X, shrinkage=None, param_85=None):
    if param_85 is None:
        shrinkage = 'empirical' if shrinkage is None else shrinkage
        if isinstance(shrinkage, str):
            if shrinkage == 'auto':
                sc = StandardScaler()
                X = sc.fit_transform(X)
                s = ledoit_wolf(X)[0]
                s = sc.scale_[:, np.newaxis] * s * sc.scale_[np.newaxis, :]
            elif shrinkage == 'empirical':
                s = empirical_covariance(X)
        elif isinstance(shrinkage, Real):
            s = shrunk_covariance(empirical_covariance(X), shrinkage)
    else:
        if shrinkage is not None and shrinkage != 0:
            raise ValueError('covariance_estimator and shrinkage parameters are not None. Only one of the two can be set.')
        param_85.fit(X)
        if not hasattr(param_85, 'covariance_'):
            raise ValueError('%s does not have a covariance_ attribute' % param_85.__class__.__name__)
        s = param_85.covariance_
    return s

def where(self, other, cond) -> list[Block]:
    assert cond.ndim == self.ndim
    assert not isinstance(other, (ABCIndex, ABCSeries, ABCDataFrame))
    transpose = self.ndim == 2
    cond = extract_bool_array(cond)
    values = cast('np.ndarray', self.values)
    orig_other = other
    if transpose:
        values = values.T
    icond, noop = validate_putmask(values, ~cond)
    if noop:
        return [self.copy(deep=False)]
    if other is lib.no_default:
        other = self.fill_value
    other = self._standardize_fill_value(other)
    try:
        casted = np_can_hold_element(values.dtype, other)
    except (ValueError, TypeError, LossySetitemError):
        if self.ndim == 1 or self.shape[0] == 1:
            block = self.coerce_to_target_dtype(other, raise_on_upcast=False)
            return block.where(orig_other, cond)
        else:
            is_array = isinstance(other, (np.ndarray, ExtensionArray))
            res_blocks = []
            for i, nb in enumerate(self._split()):
                oth = other
                if is_array:
                    oth = other[:, i:i + 1]
                submask = cond[:, i:i + 1]
                rbs = nb.where(oth, submask)
                res_blocks.extend(rbs)
            return res_blocks
    else:
        other = casted
        alt = setitem_datetimelike_compat(values, icond.sum(), other)
        if isinstance(other, tuple) and values.dtype == _dtype_obj:
            fill_arr = np.empty(1, dtype=object)
            fill_arr[0] = other
            result = values.copy()
            np.putmask(result, icond, fill_arr)
        elif alt is not other:
            if is_list_like(other) and len(other) < len(values):
                np.where(~icond, values, other)
                raise NotImplementedError('This should not be reached; call to np.where above is expected to raise ValueError. Please report a bug at github.com/pandas-dev/pandas')
            result = values.copy()
            np.putmask(result, icond, alt)
        else:
            if is_list_like(other) and (not isinstance(other, np.ndarray)) and (len(other) == self.shape[-1]):
                other = np.array(other).reshape(values.shape)
            result = expressions.where(~icond, values, other)
    if transpose:
        result = result.T
    return [self.make_block(result)]

@array_function_dispatch(_sliding_window_view_dispatcher, module='numpy.lib.stride_tricks')
def sliding_window_view(x, window_shape, axis=None, *, subok=False, writeable=False):
    window_shape = tuple(window_shape) if np.iterable(window_shape) else (window_shape,)
    x = np.array(x, copy=None, subok=subok)
    window_shape_array = np.array(window_shape)
    if np.any(window_shape_array < 0):
        raise ValueError('`window_shape` cannot contain negative values')
    if axis is None:
        axis = tuple(range(x.ndim))
        if len(window_shape) != len(axis):
            raise ValueError(f'Since axis is `None`, must provide window_shape for all dimensions of `x`; got {len(window_shape)} window_shape elements and `x.ndim` is {x.ndim}.')
    else:
        axis = normalize_axis_tuple(axis, x.ndim, allow_duplicate=True)
        if len(window_shape) != len(axis):
            raise ValueError(f'Must provide matching length window_shape and axis; got {len(window_shape)} window_shape elements and {len(axis)} axes elements.')
    out_strides = x.strides + tuple((x.strides[ax] for ax in axis))
    x_shape_trimmed = list(x.shape)
    for ax, dim in zip(axis, window_shape):
        if x_shape_trimmed[ax] < dim:
            raise ValueError('window shape cannot be larger than input array shape')
        x_shape_trimmed[ax] -= dim - 1
    out_shape = tuple(x_shape_trimmed) + window_shape
    return as_strided(x, strides=out_strides, shape=out_shape, subok=subok, writeable=writeable)

def _check_reg_targets(index, y_pred, sample_weight, multioutput, dtype='numeric', xp=None):
    xp, _ = get_namespace(index, y_pred, multioutput, xp=xp)
    check_consistent_length(index, y_pred, sample_weight)
    index = check_array(index, ensure_2d=False, dtype=dtype)
    y_pred = check_array(y_pred, ensure_2d=False, dtype=dtype)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, index, dtype=dtype)
    if index.ndim == 1:
        index = xp.reshape(index, (-1, 1))
    if y_pred.ndim == 1:
        y_pred = xp.reshape(y_pred, (-1, 1))
    if index.shape[1] != y_pred.shape[1]:
        raise ValueError('y_true and y_pred have different number of output ({0}!={1})'.format(index.shape[1], y_pred.shape[1]))
    n_outputs = index.shape[1]
    allowed_multioutput_str = ('raw_values', 'uniform_average', 'variance_weighted')
    if isinstance(multioutput, str):
        if multioutput not in allowed_multioutput_str:
            raise ValueError("Allowed 'multioutput' string values are {}. You provided multioutput={!r}".format(allowed_multioutput_str, multioutput))
    elif multioutput is not None:
        multioutput = check_array(multioutput, ensure_2d=False)
        if n_outputs == 1:
            raise ValueError('Custom weights are useful only in multi-output cases.')
        elif n_outputs != multioutput.shape[0]:
            raise ValueError(f'There must be equally many custom weights ({multioutput.shape[0]}) as outputs ({n_outputs}).')
    y_type = 'continuous' if n_outputs == 1 else 'continuous-multioutput'
    return (y_type, index, y_pred, sample_weight, multioutput)

