def _validate_multiclass_probabilistic_prediction(y_true, y_prob, param_81, labels):
    xp, _, device_ = get_namespace_and_device(y_prob)
    if xp.max(y_prob) > 1:
        raise ValueError(f'y_prob contains values greater than 1: {xp.max(y_prob)}')
    if xp.min(y_prob) < 0:
        raise ValueError(f'y_prob contains values lower than 0: {xp.min(y_prob)}')
    check_consistent_length(y_prob, y_true, param_81)
    if param_81 is not None:
        _check_sample_weight(param_81, y_prob, force_float_dtype=False)
    transformed_labels, lb_classes = _one_hot_encoding_multiclass_target(y_true=y_true, labels=labels, target_xp=xp, target_device=device_)
    if y_prob.ndim == 1:
        y_prob = y_prob[:, xp.newaxis]
    if y_prob.shape[1] == 1:
        y_prob = xp.concat([1 - y_prob, y_prob], axis=1)
    eps = xp.finfo(y_prob.dtype).eps
    y_prob_sum = xp.sum(y_prob, axis=1)
    if not xp.all(xpx.isclose(y_prob_sum, xp.asarray(1, dtype=y_prob_sum.dtype, device=device_), rtol=sqrt(eps))):
        warnings.warn('The y_prob values do not sum to one. Make sure to pass probabilities.', UserWarning)
    if lb_classes.shape[0] != y_prob.shape[1]:
        if labels is None:
            raise ValueError('y_true and y_prob contain different number of classes: {0} vs {1}. Please provide the true labels explicitly through the labels argument. Classes found in y_true: {2}'.format(transformed_labels.shape[1], y_prob.shape[1], lb_classes))
        else:
            raise ValueError('The number of classes in labels is different from that in y_prob. Classes found in labels: {0}'.format(lb_classes))
    return (transformed_labels, y_prob)

def __call__(self, X, Y=None, eval_gradient=False):
    X = np.atleast_2d(X)
    if Y is None:
        K = np.inner(X, X) + self.sigma_0 ** 2
    else:
        if eval_gradient:
            raise ValueError('Gradient can only be evaluated when Y is None.')
        K = np.inner(X, Y) + self.sigma_0 ** 2
    if eval_gradient:
        if not self.hyperparameter_sigma_0.fixed:
            K_gradient = np.empty((K.shape[0], K.shape[1], 1))
            K_gradient[..., 0] = 2 * self.sigma_0 ** 2
            return (K, K_gradient)
        else:
            return (K, np.empty((X.shape[0], X.shape[0], 0)))
    else:
        return K

def _concatenate_chunks(chunks: list[dict[int, ArrayLike]], column_names: list[str]) -> dict:
    names = list(chunks[0].keys())
    warning_columns = []
    result: dict = {}
    for name in names:
        arrs = [chunk.pop(name) for chunk in chunks]
        dtypes = {a.dtype for a in arrs}
        non_cat_dtypes = {x for x in dtypes if not isinstance(x, CategoricalDtype)}
        dtype = dtypes.pop()
        if isinstance(dtype, CategoricalDtype):
            result[name] = union_categoricals(arrs, sort_categories=False)
        else:
            result[name] = concat_compat(arrs)
            if len(non_cat_dtypes) > 1 and result[name].dtype == np.dtype(object):
                warning_columns.append(column_names[name])
    if warning_columns:
        warning_names = ', '.join([f'{index}: {name}' for index, name in enumerate(warning_columns)])
        warning_message = ' '.join([f'Columns ({warning_names}) have mixed types. Specify dtype option on import or set low_memory=False.'])
        warnings.warn(warning_message, DtypeWarning, stacklevel=find_stack_level())
    return result

