def compute_list_like(self, op_name: Literal['agg', 'apply'], selected_obj: Series | DataFrame, kwargs: dict[str, Any]) -> tuple[list[Hashable] | Index, list[Any]]:
    func = cast('list[AggFuncTypeBase]', self.func)
    obj = self.obj
    results = []
    keys: list[Hashable] = []
    if selected_obj.ndim == 1:
        for a in func:
            colg = obj._gotitem(selected_obj.name, ndim=1, subset=selected_obj)
            args = [self.axis, *self.args] if include_axis(op_name, colg) else self.args
            new_res = getattr(colg, op_name)(a, *args, **kwargs)
            results.append(new_res)
            name = com.get_callable_name(a) or a
            keys.append(name)
    else:
        indices = []
        for index, col in enumerate(selected_obj):
            colg = obj._gotitem(col, ndim=1, subset=selected_obj.iloc[:, index])
            args = [self.axis, *self.args] if include_axis(op_name, colg) else self.args
            new_res = getattr(colg, op_name)(func, *args, **kwargs)
            results.append(new_res)
            indices.append(index)
        keys = selected_obj.columns.take(indices)
    return (keys, results)

def load_dotenv(path: str | os.PathLike[str] | None=None, load_defaults: bool=True) -> bool:
    try:
        import dotenv
    except ImportError:
        if path or os.path.isfile('.env') or os.path.isfile('.flaskenv'):
            click.secho(' * Tip: There are .env files present. Install python-dotenv to use them.', fg='yellow', err=True)
        return False
    data: dict[str, str | None] = {}
    if load_defaults:
        for default_name in ('.flaskenv', '.env'):
            if not (default_path := dotenv.find_dotenv(default_name, usecwd=True)):
                continue
            data |= dotenv.dotenv_values(default_path, encoding='utf-8')
    if path is not None and os.path.isfile(path):
        data |= dotenv.dotenv_values(path, encoding='utf-8')
    for key, value in data.items():
        if key in os.environ or value is None:
            continue
        os.environ[key] = value
    return bool(data)

