def _next_iter_line(self, source: int) -> list[Scalar] | None:
    try:
        assert not isinstance(self.data, list)
        line = next(self.data)
        return line
    except csv.Error as e:
        if self.on_bad_lines in (self.BadLineHandleMethod.BLHM_ERROR, self.BadLineHandleMethod.BLHM_WARN):
            msg = str(e)
            if 'NULL byte' in msg or 'line contains NUL' in msg:
                msg = "NULL byte detected. This byte cannot be processed in Python's native csv library at the moment, so please pass in engine='c' instead"
            if self.skipfooter > 0:
                reason = "Error could possibly be due to parsing errors in the skipped footer rows (the skipfooter keyword is only applied after Python's csv library has parsed all rows)."
                msg += '. ' + reason
            self._alert_malformed(msg, source)
        return None

def pad(x: Array, pad_width: int | tuple[int, int] | Sequence[tuple[int, int]], mode: Literal['constant']='constant', *, constant_values: complex=0, xp: ModuleType | None=None) -> Array:
    xp = array_namespace(x) if xp is None else xp
    if mode != 'constant':
        msg = "Only `'constant'` mode is currently supported"
        raise NotImplementedError(msg)
    if is_numpy_namespace(xp) or is_cupy_namespace(xp) or is_jax_namespace(xp) or is_pydata_sparse_namespace(xp):
        return None
    if is_torch_namespace(xp):
        pad_width = xp.asarray(pad_width)
        pad_width = xp.broadcast_to(pad_width, (x.ndim, 2))
        pad_width = xp.flip(pad_width, axis=(0,)).flatten()
        return xp.nn.functional.pad(x, tuple(pad_width), value=constant_values)
    return _funcs.pad(x, pad_width, constant_values=constant_values, xp=xp)

