@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_score': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def label_ranking_average_precision_score(y_true, y_score, *, sample_weight=None):
    check_consistent_length(y_true, y_score, sample_weight)
    y_true = check_array(y_true, ensure_2d=False, accept_sparse='csr')
    y_score = check_array(y_score, ensure_2d=False)
    if y_true.shape != y_score.shape:
        raise ValueError('y_true and y_score have different shape')
    y_type = type_of_target(y_true, input_name='y_true')
    if y_type != 'multilabel-indicator' and (not (y_type == 'binary' and y_true.ndim == 2)):
        raise ValueError('{0} format is not supported'.format(y_type))
    if not issparse(y_true):
        y_true = csr_array(y_true)
    y_score = -y_score
    n_samples, n_labels = y_true.shape
    out = 0.0
    for i, (start, stop) in enumerate(zip(y_true.indptr, y_true.indptr[1:])):
        relevant = y_true.indices[start:stop]
        if relevant.size == 0 or relevant.size == n_labels:
            aux = 1.0
        else:
            scores_i = y_score[i]
            rank = rankdata(scores_i, 'max')[relevant]
            L = rankdata(scores_i[relevant], 'max')
            aux = (L / rank).mean()
        if sample_weight is not None:
            aux = aux * sample_weight[i]
        out += aux
    if sample_weight is None:
        out /= n_samples
    else:
        out /= np.sum(sample_weight)
    return float(out)

def check_estimator_sparse_tag(item, estimator_orig):
    estimator = clone(estimator_orig)
    rng = np.random.RandomState(0)
    n_samples = 15 if item == 'SpectralCoclustering' else 40
    X = rng.uniform(size=(n_samples, 3))
    X[X < 0.6] = 0
    y = rng.randint(0, 3, size=n_samples)
    X = _enforce_estimator_tags_X(estimator, X)
    y = _enforce_estimator_tags_y(estimator, y)
    X = sparse.csr_array(X)
    tags = get_tags(estimator)
    if tags.input_tags.sparse:
        try:
            estimator.fit(X, y)
        except Exception as e:
            err_msg = f"Estimator {item} raised an exception. The tag self.input_tags.sparse={tags.input_tags.sparse} might not be consistent with the estimator's ability to handle sparse data (i.e. controlled by the parameter `accept_sparse` in `validate_data` or `check_array` functions)."
            raise AssertionError(err_msg) from e
    else:
        err_msg = f"Estimator {item} raised an exception. The estimator failed when fitted on sparse data in accordance with its tag self.input_tags.sparse={tags.input_tags.sparse} but didn't raise the appropriate error: error message should state explicitly that sparse input is not supported if this is not the case, e.g. by using check_array(X, accept_sparse=False)."
        try:
            estimator.fit(X, y)
        except (ValueError, TypeError) as e:
            if re.search('[Ss]parse', str(e)):
                return
            raise AssertionError(err_msg) from e
        except Exception as e:
            raise AssertionError(err_msg) from e
        raise AssertionError(f"Estimator {item} didn't fail when fitted on sparse data but should have according to its tag self.input_tags.sparse={tags.input_tags.sparse}. The tag is inconsistent and must be fixed.")

