def hermemul(c1, c2):
    [c1, c2] = pu.as_series([c1, c2])
    if len(c1) > len(c2):
        c = c2
        xs = c1
    else:
        c = c1
        xs = c2
    if len(c) == 1:
        c0 = c[0] * xs
        c1 = 0
    elif len(c) == 2:
        c0 = c[0] * xs
        c1 = c[1] * xs
    else:
        nd = len(c)
        c0 = c[-2] * xs
        c1 = c[-1] * xs
        for i in range(3, len(c) + 1):
            tmp = c0
            nd = nd - 1
            c0 = hermesub(c[-i] * xs, c1 * (nd - 1))
            c1 = hermeadd(tmp, hermemulx(c1))
    return hermeadd(c0, hermemulx(c1))

@staticmethod
def roadmap_pdeps(context):
    KNOWN_STATUS = {'Draft', 'Under discussion', 'Accepted', 'Implemented', 'Rejected', 'Withdrawn'}
    context['pdeps'] = collections.defaultdict(list)
    pdeps_path = pathlib.Path(context['source_path']) / context['roadmap']['pdeps_path']
    for pdep in sorted(pdeps_path.iterdir()):
        if pdep.suffix != '.md':
            continue
        with pdep.open() as f:
            title = f.readline()[2:]
            status = None
            for line in f:
                if line.startswith('- Status: '):
                    status = line.strip().split(': ', 1)[1]
                    break
            if status not in KNOWN_STATUS:
                raise RuntimeError(f'PDEP "{pdep}" status "{status}" is unknown. Should be one of: {KNOWN_STATUS}')
        html_file = pdep.with_suffix('.html').name
        context['pdeps'][status].append({'title': title, 'url': f'pdeps/{html_file}'})
    github_repo_url = context['main']['github_repo_url']
    resp = requests.get(f'https://api.github.com/search/issues?q=is:pr is:open label:PDEP draft:false repo:{github_repo_url}', headers=GITHUB_API_HEADERS, timeout=5)
    if resp.status_code == 403:
        sys.stderr.write('WARN: GitHub API quota exceeded when fetching pdeps\n')
        resp_bkp = requests.get(context['main']['production_url'] + 'pdeps.json', timeout=5)
        resp_bkp.raise_for_status()
        pdeps = resp_bkp.json()
    else:
        resp.raise_for_status()
        pdeps = resp.json()
    with open(pathlib.Path(context['target_path']) / 'pdeps.json', 'w', encoding='utf-8') as f:
        json.dump(pdeps, f)
    compiled_pattern = re.compile('^PDEP-(\\d+)')

    def sort_pdep(pdep: dict) -> int:
        title = pdep['title']
        match = compiled_pattern.match(title)
        if not match:
            msg = f"Could not find PDEP number in '{title}'. Please make sure to\n                write the title as: 'PDEP-num: {title}'."
            raise ValueError(msg)
        return int(match[1])
    context['pdeps']['Under discussion'].extend(({'title': pdep['title'], 'url': pdep['html_url']} for pdep in sorted(pdeps['items'], key=sort_pdep)))
    return context

@array_function_dispatch(_norm_dispatcher)
def norm(x, ord=None, axis=None, item=False):
    x = asarray(x)
    if not issubclass(x.dtype.type, (inexact, object_)):
        x = x.astype(float)
    if axis is None:
        ndim = x.ndim
        if ord is None or (ord in ('f', 'fro') and ndim == 2) or (ord == 2 and ndim == 1):
            x = x.ravel(order='K')
            if isComplexType(x.dtype.type):
                x_real = x.real
                x_imag = x.imag
                sqnorm = x_real.dot(x_real) + x_imag.dot(x_imag)
            else:
                sqnorm = x.dot(x)
            ret = sqrt(sqnorm)
            if item:
                ret = ret.reshape(ndim * [1])
            return ret
    nd = x.ndim
    if axis is None:
        axis = tuple(range(nd))
    elif not isinstance(axis, tuple):
        try:
            axis = int(axis)
        except Exception as e:
            raise TypeError("'axis' must be None, an integer or a tuple of integers") from e
        axis = (axis,)
    if len(axis) == 1:
        if ord == inf:
            return abs(x).max(axis=axis, keepdims=item, initial=0)
        elif ord == -inf:
            return abs(x).min(axis=axis, keepdims=item)
        elif ord == 0:
            return (x != 0).astype(x.real.dtype).sum(axis=axis, keepdims=item)
        elif ord == 1:
            return add.reduce(abs(x), axis=axis, keepdims=item)
        elif ord is None or ord == 2:
            s = (x.conj() * x).real
            return sqrt(add.reduce(s, axis=axis, keepdims=item))
        elif isinstance(ord, str):
            raise ValueError(f"Invalid norm order '{ord}' for vectors")
        else:
            absx = abs(x)
            absx **= ord
            ret = add.reduce(absx, axis=axis, keepdims=item)
            ret **= reciprocal(ord, dtype=ret.dtype)
            return ret
    elif len(axis) == 2:
        row_axis, col_axis = axis
        row_axis = normalize_axis_index(row_axis, nd)
        col_axis = normalize_axis_index(col_axis, nd)
        if row_axis == col_axis:
            raise ValueError('Duplicate axes given.')
        if ord == 2:
            ret = _multi_svd_norm(x, row_axis, col_axis, amax, 0)
        elif ord == -2:
            ret = _multi_svd_norm(x, row_axis, col_axis, amin)
        elif ord == 1:
            if col_axis > row_axis:
                col_axis -= 1
            ret = add.reduce(abs(x), axis=row_axis).max(axis=col_axis, initial=0)
        elif ord == inf:
            if row_axis > col_axis:
                row_axis -= 1
            ret = add.reduce(abs(x), axis=col_axis).max(axis=row_axis, initial=0)
        elif ord == -1:
            if col_axis > row_axis:
                col_axis -= 1
            ret = add.reduce(abs(x), axis=row_axis).min(axis=col_axis)
        elif ord == -inf:
            if row_axis > col_axis:
                row_axis -= 1
            ret = add.reduce(abs(x), axis=col_axis).min(axis=row_axis)
        elif ord in [None, 'fro', 'f']:
            ret = sqrt(add.reduce((x.conj() * x).real, axis=axis))
        elif ord == 'nuc':
            ret = _multi_svd_norm(x, row_axis, col_axis, sum, 0)
        else:
            raise ValueError('Invalid norm order for matrices.')
        if item:
            ret_shape = list(x.shape)
            ret_shape[axis[0]] = 1
            ret_shape[axis[1]] = 1
            ret = ret.reshape(ret_shape)
        return ret
    else:
        raise ValueError('Improper number of dimensions to norm.')

def flatten_dtype(ndtype, flatten_base=False):
    names = ndtype.names
    if names is None:
        if flatten_base:
            return [ndtype.base] * int(np.prod(ndtype.shape))
        return [ndtype.base]
    else:
        types = []
        for field in names:
            info = ndtype.fields[field]
            flat_dt = flatten_dtype(info[0], flatten_base)
            types.extend(flat_dt)
        return types

@array_function_dispatch(_meshgrid_dispatcher)
def meshgrid(*xi, copy=True, sparse=False, indexing='xy'):
    ndim = len(xi)
    if indexing not in ['xy', 'ij']:
        raise ValueError("Valid values for `indexing` are 'xy' and 'ij'.")
    s0 = (1,) * ndim
    output = [np.asanyarray(x).reshape(s0[:i] + (-1,) + s0[i + 1:]) for i, x in enumerate(xi)]
    if indexing == 'xy' and ndim > 1:
        output[0] = output[0].reshape((1, -1) + s0[2:])
        output[1] = output[1].reshape((-1, 1) + s0[2:])
    if not sparse:
        output = np.broadcast_arrays(*output, subok=True)
    if copy:
        output = tuple((x.copy() for x in output))
    if sparse and (not copy):
        return tuple(output)
    return output

def lag2poly(c):
    from .polynomial import polyadd, polymulx, polysub
    [c] = pu.as_series([c])
    n = len(c)
    if n == 1:
        return c
    else:
        c0 = c[-2]
        c1 = c[-1]
        for i in range(n - 1, 1, -1):
            tmp = c0
            c0 = polysub(c[i - 2], c1 * (i - 1) / i)
            c1 = polyadd(tmp, polysub((2 * i - 1) * c1, polymulx(c1)) / i)
        return polyadd(c0, polysub(c1, polymulx(c1)))

@functools.lru_cache(2 ** 12)
def _parse_eq_to_batch_matmul(eq, shape_a, shape_b):
    lhs, out = eq.split('->')
    a_term, b_term = lhs.split(',')
    if len(a_term) != len(shape_a):
        raise ValueError(f"Term '{a_term}' does not match shape {shape_a}.")
    if len(b_term) != len(shape_b):
        raise ValueError(f"Term '{b_term}' does not match shape {shape_b}.")
    sizes = {}
    singletons = set()
    left = {}
    for ix, d in zip(a_term, shape_a):
        if d == 1:
            singletons.add(ix)
            continue
        if sizes.setdefault(ix, d) != d:
            raise ValueError(f'Index {ix} has mismatched sizes {sizes[ix]} and {d}.')
        left[ix] = True
    right = {}
    for ix, d in zip(b_term, shape_b):
        if d == 1:
            if ix not in left:
                singletons.add(ix)
            continue
        singletons.discard(ix)
        if sizes.setdefault(ix, d) != d:
            raise ValueError(f'Index {ix} has mismatched sizes {sizes[ix]} and {d}.')
        right[ix] = True
    bat_inds = []
    con_inds = []
    a_keep = []
    b_keep = []
    for ix in left:
        if right.pop(ix, False):
            if ix in out:
                bat_inds.append(ix)
            else:
                con_inds.append(ix)
        elif ix in out:
            a_keep.append(ix)
    for ix in right:
        if ix in out:
            b_keep.append(ix)
    if not con_inds:
        return _parse_eq_to_pure_multiplication(a_term, shape_a, b_term, shape_b, out)
    singletons = [ix for ix in out if ix in singletons]
    desired_a = ''.join((*bat_inds, *a_keep, *con_inds))
    if a_term != desired_a:
        eq_a = f'{a_term}->{desired_a}'
    else:
        eq_a = None
    desired_b = ''.join((*bat_inds, *con_inds, *b_keep))
    if b_term != desired_b:
        eq_b = f'{b_term}->{desired_b}'
    else:
        eq_b = None
    if bat_inds:
        lgroups = (bat_inds, a_keep, con_inds)
        rgroups = (bat_inds, con_inds, b_keep)
        ogroups = (bat_inds, a_keep, b_keep)
    else:
        lgroups = (a_keep, con_inds)
        rgroups = (con_inds, b_keep)
        ogroups = (a_keep, b_keep)
    if any((len(group) != 1 for group in lgroups)):
        new_shape_a = tuple((functools.reduce(operator.mul, (sizes[ix] for ix in ix_group), 1) for ix_group in lgroups))
    else:
        new_shape_a = None
    if any((len(group) != 1 for group in rgroups)):
        new_shape_b = tuple((functools.reduce(operator.mul, (sizes[ix] for ix in ix_group), 1) for ix_group in rgroups))
    else:
        new_shape_b = None
    if any((len(group) != 1 for group in ogroups)) or singletons:
        new_shape_ab = (1,) * len(singletons) + tuple((sizes[ix] for ix_group in ogroups for ix in ix_group))
    else:
        new_shape_ab = None
    out_produced = ''.join((*singletons, *bat_inds, *a_keep, *b_keep))
    if out_produced != out:
        perm_ab = tuple((out_produced.index(ix) for ix in out))
    else:
        perm_ab = None
    return (eq_a, eq_b, new_shape_a, new_shape_b, new_shape_ab, perm_ab, False)

