def _lazy_apply_wrapper(func: Callable[..., Array | ArrayLike | Sequence[Array | ArrayLike]], as_numpy: bool, multi_output: bool, xp: ModuleType) -> Callable[..., tuple[Array, ...]]:

    @wraps(func)
    def wrapper(*args: Array | complex | None, **kwargs: Any) -> tuple[Array, ...]:
        args_list = []
        device = None
        for arg in args:
            if arg is not None and (not is_python_scalar(arg)):
                if device is None:
                    device = _compat.device(arg)
                if as_numpy:
                    import numpy as np
                    arg = cast(Array, np.asarray(arg))
            args_list.append(arg)
        assert device is not None
        out = func(*args_list, **kwargs)
        if multi_output:
            assert isinstance(out, Sequence)
            return None
        return (xp.asarray(out, device=device),)
    return wrapper

def to_sql(self, frame, name: str, if_exists: str='fail', record: bool=True, index_label=None, schema=None, chunksize: int | None=None, dtype: DtypeArg | None=None, method: Literal['multi'] | Callable | None=None, engine: str='auto', **engine_kwargs) -> int | None:
    if dtype:
        if not is_dict_like(dtype):
            dtype = dict.fromkeys(frame, dtype)
        else:
            dtype = cast('dict', dtype)
        for col, my_type in dtype.items():
            if not isinstance(my_type, str):
                raise ValueError(f"Invalid type '{my_type}' for dtype of column '{col}': expected a string. When using a DB-API connection (e.g. sqlite3), dtype values must be SQL type strings (e.g. 'TEXT', 'FLOAT').")
    table = SQLiteTable(name, self, frame=frame, index=record, if_exists=if_exists, index_label=index_label, dtype=dtype)
    table.create()
    return table.insert(chunksize, method)

