    check_is_fitted(self)
    param_3 = check_array(param_3, input_name='X', dtype=[xp.float64, xp.float32])
    if self.whiten:
        scaled_components = xp.sqrt(self.explained_variance_[:, np.newaxis]) * self.components_
        return param_3 @ scaled_components + self.mean_
    else:
        return param_3 @ self.components_ + self.mean_

def polyder(c, m=1, scl=1, axis=0):
    c = np.array(c, ndmin=1, copy=True)
    if c.dtype.char in '?bBhHiIlLqQpP':
        c = c + 0.0
    cdt = c.dtype
    cnt = pu._as_int(m, 'the order of derivation')
    iaxis = pu._as_int(axis, 'the axis')
    if cnt < 0:
        raise ValueError('The order of derivation must be non-negative')
    iaxis = np.lib.array_utils.normalize_axis_index(iaxis, c.ndim)
    if cnt == 0:
        return None
    c = np.moveaxis(c, iaxis, 0)
    n = len(c)
    if cnt >= n:
        c = c[:1] * 0
    else:
        for i in range(cnt):
            n = n - 1
            c *= scl
            der = np.empty((n,) + c.shape[1:], dtype=cdt)
            for j in range(n, 0, -1):
                der[j - 1] = j * c[j]
            c = der
    c = np.moveaxis(c, 0, iaxis)
    return c

