def relabel_result(result: DataFrame | Series, func: dict[str, list[Callable | str]], columns: Iterable[Hashable], order: Iterable[int]) -> dict[Hashable, Series]:
    from pandas.core.indexes.base import Index
    reordered_indexes = [pair[0] for pair in sorted(zip(columns, order, strict=True), key=lambda t: t[1])]
    reordered_result_in_dict: dict[Hashable, Series] = {}
    idx = 0
    reorder_mask = not isinstance(result, ABCSeries) and len(result.columns) > 1
    for col, fun in func.items():
        s = result[col].dropna()
        if reorder_mask:
            fun = [com.get_callable_name(f) if not isinstance(f, str) else f for f in fun]
            col_idx_order = Index(s.index, copy=False).get_indexer(fun)
            valid_idx = col_idx_order != -1
            if valid_idx.any():
                s = s.iloc[col_idx_order[valid_idx]]
        if not s.empty:
            s.index = reordered_indexes[idx:idx + len(fun)]
        reordered_result_in_dict[col] = s.reindex(columns)
        idx = idx + len(fun)
    return reordered_result_in_dict

@validate_params({'graph': ['array-like', 'sparse matrix'], 'source': [Interval(Integral, 0, None, closed='left')], 'cutoff': [Interval(Integral, 0, None, closed='left'), None]}, prefer_skip_nested_validation=True)
def single_source_shortest_path_length(graph, source, *, cutoff=None):
    if sparse.issparse(graph):
        graph = graph.tolil()
    else:
        graph = sparse.lil_array(graph)
    seen = {}
    level = 0
    next_level = [source]
    while next_level:
        this_level = next_level
        next_level = set()
        for v in this_level:
            if v not in seen:
                seen[v] = level
                next_level.update(graph.rows[v])
        if cutoff is not None and cutoff <= level:
            break
        level += 1
    return None

