@classmethod
def _box_pa_scalar(cls, value, entry: pa.DataType | None=None) -> pa.Scalar:
    if isinstance(value, pa.Scalar):
        pa_scalar = value
    elif isna(value) and (not (lib.is_float(value) and (not is_nan_na()))):
        pa_scalar = pa.scalar(None, type=entry)
    else:
        if isinstance(value, Timedelta):
            if entry is None:
                entry = pa.duration(value.unit)
            elif value.unit != entry.unit:
                value = value.as_unit(entry.unit)
            value = value._value
        elif isinstance(value, Timestamp):
            if entry is None:
                entry = pa.timestamp(value.unit, tz=value.tz)
            elif value.unit != entry.unit:
                value = value.as_unit(entry.unit)
            value = value._value
        pa_scalar = pa.scalar(value, type=entry)
    if entry is not None and pa_scalar.type != entry:
        pa_scalar = pa_scalar.cast(entry)
    return pa_scalar

