    msg = f"Cannot construct a 'SparseDtype' from '{string}'"
    if string.startswith('Sparse'):
        try:
            sub_type, has_fill_value = cls._parse_subtype(string)
        except ValueError as err:
            raise TypeError(msg) from err
        else:
