def non_reducing_slice(slice_: Subset):
    kinds = (ABCSeries, np.ndarray, Index, list, str)
    if isinstance(slice_, kinds):
        slice_ = IndexSlice[:, slice_]

    def pred(part) -> bool:
        """
        Returns
        -------
        bool
            True if slice does *not* reduce,
            False if `part` is a tuple.
        """
        if isinstance(part, tuple):
            return any((isinstance(s, slice) or is_list_like(s) for s in part))
        else:
            return isinstance(part, slice) or is_list_like(part)
    if not is_list_like(slice_):
        if not isinstance(slice_, slice):
            slice_ = [[slice_]]
        else:
            slice_ = [slice_]
    else:
        slice_ = [p if pred(p) else [p] for p in slice_]
    return tuple(slice_)

@final
def _try_convert_to_date(self, data: Series) -> Series:
    if not len(data):
        return data
    new_data = data
    if new_data.dtype == 'object' or new_data.dtype == 'string':
        try:
            new_data = data.astype('int64')
        except OverflowError:
            return data
        except (TypeError, ValueError):
            pass
    if issubclass(new_data.dtype.type, np.number):
        in_range = isna(new_data._values) | (new_data > self.min_stamp) | (new_data._values == iNaT)
        if not in_range.all():
            return data
    if new_data.dtype == 'string':
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', UserWarning)
            for format in (None, 'iso8601', 'mixed'):
                try:
                    return to_datetime(new_data, errors='raise', format=format)
                except Exception:
                    pass
    else:
        date_units = (self.date_unit,) if self.date_unit else self._STAMP_UNITS
        for date_unit in date_units:
            try:
                data = to_datetime(new_data, errors='raise', unit=date_unit)
                _ = data.dt.as_unit('ns')
                break
            except OutOfBoundsDatetime:
                continue
            except (ValueError, OverflowError, TypeError):
                pass
    return data

