        data = d.pop('data')
        if not isinstance(data, DatetimeArray):
            tz = d.pop('tz')
            freq = d.pop('freq')
            dta = DatetimeArray._simple_new(data, dtype=tz_to_dtype(tz))
        else:
            dta = data
            if 'tz' in d:
                assert d.pop('tz') == dta.tz
            legacy_freq = vars(dta).pop('_freq', None)
            freq = d.pop('freq', legacy_freq)
        result = cls._simple_new(dta, **d)
        result._freq = freq
    else:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            result = cls.__new__(cls, **d)
    return result

def apply_where(cond: Array, args: Array | tuple[Array, ...], f1: Callable[..., Array], f2: Callable[..., Array] | None=None, /, *, fill_value: Array | complex | None=None, kwargs: dict[str, Array] | None=None, xp: ModuleType | None=None) -> Array:
    if (f2 is None) == (fill_value is None):
        msg = 'Exactly one of `fill_value` or `f2` must be given.'
        raise TypeError(msg)
    args_ = list(args) if isinstance(args, tuple) else [args]
    del args
    kwargs_ = {} if kwargs is None else kwargs
    kwkeys = list(kwargs_.keys())
    args_ = [*args_, *kwargs_.values()]
    del kwargs
    xp = array_namespace(cond, fill_value, *args_) if xp is None else xp
    if isinstance(fill_value, int | float | complex | NoneType):
        cond, *args_ = xp.broadcast_arrays(cond, *args_)
    else:
        cond, fill_value, *args_ = xp.broadcast_arrays(cond, fill_value, *args_)
    if is_dask_namespace(xp):
        meta_xp = meta_namespace(cond, fill_value, *args_, xp=xp)
        return xp.map_blocks(_apply_where, cond, f1, f2, fill_value, *args_, kwkeys=kwkeys, xp=meta_xp)
    return _apply_where(cond, f1, f2, fill_value, *args_, kwkeys=kwkeys, xp=xp)

def predict(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False, accept_sparse='csr')
    if not hasattr(self, 'cluster_centers_'):
        raise ValueError("Predict method is not supported when affinity='precomputed'.")
    if self.cluster_centers_.shape[0] > 0:
        with config_context(assume_finite=True):
            return pairwise_distances_argmin(X, self.cluster_centers_)
    else:
        warnings.warn("This model does not have any cluster centers because affinity propagation did not converge. Labeling every sample as '-1'.", ConvergenceWarning)
        return np.array([-1] * X.shape[0])

def transform(self, X):
    check_is_fitted(self)
    xp, _, device_ = get_namespace_and_device(X)
    X = validate_data(self, X, order='F', dtype=supported_float_dtypes(xp=xp, device=device_), reset=False, accept_sparse=('csr', 'csc'))
    n_samples, n_features = X.shape
    max_int32 = xp.iinfo(xp.int32).max
    if sparse.issparse(X) and X.format == 'csr':
        if self._max_degree > 3:
            return self.transform(X.tocsc()).tocsr()
        to_stack = []
        if self.include_bias:
            to_stack.append(sparse.csr_array(np.ones(shape=(n_samples, 1), dtype=X.dtype)))
        if self._min_degree <= 1 and self._max_degree > 0:
            to_stack.append(X)
        cumulative_size = sum((mat.shape[1] for mat in to_stack))
        for deg in range(max(2, self._min_degree), self._max_degree + 1):
            expanded = _create_expansion(X=X, interaction_only=self.interaction_only, deg=deg, n_features=n_features, cumulative_size=cumulative_size)
            if expanded is not None:
                to_stack.append(expanded)
                cumulative_size += expanded.shape[1]
        if len(to_stack) == 0:
            XP = sparse.csr_array((n_samples, 0), dtype=X.dtype)
        else:
            XP = sparse.hstack(to_stack, dtype=X.dtype, format='csr')
    elif sparse.issparse(X) and X.format == 'csc' and (self._max_degree < 4):
        return self.transform(X.tocsr()).tocsc()
    elif sparse.issparse(X):
        combinations = self._combinations(n_features=n_features, min_degree=self._min_degree, max_degree=self._max_degree, interaction_only=self.interaction_only, include_bias=self.include_bias)
        columns = []
        for combi in combinations:
            if combi:
                out_col = 1
                for col_idx in combi:
                    out_col = X[:, [col_idx]].multiply(out_col)
                columns.append(out_col)
            else:
                bias = sparse.csc_array(np.ones((X.shape[0], 1)))
                columns.append(bias)
        XP = sparse.hstack(columns, dtype=X.dtype).tocsc()
    else:
        order_kwargs = {}
        if _is_numpy_namespace(xp=xp):
            order_kwargs['order'] = self.order
        elif self.order == 'F':
            raise ValueError("PolynomialFeatures does not support order='F' for non-numpy arrays")
        XP = xp.empty(shape=(n_samples, self._n_out_full), dtype=X.dtype, device=device_, **order_kwargs)
        if self.include_bias:
            XP[:, 0] = 1
            current_col = 1
        else:
            current_col = 0
        if self._max_degree == 0:
            return _align_api_if_sparse(XP)
        XP[:, current_col:current_col + n_features] = X
        index = list(range(current_col, current_col + n_features))
        current_col += n_features
        index.append(current_col)
        for _ in range(2, self._max_degree + 1):
            new_index = []
            end = index[-1]
            for feature_idx in range(n_features):
                start = index[feature_idx]
                new_index.append(current_col)
                if self.interaction_only:
                    start += index[feature_idx + 1] - index[feature_idx]
                next_col = current_col + end - start
                if next_col <= current_col:
                    break
                if _is_numpy_namespace(xp):
                    np.multiply(XP[:, start:end], X[:, feature_idx:feature_idx + 1], out=XP[:, current_col:next_col], casting='no')
                else:
                    XP[:, current_col:next_col] = xp.multiply(XP[:, start:end], X[:, feature_idx:feature_idx + 1])
                current_col = next_col
            new_index.append(current_col)
            index = new_index
        if self._min_degree > 1:
            n_XP, n_Xout = (self._n_out_full, self.n_output_features_)
            if self.include_bias:
                Xout = xp.empty(shape=(n_samples, n_Xout), dtype=XP.dtype, device=device_, **order_kwargs)
                Xout[:, 0] = 1
                Xout[:, 1:] = XP[:, n_XP - n_Xout + 1:]
            else:
                Xout = xp.asarray(XP[:, n_XP - n_Xout:], copy=True)
            XP = Xout
    return _align_api_if_sparse(XP)

def infer_dtype_from_object(record) -> type:
    if isinstance(record, type) and issubclass(record, np.generic):
        return record
    is_dtype_instance = isinstance(record, (np.dtype, ExtensionDtype))
    try:
        record = pandas_dtype(record)
    except TypeError:
        if isinstance(record, str):
            if record in ['datetimetz', 'datetime64tz']:
                return DatetimeTZDtype.type
            elif record == 'period':
                raise NotImplementedError from None
            elif record == 'datetime':
                return np.datetime64
            elif record == 'timedelta':
                return np.timedelta64
            elif hasattr(np, record):
                maybe_dtype = getattr(np, record)
                if isinstance(maybe_dtype, type) and issubclass(maybe_dtype, np.generic):
                    return maybe_dtype
        raise
    if lib.is_np_dtype(record, 'mM'):
        _validate_date_like_dtype(record)
    if is_dtype_instance and hasattr(record, 'numpy_dtype'):
        return record.numpy_dtype.type
    return record.type

def _get_data_and_dtype_name(data: ArrayLike):
