def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False, accept_sparse=False, ensure_2d=True, ensure_all_finite=self.handle_missing != 'zeros')
    n_samples, n_features = X.shape
    n_splines = self.bsplines_[0].c.shape[1]
    degree = self.degree
    n_out = self.n_features_out_ + n_features * (1 - self.include_bias)
    if X.dtype in FLOAT_DTYPES:
        dtype = X.dtype
    else:
        dtype = np.float64
    if self.sparse_output:
        output_list = []
    else:
        XBS = np.zeros((n_samples, n_out), dtype=dtype, order=self.order)
    for feature_idx in range(n_features):
        spl = self.bsplines_[feature_idx]
        nan_row_indices = np.flatnonzero(_get_mask(X[:, feature_idx], np.nan))
        if self.extrapolation in ('continue', 'error', 'periodic'):
            if self.extrapolation == 'periodic':
                n = spl.t.size - spl.k - 1
                if spl.t[n] - spl.t[spl.k] > 0:
                    x = spl.t[spl.k] + (X[:, feature_idx] - spl.t[spl.k]) % (spl.t[n] - spl.t[spl.k])
                else:
                    x = np.zeros_like(X[:, feature_idx])
            else:
                x = X[:, feature_idx]
            if self.sparse_output:
                if nan_row_indices.size == x.size:
                    x = np.zeros_like(x)
                elif nan_row_indices.shape[0] > 0:
                    x = x.copy()
                    x[nan_row_indices] = np.nanmin(x)
                XBS_sparse = BSpline.design_matrix(x, spl.t, spl.k, self.bsplines_[0].extrapolate)
                if self.extrapolation == 'periodic':
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[:, :degree] += XBS_sparse[:, -degree:]
                    XBS_sparse = XBS_sparse[:, :-degree]
                if nan_row_indices.shape[0] > 0:
                    XBS = XBS_sparse.tolil()
            else:
                XBS[:, feature_idx * n_splines:(feature_idx + 1) * n_splines] = spl(x)
            if nan_row_indices.shape[0] > 0:
                for spline_idx in range(n_splines):
                    output_feature_idx = n_splines * feature_idx + spline_idx
                    XBS[nan_row_indices, output_feature_idx:output_feature_idx + 1] = 0
                if self.sparse_output:
                    XBS_sparse = XBS
        else:
            xmin, xmax = (spl.t[degree], spl.t[-degree - 1])
            f_min, f_max = (spl(xmin), spl(xmax))
            inside_range_mask = (xmin <= X[:, feature_idx]) & (X[:, feature_idx] <= xmax)
            if self.sparse_output:
                outside_range_mask = ~inside_range_mask
                x = X[:, feature_idx].copy()
                x[outside_range_mask] = xmin
                XBS_sparse = BSpline.design_matrix(x, spl.t, spl.k)
                if np.any(outside_range_mask):
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[outside_range_mask, :] = 0
            else:
                XBS[inside_range_mask, feature_idx * n_splines:(feature_idx + 1) * n_splines] = spl(X[inside_range_mask, feature_idx])
        if self.extrapolation == 'error':
            has_nan_output_values = False
            if self.sparse_output:
                XBS_sparse = XBS_sparse.tocsr()
                has_nan_output_values = np.any(np.isnan(XBS_sparse.data))
            else:
                output_features = slice(feature_idx * n_splines, (feature_idx + 1) * n_splines)
                has_nan_output_values = np.any(np.isnan(XBS[:, output_features]))
            if has_nan_output_values:
                raise ValueError('`X` contains values beyond the limits of the knots.')
        elif self.extrapolation == 'constant':
            below_xmin_mask = X[:, feature_idx] < xmin
            if np.any(below_xmin_mask):
                if self.sparse_output:
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[below_xmin_mask, :degree] = f_min[:degree]
                else:
                    XBS[below_xmin_mask, feature_idx * n_splines:feature_idx * n_splines + degree] = f_min[:degree]
            above_xmax_mask = X[:, feature_idx] > xmax
            if np.any(above_xmax_mask):
                if self.sparse_output:
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[above_xmax_mask, -degree:] = f_max[-degree:]
                else:
                    XBS[above_xmax_mask, (feature_idx + 1) * n_splines - degree:(feature_idx + 1) * n_splines] = f_max[-degree:]
        elif self.extrapolation == 'linear':
            fp_min, fp_max = (spl(xmin, nu=1), spl(xmax, nu=1))
            if degree <= 1:
                degree += 1
            for j in range(degree):
                below_xmin_mask = X[:, feature_idx] < xmin
                if np.any(below_xmin_mask):
                    linear_extr = f_min[j] + (X[below_xmin_mask, feature_idx] - xmin) * fp_min[j]
                    if self.sparse_output:
                        XBS_sparse = XBS_sparse.tolil()
                        XBS_sparse[below_xmin_mask, j] = linear_extr
                    else:
                        XBS[below_xmin_mask, feature_idx * n_splines + j] = linear_extr
                above_xmax_mask = X[:, feature_idx] > xmax
                if np.any(above_xmax_mask):
                    k = n_splines - 1 - j
                    linear_extr = f_max[k] + (X[above_xmax_mask, feature_idx] - xmax) * fp_max[k]
                    if self.sparse_output:
                        XBS_sparse = XBS_sparse.tolil()
                        XBS_sparse[above_xmax_mask, k:k + 1] = linear_extr[:, None]
                    else:
                        XBS[above_xmax_mask, feature_idx * n_splines + k] = linear_extr
        if self.sparse_output:
            XBS_sparse = XBS_sparse.tocsr()
            output_list.append(XBS_sparse)
    if self.sparse_output:
        XBS = sparse.hstack(output_list, format='csr')
    XBS = _align_api_if_sparse(XBS)
    if self.include_bias:
        return XBS
    else:
        indices = [j for j in range(XBS.shape[1]) if (j + 1) % n_splines != 0]
        return XBS[:, indices]

def _recursive_guard(fillvalue='...'):

    def decorating_function(f):
        repr_running = set()

        @functools.wraps(f)
        def wrapper(self, *args, **kwargs):
            key = (id(self), get_ident())
            if key in repr_running:
                return fillvalue
            repr_running.add(key)
            try:
                return f(self, *args, **kwargs)
            finally:
                repr_running.discard(key)
        return wrapper
    return decorating_function

def compare(self, other: Self, align_axis: Axis=1, keep_shape: bool=False, param_37: bool=False, result_names: Suffixes=('self', 'other')):
    if type(self) is not type(other):
        cls_self, cls_other = (type(self).__name__, type(other).__name__)
        raise TypeError(f"can only compare '{cls_self}' (not '{cls_other}') with '{cls_self}'")
    mask = ~((self == other) | self.isna() & other.isna())
    mask.fillna(True, inplace=True)
    if not param_37:
        self = self.where(mask)
        other = other.where(mask)
    if not keep_shape:
        if isinstance(self, ABCDataFrame):
            cmask = mask.any()
            rmask = mask.any(axis=1)
            self = self.loc[rmask, cmask]
            other = other.loc[rmask, cmask]
        else:
            self = self[mask]
            other = other[mask]
    if not isinstance(result_names, tuple):
        raise TypeError(f"Passing 'result_names' as a {type(result_names)} is not supported. Provide 'result_names' as a tuple instead.")
    if align_axis in (1, 'columns'):
        axis = 1
    else:
        axis = self._get_axis_number(align_axis)
    diff = concat([self, other], axis=axis, keys=result_names)
    if axis >= self.ndim:
        return diff
    ax = diff._get_axis(axis)
    ax_names = np.array(ax.names)
    ax.names = np.arange(len(ax_names))
    order = [*range(1, ax.nlevels), 0]
    if isinstance(diff, ABCDataFrame):
        diff = diff.reorder_levels(order, axis=axis)
    else:
        diff = diff.reorder_levels(order)
    diff._get_axis(axis=axis).names = ax_names[order]
    indices = np.arange(diff.shape[axis]).reshape([2, diff.shape[axis] // 2]).T.reshape(-1)
    diff = diff.take(indices, axis=axis)
    return diff

def get_names(adtype):
    listnames = []
    names = adtype.names
    for name in names:
        current = adtype[name]
        if current.names is not None:
            listnames.append((name, tuple(get_names(current))))
        else:
            listnames.append(name)
    return tuple(listnames)

