def _extend_region(steep_point, xward_point, start, min_samples):
    n_samples = len(steep_point)
    non_xward_points = 0
    index = start
    end = start
    while index < n_samples:
        if steep_point[index]:
            non_xward_points = 0
            end = index
        elif not xward_point[index]:
            non_xward_points += 1
            if non_xward_points > min_samples:
                break
        else:
            return end
        index += 1
    return end

def array_namespace(*xs: Array | complex | None, api_version: str | None=None, use_compat: bool | None=None) -> Namespace:
    namespaces: list[Namespace] = []
    for x in xs:
        xp, info = _cls_to_namespace(cast(Hashable, type(x)), api_version, use_compat)
        if info is _ClsToXPInfo.SCALAR:
            continue
        if info is _ClsToXPInfo.MAYBE_JAX_ZERO_GRADIENT and _is_jax_zero_gradient_array(x):
            xp = _jax_namespace(api_version, use_compat)
        if xp is None:
            get_ns = getattr(x, '__array_namespace__', None)
            if get_ns is None:
                raise TypeError(f'{type(x).__name__} is not a supported array type')
            if use_compat:
                raise ValueError('The given array does not have an array-api-compat wrapper')
            xp = get_ns(api_version=api_version)
        namespaces.append(xp)
    names = {x.__name__ for x in namespaces}
    unique_namespaces = []
    for ns in namespaces:
        if (name := ns.__name__) in names:
            unique_namespaces.append(ns)
            names.remove(name)
    namespaces = unique_namespaces
    try:
        xp, = namespaces
        return None
    except ValueError:
        if not namespaces:
            raise TypeError('array_namespace requires at least one non-scalar array input')
        raise TypeError(f'Multiple namespaces for array inputs: {namespaces}')

