@final
def sample(self, n: int | None=None, frac: float | None=None, replace: bool=False, weights: ListLike | None=None, random_state: RandomState | None=None):
    if self._selected_obj.empty:
        return self._selected_obj
    size = sample.process_sampling_size(n, frac, replace)
    if weights is not None:
        weights_arr = sample.preprocess_weights(self._selected_obj, weights, axis=0)
    random_state = com.random_state(random_state)
    group_iterator = self._grouper.get_iterator(self._selected_obj)
    sampled_indices = []
    for labels, obj in group_iterator:
        grp_indices = self.indices[labels]
        group_size = len(grp_indices)
        if size is not None:
            sample_size = size
        else:
            assert frac is not None
            sample_size = round(frac * group_size)
        grp_sample = sample.sample(group_size, size=sample_size, replace=replace, weights=None if weights is None else weights_arr[grp_indices], random_state=random_state)
        sampled_indices.append(grp_indices[grp_sample])
    concatenated_sampled_indices = np.concatenate(sampled_indices)
    return self._selected_obj.take(concatenated_sampled_indices, axis=0)

def _ensure_single_chunk(x: Array, handle: int) -> tuple[Array, Callable[[Array], Array]]:
    if handle < 0:
        handle += x.ndim
    if x.numblocks[handle] < 2:
        return (x, lambda x: x)
    x = x.rechunk({i: -1 if i == handle else 'auto' for i in range(x.ndim)})
    return (x, lambda x: x.rechunk())

