def _interleave(self, dtype: np.dtype | None=None, na_value: object=lib.no_default) -> np.ndarray:
    if not dtype:
        dtype = self._interleaved_dtype
        if dtype is None:
            dtype = interleaved_dtype([blk.dtype for blk in self.blocks])
            self._interleaved_dtype = dtype
    dtype = ensure_np_dtype(dtype)
    result = np.empty(self.shape, dtype=dtype)
    itemmask = np.zeros(self.shape[0])
    if dtype == np.dtype('object') and na_value is lib.no_default:
        for blk in self.blocks:
            rl = blk.mgr_locs
            arr = blk.get_values(dtype)
            result[rl.indexer] = arr
            itemmask[rl.indexer] = 1
        return result
    for blk in self.blocks:
        rl = blk.mgr_locs
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value)
        else:
            arr = blk.get_values(dtype)
        result[rl.indexer] = arr
        if na_value is not lib.no_default and blk.dtype.kind in 'mM':
            result[rl.indexer][isna(arr)] = na_value
        itemmask[rl.indexer] = 1
    if not itemmask.all():
        raise AssertionError('Some items were not contained in blocks')
    return result

def get_fieldstructure(source, lastname=None, parents=None):
    if parents is None:
        parents = {}
    names = source.names
    for name in names:
        current = source[name]
        if current.names is not None:
            if lastname:
                parents[name] = [lastname]
            else:
                parents[name] = []
            parents.update(get_fieldstructure(current, name, parents))
        else:
            lastparent = list(parents.get(lastname, []) or [])
            if lastparent:
                lastparent.append(lastname)
            elif lastname:
                lastparent = [lastname]
            parents[name] = lastparent or []
    return parents

