def _align_api_if_sparse(handle):
    if not sp.sparse.issparse(handle):
        return handle
    config_sparse_interface = get_config()['sparse_interface']
    if config_sparse_interface == 'sparray':
        if sp.sparse.isspmatrix(handle):
            return getattr(sp.sparse, handle.format + '_array')(handle)
        return handle
    elif config_sparse_interface == 'spmatrix':
        if sp.sparse.isspmatrix(handle):
            return handle
        return getattr(sp.sparse, handle.format + '_matrix')(handle)
    else:
        raise ValueError(f'Config "sparse_interface" is {config_sparse_interface}. It should be either "sparray" or "spmatrix".')

@set_module('pandas.testing')
