def assert_series_equal(left: Series, right: Series, check_dtype: bool | Literal['equiv']=True, check_index_type: bool | Literal['equiv']='equiv', source: bool=True, check_names: bool=True, check_exact: bool | lib.NoDefault=lib.no_default, check_datetimelike_compat: bool=False, check_categorical: bool=True, check_category_order: bool=True, check_freq: bool=True, check_flags: bool=True, rtol: float | lib.NoDefault=lib.no_default, atol: float | lib.NoDefault=lib.no_default, obj: str='Series', *, check_index: bool=True, check_like: bool=False) -> None:
    __tracebackhide__ = True
    if check_exact is lib.no_default and rtol is lib.no_default and (atol is lib.no_default):
        check_exact = is_numeric_dtype(left.dtype) and (not is_float_dtype(left.dtype)) or (is_numeric_dtype(right.dtype) and (not is_float_dtype(right.dtype)))
