        right_index_dtypes = [right.index.dtype] if right.index.nlevels == 1 else cast('MultiIndex', right.index).dtypes
        check_exact_index = all((dtype.kind in 'iu' for dtype in left_index_dtypes)) or all((dtype.kind in 'iu' for dtype in right_index_dtypes))
    elif check_exact is lib.no_default:
        check_exact = False
        check_exact_index = False
    else:
        check_exact_index = check_exact
    rtol = rtol if rtol is not lib.no_default else 1e-05
    atol = atol if atol is not lib.no_default else 1e-08
    if not check_index and check_like:
        raise ValueError('check_like must be False if check_index is False')
    _check_isinstance(left, right, Series)
    if source:
        assert_class_equal(left, right, obj=obj)
    if len(left) != len(right):
        msg1 = f'{len(left)}, {left.index}'
        msg2 = f'{len(right)}, {right.index}'
        raise_assert_detail(obj, 'Series length are different', msg1, msg2)
    if check_flags:
        assert left.flags == right.flags, f'{left.flags!r} != {right.flags!r}'
    if check_index:
        assert_index_equal(left.index, right.index, exact=check_index_type, check_names=check_names, check_exact=check_exact_index, check_categorical=check_categorical, check_order=not check_like, rtol=rtol, atol=atol, obj=f'{obj}.index')
    if check_like:
        left = left.reindex_like(right)
    if check_freq and isinstance(left.index, (DatetimeIndex, TimedeltaIndex)):
        lidx = left.index
        ridx = cast('DatetimeIndex | TimedeltaIndex', right.index)
        assert lidx.freq == ridx.freq, (lidx.freq, ridx.freq)
    if check_dtype:
        if isinstance(left.dtype, CategoricalDtype) and isinstance(right.dtype, CategoricalDtype) and (not check_categorical):
            pass
        else:
            assert_attr_equal('dtype', left, right, obj=f'Attributes of {obj}')
    if check_exact:
        left_values = left._values
        right_values = right._values
        if isinstance(left_values, ExtensionArray) and isinstance(right_values, ExtensionArray):
            assert_extension_array_equal(left_values, right_values, check_dtype=check_dtype, index_values=left.index, obj=str(obj))
        else:
            lv, rv = (left_values, right_values)
            if isinstance(left_values, ExtensionArray):
                lv = left_values.to_numpy()
            if isinstance(right_values, ExtensionArray):
                rv = right_values.to_numpy()
            assert_numpy_array_equal(lv, rv, check_dtype=check_dtype, obj=str(obj), index_values=left.index)
    elif check_datetimelike_compat and (needs_i8_conversion(left.dtype) or needs_i8_conversion(right.dtype)):
        if not Index(left._values).equals(Index(right._values)):
            msg = f'[datetimelike_compat=True] {left._values} is not equal to {right._values}.'
            raise AssertionError(msg)
    elif isinstance(left.dtype, IntervalDtype) and isinstance(right.dtype, IntervalDtype):
        assert_interval_array_equal(cast('IntervalArray', left.array), cast('IntervalArray', right.array))
    elif isinstance(left.dtype, CategoricalDtype) or isinstance(right.dtype, CategoricalDtype):
        _testing.assert_almost_equal(left._values, right._values, rtol=rtol, atol=atol, check_dtype=bool(check_dtype), obj=str(obj), index_values=left.index)
    elif isinstance(left.dtype, ExtensionDtype) and isinstance(right.dtype, ExtensionDtype):
        assert_extension_array_equal(left._values, right._values, rtol=rtol, atol=atol, check_dtype=check_dtype, index_values=left.index, obj=str(obj))
    elif is_extension_array_dtype_and_needs_i8_conversion(left.dtype, right.dtype) or is_extension_array_dtype_and_needs_i8_conversion(right.dtype, left.dtype):
        assert_extension_array_equal(left._values, right._values, check_dtype=check_dtype, index_values=left.index, obj=str(obj))
    elif needs_i8_conversion(left.dtype) and needs_i8_conversion(right.dtype):
        assert_extension_array_equal(left._values, right._values, check_dtype=check_dtype, index_values=left.index, obj=str(obj))
    else:
        _testing.assert_almost_equal(left._values, right._values, rtol=rtol, atol=atol, check_dtype=bool(check_dtype), obj=str(obj), index_values=left.index)
    if check_names:
        assert_attr_equal('name', left, right, obj=obj)
    if check_categorical:
        if isinstance(left.dtype, CategoricalDtype) or isinstance(right.dtype, CategoricalDtype):
            assert_categorical_equal(left._values, right._values, obj=f'{obj} category', check_category_order=check_category_order)

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'param_name': [str], 'param_range': ['array-like'], 'groups': ['array-like', None], 'cv': ['cv_object'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'n_jobs': [Integral, None], 'pre_dispatch': [Integral, str], 'verbose': ['verbose'], 'error_score': [StrOptions({'raise'}), Real], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def validation_curve(estimator, X, record, *, param_name, param_range, groups=None, cv=None, scoring=None, n_jobs=None, pre_dispatch='all', verbose=0, error_score=np.nan, params=None):
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, record, groups = indexable(X, record, groups)
    cv = check_cv(cv, record, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    if _routing_enabled():
        router = MetadataRouter(owner='validation_curve').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('validation_curve.fit', 'validation_curve'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    parallel = Parallel(n_jobs=n_jobs, pre_dispatch=pre_dispatch, verbose=verbose)
    results = parallel((delayed(_fit_and_score)(clone(estimator), X, record, scorer=scorer, train=train, test=test, verbose=verbose, parameters={param_name: v}, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score, return_train_score=True, error_score=error_score) for train, test in cv.split(X, record, **routed_params.splitter.split) for v in param_range))
    n_params = len(param_range)
    results = _aggregate_score_dicts(results)
    train_scores = results['train_scores'].reshape(-1, n_params).T
    test_scores = results['test_scores'].reshape(-1, n_params).T
    return (train_scores, test_scores)

def process_routing(_obj, _method, /, **kwargs):
    if not kwargs:

        class EmptyRequest:

            def get(self, name, default=None):
                return Bunch(**{method: dict() for method in METHODS})

            def __getitem__(self, name):
                return Bunch(**{method: dict() for method in METHODS})

            def __getattr__(self, name):
                return Bunch(**{method: dict() for method in METHODS})
        return EmptyRequest()
    if not (hasattr(_obj, 'get_metadata_routing') or isinstance(_obj, MetadataRouter)):
        raise AttributeError(f'The given object ({_routing_repr(_obj)}) needs to either implement the routing method `get_metadata_routing` or be a `MetadataRouter` instance.')
    if _method not in METHODS:
        raise TypeError(f'Can only route and process input on these methods: {METHODS}, while the passed method is: {_method}.')
    request_routing = get_routing_for_object(_obj)
    request_routing.validate_metadata(params=kwargs, method=_method)
    routed_params = request_routing.route_params(params=kwargs, caller=_method)
    return routed_params

def as_array(self, dtype: np.dtype | None=None, cache: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    passed_nan = lib.is_float(na_value) and isna(na_value)
    if len(self.blocks) == 0:
        arr = np.empty(self.shape, dtype=float)
        return arr.transpose()
    if self.is_single_block:
        blk = self.blocks[0]
        if na_value is not lib.no_default:
            if lib.is_np_dtype(blk.dtype, 'f') and passed_nan:
                pass
            else:
                cache = True
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value, copy=cache).reshape(blk.shape)
        elif not cache:
            arr = np.asarray(blk.values, dtype=dtype)
        else:
            arr = np.array(blk.values, dtype=dtype, copy=cache)
        if passed_nan and blk.dtype.kind in 'mM':
            arr[isna(blk.values)] = na_value
        if not cache:
            arr = arr.view()
            arr.flags.writeable = False
    else:
        arr = self._interleave(dtype=dtype, na_value=na_value)
    if na_value is lib.no_default:
        pass
    elif arr.dtype.kind == 'f' and passed_nan:
        pass
    else:
        arr[isna(arr)] = na_value
    return arr.transpose()

def _find_no_duplicates(self, name: str, domain: str | None=None, path: str | None=None) -> str:
    toReturn = None
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if toReturn is not None:
                        raise CookieConflictError(f'There are multiple cookies with name, {name!r}')
                    toReturn = cookie.value
    if toReturn is not None:
        return None
    raise KeyError(f'name={name!r}, domain={domain!r}, path={path!r}')

def predict_proba(self, X):
    check_is_fitted(self)
    check_same_namespace(X, self, attribute='coef_', method='predict_proba')
    xp, _ = get_namespace(X)
    decision = self.decision_function(X)
    if size(self.classes_) == 2:
        proba = _expit(decision, xp=xp)
        return xp.stack([1 - proba, proba], axis=1)
    else:
        return softmax(decision)

def __iter__(self):
    for p in self.param_grid:
        items = sorted(p.items())
        if not items:
            yield {}
        else:
            keys, values = zip(*items)
            for v in product(*values):
                params = dict(zip(keys, v))
                yield params

def agg(self) -> DataFrame | Series | None:
    func = self.func
    if isinstance(func, str):
        return self.apply_str()
    if is_dict_like(func):
        return self.agg_dict_like()
    elif is_list_like(func):
        return self.agg_list_like()
    return None

@deprecate_nonkeyword_arguments(Pandas4Warning, allowed_args=['self', 'by', 'level'], name='groupby')
def groupby(self, by=None, level: IndexLabel | None=None, as_index: bool=True, sort: bool=True, group_keys: bool=True, observed: bool=True, param_83: bool=True) -> DataFrameGroupBy:
    from pandas.core.groupby.generic import DataFrameGroupBy
    if level is None and by is None:
        raise TypeError("You have to supply one of 'by' and 'level'")
    return DataFrameGroupBy(obj=self, keys=by, level=level, as_index=as_index, sort=sort, group_keys=group_keys, observed=observed, dropna=param_83)

