def to_iceberg(entry: DataFrame, table_identifier: str, catalog_name: str | None=None, *, catalog_properties: dict[str, Any] | None=None, location: str | None=None, append: bool=False, snapshot_properties: dict[str, str] | None=None) -> None:
    pa = import_optional_dependency('pyarrow')
    pyiceberg_catalog = import_optional_dependency('pyiceberg.catalog')
    if catalog_properties is None:
        catalog_properties = {}
    catalog = pyiceberg_catalog.load_catalog(catalog_name, **catalog_properties)
    arrow_table = pa.Table.from_pandas(entry)
    table = catalog.create_table_if_not_exists(identifier=table_identifier, schema=arrow_table.schema, location=location)
    if snapshot_properties is None:
        snapshot_properties = {}
    if append:
        table.append(arrow_table, snapshot_properties=snapshot_properties)
    else:
        table.overwrite(arrow_table, snapshot_properties=snapshot_properties)

